// amazing plants (Russian only: the other languages get an empty list and the tile hides); source: stories/v145/plants.json
LEARN.plants = { name: 'Удивительные растения', e: '🌳', bg: 'var(--t-green)', sub: 'баобаб, росянка, кактус, бамбук…', items: LX('PLANT_STORIES', [{"id": "pl-baobab", "e": "🌳", "t": "Баобаб — дерево-бочка", "s": "В жаркой Африке растёт баобаб. Ствол у него толстый, как огромная бочка. Дожди там идут редко, и баобаб запасает воду прямо в мягкой древесине: в большом дереве её могут быть тысячи литров. Когда наступает засуха, он сбрасывает листья, и голые ветки торчат, будто корни. Кажется, что дерево перевернули вверх ногами.", "q": "Зачем баобабу такой толстый ствол?", "a": ["Чтобы хранить в нём воду", "Чтобы не падать от ветра", "Чтобы согреваться зимой"]}, {"id": "pl-sekvoyya", "e": "🌲", "t": "Самое высокое дерево", "s": "В Америке, в Калифорнии, растёт секвойя по имени Гиперион. Она вытянулась примерно на сто шестнадцать метров, это как дом этажей в тридцать пять. Секвойя пьёт воду корнями, а ещё ловит хвоинками капельки тумана, который наползает с океана. Так вода попадает и на самую верхушку. Где именно стоит это дерево, люди не рассказывают, чтобы никто не вытоптал траву вокруг.", "q": "Что помогает секвойе напиться на такой высоте?", "a": ["Корни и капельки тумана на хвоинках", "Длинные ветки, которые достают до земли", "Дождь, который идёт каждый день"]}, {"id": "pl-rosyanka", "e": "🌿", "t": "Росянка с липкими каплями", "s": "На болоте растёт маленькая росянка. Её листья покрыты тонкими волосками, а на каждом блестит прозрачная липкая капелька, как роса. Комарик садится на лист, прилипает, и лист медленно сворачивается вокруг него. В болоте земля бедная, и росянка добывает недостающую еду именно так. Но человека она не тронет: она совсем крошечная.", "q": "Чем росянка ловит насекомых?", "a": ["Липкими капельками на волосках", "Острыми колючками", "Крепкой паутиной"]}, {"id": "pl-kaktus", "e": "🌵", "t": "Колючки кактуса", "s": "В пустыне жарко и сухо, а кактус не боится. Его толстый стебель, как бак, набирается водой после редкого дождя. А колючки — это его листья, только очень узкие и острые. Они не дают голодным зверям съесть сочный стебель и даже немного затеняют его от жгучего солнца. Зато когда кактус цветёт, цветы у него нежные и яркие.", "q": "Чем на самом деле были колючки кактуса?", "a": ["Узкими острыми листьями", "Сухими ветками", "Корешками"]}, {"id": "pl-bambuk", "e": "🎋", "t": "Бамбук-скороход", "s": "Бамбук — самая быстрая трава на свете, хотя и вырастает высотой с дерево. Некоторые виды растут почти на метр за сутки. Лёг спать, а за ночь он подрос на ладонь или две! Внутри ствола пусто, но через каждые несколько ладоней есть перегородки-узлы. Они делают стебель лёгким, прочным и гибким, так что сильный ветер его только покачает.", "q": "Что делает бамбуковый стебель прочным, хоть он и пустой внутри?", "a": ["Перегородки-узлы", "Толстая кора", "Каменные корни"]}, {"id": "pl-podsolnukh", "e": "🌻", "t": "Подсолнух идёт за солнцем", "s": "Молодой подсолнух весь день смотрит на солнце. Утром его бутон повернут на восток, днём он плавно переводит взгляд, а к вечеру глядит на запад. За ночь он поворачивается обратно и встречает рассвет. Так растёт стебель: сторона в тени вытягивается чуть быстрее, и цветок наклоняется к свету. Когда подсолнух вырос и расцвёл, он замирает и глядит на восток.", "q": "Когда подсолнух поворачивается за солнцем?", "a": ["Пока он молодой", "Только зимой", "Только когда идёт дождь"]}, {"id": "pl-lotos", "e": "🪷", "t": "Чистый лотос", "s": "Лотос растёт в тёплых прудах, а листья у него огромные и круглые. Если на лист упадёт дождь, капли собираются в блестящие шарики и катятся, как бусинки. По дороге они уносят с собой пылинки, и лист снова чистый. Всё дело в мельчайших бугорках на его поверхности: вода на них не растекается. Поэтому лотос и в мутной воде остаётся свежим и чистым.", "q": "Что случается с каплями дождя на листе лотоса?", "a": ["Они собираются в шарики и скатываются", "Они впитываются внутрь листа", "Они замерзают на листе"]}, {"id": "pl-viktoriya", "e": "🪷", "t": "Лист-лодка кувшинки Виктория", "s": "В реках Амазонки плавает кувшинка Виктория. Её круглые листья вырастают до трёх метров в ширину, и края у них загнуты, как у большого блюда. Снизу лист укреплён толстыми жилками, как каркас, а между ними полно воздуха. Поэтому лист держится на воде, как плот, и может удержать даже маленького ребёнка, если он сядет посередине. Кувшинка цветёт по ночам.", "q": "Почему лист кувшинки Виктория держится на воде?", "a": ["Снизу у него крепкие жилки и воздух", "Он очень тяжёлый", "Он приклеен к камню"]}, {"id": "pl-muholovka", "e": "🪤", "t": "Мухоловка, которая считает", "s": "У венериной мухоловки листья похожи на маленькие зелёные ракушки с ресничками по краям. Внутри каждой створки есть чувствительные волоски. Если комарик заденет один волосок, ничего не случится. Но если он заденет второй, ловушка быстро захлопывается. Так мухоловка не тратит силы зря: капля дождя или соринка не заставят её закрыться. Живёт она на воле только в одном месте — на юго-востоке Америки.", "q": "Что нужно, чтобы ловушка мухоловки захлопнулась?", "a": ["Два прикосновения к волоскам", "Громкий звук", "Яркий свет"]}, {"id": "pl-mimoza", "e": "🍃", "t": "Мимоза-недотрога", "s": "Тронь пальцем лист мимозы стыдливой, и он тут же сложится пополам, а маленькие листочки сомкнутся, как ладошки. Через несколько минут мимоза успокоится и снова всё расправит. Это происходит потому, что в основании листа вода быстро перетекает из одних клеточек в другие, и лист обмякает. Возможно, так мимоза пугает тех, кто хочет её съесть: был сочный листочек, а стал жалкий и увядший.", "q": "Что делает лист мимозы, когда его потрогать?", "a": ["Складывается", "Краснеет", "Подпрыгивает"]}, {"id": "pl-oduvanchik", "e": "🌼", "t": "Парашютики одуванчика", "s": "Жёлтый одуванчик отцветает и превращается в пушистый шар. У каждого семечка есть свой крошечный парашютик из тонких волосков. Дунул ветерок, и семена взлетают, плывут по воздуху и садятся далеко от мамы-цветка. Пушистый зонтик замедляет падение, и ветер успевает унести семечко на много метров, а иногда и на километры. Так одуванчики расселяются по лугам и дворам.", "q": "Что помогает семечку одуванчика улететь далеко?", "a": ["Пушистый парашютик", "Лёгкие крылышки как у бабочки", "Маленькие колёсики"]}, {"id": "pl-klyon", "e": "🍁", "t": "Вертолётики клёна", "s": "Осенью с клёна слетают не только листья. Вместе с ними падают парочки семян с длинным крылышком. Крылышко заставляет семечко кружиться, как лопасть вертолёта, поэтому оно падает медленно. Если подует ветер, оно успеет улететь подальше от родного дерева. Там, где никто не загораживает свет, из семечка вырастет новый клён. Ребята любят надевать такие семена на нос.", "q": "Как падает семя клёна с крылышком?", "a": ["Кружится, как вертолёт", "Летит прямо, как стрела", "Катится, как мячик"]}, {"id": "pl-kokos", "e": "🥥", "t": "Кокос-путешественник", "s": "Кокосовая пальма любит расти на берегу моря. Когда спелый кокос падает в воду, он не тонет: у него толстая волокнистая оболочка, а внутри воздух. Волны уносят орех, и он может плыть по морю много месяцев. Если его выбросит на берег далёкого острова, там может вырасти новая пальма. Так кокосовые пальмы разбрелись по островам тёплых морей.", "q": "Почему кокос не тонет в море?", "a": ["Оболочка волокнистая, а внутри воздух", "Он очень лёгкий, как пёрышко", "Он привязан к пальме"]}, {"id": "pl-banan", "e": "🍌", "t": "Банан — не дерево", "s": "Банановая пальма — вовсе не пальма и даже не дерево. Это гигантское травянистое растение, самое крупное в мире среди таких. Ствол у неё не деревянный. Он сделан из плотно свёрнутых оснований больших листьев, словно свитки, вложенные один в другой. Банановое растение может вытянуться выше двух человеческих ростов. А бананы растут связками, и каждая такая связка называется «рука».", "q": "Из чего сделан «ствол» банана?", "a": ["Из свёрнутых оснований листьев", "Из твёрдого дерева", "Из камня"]}, {"id": "pl-litopsy", "e": "🪨", "t": "Живые камни литопсы", "s": "В пустынях Африки лежат серые и коричневые камешки. Но некоторые из них — растения под названием литопсы, или живые камни. У каждого всего два толстых сочных листа, срощенных вместе, как пара щёчек. Они очень похожи на гальку, и голодные звери проходят мимо. А осенью из щели между листьями вдруг показывается цветок, белый или жёлтый, и камешек становится нарядным.", "q": "Зачем литопсам нужно быть похожими на камни?", "a": ["Чтобы их не съели звери", "Чтобы согреваться", "Чтобы их полюбили дети"]}, {"id": "pl-sosna", "e": "🌲", "t": "Сосна-долгожительница", "s": "В горах Калифорнии, где сухо и ветрено, растёт остистая сосна. Самой старой из них почти пять тысяч лет. Она уже росла, когда в Египте строили первые пирамиды. Сосна растёт очень медленно, и древесина у неё плотная и смолистая, поэтому её не одолевают ни жуки, ни гниль. Кажется, что она никуда не спешит, потому что впереди у неё много лет.", "q": "Сколько лет самой старой остистой сосне?", "a": ["Почти пять тысяч", "Около ста", "Около пятидесяти"]}, {"id": "pl-velvichiya", "e": "🏜️", "t": "Вельвичия с двумя листьями", "s": "В африканской пустыне Намиб растёт вельвичия. За всю свою долгую жизнь она отращивает всего два листа. Эти два листа не перестают расти, пока живёт растение. Они бывают длиной в несколько метров, а ветер разрывает их на ленты, поэтому кажется, что листьев много. Воду вельвичия получает из утреннего тумана, который оседает на листьях, а корни у неё уходят глубоко в землю. Живёт она сотни лет.", "q": "Сколько листьев растёт у вельвичии?", "a": ["Всего два", "Сто", "Десять"]}, {"id": "pl-ananas", "e": "🍍", "t": "Ананас растёт на земле", "s": "Многие думают, что ананасы растут на деревьях, но это не так. Ананас — невысокое растение с жёсткими колючими листьями, он растёт прямо у земли. Из центра выходит цветочный стебель, а на нём не один цветок, а много. Они срастаются в один большой плод. Поэтому на ананасе столько «глазков»: каждый из них раньше был отдельным цветком. А верхушку с зелёными листьями можно посадить, и вырастет новое растение.", "q": "Что нужно посадить в землю, чтобы вырос новый ананас?", "a": ["Верхушку с зелёными листьями", "Косточку из мякоти", "Нижнюю часть плода"]}, {"id": "pl-kakao", "e": "🍫", "t": "Какао растёт из ствола", "s": "Шоколад делают из семян какао. Дерево какао живёт в тёплых лесах, а его крупные плоды растут не на концах веток, а прямо на стволе и толстых ветвях. Такие плоды похожи на маленькие дыньки. Цветки у какао крошечные, и опыляют их мошки, которые прячутся в тени возле земли. Поэтому цветки и плоды появляются на стволе, поближе к этим помощникам.", "q": "Где на дереве какао растут плоды?", "a": ["Прямо на стволе", "На самых тонких веточках", "Под землёй, на корнях"]}, {"id": "pl-mokh", "e": "🌱", "t": "Мох-губка", "s": "Мох сфагнум растёт на болотах мягкими подушками. У него нет настоящих корней, и он пьёт воду всем телом. Сфагнум впитывает её, как губка, и может удержать воды до двадцати раз больше, чем весит сам. Поэтому в болоте под ногами так сыро. Давным-давно им даже перевязывали раны: в таком мохе не заводится плесень. Он помогает болоту хранить воду для рек и лесов.", "q": "На что похож мох сфагнум по своему свойству?", "a": ["На губку, которая впитывает воду", "На зонтик, который не пускает воду", "На лампу, которая светит"]}]) };
