// more cities and countries; each family picks the places it wants to learn about
const PLACE_DATA = /*__PLACES__*/[{"id":"msk","cc":"RU","n":"Москва","e":"⭐","items":[{"id":"msk-kuranty","e":"🕰️","t":"Главные часы страны","s":"На Спасской башне Кремля живут большие часы — куранты. Каждые пятнадцать минут они играют мелодию, а в начале каждого часа большой колокол отбивает время. В новогоднюю ночь вся страна слушает бой курантов, загадывает желания и встречает Новый год. А над часами сияет рубиновая звезда. Она светится днём и ночью и может поворачиваться на ветру, как флюгер.","q":"Когда вся страна слушает бой курантов?","a":["В новогоднюю ночь","Когда чихает слон","Только по вторникам в обед"]},{"id":"msk-vasily","e":"⛪","t":"Собор с разноцветными куполами","s":"На Красной площади стоит собор Василия Блаженного. Его купола похожи на огромные пёстрые луковки, и все они разные: у каждого свой узор и свои цвета. Собор построили больше четырёхсот лет назад, при царе Иване Грозном. А саму площадь назвали Красной вовсе не за цвет. В старину слово «красный» значило «красивый».","q":"Что в старину значило слово «красный»?","a":["Красивый","Холодный","Круглый, как блин"]},{"id":"msk-tsar","e":"🔔","t":"Два кремлёвских великана","s":"В Кремле стоят два великана. Царь-пушку отлил мастер Андрей Чохов в 1586 году, но на войне из неё ни разу не стреляли. Ядра рядом с ней положили гораздо позже, просто для красоты. А Царь-колокол — самый большой колокол на свете. Во время пожара от него откололся огромный кусок, поэтому он ни разу не звонил. Этот кусок и сейчас стоит рядом с колоколом.","q":"Почему Царь-колокол ни разу не звонил?","a":["От него откололся кусок","Он стесняется громко петь","В нём спит медведь"],"big":1},{"id":"msk-metro","e":"🚇","t":"Дворцы под землёй","s":"Московское метро открыли в 1935 году, и многие его станции похожи на дворцы: с люстрами, мрамором и мозаиками. На станции «Маяковская» поднимите голову — на потолке мозаичное небо с самолётами. А на станции «Площадь Революции» стоят бронзовые фигуры. Среди них есть пограничник с собакой. Нос у собаки блестит, потому что люди трут его на удачу.","q":"Почему у бронзовой собаки в метро блестит нос?","a":["Люди трут его на удачу","Его чистят зубной пастой","Собака сама его облизывает"]},{"id":"msk-bolshoi","e":"🩰","t":"Четыре коня над театром","s":"Большой театр — один из самых знаменитых театров мира. Над его колоннами мчится колесница, запряжённая четырьмя конями. Правит ею Аполлон — древний бог, покровитель искусств. На сцене Большого театра танцуют балет и поют оперу. Именно здесь в 1877 году впервые показали балет Петра Чайковского «Лебединое озеро».","q":"Сколько коней мчится над Большим театром?","a":["Четыре","Сто двадцать","Ни одного, там едет трактор"]},{"id":"msk-tretyakov","e":"🐻","t":"Медведи на знаменитой картине","s":"Купец Павел Третьяков всю жизнь собирал картины русских художников, а потом подарил их Москве. Так появилась Третьяковская галерея. Там висит картина Ивана Шишкина «Утро в сосновом лесу»: три медвежонка играют на поваленной сосне, а мама-медведица присматривает за ними. Шишкин замечательно рисовал лес, а медведей помог написать его друг, художник Константин Савицкий.","q":"Кто нарисовал медведей на картине Шишкина?","a":["Художник Константин Савицкий","Сами медведи лапами","Дед Мороз на каникулах"],"big":1},{"id":"msk-druzhba","e":"⛲","t":"Шестнадцать золотых девушек","s":"На Выставке достижений народного хозяйства стоит фонтан «Дружба народов». В середине возвышается огромный золотой сноп из колосьев и подсолнухов. Вокруг стоят шестнадцать золотых девушек, каждая в наряде своего народа и с дарами своего края в руках. Фонтан открыли в 1954 году. Когда он работает, вверх бьют сотни струй, и в брызгах иногда появляется радуга.","q":"Сколько золотых девушек стоит у фонтана?","a":["Шестнадцать","Одна, и та спит","Тысяча и ещё три"]},{"id":"msk-ostankino","e":"📡","t":"Башня до самых облаков","s":"Останкинская телебашня — самая высокая башня в Европе, её высота пятьсот сорок метров. С неё по воздуху передают телевизионные и радиопередачи. Скоростной лифт поднимает гостей на смотровую площадку меньше чем за минуту. Там есть стеклянный пол, и город видно прямо под ногами. А в пасмурный день верхушка башни прячется в облаках.","q":"Что есть на смотровой площадке башни?","a":["Стеклянный пол","Бассейн с крокодилами","Горка до самой земли"],"big":1},{"id":"msk-reka","e":"🚢","t":"Город, названный в честь реки","s":"Через Москву, петляя, течёт Москва-река. Город получил своё имя от реки, а не река от города. Летом по ней плывут речные трамвайчики, и с палубы видно стены Кремля. На берегу реки раскинулся Парк Горького. Зимой на его дорожках устраивают огромный каток, и по всему парку можно кататься на коньках.","q":"В честь чего назвали город Москву?","a":["В честь реки","В честь вкусного торта","В честь кошки по имени Мося"]},{"id":"msk-panda","e":"🐼","t":"Панды из Китая","s":"Московскому зоопарку больше ста шестидесяти лет. В 2019 году сюда из Китая приехали две большие панды — Жуи и Диндин. Почти весь день они жуют бамбук, а потом сладко отдыхают. А в 2023 году у них родилась дочка Катюша. Она стала первой большой пандой, которая родилась в России!","q":"Откуда приехали панды в Московский зоопарк?","a":["Из Китая","С Луны","Из соседнего подъезда"]}]},{"id":"lon","cc":"GB","n":"Лондон","e":"💂","items":[{"id":"lon-big-ben","e":"🔔","t":"Биг-Бен — это колокол","s":"Высокую башню с часами в Лондоне все называют Биг-Беном. Но на самом деле Биг-Бен — это имя огромного колокола внутри башни, он весит больше тринадцати тонн. А сама башня с 2012 года называется башней Елизаветы. Ход часов поправляют хитро: на маятник кладут старинные монетки. Одна лишняя монетка — и часы начинают идти чуть-чуть быстрее.","q":"Что такое Биг-Бен на самом деле?","a":["Огромный колокол","Имя королевской собаки","Большой бутерброд"],"big":1},{"id":"lon-ravens","e":"🐦","t":"Вороны Тауэра","s":"Тауэр — старинная крепость на берегу реки Темзы. В ней хранятся короны и драгоценности британских королей. А ещё в Тауэре живут вороны, и их всегда не меньше шести. По старой легенде, если вороны улетят, с королевством случится беда. За птицами ухаживает особый смотритель воронов, и у каждого ворона есть своё имя.","q":"Сколько воронов всегда живёт в Тауэре?","a":["Не меньше шести","Ровно один, самый важный","Миллион и ещё чуть-чуть"]},{"id":"lon-guard","e":"💂","t":"Солдаты в меховых шапках","s":"Букингемский дворец — главный дворец короля в Лондоне. Его охраняют солдаты в красных мундирах и высоких чёрных меховых шапках. Часовые стоят очень прямо и не отвлекаются, даже когда туристы их фотографируют. Время от времени караул сменяется: под музыку оркестра одни солдаты маршируют на смену другим. Посмотреть на это собираются толпы людей.","q":"Какие шапки носят солдаты у дворца?","a":["Высокие чёрные меховые","С помпоном и заячьими ушками","Кастрюли"]},{"id":"lon-bus","e":"🚌","t":"Красный автобус и чёрное такси","s":"По Лондону ездят красные двухэтажные автобусы. Лучше всего сесть наверху, в первом ряду: оттуда город видно, как с балкона. А ещё в Лондоне есть знаменитые чёрные такси — кэбы. Чтобы стать водителем кэба, нужно выучить наизусть тысячи улиц. На это уходят годы, а сам экзамен так и называется — «Знание».","q":"Что должен выучить водитель лондонского кэба?","a":["Тысячи улиц города","Все песни про такси","Как летать на зонтике"]},{"id":"lon-tube","e":"🚇","t":"Самое старое метро","s":"Лондонское метро — самое старое в мире, его открыли в 1863 году. Сначала поезда там тянули паровозы. Лондонцы зовут метро «Трубой», потому что многие тоннели круглые, как труба. А на станциях часто звучат слова: «Осторожно, зазор!» Это значит: смотри под ноги, между вагоном и платформой есть щель.","q":"Как лондонцы называют своё метро?","a":["«Труба»","«Кастрюля»","«Кроличья нора»"]},{"id":"lon-eye","e":"🎡","t":"Колесо без тринадцатой кабинки","s":"На берегу Темзы вращается огромное колесо обозрения — Лондонский глаз. У него тридцать две стеклянные кабинки, по одной на каждый район Лондона. Колесо крутится так медленно, что люди заходят в кабинку прямо на ходу, а один круг длится около получаса. Кабинки пронумерованы от одного до тридцати трёх: номер тринадцать пропустили, его многие считают несчастливым.","q":"Почему у колеса нет кабинки номер тринадцать?","a":["Многие считают это число несчастливым","Её унёс ветер на Луну","В ней поселился дракон"]},{"id":"lon-tower-bridge","e":"🌉","t":"Мост, который поднимает крылья","s":"Тауэрский мост открыли в 1894 году, у него две высокие каменные башни. Когда по Темзе плывёт высокий корабль, середина моста поднимается: две половинки встают вверх, как крылья. Наверху между башнями есть переходы со стеклянным полом, и сквозь него видно, как внизу едут машины. Многие путают его с Лондонским мостом, но это совсем другой мост.","q":"Что делает Тауэрский мост, когда плывёт высокий корабль?","a":["Поднимает половинки вверх","Перепрыгивает через корабль","Прячется под воду"]},{"id":"lon-museum","e":"🏛️","t":"Камень-подсказка","s":"В Британском музее хранятся сокровища со всего света, а вход туда бесплатный. Одна из главных находок — Розеттский камень. На нём высечен один и тот же текст тремя разными письменами, среди них египетские иероглифы и древнегреческие буквы. Греческий учёные умели читать, поэтому смогли сравнить надписи. Так люди научились понимать древние египетские иероглифы.","q":"Что помог прочитать Розеттский камень?","a":["Египетские иероглифы","Меню в кафе","Мысли кошки"],"big":1},{"id":"lon-sherlock","e":"🔍","t":"Сыщик с Бейкер-стрит","s":"Шерлок Холмс — знаменитый сыщик, которого придумал писатель Артур Конан Дойл. В книгах он жил в Лондоне на улице Бейкер-стрит, в доме двести двадцать один «Б». Сейчас там музей, где комнаты обставлены так, как описано в книгах. У станции метро «Бейкер-стрит» стоит памятник сыщику в шляпе с двумя козырьками. А люди со всего мира присылают Шерлоку письма, будто он настоящий!","q":"Кто придумал Шерлока Холмса?","a":["Писатель Артур Конан Дойл","Королевский повар","Лондонский голубь"]},{"id":"lon-greenwich","e":"🌍","t":"Одна нога на востоке, другая на западе","s":"В лондонском районе Гринвич, у старинной обсерватории, по земле проходит линия — нулевой меридиан. От неё учёные всего мира отсчитывают долготу. Можно встать так, чтобы одна нога была в восточном полушарии Земли, а другая — в западном. А на крыше обсерватории есть красный шар. Каждый день ровно в час дня он падает вниз, и раньше по нему моряки сверяли свои часы.","q":"Что падает с крыши обсерватории ровно в час дня?","a":["Красный шар","Яблоко для учёных","Снеговик в шляпе"],"big":1}]},{"id":"par","cc":"FR","n":"Париж","e":"🗼","items":[{"id":"par-eiffel","e":"🗼","t":"Железная дама","s":"Эйфелеву башню построили к Всемирной выставке 1889 года. Сначала многие парижане её ругали, а теперь это главный символ Парижа. Красят её вручную, кисточками, примерно раз в семь лет. По вечерам в начале каждого часа башня пять минут сверкает тысячами огоньков. А на самом верху у инженера Гюстава Эйфеля была маленькая квартира.","q":"Что делает башня по вечерам в начале каждого часа?","a":["Сверкает огоньками","Поёт песню","Подпрыгивает на месте"]},{"id":"par-louvre","e":"🖼️","t":"Улыбка Моны Лизы","s":"Лувр — огромный музей в старинном дворце, где когда-то жили французские короли. Главный вход в него — через большую стеклянную пирамиду. В Лувре висит картина Леонардо да Винчи «Мона Лиза». Многие удивляются, что она совсем небольшая. Картину берегут за толстым стеклом, а перед ней всегда толпятся люди, чтобы увидеть её загадочную улыбку.","q":"Чем знаменита Мона Лиза?","a":["Загадочной улыбкой","Зелёными усами","Тем, что умеет показывать язык"]},{"id":"par-notre-dame","e":"⛪","t":"Каменные чудища собора","s":"Собор Парижской Богоматери, или Нотр-Дам, стоит на острове посреди реки Сены. С его стен и башен на город смотрят каменные чудища с крыльями, рожками и забавными мордами. Некоторые из них — водостоки, их называют горгульями: в дождь вода льётся у них прямо изо рта. После пожара собор несколько лет чинили, а в 2024 году снова открыли.","q":"Что делают горгульи в дождь?","a":["Выливают воду изо рта","Раскрывают зонтики","Поют песни про лужи"]},{"id":"par-arc","e":"⭐","t":"Площадь-звезда","s":"Триумфальную арку приказал построить император Наполеон в 1806 году, в честь побед своей армии. Достроили её только через тридцать лет. Арка стоит посреди круглой площади, от которой, как лучи, расходятся двенадцать широких улиц. Поэтому площадь называют площадью Звезды. На крышу арки можно подняться по лестнице и увидеть эту звезду сверху.","q":"Почему площадь вокруг арки называют Звездой?","a":["От неё лучами расходятся улицы","На ней живёт морская звезда","Туда каждую ночь падают звёзды"],"big":1},{"id":"par-montmartre","e":"🎨","t":"Холм художников","s":"Монмартр — самый высокий холм Парижа. На его вершине стоит белоснежная базилика Сакре-Кёр. Её построили из особого камня, который от дождя становится только белее. Рядом есть маленькая площадь, где художники прямо на улице рисуют картины и портреты прохожих. Когда-то на Монмартре жили знаменитые художники, например Пабло Пикассо.","q":"Что делают художники на площади Монмартра?","a":["Рисуют портреты прохожих","Красят голубей в розовый","Пекут блины из красок"]},{"id":"par-seine","e":"📚","t":"Новый мост, который самый старый","s":"Через Сену в Париже перекинуто много мостов. Самый старый из них называется Новый мост. Его достроили больше четырёхсот лет назад: тогда он и правда был новым, а имя так и осталось. А вдоль реки на каменных оградах набережной стоят зелёные ящики. Днём их открывают, и получаются маленькие лавочки со старыми книгами, открытками и картинками.","q":"Как называется самый старый мост Парижа?","a":["Новый мост","Мост из печенья","Вчерашний мост"]},{"id":"par-baguette","e":"🥖","t":"Багет и круассан","s":"Багет — длинный хрустящий хлеб, без которого трудно представить Париж. Многие парижане покупают свежий багет каждый день. Каждый год в Париже выбирают пекаря, который печёт лучший багет, и целый год он возит свой хлеб во дворец президента. В 2022 году умение печь багеты признали частью культурного наследия всего человечества. А круассан назвали за форму: по-французски это слово значит «полумесяц».","q":"Куда целый год возит хлеб лучший пекарь Парижа?","a":["Во дворец президента","На Луну","В гнездо к воробьям"]},{"id":"par-versailles","e":"👑","t":"Дворец Короля-Солнца","s":"Недалеко от Парижа стоит Версаль — огромный дворец французских королей. Таким пышным его сделал король Людовик Четырнадцатый, которого называли Королём-Солнцем. В юности он танцевал в балете роль Солнца в золотом костюме. Во дворце есть Зеркальная галерея, где сотни зеркал смотрят на высокие окна. А в саду бьют фонтаны, которые иногда танцуют под музыку.","q":"Как называли короля Людовика Четырнадцатого?","a":["Король-Солнце","Король-Пельмень","Король-Тапочка"],"big":1},{"id":"par-metro","e":"🌿","t":"Метро с железными цветами","s":"Парижское метро открыли в 1900 году. Входы на старые станции придумал архитектор Эктор Гимар. Они сделаны из зелёного чугуна и похожи на сказочные растения: изогнутые стебли, а наверху фонари, как бутоны цветов. Над входом написано «Метрополитен». Многие такие входы сохранились до сих пор, и по ним сразу узнают Париж.","q":"На что похожи старинные входы в парижское метро?","a":["На сказочные растения","На пасть крокодила","На огромные ботинки"]},{"id":"par-luxembourg","e":"⛵","t":"Кораблики в саду","s":"В Люксембургском саду в Париже есть большой пруд с фонтаном. Там можно взять напрокат деревянный кораблик с парусом. Дети толкают его длинной палочкой, и ветер гонит кораблик через пруд. Когда он приплывает к другому краю, надо бежать вокруг пруда и снова его подтолкнуть. Так в этом саду играют уже почти сто лет.","q":"Чем дети толкают кораблики в пруду?","a":["Длинной палочкой","Ложкой для супа","Хвостом кошки"]}]},{"id":"rom","cc":"IT","n":"Рим и Италия","e":"🇮🇹","items":[{"id":"rom-colosseum","e":"🏟️","t":"Колизей — каменная чаша","s":"Колизей построили в Риме почти две тысячи лет назад. Это огромный овальный театр под открытым небом, похожий на каменную чашу. Здесь собирались десятки тысяч зрителей, чтобы смотреть на бои гладиаторов. В жаркие дни над рядами натягивали большой навес, как парус. Пол посыпали песком, и само слово «арена» по-латыни значит «песок».","q":"Что значит слово «арена»?","a":["Песок","Мороженое","Громкий чих"]},{"id":"rom-trevi","e":"🪙","t":"Монетка в фонтане Треви","s":"Фонтан Треви — самый знаменитый фонтан Рима. Посередине стоит каменный бог Океан, а его колесницу-раковину тянут морские кони. Есть обычай: встать к фонтану спиной и бросить монетку через плечо. Говорят, тогда ты обязательно вернёшься в Рим. Монетки потом собирают и отдают на помощь людям, которым живётся трудно.","q":"Зачем бросают монетку в фонтан Треви?","a":["Чтобы вернуться в Рим","Чтобы накормить рыбок","Чтобы вода стала сладкой"]},{"id":"rom-pantheon","e":"☀️","t":"Дыра в куполе Пантеона","s":"Пантеону почти две тысячи лет, а его огромный купол до сих пор цел. На самой макушке купола есть круглое окно без стекла. Его называют «оком», то есть глазом. Через него внутрь падает солнечный луч, а в дождь — капли. Чтобы не было луж, в полу сделали маленькие дырочки для воды. А раз в год, в церковный праздник, через око сверху сыплют лепестки роз.","q":"Что падает через око Пантеона в дождь?","a":["Дождевые капли","Конфеты","Маленькие лягушки"]},{"id":"rom-wolf","e":"🐺","t":"Волчица и близнецы","s":"По древней легенде, Рим основали братья-близнецы Ромул и Рем. Когда они были совсем малышами, их корзинку унесла река Тибр. Корзинка застряла у берега, и малышей нашла волчица. Она не обидела их, а накормила своим молоком, как волчат. Потом мальчиков забрал и вырастил пастух. Город назвали Римом по имени Ромула, а волчица стала его символом.","q":"Кто накормил малышей Ромула и Рема?","a":["Волчица","Голодный крокодил","Почтальон"]},{"id":"rom-vatican","e":"🎨","t":"Страна внутри города","s":"Прямо внутри Рима есть целая страна — Ватикан, самая маленькая страна в мире. Там живёт Папа Римский. Потолок Сикстинской капеллы в Ватикане расписал художник Микеланджело. Он работал около четырёх лет, стоя на высоких лесах и запрокинув голову. Когда выбирают нового Папу, над капеллой из трубы идёт дым: белый дым значит, что Папу выбрали.","q":"Что значит белый дым над капеллой?","a":["Нового Папу выбрали","Сгорела каша","Пора ложиться спать"],"big":1},{"id":"rom-pisa","e":"🔔","t":"Башня, которая наклонилась","s":"В городе Пиза стоит белая башня, которая наклонилась набок. Это колокольня, наверху у неё висят колокола. Башню начали строить больше восьмисот лет назад, и она накренилась, когда построили всего несколько этажей: земля под ней оказалась мягкой. Инженеры укрепили землю и чуть-чуть выпрямили башню, чтобы она не упала. А туристы любят фотографироваться так, будто держат её рукой.","q":"Почему Пизанская башня наклонилась?","a":["Земля под ней мягкая","Она устала стоять","Её толкнул слон"]},{"id":"rom-venice","e":"🛶","t":"Город, где вместо улиц каналы","s":"Венеция построена на воде, на ста с лишним маленьких островах. Вместо многих улиц здесь каналы, а вместо машин — лодки. Самые известные лодки — чёрные гондолы. Гондольер стоит на корме и гребёт одним длинным веслом. Хитрость в том, что гондола немного кривая: один бок у неё длиннее другого. Поэтому она плывёт прямо, хотя весло только с одной стороны.","q":"Сколько вёсел у гондольера?","a":["Одно длинное весло","Сто маленьких вёсел","Ни одного, он дует в парус"]},{"id":"rom-pizza","e":"🍕","t":"Пицца Маргарита","s":"Родина пиццы — итальянский город Неаполь. Там её пекут в очень горячей печи на дровах, и пицца готова меньше чем за две минуты. Рассказывают, что одну пиццу назвали в честь королевы Маргариты. На ней красные помидоры, белый сыр моцарелла и зелёные листики базилика. Это цвета итальянского флага: зелёный, белый и красный.","q":"Какие цвета у пиццы Маргарита?","a":["Красный, белый и зелёный","Синий и фиолетовый","Полосатый, как зебра"]},{"id":"rom-pompeii","e":"🌋","t":"Город под пеплом","s":"Рядом с Неаполем стоит вулкан Везувий. В 79 году он проснулся и засыпал соседний город Помпеи толстым слоем пепла. Город пролежал под землёй больше полутора тысяч лет, пока его не нашли и не начали раскапывать. Теперь по Помпеям можно гулять. Там видны каменные мостовые, пекарни с печами и даже мозаика у входа в дом с надписью «Осторожно, собака».","q":"Что написано на мозаике у входа в дом?","a":["Осторожно, собака","Здесь живёт дракон","Мойте лапы"],"big":1},{"id":"rom-gelato","e":"🍨","t":"Мороженое джелато","s":"Итальянское мороженое называют джелато. В него взбивают меньше воздуха, чем в обычное мороженое, поэтому оно плотное и очень нежное. В итальянских кафе его часто накладывают не шариком, а плоской лопаточкой. Вкусов бывает очень много: фисташковое, лимонное, клубничное. А ещё есть страчателла — молочное мороженое с кусочками шоколада.","q":"Чем накладывают джелато в Италии?","a":["Плоской лопаточкой","Лопатой для снега","Прямо из шланга"]}]},{"id":"esp","cc":"ES","n":"Испания","e":"🇪🇸","items":[{"id":"esp-sagrada","e":"⛪","t":"Храм, который строят до сих пор","s":"В Барселоне стоит храм Саграда Фамилия. Его придумал архитектор Антонио Гауди и работал над ним больше сорока лет. Строить храм начали больше ста сорока лет назад, а он всё ещё не закончен! Колонны внутри похожи на стволы деревьев, а через цветные стёкла льётся радужный свет. В 2026 году самая высокая башня выросла до полной высоты, но стройка продолжается.","q":"На что похожи колонны внутри храма?","a":["На стволы деревьев","На огромные макароны","На ноги жирафа"],"big":1},{"id":"esp-guell","e":"🦎","t":"Мозаичная ящерица","s":"Парк Гуэль в Барселоне тоже придумал архитектор Гауди. На лестнице у входа сидит большая разноцветная ящерица, многие зовут её драконом. Она покрыта мозаикой из кусочков битой плитки. Такая же мозаика украшает длинную скамейку, которая извивается, как змея. А домики у входа похожи на пряничные, с крышами, будто политыми глазурью.","q":"Из чего сделана мозаика на ящерице?","a":["Из кусочков битой плитки","Из леденцов","Из старых носков"]},{"id":"esp-alhambra","e":"🏰","t":"Красная крепость Альгамбра","s":"В городе Гранада на холме стоит Альгамбра — дворец и крепость. Её построили мусульманские правители, которые жили в Испании много веков назад. Название значит «красная»: стены крепости красноватого цвета. Внутри стены покрыты резьбой, тонкой, как кружево. А в одном дворике стоит фонтан, чашу которого держат на спинах двенадцать каменных львов.","q":"Сколько львов держат фонтан?","a":["Двенадцать","Один, но очень сильный","Сто котят"],"big":1},{"id":"esp-prado","e":"🖼️","t":"Художник внутри картины","s":"Мадрид — столица Испании. Здесь есть один из самых известных музеев мира — Прадо. В нём висит картина Диего Веласкеса «Менины». В центре стоит маленькая принцесса Маргарита в пышном платье, вокруг неё служанки, а впереди лежит большая собака. А слева у огромного холста с кистью в руке стоит сам художник: он нарисовал на картине себя!","q":"Кого ещё нарисовал Веласкес на картине «Менины»?","a":["Самого себя","Космонавта","Летающую корову"],"big":1},{"id":"esp-flamenco","e":"💃","t":"Танец фламенко","s":"Фламенко родилось на юге Испании, в Андалусии. Это песня, гитара и танец вместе. Танцовщица гордо держит спину, кружится в пышном платье и громко отбивает ритм каблуками: тук-тук-тук! Остальные помогают ей, звонко хлопая в ладоши. Иногда танцоры щёлкают кастаньетами — деревянными ракушками, которые держат в руках.","q":"Чем танцовщица фламенко отбивает ритм?","a":["Каблуками","Половником","Ушами"]},{"id":"esp-paella","e":"🥘","t":"Паэлья на большой сковороде","s":"Паэлья родом из испанского города Валенсия. Это рис, который готовят в широкой плоской сковороде, и сама сковорода тоже называется «паэлья». Жёлтым рис делает пряность шафран. В паэлью кладут курицу, овощи или морских жителей, например креветок. А снизу рис чуть поджаривается и хрустит, и многие считают эту корочку самой вкусной.","q":"Что делает рис в паэлье жёлтым?","a":["Шафран","Солнечный зайчик","Краска для забора"]},{"id":"esp-quixote","e":"🐴","t":"Рыцарь и ветряные мельницы","s":"Писатель Мигель де Сервантес придумал Дон Кихота — смешного и доброго рыцаря на худом коне Росинанте. Дон Кихот начитался книг о подвигах и решил сам защищать слабых. Однажды он увидел ветряные мельницы и подумал, что это великаны машут руками. И бросился на них с копьём! Такие белые мельницы до сих пор стоят на холмах Ла-Манчи.","q":"Кого Дон Кихот увидел вместо мельниц?","a":["Великанов","Гигантских кроликов","Свою бабушку"]},{"id":"esp-teide","e":"🌋","t":"Вулкан Тейде и канарейки","s":"Канарские острова лежат в Атлантическом океане, недалеко от Африки. На острове Тенерифе стоит вулкан Тейде — самая высокая гора Испании. Зимой его вершину иногда покрывает снег, а внизу у моря в это время тепло. Почти до самой вершины можно подняться на канатной дороге. А певчую птичку канарейку назвали в честь этих островов, где она живёт на воле.","q":"В честь чего назвали птичку канарейку?","a":["В честь Канарских островов","В честь знаменитого повара","В честь дырявого носка"]},{"id":"esp-tomatina","e":"🍅","t":"Томатная битва","s":"В маленьком испанском городке Буньоль каждый год в последнюю среду августа устраивают праздник Томатина. Тысячи людей бросаются друг в друга спелыми помидорами! По правилам помидор надо раздавить в руке, прежде чем бросить, чтобы никому не было больно. Скоро вся улица становится красной, как томатный суп. А потом улицы отмывают из пожарных шлангов.","q":"Что надо сделать с помидором перед броском?","a":["Раздавить в руке","Покрасить в синий цвет","Спеть ему песенку"]},{"id":"esp-castells","e":"🤸","t":"Живые башни","s":"В Каталонии люди строят башни не из камня, а из самих себя. Такие живые башни называют кастельс. Внизу много людей встают плотной толпой и держат тех, кто стоит у них на плечах. Ярус за ярусом башня растёт вверх. На самую вершину забирается ребёнок в защитном шлеме и поднимает руку: башня готова!","q":"Кто забирается на самый верх живой башни?","a":["Ребёнок в шлеме","Корова в шляпе","Самый тяжёлый дедушка"]}]},{"id":"ger","cc":"DE","n":"Германия","e":"🇩🇪","items":[{"id":"ger-brandenburg","e":"🐎","t":"Кони на Бранденбургских воротах","s":"Бранденбургские ворота — главный символ Берлина. Наверху стоит колесница, которую везут четыре коня, а правит ими богиня победы. Когда-то французский император Наполеон захватил Берлин и увёз эту колесницу в Париж. Но через несколько лет её привезли обратно. С тех пор кони снова смотрят на город с высоты ворот.","q":"Сколько коней везут колесницу на воротах?","a":["Четыре","Сорок","Ни одного, там велосипед"]},{"id":"ger-wall","e":"🧱","t":"Стена, которая упала","s":"Когда-то Берлин разделила длинная стена. Люди с разных сторон не могли свободно ходить друг к другу в гости, даже родственники. Так было почти тридцать лет. А девятого ноября 1989 года границу открыли. Люди забирались на стену, обнимались, плакали от радости и отбивали кусочки стены на память. Теперь там, где стояла стена, по улицам тянется дорожка из камней.","q":"Что делали люди, когда стену открыли?","a":["Обнимались и радовались","Ложились спать","Строили стену ещё выше"],"big":1},{"id":"ger-neuschwanstein","e":"🏰","t":"Замок лебединого короля","s":"На скале среди гор Баварии стоит белый замок Нойшванштайн, словно из сказки. Его велел построить король Людвиг Второй, который мечтал о рыцарях и легендах. Название замка значит «Новый лебединый камень». Король очень любил лебедей, поэтому они в замке повсюду: на картинах и в украшениях. Даже вода в умывальнике короля текла из серебристого крана в виде лебедя.","q":"Какую птицу очень любил король Людвиг?","a":["Лебедя","Пингвина","Курицу-несушку"]},{"id":"ger-grimm","e":"📖","t":"Братья, которые собирали сказки","s":"Братья Якоб и Вильгельм Гримм выпустили свою первую книгу сказок больше двухсот лет назад. Сказки они собирали у разных людей и бережно записывали. Так в их книгах оказались «Белоснежка», «Гензель и Гретель», «Красная Шапочка» и «Бременские музыканты». А в городе Бремене стоит памятник музыкантам: на осле собака, на собаке кошка, а сверху петух.","q":"Кто стоит на самом верху памятника в Бремене?","a":["Петух","Слон","Сам король"]},{"id":"ger-xmas","e":"🎄","t":"Рождественская ярмарка","s":"Перед Рождеством на площадях немецких городов открываются ярмарки. В деревянных домиках горят огоньки, пахнет жареным миндалём и пряниками. Пряники продают в форме сердечек с надписями из глазури. А ещё там есть деревянные пирамидки с пропеллером наверху: их крутит тёплый воздух от горящих свечей. И обычай наряжать ёлку на Рождество тоже пришёл из Германии.","q":"Что крутит рождественскую пирамидку?","a":["Тёплый воздух от свечей","Хомячок в колесе","Громкий чих"]},{"id":"ger-cologne","e":"⛪","t":"Собор, который строили шестьсот лет","s":"Кёльнский собор начали строить в 1248 году. Потом стройка надолго остановилась, а закончили собор только в 1880 году, больше чем через шестьсот лет! Сотни лет на недостроенной башне стоял старый подъёмный кран, и он стал символом города. Две острые башни собора видно издалека. А цветные окна-витражи внутри светятся, как огромные картинки из стекла.","q":"Что сотни лет стояло на недостроенной башне?","a":["Старый подъёмный кран","Гигантский торт","Сторож на ходулях"],"big":1},{"id":"ger-cuckoo","e":"🐦","t":"Часы с кукушкой","s":"На юго-западе Германии есть горы, покрытые густым еловым лесом. Их называют Шварцвальд, что значит «Чёрный лес». Здесь уже больше двухсот лет мастерят часы с кукушкой. Каждый час открывается дверца, выглядывает деревянная птичка и кричит: «Ку-ку!» Голос ей дают две маленькие дудочки с мехами. А гири у таких часов часто сделаны в виде еловых шишек.","q":"На что похожи гири у часов с кукушкой?","a":["На еловые шишки","На сосиски","На резиновых уточек"]},{"id":"ger-autobahn","e":"🚗","t":"Дороги, где можно ехать быстро","s":"Большие скоростные дороги в Германии называются автобанами. На многих участках стоят знаки, которые говорят, как быстро можно ехать. Но есть и такие участки, где ограничения скорости нет совсем! В мире это большая редкость. Правда, водителям всё равно советуют ехать не быстрее ста тридцати километров в час. А обгонять на автобане можно только слева.","q":"С какой скоростью советуют ехать на автобане?","a":["Не быстрее ста тридцати километров в час","Со скоростью улитки","Быстрее ракеты"]},{"id":"ger-bach-beethoven","e":"🎼","t":"Бах и Бетховен","s":"Два великих композитора родились в Германии. Иоганн Себастьян Бах родился в 1685 году в городе Эйзенахе и прекрасно играл на органе. Людвиг ван Бетховен родился в 1770 году в городе Бонне. Когда Бетховен вырос, он стал плохо слышать, а потом почти совсем оглох. Но он продолжал сочинять музыку! Его мелодия «Ода к радости» стала гимном Европы.","q":"Какая мелодия Бетховена стала гимном Европы?","a":["«Ода к радости»","«Песенка про пельмени»","«Марш храпящих котов»"],"big":1},{"id":"ger-pretzel","e":"🥨","t":"Крендель-брецель","s":"Брецель — это немецкий крендель, завязанный узлом. Перед выпечкой его ненадолго окунают в особый раствор, поэтому корочка становится тёмно-коричневой и блестящей. Сверху брецель посыпают крупной солью. Говорят, что его форма похожа на руки, сложенные на груди. А над дверями многих пекарен в Германии висит вывеска в виде брецеля.","q":"Чем посыпают брецель?","a":["Крупной солью","Цветными мелками","Конфетти"]}]},{"id":"nyc","cc":"US","n":"Нью-Йорк и США","e":"🗽","items":[{"id":"nyc-liberty","e":"🗽","t":"Зелёная дама с факелом","s":"Статуя Свободы — подарок Франции американцам. Её привезли в Нью-Йорк по морю в разобранном виде, в ящиках, и собрали на острове. Сначала статуя была рыжей и блестящей, как новая монетка, ведь она сделана из меди. Но от дождя и морского ветра медь со временем позеленела. В поднятой руке у неё факел, а на короне семь лучей.","q":"Почему Статуя Свободы стала зелёной?","a":["Медь позеленела от дождя и ветра","Её покрасили зелёнкой","Она объелась огурцов"]},{"id":"nyc-empire-state","e":"🏢","t":"Небоскрёб в сто два этажа","s":"Эмпайр-стейт-билдинг — знаменитый небоскрёб Нью-Йорка. В нём сто два этажа, а построили его в 1931 году. Почти сорок лет он был самым высоким зданием в мире. На восемьдесят шестом этаже есть открытая площадка: оттуда машины внизу кажутся игрушечными. По вечерам верхушку небоскрёба подсвечивают разными цветами, например к праздникам.","q":"Сколько этажей в Эмпайр-стейт-билдинг?","a":["Сто два","Три с половиной","Миллион и ещё один"],"big":1},{"id":"nyc-central-park","e":"🌳","t":"Центральный парк","s":"Посреди Нью-Йорка, среди высоких домов, раскинулся огромный Центральный парк. Он больше, чем целая страна Монако! В парке есть озеро с лодками, зоопарк и карусель, а зимой заливают каток. Повсюду скачут шустрые белки. А ещё там стоит бронзовая Алиса из Страны чудес, и дети забираются к ней на гигантский гриб.","q":"На чём сидит бронзовая Алиса в парке?","a":["На огромном грибе","На жёлтом такси","На спине у белки"]},{"id":"nyc-brooklyn-bridge","e":"🌉","t":"Бруклинский мост и слоны","s":"Бруклинский мост соединяет две части Нью-Йорка — Манхэттен и Бруклин. Его открыли в 1883 году, и держится он на двух каменных башнях и толстых стальных тросах. Сначала многие боялись, что он не выдержит. Тогда хозяин цирка провёл по мосту двадцать одного слона! Мост выдержал, и все успокоились. А пешеходы гуляют по дорожке, которая проходит над машинами.","q":"Кто прошёл по мосту, чтобы показать, что он крепкий?","a":["Двадцать один слон","Один маленький муравей","Пингвины на роликах"]},{"id":"nyc-yellow-taxi","e":"🚕","t":"Жёлтые такси","s":"По улицам Нью-Йорка ездят тысячи жёлтых такси. Яркий жёлтый цвет видно издалека, и такси сразу узнаешь среди других машин. Чтобы поймать такси, нужно встать у края тротуара и поднять руку. На крыше у машины есть табличка с огоньком. Если огонёк горит, значит, такси свободно и можно садиться.","q":"Что значит горящий огонёк на крыше такси?","a":["Такси свободно","Внутри едет фонарик","Водитель пьёт чай"]},{"id":"nyc-dinosaurs","e":"🦖","t":"Динозавры и кит в музее","s":"В Нью-Йорке есть Музей естественной истории. Там стоят огромные скелеты динозавров, и среди них тираннозавр. Один динозавр, титанозавр, такой длинный, что не поместился в зал целиком: его голова выглядывает в коридор! А в другом зале под потолком висит модель синего кита в настоящую величину. Этот кит длиннее двух автобусов.","q":"Что выглядывает из зала в коридор?","a":["Голова титанозавра","Хвост жёлтого такси","Уши кролика"]},{"id":"nyc-grand-canyon","e":"🏜️","t":"Гранд-Каньон","s":"Гранд-Каньон — огромное ущелье в штате Аризона. Его прорыла река Колорадо, и работала она миллионы лет. Местами каньон глубже полутора километров, и река на дне сверху кажется тонкой ниточкой. Стены каньона полосатые, как слоёный торт: каждый слой камня появился в своё время. На закате скалы становятся красными, оранжевыми и розовыми.","q":"Кто прорыл Гранд-Каньон?","a":["Река Колорадо","Гигантский крот","Ковбои лопатами"]},{"id":"nyc-yellowstone","e":"♨️","t":"Гейзеры Йеллоустоуна","s":"Йеллоустоун стал первым национальным парком в мире в 1872 году. Под землёй там очень горячо, и из земли бьют гейзеры — фонтаны горячей воды и пара. Самый знаменитый гейзер зовут Старым служакой: он извергается так регулярно, что смотрители заранее говорят, когда ждать фонтан. Рядом есть горячие источники всех цветов радуги, их раскрашивают крошечные микробы. А по дорогам неспешно бродят бизоны.","q":"Что такое гейзер?","a":["Фонтан горячей воды из-под земли","Сердитый бизон","Мороженое с паром"],"big":1},{"id":"nyc-rushmore","e":"🗿","t":"Гора с лицами президентов","s":"В штате Южная Дакота есть гора Рашмор. Прямо в скале высекли лица четырёх американских президентов: Джорджа Вашингтона, Томаса Джефферсона, Теодора Рузвельта и Авраама Линкольна. Каждое лицо высотой примерно с шестиэтажный дом. Работа шла четырнадцать лет, с 1927 по 1941 год. Лишний камень снимали взрывами, а потом мастера осторожно доделывали каждое лицо.","q":"Сколько лиц высечено на горе Рашмор?","a":["Четыре","Сорок четыре","Ни одного, там спит медведь"],"big":1},{"id":"nyc-thanksgiving","e":"🦃","t":"День благодарения","s":"В четвёртый четверг ноября в Америке празднуют День благодарения. Семьи собираются за большим столом и говорят, за что они благодарны. Главное блюдо — запечённая индейка, к ней подают клюквенный соус, а на сладкое — тыквенный пирог. Утром в Нью-Йорке проходит парад: над улицами плывут огромные надувные шары в виде сказочных героев. Каждый шар держат на верёвках много людей.","q":"Какое главное блюдо на День благодарения?","a":["Запечённая индейка","Мороженое с селёдкой","Жареные кеды"]}]},{"id":"can","cc":"CA","n":"Торонто и Канада","e":"🍁","items":[{"id":"can-niagara","e":"💦","t":"Ниагарский водопад","s":"Ниагарский водопад находится на границе Канады и Америки. На самом деле это три водопада, а самый большой из них похож на подкову. Вода падает с таким грохотом, что над ней поднимается облако брызг, и в нём часто видна радуга. К водопаду подплывают кораблики, и всем пассажирам дают дождевики. А по вечерам водопад подсвечивают разноцветными огнями.","q":"Что дают пассажирам на кораблике у водопада?","a":["Дождевики","Шубы и валенки","Удочки для ловли китов"]},{"id":"can-cn-tower","e":"🗼","t":"Башня со стеклянным полом","s":"В Торонто стоит Си-Эн Тауэр — башня высотой пятьсот пятьдесят три метра. Много лет она была самой высокой башней в мире. Быстрый лифт поднимает гостей наверх меньше чем за минуту. А на высоте трёхсот сорока двух метров есть стеклянный пол. Встаёшь на него — и видишь далеко внизу улицы и крошечные машины!","q":"Что необычного есть на башне в Торонто?","a":["Стеклянный пол высоко над землёй","Лифт, который тянет лошадь","Батут на самой макушке"]},{"id":"can-maple","e":"🍁","t":"Кленовый лист и кленовый сироп","s":"На флаге Канады нарисован красный кленовый лист. А из сока клёна делают сладкий кленовый сироп. Ранней весной в стволы вставляют трубочки и по капле собирают сок. Потом его долго варят, и примерно из сорока литров сока получается всего один литр сиропа. А ещё горячий сироп льют прямо на чистый снег, он застывает, и его накручивают на палочку, как ириску.","q":"Что нарисовано на флаге Канады?","a":["Красный кленовый лист","Зелёный огурец","Синий пингвин"]},{"id":"can-beaver","e":"🦫","t":"Бобр — символ Канады","s":"Бобр — один из символов Канады, его даже изображают на монетке в пять центов. Бобры строят на реках плотины из веток, брёвен и ила. Деревья они грызут сами, ведь зубы у них очень крепкие и оранжевые. Эти зубы растут всю жизнь, поэтому, сколько бы бобр ни грыз, они не кончаются. А ещё в канадских лесах живёт лось — самый большой олень на свете, у самцов рога широкие, как лопаты.","q":"Какого цвета зубы у бобра?","a":["Оранжевые","Фиолетовые в горошек","Прозрачные, как стекло"]},{"id":"can-hockey","e":"🏒","t":"Хоккей","s":"Хоккей — любимая зимняя игра Канады, по закону это национальный зимний вид спорта. Зимой многие семьи заливают каток прямо во дворе, а дети гоняют шайбу на замёрзших прудах. Шайба — это плоский резиновый кружок, и по льду она летит очень быстро. Одна из первых хоккейных игр в крытом зале прошла в канадском городе Монреале.","q":"Чем играют в хоккей на льду?","a":["Клюшкой и шайбой","Ложкой и арбузом","Зонтиком и подушкой"]},{"id":"can-lake-louise","e":"🏔️","t":"Бирюзовое озеро Луиза","s":"Высоко в Скалистых горах лежит озеро Луиза. Вода в нём удивительного бирюзового цвета. Такой цвет ей дают ледники: они перетирают камни в тончайшую каменную пыль, а ручьи приносят её в озеро. Эта пыль висит в воде и по-особому отражает солнечный свет. Зимой озеро замерзает, и люди катаются по нему на коньках прямо среди гор.","q":"Что делает воду в озере Луиза бирюзовой?","a":["Каменная пыль от ледников","Краска из гигантских фломастеров","Голубые рыбки, которые линяют"],"big":1},{"id":"can-mounties","e":"🐴","t":"Конная полиция в красных мундирах","s":"В Канаде есть знаменитая конная полиция. На праздники полицейские надевают ярко-красные мундиры, шляпы с широкими полями и высокие сапоги. Сегодня они ездят на машинах, но лошадей не забыли. Всадники показывают конное представление под музыку: лошади выстраиваются в красивые фигуры. Все кони там вороные, то есть чёрные, чтобы красные мундиры смотрелись ярче.","q":"Какого цвета кони у конной полиции на представлениях?","a":["Чёрные","В розовую клеточку","Прозрачные"]},{"id":"can-two-languages","e":"🗣️","t":"Два языка Канады","s":"В Канаде два официальных языка: английский и французский. Поэтому надписи на коробках с хлопьями и на пакетах молока делают сразу на двух языках. В провинции Квебек большинство людей говорят по-французски. Там здороваются словом «бонжур», а в Торонто чаще говорят «хеллоу». Многие канадские дети учат в школе оба языка.","q":"Какие два языка официальные в Канаде?","a":["Английский и французский","Кошачий и собачий","Китовый и бобровый"],"big":1},{"id":"can-northern-lights","e":"🌌","t":"Северное сияние","s":"На севере Канады зимними ночами небо иногда начинает светиться. По нему плывут и колышутся зелёные ленты, порой с розовыми и фиолетовыми краями. Это северное сияние. Оно появляется, когда крошечные частицы от Солнца долетают до Земли и заставляют воздух высоко в небе светиться. Лучше всего сияние видно в ясную тёмную ночь, вдали от городских огней.","q":"Что заставляет небо светиться при северном сиянии?","a":["Частицы от Солнца","Гигантский фонарик лося","Светлячки в шапках"],"big":1},{"id":"can-polar-bears","e":"🐻‍❄️","t":"Белые медведи Черчилля","s":"Городок Черчилль на берегу Гудзонова залива называют столицей белых медведей. Каждую осень медведи приходят сюда и ждут, когда море замёрзнет, чтобы уйти по льду ловить тюленей. Туристы смотрят на них из окон больших вездеходов на огромных колёсах. А знаешь, что кожа у белого медведя чёрная? И шерсть у него не белая, а прозрачная, просто на свету она кажется белой.","q":"Какого цвета кожа у белого медведя?","a":["Чёрная","В зелёную полоску","Белая с блёстками"]}]},{"id":"cyp","cc":"CY","n":"Кипр","e":"🏝️","items":[{"id":"cyp-aphrodite","e":"🐚","t":"Камень Афродиты","s":"Древние греки рассказывали, что богиня любви и красоты Афродита родилась из морской пены у берегов Кипра. Место, где она вышла на берег, показывают до сих пор: это большая скала в море недалеко от Пафоса. Её называют Камнем Афродиты. Волны разбиваются там о камни и превращаются в белую пену. Есть поверье, что если проплыть вокруг скалы, станешь красивее.","q":"Из чего, по легенде, родилась Афродита?","a":["Из морской пены","Из сахарной ваты","Из старого ботинка"]},{"id":"cyp-turtles","e":"🐢","t":"Черепахи на пляже","s":"Летом по ночам на тихие пляжи Кипра выходят морские черепахи каретта. Черепаха-мама ластами роет в песке ямку и откладывает туда яйца, похожие на мячики для пинг-понга. Примерно через два месяца из песка выбираются крошечные черепашата и бегут к морю. Дорогу им подсказывает светлое море под луной, поэтому на таких пляжах ночью не включают яркие фонари.","q":"Куда бегут черепашата, когда вылупятся?","a":["К морю","В ближайшее кафе","На вершину горы"]},{"id":"cyp-copper","e":"⛏️","t":"Остров меди","s":"В древности Кипр славился медью. Её добывали на острове несколько тысяч лет назад и увозили на кораблях в другие страны. Медь отсюда была так знаменита, что римляне называли её «кипрским металлом». От этого и произошло латинское название меди — «купрум». В таблице химических элементов значок меди и сегодня читают «купрум».","q":"Как по-латыни называется медь?","a":["Купрум","Кукареку","Макарони"],"big":1},{"id":"cyp-mosaics","e":"🖼️","t":"Картины из камешков в Пафосе","s":"В 1962 году крестьянин в Пафосе пахал поле и вдруг наткнулся на древние развалины. Так нашли римский дом, полы которого выложены мозаикой — картинами из тысяч крошечных цветных камешков. Этим мозаикам около тысячи восьмисот лет! На них можно разглядеть древних богов и героев, зверей, птиц и охотников. Дом назвали Домом Диониса, и сегодня его может увидеть каждый.","q":"Из чего сделаны картины-мозаики?","a":["Из крошечных цветных камешков","Из пластилина и конфет","Из старых носков"]},{"id":"cyp-kolossi","e":"🏰","t":"Рыцарский замок Колосси","s":"Недалеко от Лимассола стоит замок Колосси — высокая квадратная башня с толстыми стенами. Её построили рыцари в 1454 году. Вход сделан не внизу, а на втором этаже, и раньше попасть туда можно было только по подъёмному мосту. Внутри узкая винтовая лестница ведёт на самую крышу. А рядом с замком сохранились остатки старой мастерской, где рыцари делали сахар из сахарного тростника.","q":"Что делали рыцари рядом с замком?","a":["Сахар из сахарного тростника","Мороженое из снега","Пиццу для драконов"]},{"id":"cyp-troodos","e":"🐏","t":"Снег и муфлоны в горах Троодос","s":"Кипр — жаркий остров, но зимой в горах Троодос лежит снег. На самой высокой горе, Олимпе, работают подъёмники, и дети катаются на лыжах и санках. А до тёплого моря оттуда можно доехать примерно за час. В горных лесах живут муфлоны — дикие горные бараны с большими закрученными рогами. Муфлон — символ Кипра, его можно найти на кипрских монетках.","q":"Кто живёт в горных лесах Кипра?","a":["Муфлоны","Белые медведи","Кенгуру"]},{"id":"cyp-halloumi","e":"🧀","t":"Сыр, который скрипит","s":"На Кипре делают сыр халуми из козьего и овечьего молока. Он не похож на другие сыры: на сковородке халуми не растекается, а покрывается румяной корочкой. Когда его жуёшь, он смешно поскрипывает на зубах. Часто его посыпают мятой. А подают халуми с оливками, которые растут на Кипре повсюду: некоторые оливковые деревья живут сотни лет.","q":"Что происходит с халуми на сковородке?","a":["Он покрывается корочкой, но не растекается","Он улетает в окно","Он превращается в мороженое"]},{"id":"cyp-carob","e":"🌳","t":"Рожковое дерево и слово «карат»","s":"На Кипре растёт рожковое дерево. На нём висят длинные тёмно-коричневые стручки, похожие на рожки. Они сладкие: из них варят густой сироп, а порошок из стручков на вкус немного напоминает какао. Внутри стручков прячутся твёрдые семечки. По-гречески такое семечко называлось «кератион», и от этого слова произошло слово «карат», которым до сих пор взвешивают драгоценные камни.","q":"Какое слово произошло от названия семечка рожкового дерева?","a":["Карат","Кукуруза","Крокодил"],"big":1},{"id":"cyp-nicosia","e":"⭐","t":"Никосия — город в звезде","s":"Никосия — столица Кипра. Её старый центр окружают стены в форме звезды с одиннадцатью выступами-бастионами. Их построили венецианцы больше четырёхсот лет назад, и сверху город похож на снежинку. Уже много лет Никосия разделена на две части, и посреди старой пешеходной улицы есть пункт перехода, где люди спокойно переходят с одной стороны на другую.","q":"Какую форму имеют старые стены Никосии?","a":["Форму звезды","Форму чайника","Форму сапога"],"big":1},{"id":"cyp-sea-caves","e":"🌊","t":"Морские пещеры Айя-Напы","s":"Возле городка Айя-Напа море за много лет выточило в светлых скалах пещеры и арки. Вода там такая прозрачная, что с лодки видно камни на дне. К пещерам подплывают на лодках и каяках, а под каменной аркой, которую называют Мостом влюблённых, можно проплыть на каяке. Рядом мыс Греко, где море переливается голубым и бирюзовым.","q":"Кто выточил пещеры в скалах у Айя-Напы?","a":["Море","Гномы чайными ложками","Черепахи зубами"]}]},{"id":"geo","cc":"GE","n":"Тбилиси и Грузия","e":"🇬🇪","items":[{"id":"geo-legenda","e":"🦅","t":"Сокол царя Вахтанга","s":"Есть старинная легенда о грузинском царе Вахтанге. Однажды он охотился с соколом, и сокол погнался за фазаном. Обе птицы пропали, а нашли их у источника, где из-под земли била горячая вода. Царь удивился и велел построить на этом месте город. Его назвали Тбилиси, от грузинского слова «тбили», что значит «тёплый».","q":"Что значит грузинское слово «тбили»?","a":["Тёплый","Колючий","Сонный"]},{"id":"geo-bani","e":"🛁","t":"Бани с круглыми крышами","s":"В старом Тбилиси из-под земли бьёт горячая вода с серой. Над ней построили бани, и снаружи видны только круглые кирпичные купола, похожие на маленькие холмики. Вода в банях пахнет варёными яйцами, зато в ней хорошо греться и отдыхать. Поэт Пушкин побывал здесь и написал, что ничего роскошнее этих бань никогда не встречал.","q":"Чем пахнет вода в серных банях?","a":["Варёными яйцами","Клубничным вареньем","Новогодней ёлкой"]},{"id":"geo-narikala","e":"🚡","t":"По воздуху к старой крепости","s":"Над старым Тбилиси на горе стоит древняя крепость Нарикала. Подняться к ней можно пешком, а можно по воздуху. Из парка на берегу реки Куры к крепости плывут стеклянные кабинки канатной дороги. Они проплывают прямо над рекой и крышами домов. Сверху виден весь город: мосты, купола церквей и разноцветные крыши.","q":"Как подняться к крепости Нарикала по воздуху?","a":["На канатной дороге","На воздушном змее","Верхом на гусе"]},{"id":"geo-mat","e":"🗡️","t":"Мать Грузии с чашей и мечом","s":"Над Тбилиси на горе стоит огромная серебристая статуя женщины, её называют Мать Грузии. В одной руке у неё чаша, в другой меч. Чаша нужна, чтобы угощать тех, кто пришёл с добром. А меч — чтобы защищать свой дом от тех, кто пришёл со злом. Так статуя рассказывает о грузинах: они любят гостей, но умеют постоять за себя.","q":"Что держит в руках Мать Грузии?","a":["Чашу и меч","Зонтик и мороженое","Удочку и ведёрко"]},{"id":"geo-bukvy","e":"🔤","t":"Буквы-завитки","s":"Грузинские буквы не похожи ни на какие другие. Они круглые, с завитками, будто колечки и улитки. В грузинском алфавите тридцать три буквы, и предложения здесь не начинают с большой буквы. А ещё в грузинском языке есть забавная путаница: словом «мама» называют папу, а маму зовут «дэда».","q":"Кого по-грузински называют словом «мама»?","a":["Папу","Бабушкиного кота","Соседский трамвай"]},{"id":"geo-pesnya","e":"🎶","t":"Песня, которая летит в космосе","s":"Грузины любят петь хором на несколько голосов. Один голос ведёт мелодию, другие поют выше и ниже, и голоса сплетаются, как нитки в узоре. Такое многоголосое пение признано сокровищем всего человечества. А старинную песню «Чакруло» в 1977 году записали на золотую пластинку и отправили в космос на аппарате «Вояджер». Она до сих пор летит среди звёзд.","q":"Куда отправили грузинскую песню «Чакруло»?","a":["В космос","В бабушкин сундук","В гнездо к аисту"],"big":1},{"id":"geo-hachapuri","e":"🧀","t":"Лодочка с сыром","s":"Хачапури — это грузинская лепёшка с сыром. А хачапури по-аджарски похоже на лодочку: края загнуты, а внутри горячий тянучий сыр. Сверху разбивают яйцо и кладут кусочек сливочного масла. Отламываешь хрустящий бортик и макаешь в серединку. А на сладкое бывает чурчхела: орехи на ниточке, облитые густым виноградным соком.","q":"На что похоже хачапури по-аджарски?","a":["На лодочку","На ботинок великана","На летающую тарелку"]},{"id":"geo-kazbek","e":"🏔️","t":"Ледяная вершина Казбек","s":"На севере Грузии поднимаются высокие горы Кавказа. Одна из самых красивых вершин — Казбек. Снег и лёд лежат на нём круглый год, даже жарким летом. По-грузински название этой горы значит «ледяная вершина». А под Казбеком, на высоком зелёном холме, стоит старинная церковь Гергети, и путешественники поднимаются к ней пешком.","q":"Когда на Казбеке лежит снег?","a":["Круглый год","Только по вторникам","Никогда, там растут арбузы"]},{"id":"geo-mtskheta","e":"🏞️","t":"Где обнимаются две реки","s":"Мцхета — один из самых древних городов Грузии. Когда-то здесь была столица страны. Тут сливаются две реки, Арагви и Кура, и часто видно, что вода у них разного цвета. На горе над ними стоит древний монастырь Джвари, а в городе — большой собор Светицховели. Поэт Лермонтов написал про эти реки: «Обнявшись, будто две сестры, струи Арагвы и Куры».","q":"Какие две реки сливаются у Мцхеты?","a":["Арагви и Кура","Компот и Кисель","Молоко и Кефир"],"big":1},{"id":"geo-batumi","e":"🌊","t":"Батуми у Чёрного моря","s":"Батуми стоит на берегу Чёрного моря. Вдоль моря тянется длинный бульвар с пальмами, а пляж здесь не песчаный, а из гладких камешков. Каждый вечер на набережной оживают две огромные металлические фигуры, юноша и девушка. Они медленно движутся навстречу друг другу, встречаются и проходят друг сквозь друга. Кажется, что это волшебство!","q":"Что делают металлические фигуры в Батуми по вечерам?","a":["Движутся навстречу друг другу","Играют в футбол","Поют колыбельные"]}]},{"id":"arm","cc":"AM","n":"Ереван и Армения","e":"🇦🇲","items":[{"id":"arm-ararat","e":"⛰️","t":"Гора Арарат","s":"Из Еревана в ясный день видна огромная гора Арарат. У неё две вершины: Большой Арарат и Малый Арарат. На большой вершине круглый год лежит снег и блестит на солнце. По старинному преданию, после великого потопа к этой горе причалил Ноев ковчег со всеми зверями. Армяне очень любят Арарат и часто рисуют его на картинах.","q":"Сколько вершин у горы Арарат?","a":["Две","Сто двадцать","Ни одной, она плоская, как блин"]},{"id":"arm-tuf","e":"🌸","t":"Розовый город","s":"Ереван называют розовым городом. Многие дома здесь построены из туфа — камня, который получился из пепла древних вулканов. Туф бывает розовым, оранжевым и даже сиреневым. Этот камень легко обрабатывать, поэтому мастера вырезают на нём узоры. Вечером, когда садится солнце, стены домов светятся тёплым розовым светом.","q":"Из какого камня построены многие дома Еревана?","a":["Из туфа","Из шоколада","Из снежков"]},{"id":"arm-bukvy","e":"✍️","t":"Буквы Месропа Маштоца","s":"Больше полутора тысяч лет назад у армян ещё не было своих букв. Тогда учёный монах Месроп Маштоц придумал армянский алфавит из тридцати шести букв. С тех пор армяне пишут своими буквами, с крючками и хвостиками. А на склоне горы Арагац стоят большие каменные буквы армянского алфавита, почти в рост человека. Между ними можно гулять, как в каменном лесу.","q":"Кто придумал армянский алфавит?","a":["Месроп Маштоц","Кот в сапогах","Дед Мороз"],"big":1},{"id":"arm-matenadaran","e":"📚","t":"Дом древних книг","s":"В Ереване есть Матенадаран, по-армянски это значит «хранилище книг». Здесь берегут тысячи старинных книг, которые писали от руки и украшали яркими картинками. Самая большая книга весит больше, чем пятилетний ребёнок. А самая маленькая легко помещается на ладошке. У входа стоит памятник Месропу Маштоцу, который придумал армянские буквы.","q":"Что берегут в Матенадаране?","a":["Старинные книги","Зимние валенки","Пирожки с капустой"]},{"id":"arm-abrikos","e":"🌳","t":"Армянская слива","s":"Абрикосы растут в Армении с древних времён. В старину европейцы считали Армению родиной абрикоса, поэтому учёные дали ему латинское имя, которое значит «армянская слива». Летом на рынках горы абрикосов, сладких и оранжевых, как маленькие солнышки. А из абрикосового дерева делают дудук — армянскую дудочку с мягким, певучим голосом.","q":"Что делают из абрикосового дерева?","a":["Дудук, армянскую дудочку","Велосипеды","Подушки"]},{"id":"arm-lavash","e":"🫓","t":"Лаваш из тонира","s":"Армянский лаваш тонкий, как лист бумаги. Его пекут в тонире — круглой глиняной печи, которая спрятана прямо в земле. Хозяйки раскатывают тесто, растягивают его и ловко прилепляют к горячей стенке печи. Печётся лаваш совсем недолго. Сухой лаваш может храниться очень долго, а чтобы он снова стал мягким, его сбрызгивают водой.","q":"Где пекут армянский лаваш?","a":["В тонире, печи в земле","В холодильнике","В скворечнике"]},{"id":"arm-sevan","e":"💧","t":"Голубое озеро Севан","s":"Высоко в горах Армении лежит огромное озеро Севан. Это самое большое озеро Армении и всего Кавказа. Вода в нём голубая и прохладная даже летом. На берегу стоят старинные церкви монастыря Севанаванк. Раньше они стояли на острове, но вода в озере опустилась, и остров стал полуостровом. Теперь к монастырю можно дойти пешком.","q":"Чем раньше был полуостров с монастырём?","a":["Островом","Огромным арбузом","Спиной кита"]},{"id":"arm-garni","e":"🏛️","t":"Храм Гарни","s":"Почти две тысячи лет назад в армянских горах построили храм Гарни. Он похож на древнегреческий: со всех сторон его окружают двадцать четыре колонны. Считается, что храм посвятили богу солнца. Однажды землетрясение разрушило его, но учёные собрали храм заново из старых камней. А в ущелье под храмом стоят каменные столбы, похожие на трубы огромного органа. Их называют «Симфонией камней».","q":"Сколько колонн у храма Гарни?","a":["Двадцать четыре","Ни одной","Миллион"],"big":1},{"id":"arm-shahmaty","e":"♟️","t":"Шахматы на уроке","s":"В Армении очень любят шахматы. Армянский шахматист Тигран Петросян был чемпионом мира. В 2011 году Армения одной из первых в мире сделала шахматы обязательным школьным уроком. Со второго класса дети учатся ходить конём, ставить мат и думать на несколько ходов вперёд. На таких уроках учатся не спешить и хорошо обдумывать каждый шаг.","q":"С какого класса армянские дети учатся шахматам на уроках?","a":["Со второго","С сорок пятого","Только на пенсии"]},{"id":"arm-kaskad","e":"🪜","t":"Лестница над городом","s":"В центре Еревана по склону холма поднимается Каскад — огромная светлая лестница. В ней больше пятисот ступенек, а между ними журчат фонтаны и стоят забавные скульптуры. Внизу, например, стоит большой толстый кот из бронзы. Кто устал, может подняться внутри Каскада на эскалаторе. С самого верха виден весь Ереван, а в ясный день и гора Арарат.","q":"Как подняться на Каскад, если устал?","a":["На эскалаторе внутри","На верблюде","На воздушном шарике"]}]},{"id":"srb","cc":"RS","n":"Белград и Сербия","e":"🇷🇸","items":[{"id":"srb-kalemegdan","e":"🏰","t":"Крепость над двумя реками","s":"Белград по-сербски значит «белый город». Над ним на высоком берегу стоит старинная крепость Калемегдан. С её стен видно, как река Сава впадает в широкий Дунай. Вокруг крепости раскинулся большой парк, где гуляют семьи и играют дети. А прямо в крепости есть зоопарк!","q":"Что значит слово «Белград»?","a":["Белый город","Город сладкой ваты","Город без дверей"]},{"id":"srb-tesla","e":"⚡","t":"Лампа без проводов","s":"Никола Тесла родился в 1856 году в маленьком селе Смиляны. Он вырос и стал великим изобретателем: его изобретения помогли провести электричество в дома по всему миру. В Белграде есть музей Николы Теслы. Там включают огромную катушку, и лампа в руке у гостя загорается сама, без проводов и батареек!","q":"Что случается с лампой в музее Теслы?","a":["Загорается сама, без проводов","Превращается в банан","Улетает в окно"],"big":1},{"id":"srb-sava","e":"⛪","t":"Храм Святого Саввы","s":"На холме в Белграде стоит огромный белый храм Святого Саввы. Это один из самых больших православных храмов в мире. Если войти внутрь и посмотреть вверх, увидишь купол, который сияет золотой мозаикой. Святого Савву в Сербии почитают как первого учителя и покровителя школ. Поэтому двадцать седьмого января, в его день, во всех сербских школах праздник.","q":"Когда в сербских школах празднуют день Святого Саввы?","a":["Двадцать седьмого января","Каждый понедельник","В день рождения кошки"]},{"id":"srb-slivy","e":"🥧","t":"Сливовое царство","s":"В Сербии растёт очень много слив, это один из самых любимых фруктов страны. В конце лета из них варят густое сливовое повидло — пекмез. Его варят много часов в большом котле на огне и помешивают длинной деревянной лопаткой. А ещё пекут пироги со сливами и лепят кнедле: шарики из картофельного теста, а внутри целая слива.","q":"Что прячется внутри сербских кнедле?","a":["Целая слива","Мячик для пинг-понга","Тапочек"]},{"id":"srb-guca","e":"🎺","t":"Праздник трубачей в Гуче","s":"Каждый год в августе маленький сербский посёлок Гуча наполняется музыкой. Сюда съезжаются оркестры трубачей со всей Сербии и из других стран. Трубы и барабаны гремят на каждой улице, а люди танцуют, взявшись за руки, — этот хоровод называется коло. Первый такой праздник прошёл в 1961 году, и тогда в нём играли всего четыре оркестра.","q":"Какие оркестры съезжаются в Гучу?","a":["Оркестры трубачей","Оркестры кузнечиков","Оркестры пылесосов"]},{"id":"srb-djavolja","e":"🪨","t":"Каменные столбы в шляпах","s":"На юге Сербии есть место со страшным названием — Дьявольский город. Но бояться нечего: это просто каменные столбы. Их больше двухсот, и у многих на макушке лежит камень, будто шляпа. Дождь веками размывал мягкую землю вокруг, а камень сверху защищал её, как зонтик. Так и выросли эти удивительные столбы в шляпах.","q":"Что защищало столбы от дождя?","a":["Камень на макушке, как зонтик","Резиновые сапоги","Большой тёплый плед"],"big":1},{"id":"srb-monastyri","e":"🔔","t":"Белые монастыри","s":"В зелёных долинах Сербии прячутся старинные монастыри. Один из самых известных — Студеница. Его главную церковь построили из белого мрамора больше восьмисот лет назад. Стены внутри расписаны фресками — это картины, которые рисуют прямо на сырой штукатурке. А в монастыре Милешева есть знаменитая фреска «Белый ангел»: ангел в сияющих белых одеждах.","q":"Из чего построена главная церковь Студеницы?","a":["Из белого мрамора","Из пряников","Из пластилина"]},{"id":"srb-dunaj","e":"🚢","t":"Дунай и Железные ворота","s":"Дунай течёт через десять стран, больше, чем любая другая река в мире. На востоке Сербии он пробирается между высокими скалами по ущелью, которое называют Железными воротами. Здесь река становится узкой и очень глубокой. У входа в ущелье стоит старинная крепость Голубац с высокими башнями. А в скале над водой видна надпись, которую древние римляне высекли почти две тысячи лет назад.","q":"Через сколько стран течёт Дунай?","a":["Через десять","Только через одну","Через сто тысяч"],"big":1},{"id":"srb-azbuka","e":"✏️","t":"Пиши, как говоришь","s":"В сербской азбуке тридцать букв, и каждая всегда читается одинаково. Порядок в азбуке навёл учёный Вук Караджич. Его главное правило звучит так: «Пиши, как говоришь, и читай, как написано». Есть в ней и буквы, которых нет в русской: одна читается как «ль», а другая как «нь». А сербские школьники учат два алфавита: сначала кириллицу, потом латиницу.","q":"Что советует правило Вука Караджича?","a":["Писать, как говоришь","Писать задом наперёд","Писать только ногой"]},{"id":"srb-djokovic","e":"🎾","t":"Теннисист из Белграда","s":"Знаменитый теннисист Новак Джокович родился в Белграде. Свою первую ракетку он взял в руки, когда ему было четыре года. Он много раз побеждал на самых главных турнирах мира и стал олимпийским чемпионом. А ещё в Сербии очень любят баскетбол: сербские баскетболисты играют в самых сильных командах мира.","q":"Сколько лет было Новаку, когда он взял первую ракетку?","a":["Четыре года","Девяносто девять","Он родился с ракеткой в руке"]}]}];
