const MORE_STORIES = LX('MORE_STORIES', { "cascais": [ { "id": "cas-paula-rego", "e": "🎨", "t": "Дом историй", "s": "В Кашкайше стоит музей с двумя красными башнями. Башни острые, как пирамиды, и их видно издалека над деревьями. Это Дом историй художницы Паулы Регу. Паула Регу рисовала картины, похожие на сказки: про девочек, собак и других зверей. На каждую картину можно смотреть долго и придумывать, что случится дальше.", "q": "На что похожи башни Дома историй?", "a": [ "На пирамиды", "На кастрюли", "На подушки" ] }, { "id": "cas-castro-guimaraes", "e": "🏰", "t": "Замок над бухтой", "s": "В Кашкайше над маленькой бухтой стоит дом, похожий на сказочный замок с башенкой. Его построили больше ста лет назад. Потом в нём жил граф Каштру Гимарайнш, который собирал старинные вещи и книги. Граф оставил свой дом-замок городу, и теперь там музей. В музее хранится книга, которой больше пятисот лет, а в ней один из самых старых рисунков Лиссабона.", "q": "Кому граф оставил свой дом-замок?", "a": [ "Городу", "Своему коту", "Соседской курице" ] }, { "id": "cas-praia-rainha", "e": "👑", "t": "Пляж королевы", "s": "В самом центре Кашкайша между скалами прячется крошечный пляж. Он называется Прайя-да-Раинья, то есть «Пляж королевы». Давным-давно здесь купалась королева Амелия, жена короля Карлуша. В те времена этот пляж был только для неё. А теперь тут могут купаться все, и дети строят замки из песка там, где когда-то плавала королева.", "q": "Кто давным-давно купался на Пляже королевы?", "a": [ "Королева Амелия", "Бабушка-черепаха", "Пожарная команда" ] }, { "id": "cas-rei-carlos", "e": "🐠", "t": "Король, который изучал море", "s": "Король Карлуш Первый очень любил море. На яхте «Амелия», названной в честь королевы, он выходил в океан у Кашкайша. Король опускал сети глубоко-глубоко и доставал оттуда рыб и других морских жителей, чтобы их изучать. А ещё он умел красиво рисовать море. Теперь в Кашкайше есть Музей моря, названный в честь короля Карлуша.", "q": "Как называлась яхта короля Карлуша?", "a": [ "«Амелия»", "«Котлета»", "«Тапочка»" ] }, { "id": "cas-comboio", "e": "🚆", "t": "Поезд вдоль океана", "s": "Из Кашкайша в Лиссабон ходит поезд, и почти всю дорогу он едет вдоль океана. Из окна видно волны, пляжи, старые крепости и рыбацкие лодки. Железную дорогу до Кашкайша открыли в 1889 году. Тогда жители Лиссабона стали ездить на поезде к морю купаться и гулять. А позже здесь одними из первых в Португалии появились электрички.", "q": "Вдоль чего едет поезд из Кашкайша в Лиссабон?", "a": [ "Вдоль океана", "Вдоль шоколадной реки", "Вдоль огромной колбасы" ] }, { "id": "cas-cresmina", "e": "🏜️", "t": "Дюна, которая гуляет", "s": "Рядом с пляжем Гиншу лежит дюна Кресмина — большая гора из песка. Только эта гора не стоит на месте! Сильный ветер дует и дует, переносит песчинку за песчинкой, и за год дюна сдвигается примерно на длину автобуса. Чтобы не топтать растения, люди гуляют там по деревянным дорожкам. С них видно, как ветер рисует на песке маленькие волны.", "q": "Кто двигает дюну Кресмина?", "a": [ "Ветер", "Слон", "Пылесос" ] }, { "id": "cas-oitavos", "e": "🔭", "t": "Крепость Ойтавуш", "s": "На берегу океана, недалеко от Кашкайша, стоит старая крепость Ойтавуш. Её построили почти четыреста лет назад, чтобы охранять берег. Солдаты днём и ночью смотрели в море, не плывут ли чужие корабли. Теперь крепость стала музеем, и туда может зайти любой. Можно встать у старой стены и смотреть на волны, как настоящий часовой.", "q": "Зачем построили крепость Ойтавуш?", "a": [ "Чтобы охранять берег", "Чтобы сушить носки", "Чтобы прятать конфеты" ] }, { "id": "cas-cabo-raso", "e": "🔴", "t": "Красный маяк на мысе Разу", "s": "По дороге из Кашкайша к пляжу Гиншу есть скалистый мыс Разу. На нём стоит маленький маяк, красный, как пожарная машина. Его поставили прямо внутри старой крепости, за её стенами. Маяк светит кораблям уже больше ста лет, и его огонь видно далеко в море. Раньше за огнём следил смотритель, а теперь маяк включается сам.", "q": "Какого цвета маяк на мысе Разу?", "a": [ "Красного", "Клетчатого", "Прозрачного" ] }, { "id": "cas-lota", "e": "🐟", "t": "Рыбный аукцион", "s": "Когда рыбаки Кашкайша возвращаются с моря, они сдают улов в лоту. Лота — это рыбный аукцион, где рыбу продают по особым правилам. Ящики с рыбой выставляют по очереди, и цена сначала большая, а потом становится всё меньше и меньше. Кто из покупателей первым подаст знак, тот и забирает ящик. Так свежая рыба быстро попадает в магазины и рестораны.", "q": "Как меняется цена на рыбном аукционе?", "a": [ "Становится всё меньше", "Улетает на луну", "Прыгает обратно в море" ] }, { "id": "cas-fleming", "e": "🕵️", "t": "Писатель и шпион", "s": "В Эшториле, рядом с Кашкайшем, есть казино — большой нарядный дом, где взрослые играют в карты и другие игры. Перед ним раскинулся сад с пальмами. Давным-давно в Эшториле останавливался английский писатель Ян Флеминг и смотрел, как играют в казино. Говорят, именно казино Эшторила помогло ему придумать первую книгу о смелом шпионе Джеймсе Бонде. Шпион — это тайный разведчик, а о Джеймсе Бонде потом сняли много фильмов.", "q": "О ком писал книги Ян Флеминг?", "a": [ "О шпионе Джеймсе Бонде", "О говорящем батоне", "О летающей кастрюле" ] }, { "id": "cas-carcavelos", "e": "🏄", "t": "Сёрферы Каркавелуша", "s": "Каркавелуш — длинный песчаный пляж между Кашкайшем и Лиссабоном. Сюда круглый год приходят сёрферы с длинными досками. Вода в океане прохладная, поэтому они надевают гидрокостюмы, похожие на резиновую кожу. Сёрфер ложится на доску, гребёт руками, как утка лапками, ловит волну и встаёт. Волна несёт его к берегу, будто с горки! На пляже есть школы сёрфинга, где учатся даже дети.", "q": "Чем гребёт сёрфер, когда плывёт к волне?", "a": [ "Руками", "Ушами", "Бровями" ] }, { "id": "cas-mercado", "e": "🍊", "t": "Рынок Кашкайша", "s": "В центре Кашкайша есть рынок, он называется Меркаду-да-Вила. Рано утром фермеры из окрестных деревень привозят туда овощи, фрукты, хлеб, сыр и цветы. В рыбном ряду на льду блестят серебристые рыбы, а рядом лежат креветки и ракушки. Покупатели ходят между прилавками с сумками и корзинками. Здесь пахнет морем, свежим хлебом и апельсинами сразу!", "q": "Что фермеры привозят на рынок Кашкайша?", "a": [ "Овощи и фрукты", "Пингвинов и моржей", "Самолёты и ракеты" ] }, { "id": "cas-a-kazino-eshtoril", "e": "🏛️", "t": "Большое здание у моря", "s": "Недалеко от моря в Эшториле стоит одно из самых больших казино Европы. Строить его начали в 1916 году: первый камень заложил тогдашний президент Португалии. А открылось здание в 1931 году. Дети внутрь не ходят — это взрослое место. Но для путешественников оно стало настоящим знаком Эшторила: большое, в современном стиле, а рядом тянутся сады, которые ведут к пляжу.", "q": "Что сделал президент Португалии в 1916 году?", "a": [ "Заложил первый камень будущего казино", "Запустил первый поезд до Кашкайша", "Зажёг огонь на новом маяке" ] }, { "id": "cas-a-kasa-santa-mariya", "e": "🏠", "t": "Дом с плиточными картинами", "s": "В Кашкайше есть дом, стены которого украшены азулежу — расписной плиткой. Называется он Каза-ди-Санта-Мария. Построили его в 1902 году по проекту архитектора Раула Лину для богатого человека по имени Жоржи Онил. Рассказывают, что это был свадебный подарок его дочери Марии Терезе. Теперь в доме музей, а совсем рядом, у моря, стоит старый маяк, в котором тоже можно побывать.", "q": "Чем украшены стены дома Санта-Мария?", "a": [ "Расписной плиткой азулежу", "Раковинами и кораллами", "Резными деревянными панелями" ] }, { "id": "cas-a-zamok-grafov", "e": "🏰", "t": "Маленький замок в парке", "s": "Если зайти в парк в центре Кашкайша, увидишь маленький замок. У него башенки и тенистый двор с арками, будто из сказки. Это дворец графов Кастру Гимарайнш. Построили его не в древности, а примерно сто лет назад, но выглядит он как рыцарский. С 1931 года здесь музей: красивые вещи, которые собирали графы, теперь можно рассматривать всем.", "q": "Что есть у дворца графов Кастру Гимарайнш?", "a": [ "Башенки и двор с арками", "Подъёмный мост и ров с водой", "Стеклянный купол и фонтан-горка" ] }, { "id": "cas-a-park-karmona", "e": "🦆", "t": "Павлины в парке", "s": "Рядом с замком графов раскинулся парк маршала Кармона. Здесь на свободе гуляют утки, куры и павлины, а в пруду и на камнях у воды можно увидеть черепашек. Птиц лучше не кормить чем попало — в парке за этим следят. Зато можно сесть на скамейку и смотреть, как важный павлин ходит по дорожке, будто это его собственный сад.", "q": "Кто гуляет на свободе в парке маршала Кармона?", "a": [ "Утки, куры и павлины", "Белые медведи и тюлени", "Жирафы и слоны" ] }, { "id": "cas-a-muzey-muzyki", "e": "🎻", "t": "Дом, где живёт музыка", "s": "В Монте-Эшториле, на холме, стоит дом-музей, где собрана музыка. Это Музей португальской музыки. Главное его сокровище — народные инструменты, которые собрал Мишель Джакометти: он ездил по деревням и записывал песни. Дом построили в 1917–1918 годах по заказу всё того же Жоржи Онила, а потом он стал музеем и садом для всех горожан.", "q": "Какие инструменты собраны в Музее португальской музыки?", "a": [ "Народные инструменты Португалии", "Старинные японские барабаны", "Африканские маримбы" ] }, { "id": "cas-a-avtodrom-eshtoril", "e": "🏎️", "t": "Гоночная трасса", "s": "Рядом с Эшторилом есть автодром — трасса для гонок. Её открыли в 1972 году. С 1984 по 1996 год здесь проходил Гран-при Португалии: самые быстрые гоночные машины мира, «Формулы-1», неслись по кругу. Сейчас круг трассы — чуть больше четырёх километров: пешком его идти почти час, а гоночной машине хватает куда меньше двух минут.", "q": "Какие гонки проходили в Эшториле с 1984 по 1996 год?", "a": [ "Гран-при «Формулы-1»", "Велогонка вокруг страны", "Гонки на санях" ] }, { "id": "cas-a-paredan", "e": "🚶", "t": "Дорожка вдоль океана", "s": "Между Кашкайшем и Эшторилом вдоль моря идёт длинная набережная-дорожка. Её зовут Паредан — по-португальски это «большая стена». Длиной она почти три километра: ровно 2 750 метров. Идёшь, а рядом плещется океан, видны пляжи и скалы, и можно пешком дойти из одного города в другой, ни разу не свернув на улицу.", "q": "Какой длины дорожка Паредан?", "a": [ "Чуть меньше трёх километров", "Тридцать метров", "Сто километров" ] }, { "id": "cas-a-marina-kashkaysh", "e": "⛵", "t": "Гавань для яхт", "s": "В Кашкайше есть большая гавань для яхт — марина. Её открыли в 1999 году. В ней 650 мест для лодок и яхт, а самые длинные яхты могут быть до 36 метров — как три автобуса, поставленных в ряд. Сто двадцать пять мест оставлены для гостей, которые зашли на пару дней: сегодня тут стоит яхта из одной страны, завтра — из другой.", "q": "Сколько мест для лодок в марине Кашкайша?", "a": [ "Шестьсот пятьдесят", "Двадцать", "Пятьдесят тысяч" ] }, { "id": "cas-a-kubok-ameriki", "e": "🏁", "t": "Гонка у самого берега", "s": "В августе 2011 года у берегов Кашкайша прошёл первый этап большой парусной серии — Кубка Америки. Лёгкие яхты с жёсткими парусами-крыльями мчались по бухте так близко, что зрители смотрели прямо с берега. А ещё раньше, в 2007 году, Кашкайш принимал чемпионат мира по парусному спорту. Море здесь для гонок очень удобное.", "q": "Что смотрели зрители с берега в августе 2011 года?", "a": [ "Гонки парусных яхт", "Гонки на верблюдах", "Бег собачьих упряжек" ] }, { "id": "cas-a-gora-rakushek", "e": "🐚", "t": "Гора ракушек", "s": "Откуда у города такое имя — Кашкайш? Есть версия, что оно связано с ракушками. Давным-давно жители этого берега собирали моллюсков, а старое слово означало что-то вроде «горы ракушек». Точно этого не знает никто, но версия красивая. Представь: стоишь на берегу, а перед тобой целая гора пустых блестящих раковин.", "q": "С чем, по одной из версий, связано имя Кашкайш?", "a": [ "С ракушками", "С каштанами", "С кашей" ] }, { "id": "cas-a-linza-mayaka", "e": "💡", "t": "Линза выше двери", "s": "У марины Кашкайша стоит маяк Санта-Марта, а в нём — музей, открытый в 2007 году. Внутри лежат огромные стеклянные линзы Френеля. Одна из них раньше светила на острове Берленга и высотой в 3 метра 70 сантиметров — почти вдвое выше обычной двери. Такая линза собирает свет лампы в один длинный луч, чтобы корабли видели маяк издалека.", "q": "Что делает линза маяка?", "a": [ "Собирает свет лампы в длинный луч", "Греет воду для моряков", "Показывает, какая будет погода" ] }, { "id": "cas-a-doroga-marzhinal", "e": "🛣️", "t": "Дорога на краю берега", "s": "Из Лиссабона в Кашкайш ведёт прибрежная дорога — Маржинал. Её имя значит что-то вроде «дороги по краю»: она идёт прямо вдоль берега. Раньше на её месте была обычная грунтовая дорога, а потом построили широкую, и ехать вдоль океана стало быстро и удобно. По пути один за другим сменяются пляжи, форты и дома у воды.", "q": "Что было на месте дороги Маржинал раньше?", "a": [ "Грунтовая дорога", "Канал с лодками", "Железный мост" ] }, { "id": "cas-a-kurort-pridumali", "e": "🌴", "t": "Курорт, который придумали", "s": "Лет сто назад Эшторил стал курортом. Предприниматель Фаусту Фигейреду с партнёром начал строить здесь гостиницы, сады, дороги к морю и большое казино. Тихое место у океана превратилось в город, куда приезжали гости из многих стран. Историки даже называют это «изобретением Эшторила», потому что курорт придумали и построили почти с нуля.", "q": "Что построили в Эшториле, чтобы он стал курортом?", "a": [ "Гостиницы, сады и казино", "Горные трассы для лыж", "Большой зоопарк" ] }, { "id": "cas-a-vereskovoe-imya", "e": "🌿", "t": "Вереск или ястреб", "s": "Никто точно не знает, откуда взялось имя Эшторил. Одни думают, что оно пошло от старого слова, которым называли вереск — кустарник с мелкими цветами, он растёт на этих холмах. Другие — что от слова, которым называли ястреба. Может быть, на склонах цвёл вереск, а над ними кружил ястреб. Выбирай ту версию, что тебе нравится больше.", "q": "Что, по одной из версий, означало слово, от которого пошёл Эшторил?", "a": [ "Вереск", "Морская звезда", "Рыбачья лодка" ] }, { "id": "cas-a-rimskaya-masterskaya", "e": "🏺", "t": "Римская солёная рыба", "s": "В центре Кашкайша нашли остатки римской мастерской, где солили рыбу. Римляне ловили её в океане, пересыпали солью, чтобы она не портилась, и увозили в больших кувшинах. Значит, жители этого берега кормились морем уже две тысячи лет назад. Сегодня здесь тоже любят рыбу, только хранят её во льду и в холодильниках.", "q": "Что делали в римской мастерской в Кашкайше?", "a": [ "Солили рыбу", "Пекли хлеб", "Ткали ковры" ] }, { "id": "cas-a-derevnya-stala-gorodom", "e": "📜", "t": "Подарки двух королей", "s": "Когда-то Кашкайш был рыбацкой деревней. В 1364 году король Педру Первый объявил её городом. А в 1514 году король Мануэл Первый дал городу особую грамоту: она разрешала жителям самим решать свои городские дела. Получилось два королевских подарка, и оба Кашкайш хранит в памяти до сих пор.", "q": "Кем стал Кашкайш в 1364 году?", "a": [ "Городом", "Островом", "Столицей страны" ] }, { "id": "cas-a-letnie-dachi", "e": "🏡", "t": "Дачи у океана", "s": "С 1870 по 1908 год королевская семья приезжала на лето в Кашкайш. Следом потянулись богатые семьи и строили нарядные дачи у моря. Этот стиль называют «летней архитектурой»: он смешивает разные стили, так что в одном доме могут встретиться башенка, веранда и узорная плитка. Многие такие дома стоят в центре города до сих пор.", "q": "Как называют стиль нарядных дач Кашкайша?", "a": [ "Летняя архитектура", "Зимняя архитектура", "Подводная архитектура" ] }, { "id": "cas-a-molodezhnaya-stolitsa", "e": "🎈", "t": "Молодёжная столица Европы", "s": "Каждый год в Европе выбирают город, который называют молодёжной столицей. В 2018 году такое звание получил Кашкайш. Это значит, что весь год в городе устраивали события для детей и молодых людей, придумывали проекты и слушали, чего хотят ребята. Представь: целый год город заботится о тех, кто только начинает расти.", "q": "Какое звание получил Кашкайш в 2018 году?", "a": [ "Молодёжная столица Европы", "Столица рыбаков мира", "Самый тихий город планеты" ] }, { "id": "cas-a-chetyre-eshtorila", "e": "🚉", "t": "Четыре Эшторила подряд", "s": "Едешь на поезде из Лиссабона к Кашкайшу и слышишь одно и то же имя много раз. Остановки идут так: Сан-Педру-ду-Эшторил, Сан-Жуан-ду-Эшторил, просто Эшторил, Монте-Эшторил. Четыре станции подряд, и в каждой — Эшторил! А следом, на самом краю линии, — Кашкайш: дальше рельсов нет, только океан.", "q": "Какая станция идёт сразу после Монте-Эшторила?", "a": [ "Кашкайш", "Синтра", "Порту" ] }, { "id": "cas-a-plyazh-tamarish", "e": "🏖️", "t": "Из сада — на пляж", "s": "Пляж Тамариш в Эшториле начинается сразу под садами казино. От вокзала до моря можно дойти пешком за несколько минут, и дорога идёт через зелёный сад. Говорят, что там растут пальмы, а на газонах гуляют люди с собаками. Вот так: вышел из поезда, прошёл по аллее, и вот уже горячий песок под ногами.", "q": "Куда ведёт сад возле казино Эшторила?", "a": [ "К пляжу Тамариш", "К замку на горе", "К зоопарку" ] }, { "id": "cas-a-fort-santu-antoniu", "e": "🏯", "t": "Старый форт на скале", "s": "На скалах возле Сан-Жуан-ду-Эшторил стоит старый форт Санту-Антониу-да-Барра. Его построили около 1590 года, чтобы чужие корабли не подходили к входу в реку Тежу и не высаживались за водой. Много лет форт был закрыт, а с 2018 года в него снова можно зайти: оттуда видно синее море и берег, который он когда-то охранял.", "q": "Зачем построили форт Санту-Антониу-да-Барра?", "a": [ "Чтобы охранять вход к Лиссабону с моря", "Чтобы хранить рыбу", "Чтобы запускать фейерверки" ] }, { "id": "cas-a-tsepochka-fortov", "e": "🔗", "t": "Цепочка фортов", "s": "Берег от Кашкайша до Лиссабона похож на каменную цепочку: сюда много раз пытались подойти пираты, поэтому вдоль воды построили целый ряд фортов. После 1640 года их появилось ещё около дюжины, поменьше. Они стояли так, чтобы прикрывать друг друга и вход в реку Тежу. Говорят, что такого множества береговых крепостей почти нигде больше нет.", "q": "От кого защищали берег форты?", "a": [ "От пиратов", "От снежных лавин", "От диких слонов" ] }, { "id": "cas-a-kasa-sommer", "e": "📚", "t": "Дом старых бумаг", "s": "Каза Соммер — большой дом в Кашкайше. Его отремонтировали, и 7 декабря 2016 года в нём снова открылись двери. Внутри хранится исторический архив города: старые бумаги с 1387 по 2016 год. А ещё там есть библиотека и книжный магазин. Если сложить все эти листы, получится история Кашкайша — такой, какой её записывали люди.", "q": "Что хранится в Каза Соммер?", "a": [ "Старые городские бумаги", "Модели кораблей", "Коллекция бабочек" ] }, { "id": "cas-a-kto-zhil-ranshe", "e": "🌍", "t": "Тёплое место для жизни", "s": "Берег Эшторила люди выбирали очень давно. Здесь побывали финикийцы — мореплаватели и купцы с востока Средиземного моря, потом римляне, а затем арабы. В Эшториле находили остатки римской виллы. Мягкий климат, море рядом и ровная земля — всё это понравилось людям и тысячу лет назад, и понравилось сегодня.", "q": "Кто, судя по находкам, жил на берегу Эшторила?", "a": [ "Римляне", "Викинги", "Древние китайцы" ] }, { "id": "cas-a-tennis-eshtoril", "e": "🎾", "t": "Теннис у океана", "s": "Португальский теннисный турнир называется «Эшторил Опен», хотя первые его матчи в 1990 году сыграли в соседнем городе Ойраш. С 2015 года турнир проходит в теннисном клубе Эшторила. Игроки со всего мира приезжают на ракетки и мячи, а зрители слушают, как мяч стучит по корту, и чувствуют запах моря.", "q": "Где с 2015 года проходит турнир «Эшторил Опен»?", "a": [ "В теннисном клубе Эшторила", "На ледовом катке в Лиссабоне", "На горе возле Синтры" ] }, { "id": "cas-a-spasennye-plitki", "e": "🧩", "t": "Спасённая плитка", "s": "В доме Санта-Мария есть часовня, а в ней — плитка XVIII века. Рассказывают, что её спасли из руин старой часовни: плитки аккуратно сняли и поставили на новое место. На такой плитке нарисованы библейские сцены. Получается, что картины, которым почти триста лет, нашли второй дом — и в нём они тоже красивы.", "q": "Что сделали с плиткой из старой часовни?", "a": [ "Спасли и поставили в доме Санта-Мария", "Выбросили в океан", "Продали на рынке" ] }, { "id": "cas-a-trassa-dlya-motociklov", "e": "🏍️", "t": "Трасса для мотоциклов", "s": "Автодром Эшторила когда-то был для машин, а потом его изменили. Около 2000 года трассу перестроили, чтобы здесь могли гоняться и мотоциклисты. Теперь её длина — 4 183 метра. Мотогонки проходили на ней много лет, и зрители сидели на холмах рядом, чтобы увидеть, как гонщики наклоняются в поворотах почти до земли.", "q": "Для кого перестроили трассу около 2000 года?", "a": [ "Для мотоциклистов", "Для лыжников", "Для всадников на лошадях" ] }, { "id": "cas-b-sardina-na-hlebe", "e": "🐟", "t": "Сардина на хлебе", "s": "Летом у моря в Португалии пахнет дымом: на угольях жарят сардины. Тарелка им не нужна. Горячую рыбку кладут прямо на ломоть хлеба. Хлеб впитывает сок и становится самым вкусным кусочком. Сардины живут большими стаями и плывут рядом, плечом к плечу, как будто идут строем. Рыбаки Кашкайша ловят их сетями, а потом на берегу пекут для всех.", "q": "Что кладут под жареную сардину?", "a": [ "Ломоть хлеба", "Лист кувшинки", "Ломтик арбуза" ] }, { "id": "cas-b-bakalyau", "e": "🧂", "t": "Рыба, которая ждёт в шкафу", "s": "Португальцы очень любят треску и зовут её «бакальяу». Свежая треска живёт в холодных северных морях, далеко от Кашкайша. Давным-давно португальские рыбаки плавали за ней аж к берегам Ньюфаундленда. Чтобы рыба не испортилась в дороге, её солили и сушили. Такая треска становилась твёрдой, как доска, и могла лежать долго-долго. Дома её замачивали в воде, и она снова оживала для обеда.", "q": "Как сохраняли треску на долгую дорогу?", "a": [ "Солили и сушили", "Прятали в мёд", "Закапывали в сырой песок" ] }, { "id": "cas-b-portugalskiy-korablik", "e": "🎐", "t": "Синий кораблик без команды", "s": "После сильного ветра на пляже иногда лежит нечто синее и блестящее, как воздушный шарик с длинными нитями. Это португальский кораблик. Он вовсе не медуза, а целая семья крошечных существ, которые живут вместе. Сверху у него надутый пузырь-парус, и ветер гонит кораблик по волнам. Нити под водой жгучие, даже когда кораблик выброшен на берег. Поэтому увидев его, не трогай, а позови взрослого.", "q": "Что у португальского кораблика похоже на парус?", "a": [ "Надутый пузырь", "Настоящая мачта", "Большой плавник" ] }, { "id": "cas-b-baklany", "e": "🐦", "t": "Баклан сушит крылья", "s": "На тёмных скалах у океана сидят чёрные птицы и стоят как будто с раскинутыми руками. Это бакланы. Они отлично ныряют за рыбой, и под водой их перья намокают. Поэтому после рыбалки баклан выбирается на камень, расправляет крылья и сушит их на ветру и солнце, как бельё на верёвке. Посмотри, как терпеливо он сидит. Пока не высохнет, он не улетит.", "q": "Зачем баклан расправляет крылья на скале?", "a": [ "Чтобы высушить перья", "Чтобы позвать друзей", "Чтобы согреть рыбу" ] }, { "id": "cas-b-olushi", "e": "🪂", "t": "Птицы-стрелы", "s": "Зимой над океаном у берегов Португалии летают большие белые птицы с чёрными кончиками крыльев. Это олуши. Заметив рыбу, олуша складывает крылья и падает вниз, как стрела, прямо с высоты многоэтажного дома. В воду она входит со скоростью машины на шоссе. Чтобы голове не было больно, под кожей у неё есть воздушные подушечки. Потом олуша выныривает с рыбкой в клюве.", "q": "Как олуша ловит рыбу?", "a": [ "Падает в воду, как стрела", "Ловит рыбу сачком", "Роет лапами в песке" ] }, { "id": "cas-b-chayki", "e": "🕊️", "t": "Хитрая чайка", "s": "На набережной Кашкайша всегда гуляют чайки с жёлтыми лапами. Они умные и внимательные. Чайка любит ракушки и крабов, но панцирь крепкий, а клюв не щипцы. Тогда она хватает добычу, взлетает повыше и бросает её на камни. Ракушка трескается, и чайка спускается за обедом. А ещё чайки запоминают, где люди едят, и поглядывают на чужие булочки. Не оставляй свой бутерброд без присмотра!", "q": "Как чайка раскалывает ракушку?", "a": [ "Бросает её с высоты на камни", "Прячет её в песок", "Ждёт, пока она сама откроется" ] }, { "id": "cas-b-delfiny", "e": "🐬", "t": "Свист вместо имени", "s": "Из Кашкайша выходят лодки смотреть на дельфинов. Они живут в океане недалеко от берега и любят плыть вровень с носом лодки, выпрыгивая из воды. У каждого дельфина есть свой особенный свист, как у нас имя. Услышав его, друзья понимают, кто их зовёт. Дельфины встречаются не каждый день, поэтому все на лодке смотрят на волны и ждут, не мелькнёт ли серая спинка.", "q": "Как дельфины узнают друг друга?", "a": [ "По особому свисту", "По запаху хвоста", "По цвету пятен" ] }, { "id": "cas-b-prilivy", "e": "🌊", "t": "Море дышит", "s": "Утром на пляже под Кашкайшем лежит широкая полоса мокрого песка, а через несколько часов вода уже подошла к самым скалам. Так бывает дважды в день. Это приливы и отливы. Воду тянет к себе Луна, и огромный океан чуть-чуть поднимается и опускается, как будто дышит. Рыбаки и сёрферы всегда смотрят, когда будет прилив, чтобы не остаться на камнях, когда вода придёт.", "q": "Кто тянет воду, создавая приливы?", "a": [ "Луна", "Подводные вулканы", "Огромные киты" ] }, { "id": "cas-b-luzhi-na-kamnyah", "e": "🦀", "t": "Лужи с сюрпризами", "s": "Когда океан отступает, между камней остаются маленькие лужицы. Для краба это целый дом! Загляни в такую лужу. Там сидят морские анемоны, похожие на цветы, ползёт морская звезда, юркают крошечные рыбки. Все они ждут возвращения воды. Рассматривай их осторожно, не вытаскивай и верни камни на место, ведь под ними чья-то спальня. Лучшее время для охоты за чудесами, это сразу после отлива.", "q": "Кого можно найти в каменных лужах после отлива?", "a": [ "Крабов и морских звёзд", "Пчёл и бабочек", "Лягушек и ужей" ] }, { "id": "cas-b-nortada", "e": "💨", "t": "Ветер с севера", "s": "Летом на побережье возле Кашкайша часто дует сильный ветер. Португальцы зовут его нортада, от слова «норте», то есть «север». Он приходит после обеда, раскидывает пляжные зонты и надувает паруса. Зато с ним не так жарко, он охлаждает берег. А ещё он приносит в океан холодные воды, и поэтому море здесь прохладное даже в самый тёплый день.", "q": "Что значит слово «норте» в португальском?", "a": [ "Север", "Юг", "Парус" ] }, { "id": "cas-b-kajtsurf", "e": "🪁", "t": "Змей над океаном", "s": "Пляж Гинчу недалеко от Кашкайша любят все, кому нужен ветер. В небе над волнами парят огромные яркие змеи, полосатые, зелёные, жёлтые. Под каждым стоит человек на доске, это кайтсерфер. Ветер надувает змей и тянет его вперёд, а вместе с ним и доску по воде. Он может даже прыгать над волнами, как кузнечик. Весь пляж смотрит вверх и смеётся от радости.", "q": "Что тянет кайтсерфера по воде?", "a": [ "Воздушный змей", "Моторчик", "Дельфин" ] }, { "id": "cas-b-parus-na-doske", "e": "🏄", "t": "Парусная доска", "s": "Рядом с серфингом у Гинчу есть ещё одна забава, виндсерфинг. Это доска с мачтой и парусом. Парус не приделан намертво. Его держат руками за дугу и наклоняют вперёд, назад и в стороны. Так можно ловить ветер и поворачивать, как велосипедист рулём. На волнах доска подпрыгивает, а виндсерфер держится и летит над брызгами. Здесь даже проходили большие соревнования.", "q": "Чем управляют парусом на парусной доске?", "a": [ "Наклоняют его руками", "Крутят педали", "Дёргают за хвост" ] }, { "id": "cas-b-karavella", "e": "⛵", "t": "Лёгкая каравелла", "s": "Много лет назад португальские моряки придумали корабли, на которых отправились открывать новые земли. Они назывались каравеллы. Они были небольшими и лёгкими, а паруса на них поднимали треугольные. Такие паруса позволяли плыть не только по ветру, но и немного против него. Поэтому каравеллы могли уходить далеко и возвращаться домой. Сегодня в океане у Кашкайша тоже плавают парусники, только поменьше.", "q": "Какие паруса помогали каравелле идти против ветра?", "a": [ "Треугольные", "Круглые", "В форме сердца" ] }, { "id": "cas-b-zigzag", "e": "🧭", "t": "Зигзаг для парусника", "s": "Ветер дует в лицо, а парусник всё равно плывёт вперёд! Как? Яхтсмены ставят парус под углом и плывут то вправо, то влево, зигзагом, как лыжник, который поднимается в горку «ёлочкой». В конце концов яхта оказывается там, куда надо. В заливе Кашкайша часто видны белые паруса, и со стороны кажется, что яхты танцуют. Просто они ловят ветер так, как им нужно.", "q": "Как парусник идёт против ветра?", "a": [ "Зигзагом, то вправо, то влево", "Строго по прямой", "Задом наперёд" ] }, { "id": "cas-b-probka-v-more", "e": "🍾", "t": "Пробка в море", "s": "Португальцы делают пробку из коры особого дуба. Она лёгкая, как пёрышко, и не тонет. Секрет в том, что внутри пробки миллионы крошечных ячеек с воздухом. Поэтому кусочек пробки держится на воде, как поплавок. Раньше рыбаки привязывали пробки к рыболовным сетям, чтобы те не уходили на дно. А ещё из пробки делают затычки для бутылок, коврики, сумки и даже шляпы.", "q": "Почему пробка не тонет?", "a": [ "Внутри неё много воздуха", "Она приклеена ко дну", "Она тяжелее воды" ] }, { "id": "cas-b-probkovyj-dub", "e": "🌳", "t": "Дуб без рубашки", "s": "В португальских лесах растут пробковые дубы. Раз в девять лет с них аккуратно снимают кору, словно рубашку. Дереву от этого не больно, оно просто растёт дальше и отращивает новую кору. На стволе, который только что раздели, пишут белой краской последнюю цифру года. Так все знают, когда ждать следующего урожая. Голый ствол сначала оранжевый, а потом снова темнеет.", "q": "Как часто снимают кору с дуба?", "a": [ "Раз в девять лет", "Каждую неделю", "Раз в сто лет" ] }, { "id": "cas-b-oblako-na-gore", "e": "☁️", "t": "Облако в гостях у Синтры", "s": "Над горами Синтры часто сидит туман, хотя в Кашкайше светит солнце. Почему так? Влажный воздух с океана добегает до гор, упирается в склоны и поднимается вверх. Там он остывает, и из него получаются облака. Поэтому в лесах Синтры всегда сыро и прохладно. На камнях лежит мягкий мох, а между деревьев растут папоротники, и всё похоже на сказочные джунгли.", "q": "Почему на горах Синтры часто бывает туман?", "a": [ "Горы ловят влажный воздух с океана", "Из трубы выходит дым", "Туман приносят птицы" ] }, { "id": "cas-b-evkalipt", "e": "🍃", "t": "Дерево из Австралии", "s": "Если пройтись по холмам возле Кашкайша, вдруг запахнет, как от леденцов от кашля. Это эвкалипты. Они не португальские, их привезли из далёкой Австралии. Деревья растут быстро, тянутся вверх, а листья у них длинные и узкие и свисают вниз. Правда, коал в Португалии нет. Они едят только листья своих австралийских эвкалиптов и сюда не приехали.", "q": "Из какой страны привезли эвкалипты?", "a": [ "Из Австралии", "Из Норвегии", "Из Монголии" ] }, { "id": "cas-b-sosny-zontiki", "e": "🌲", "t": "Сосны-зонтики", "s": "В парке Синтра-Кашкайш растут сосны с широкой плоской кроной, как зонтик от солнца. Это пинии. В их больших шишках прячутся орешки, и их называют пиниевыми. Орешки созревают очень медленно, около трёх лет! Достать их из шишки не так просто, скорлупа твёрдая. Зато в Португалии орешки добавляют в сладости и пироги. А в тени под такой сосной в жару приятно отдыхать.", "q": "Что прячется в шишках пинии?", "a": [ "Пиниевые орешки", "Жёлуди", "Каштаны" ] }, { "id": "cas-b-golubaya-soroka", "e": "🐦", "t": "Голубая сорока", "s": "В сосновых и дубовых рощах Португалии живёт красивая птица, голубая сорока. У неё чёрная шапочка, как у школьника, а крылья и длинный хвост нежно-голубые. Они держатся шумными стайками и громко перекликаются, как болтливые подружки. Самое удивительное, что близкая родственница этой птицы живёт в Восточной Азии, за тысячи километров. Почему так вышло, учёные до сих пор обсуждают.", "q": "Какого цвета крылья у голубой сороки?", "a": [ "Голубые", "Красные", "Золотистые" ] }, { "id": "cas-b-dyuny-dorozhki", "e": "🏖️", "t": "Дорожки в дюнах", "s": "Возле Кашкайша, в дюнах Кресмины, лежат деревянные дорожки. Они нужны, чтобы люди не ходили по песку и не топтали растения. Ведь песок не убегает от ветра только потому, что его держат корни трав. Корни как невидимая сеть. Если траву вытоптать, ветер раздует дюну. Идёшь по доскам, а по сторонам цветут маленькие цветы и пробегают ящерицы. Красиво и ничего не сломано.", "q": "Что удерживает песок на дюне?", "a": [ "Корни растений", "Тяжёлые камни", "Забор из сетей" ] }, { "id": "cas-b-volny-puteshestvenniki", "e": "🌐", "t": "Волны-путешественницы", "s": "Большие волны у Кашкайша приходят издалека. Где-то посреди Атлантики, за тысячи километров, штормовой ветер взбивает воду. Волны выбегают оттуда и катятся к берегу много дней. Когда они доходят до Португалии, шторма уже нет, а волны остаются, ровные и длинные. Именно такие любят сёрферы. Можно сказать, что каждая волна на пляже, это письмо из океана.", "q": "Откуда приходят длинные океанские волны?", "a": [ "От далёких штормов в океане", "От проплывающих лодок", "От больших рыб" ] }, { "id": "cas-b-flagi-na-plyazhe", "e": "🚩", "t": "Флаги на пляже", "s": "На пляжах Португалии развеваются флажки. Зелёный означает, что купаться можно. Жёлтый, что лучше зайти только по колено. Красный, что в воду нельзя, волны слишком большие. Спасатели следят за морем и вовремя меняют флаг. Есть ещё синий флаг. Его дают пляжам, где проверяют чистоту воды и заботятся о природе. Если увидел такой, значит, здесь следят за порядком и за морем.", "q": "Что значит синий флаг на пляже?", "a": [ "Чистая вода и забота о природе", "Здесь продают мороженое", "Пляж только для лодок" ] }, { "id": "cas-b-bola-de-berlin", "e": "🍩", "t": "Пончик с пляжа", "s": "По песку ходит продавец с большой корзиной и кричит: «Болаш де Берлин!» Так называют круглые жареные пончики. Их посыпают сахаром, а внутри прячется сладкий яичный крем. Название можно перевести как «берлинские шарики», хотя пекут их по всей Португалии. Для ребят на пляже это настоящий праздник. Только руки потом нужно вытереть, а то песок прилипнет к сахару и придётся его разгонять.", "q": "Что внутри пончика «бола де Берлин»?", "a": [ "Сладкий крем", "Селёдка", "Горох" ] }, { "id": "cas-b-travesseiro", "e": "🥐", "t": "Подушечки из Синтры", "s": "В городке Синтра, рядом с Кашкайшем, пекут слоёные пирожные травессейру. Слово значит «подушка». Тесто раскатано тонко-тонко, свёрнуто конвертом, внутри миндальный крем с яйцом, а снаружи сахар. Получается хрустящая подушечка, которая тает во рту. После прогулки по лесам Синтры такое угощение особенно вкусно. Только не торопись, крошки сыплются повсюду, и голуби уже ждут.", "q": "Что значит слово «травессейру»?", "a": [ "Подушка", "Кораблик", "Ключик" ] }, { "id": "cas-b-kaldu-verdi", "e": "🥬", "t": "Зелёный суп", "s": "Португальцы варят суп, который называется «кальду верде», то есть «зелёный бульон». Его готовят из картошки и тёмно-зелёной капусты кале. Капусту режут очень-очень тонко, почти как нитки, и опускают в суп в самом конце. Сверху иногда кладут тонкий кружок колбасы и капают немного масла. Подают его горячим, с хлебом. Хорошо согреться таким супом после прохладного ветра с океана.", "q": "Из какой зелени варят «кальду верде»?", "a": [ "Из капусты кале", "Из листьев мяты", "Из еловых иголок" ] }, { "id": "cas-b-osminog", "e": "🐙", "t": "Осьминог с тремя сердцами", "s": "В скалах у побережья Португалии прячутся осьминоги. У них восемь рук и целых три сердца! Два гоняют кровь к жабрам, а одно по всему телу. Кровь у осьминога голубоватая. Он очень умный: умеет открывать банки, находить дорогу и менять цвет, чтобы слиться с камнями. Днём он обычно отдыхает в норке, а выходит ловить крабов, когда на берегу уже темнеет.", "q": "Сколько сердец у осьминога?", "a": [ "Три", "Одно", "Восемь" ] }, { "id": "cas-c-santini-ice-cream", "e": "🍦", "t": "Мороженое Сантини", "s": "В 1949 году итальянец Аттилио Сантини открыл на пляже Тамариш, рядом с Кашкайшем, маленькую лавку мороженого. Потом такая же лавка появилась и в самом Кашкайше. Мороженое так понравилось людям, что в жаркие дни у прилавка выстраивается очередь. Семья говорит, что делает его по тем же рецептам, что и много лет назад. А вкусов там столько, что глаза разбегаются: шоколад, ягоды, лимон.", "q": "Из какой страны приехал Аттилио Сантини?", "a": [ "Из Италии", "Из Норвегии", "Из Японии" ] }, { "id": "cas-c-king-of-may", "e": "👑", "t": "Король мая", "s": "Умберто Второй был королём Италии всего чуть больше месяца, весной 1946 года. Поэтому его и прозвали «королём мая». Потом он уехал жить в Португалию, в Кашкайш, и жил там много лет. Для него построили дом и назвали его «Вилла Италия». Сегодня в этом доме гостиница, и туристы могут в нём остановиться, как когда-то жил настоящий король.", "q": "Как прозвали короля Умберто Второго?", "a": [ "Королём мая", "Королём осени", "Королём зимы" ] }, { "id": "cas-c-king-luis-shakespeare", "e": "🎻", "t": "Король, который переводил Шекспира", "s": "Король Луиш Первый любил музыку и книги. Он играл на виолончели, а ещё переводил на португальский язык пьесы англичанина Шекспира, например «Гамлета». Лето королевская семья проводила в Кашкайше, у океана. Вот какой был король: днём государственные дела, а вечером виолончель и слова великого писателя, которые нужно было красиво пересказать по-португальски.", "q": "Чьи пьесы переводил король Луиш?", "a": [ "Шекспира", "Гоголя", "Астрид Линдгрен" ] }, { "id": "cas-c-king-carlos-painter", "e": "🎨", "t": "Король-художник", "s": "Король Карлуш Первый любил не только изучать море, но и рисовать его. Он писал картины красками и особенно охотно рисовал берег, лодки и волны. Его картины показывали на выставках, а ещё король изучал море и его обитателей, как настоящий учёный. Король жил летом в Кашкайше и мог рисовать то, что видел из окна: синий океан, белые паруса и рыбачьи лодки у берега.", "q": "Что особенно любил рисовать король Карлуш?", "a": [ "Берег, лодки и волны", "Снежные горы", "Пустыню с верблюдами" ] }, { "id": "cas-c-cable-telegram", "e": "⚡", "t": "Телеграмма по дну океана", "s": "В 1870 году в Каркавелуш, рядом с Кашкайшем, на берег вышел длинный кабель. Он лежал на дне моря и соединял Португалию с Англией. По нему бежали телеграммы: точки и тире, быстрее любого корабля. Когда кабель открывали, король Луиш и английская королева Виктория обменялись телеграммами. Потом от Каркавелуша кабели пошли дальше в мир.", "q": "Где лежал телеграфный кабель между Португалией и Англией?", "a": [ "На дне моря", "На столбах над горами", "В небе на воздушных шарах" ] }, { "id": "cas-c-senna-estoril", "e": "🏎️", "t": "Гонка под дождём", "s": "Рядом с Кашкайшем, в Эшториле, есть гоночная трасса. В 1985 году там лил сильный ливень, а бразильский гонщик Айртон Сенна всё равно приехал первым и обогнал остальных больше чем на минуту. Это была его самая первая победа в больших гонках «Формулы-1». Трасса работает и сегодня: там проходят соревнования, а рядом шумит океан.", "q": "Из какой страны был гонщик Айртон Сенна?", "a": [ "Из Бразилии", "Из Финляндии", "Из Австралии" ] }, { "id": "cas-c-game-macaca", "e": "🐵", "t": "Классики с обезьянкой", "s": "Португальские дети играют в классики, и называется эта игра «макака», то есть «обезьяна». Мелом на плитке рисуют клетки с цифрами, бросают камешек и прыгают на одной ноге из клетки в клетку. Играют на площадях и дорожках рядом с пляжем. Выигрывает тот, кто дошёл до конца и ни разу не наступил на линию.", "q": "Какое животное спрятано в названии португальских классиков?", "a": [ "Обезьяна", "Лошадь", "Кошка" ] }, { "id": "cas-c-game-piao", "e": "🪀", "t": "Волчок с верёвкой", "s": "В Португалии любят старую игру с деревянным волчком. Он называется «пиао». Ребёнок крепко наматывает на волчок верёвку, бросает его на землю и дёргает за конец, и волчок начинает крутиться! Можно устроить состязание: чей волчок крутится дольше. Такие игрушки продают в лавочках с сувенирами, и многие бабушки и дедушки помнят их с детства.", "q": "Что наматывают на волчок, чтобы он закрутился?", "a": [ "Верёвку", "Бумажную ленту", "Мокрую губку" ] }, { "id": "cas-c-berlin-balls", "e": "🍩", "t": "Берлинские шарики на пляже", "s": "Летом по пляжам ходят продавцы с большими корзинами и громко кричат: «Болаш де Берлин!» Так по-португальски называют мягкие пончики, посыпанные сахаром. Название значит «берлинские шарики». Пончик разрезают, и внутри обычно прячется сладкий жёлтый крем. Дети в Кашкайше любят их есть прямо на песке, вытирая сахар с носа.", "q": "Что обычно прячется внутри такого пончика?", "a": [ "Сладкий крем", "Солёная рыба", "Варёная картошка" ] }, { "id": "cas-c-obrigado", "e": "🙏", "t": "Спасибо для мальчиков и девочек", "s": "По-португальски «спасибо» говорят по-разному, смотря кто говорит. Мальчик и мужчина скажут «обригаду», а девочка и женщина — «обригада». Слово слегка меняется на конце. Так что в кафе в Кашкайше по одному этому слову сразу ясно, мальчик перед вами или девочка. Хорошо, что это самое важное слово, и выучить его просто.", "q": "Как скажет «спасибо» девочка по-португальски?", "a": [ "Обригада", "Грацие", "Данке" ] }, { "id": "cas-c-pao-por-deus", "e": "🎒", "t": "Хлеб ради Бога", "s": "Первого ноября в Португалии дети ходят по домам с тканевыми мешочками и просят: «Пан-пур-Деуш!», что значит «хлеб ради Бога». Хозяева кладут им в мешочки орехи, фрукты, булочки и сладости. Обычай очень старый. Кое-где дети хранят его и сегодня, и вечером им есть что показать родителям и пересчитать.", "q": "В какой день дети просят «хлеб ради Бога»?", "a": [ "Первого ноября", "Первого июня", "В новогоднюю ночь" ] }, { "id": "cas-c-sao-martinho", "e": "🌰", "t": "Каштаны святого Мартина", "s": "Одиннадцатого ноября в Португалии празднуют день святого Мартина. На улицах жарят каштаны и продают их горячими в бумажных кульках. Тёплые руки, сладкий запах дыма — вот что вспоминают дети. В эти дни часто бывает по-летнему тепло, и португальцы даже называют это время «летом святого Мартина». Каштаны можно есть, пока сидишь на скамейке у моря.", "q": "Что жарят на улицах в день святого Мартина?", "a": [ "Каштаны", "Бананы", "Апельсины" ] }, { "id": "cas-c-june-sardines", "e": "🐟", "t": "Июньские сардины", "s": "В июне по всей Португалии, и в Кашкайше тоже, идут праздники в честь святых: Антония, Иоанна и Петра. На улицах вешают бумажные гирлянды, а во дворах жарят на углях сардины. Свежую рыбку кладут прямо на ломоть хлеба, и сок впитывается в мякиш. Это очень вкусно. Дети бегают среди столов и ждут, когда им дадут кусочек.", "q": "Какую рыбу жарят на июньских праздниках?", "a": [ "Сардины", "Акул", "Щук" ] }, { "id": "cas-c-manjerico", "e": "🌿", "t": "Горшочек с душистым базиликом", "s": "На июньские праздники португальцы дарят друг другу «манжерику» — маленький горшочек с душистым базиликом. В землю втыкают бумажную гвоздику, а к ней прикрепляют короткое стихотворение: тёплые слова или шутку. Базилик не едят, его осторожно нюхают: достаточно провести рукой по листьям, и пахнет на весь двор. Такой горшочек ставят на подоконник.", "q": "Что растёт в горшочке манжерику?", "a": [ "Базилик", "Кактус", "Картошка" ] }, { "id": "cas-c-bolo-rei", "e": "🥧", "t": "Пирог-корона", "s": "К Рождеству в Португалии пекут «боло-рей», что значит «королевский пирог». Он круглый, с дыркой посередине, как корона, и усыпан цукатами и орехами. В тесто прячут фасолину, а раньше и маленький подарок. Кому достанется фасолина, тот должен на следующий год купить такой же пирог. Поэтому все едят осторожно и заглядывают в каждый кусок.", "q": "На что похож рождественский пирог «боло-рей»?", "a": [ "На корону", "На башню", "На лодку" ] }, { "id": "cas-c-janeiras", "e": "🎶", "t": "Песни у дверей", "s": "В начале января в Португалии люди ходят от дома к дому и поют новогодние песни, которые называются «жанейраш». Это старый обычай. Хозяева открывают дверь, слушают и угощают гостей сладостями или чем-нибудь тёплым. Иногда поют целыми компаниями: дети, мамы, дедушки. Песни про добрый год и про то, чтобы в доме всегда было что поесть.", "q": "Что делают люди в Португалии, когда ходят по домам в январе?", "a": [ "Поют песни", "Запускают воздушных змеев", "Катаются на санях" ] }, { "id": "cas-c-calceteiro", "e": "🔨", "t": "Мастер мостовой", "s": "Мостовые Кашкайша выложены вручную. Мастер садится на корточки с маленьким молотком и берёт камешки: белые из известняка и чёрные из базальта. Он кладёт их в песок один к одному и постукивает, пока камень не встанет ровно. Так на площадях получаются узоры: волны, рыбы, корабли и звёзды. Работа медленная, а ходить по картинам можно сколько угодно.", "q": "Какого цвета камешки кладёт мастер мостовой?", "a": [ "Белые и чёрные", "Красные и синие", "Зелёные и золотые" ] }, { "id": "cas-c-cork", "e": "🌳", "t": "Кора, которая вырастает снова", "s": "Пробка — это кора особого дуба, пробкового. Раз в девять лет мастера осторожно снимают кору топориками, а дерево не болеет и растит новую. Из пробки делают не только затычки для бутылок, но и сумки, кошельки, шляпы и даже обувь. Лёгкую и тёплую пробку в магазинах Португалии, в том числе в Кашкайше, можно потрогать руками и убедиться, какая она мягкая.", "q": "Как часто с дуба снимают пробковую кору?", "a": [ "Раз в девять лет", "Каждый день", "Раз в сто лет" ] }, { "id": "cas-c-festival-sea-procession", "e": "⛵", "t": "Праздник моря", "s": "В конце лета в Кашкайше идёт праздник моря. Главный день — шествие рыбаков. Статую Богоматери Мореплавателей несут к пляжу Рибейра, ставят на рыбацкую лодку, и нарядные лодки выходят в море. Люди смотрят с берега и машут, а рыбаки в этот день особенно гордятся своей работой. В 2023 году это шествие объявили частью культурного наследия страны.", "q": "На чём плывёт статуя Богоматери Мореплавателей?", "a": [ "На рыбацкой лодке", "На поезде", "На воздушном шаре" ] }, { "id": "cas-c-name-shells", "e": "🐚", "t": "Откуда имя Кашкайш", "s": "Откуда взялось название города, точно никто не знает. Есть красивая версия: оно от португальского слова «каскаш», то есть «ракушки». Когда-то на берегу лежали целые груды пустых ракушек, и люди назвали место по ним. Хорошо верить, что так и было. Теперь на песке Кашкайша можно найти ракушки и самому, и положить в карман на память.", "q": "Какое слово, по одной из версий, дало имя Кашкайшу?", "a": [ "Ракушки", "Яблоки", "Перья" ] }, { "id": "cas-c-bike-path", "e": "🚲", "t": "Велодорожка к океану", "s": "От кашкайшской гавани идёт велодорожка вдоль берега. Она длиной около десяти километров и почти без подъёмов, так что ехать легко даже тем, кто только недавно научился. По дороге видны скалы, волны и чайки, а в конце ждёт большой пляж Гинчу, где всегда дует ветер. Велосипед можно взять напрокат, и отдыхать по дороге удобно на скамейках.", "q": "Куда приводит велодорожка из Кашкайша?", "a": [ "К пляжу Гинчу", "К снежной горе", "В соседнюю страну" ] }, { "id": "cas-c-green-soup", "e": "🥣", "t": "Зелёный суп", "s": "Один из самых любимых португальских супов называется «кальду верде», то есть «зелёный суп». В нём картошка, оливковое масло и особая капуста, которую режут очень-очень тонкими лентами, почти как нитки. Иногда сверху кладут кружочек колбасы. Суп любят и дети, и взрослые. Его подают на праздниках и дома, а по вечерам в кафе Кашкайша он согреет после ветра с океана.", "q": "Какой овощ режут тонкими лентами для зелёного супа?", "a": [ "Капусту", "Огурец", "Свёклу" ] }, { "id": "cas-c-entrudo", "e": "💦", "t": "Праздник брызг", "s": "Давным-давно перед Великим постом в Португалии праздновали «энтрудо». Люди выходили на улицы и веселились: брызгали друг на друга водой, сыпали муку и бросали маленькие мешочки. Никто не сердился: все были мокрые и смеющиеся. Потом этот шумный праздник стал более спокойным карнавалом, где дети надевают костюмы и маски, а взрослые наряжают целые улицы.", "q": "Чем веселились люди на старом празднике «энтрудо»?", "a": [ "Брызгали водой и сыпали муку", "Катались с горок", "Пускали воздушных змеев" ] }, { "id": "cas-c-folar", "e": "🥚", "t": "Пасхальный хлеб с яйцом", "s": "На Пасху в Португалии пекут «фолар» — сладкий или солёный хлеб с сюрпризом. В тесто кладут целое яйцо прямо в скорлупе, а сверху лепят крест из теста. Яйцо запекается вместе с хлебом и получается крепким. В некоторых семьях такой хлеб дарят крестникам. Дети с радостью разглядывают румяную корочку и ищут, где спрятано яйцо.", "q": "Что запекают в португальском пасхальном хлебе «фолар»?", "a": [ "Целое яйцо", "Целую рыбку", "Конфету" ] }, { "id": "cas-c-st-anthony-fish", "e": "🐠", "t": "Святой, который говорил с рыбами", "s": "Святой Антоний родился в Лиссабоне, и в Португалии его очень любят. Есть старая легенда: когда люди на берегу не хотели его слушать, он повернулся к воде и стал говорить с рыбами. Рыбы будто бы подняли головы из воды, чтобы слушать. В июне в его день устраивают праздник с гирляндами и угощением, а рыбаки Кашкайша вспоминают эту историю с улыбкой.", "q": "Кого, по легенде, слушал святой Антоний у воды?", "a": [ "Рыб", "Лебедей", "Обезьян" ] }, { "id": "cas-c-rooster-legend", "e": "🐓", "t": "Петух, который закукарекал", "s": "В Португалии продают расписных петухов: глиняных, деревянных, на магнитах. За ними стоит легенда. Путника несправедливо обвинили в краже, а он сказал судье: «Я невиновен, и вот знак: этот жареный петух на столе закукарекает». Судья с гостями рассмеялись, но петух вскочил и закукарекал! Путника отпустили. С тех пор петух — знак удачи и честности.", "q": "Что сделал жареный петух из легенды?", "a": [ "Закукарекал", "Улетел в окно", "Заговорил" ] }, { "id": "cas-c-two-surnames", "e": "📛", "t": "Две фамилии", "s": "В Португалии у человека обычно не одна фамилия, а несколько. Одну он получает от мамы, другую от папы, а иногда и больше. Поэтому полное имя может быть очень длинным. В школе в Кашкайше учитель записывает его целиком, и дети гордятся, что в их имени живут сразу и мама, и папа, а, может быть, и бабушки с дедушками.", "q": "От кого ребёнок в Португалии обычно получает фамилии?", "a": [ "От мамы и от папы", "От соседей", "От учителя" ] } ], "lisbon": [ { "id": "lis-bertrand", "e": "📚", "t": "Самый старый книжный магазин", "s": "В Лиссабоне, в районе Шиаду, есть книжный магазин «Бертран». Он открылся в 1732 году и продаёт книги уже почти триста лет! Книга рекордов Гиннесса назвала его самым старым работающим книжным магазином в мире. Внутри несколько комнат, одна за другой, и везде полки с книгами. Когда магазин открылся, ещё не было электричества, и книги читали при свечах.", "q": "Каким назвали книжный магазин «Бертран»?", "a": [ "Самым старым в мире", "Самым мокрым в мире", "Самым колючим в мире" ] }, { "id": "lis-fado", "e": "🎸", "t": "Песни фаду", "s": "По вечерам в старых кварталах Лиссабона звучат песни фаду. Поёт один певец или певица, а рядом играют гитаристы. Одна гитара особенная, португальская: она похожа на грушу, и у неё двенадцать струн. Песни фаду грустные и красивые — о море, о доме и о тех, по кому скучают. В 2011 году фаду назвали сокровищем всего человечества.", "q": "На что похожа португальская гитара?", "a": [ "На грушу", "На сосиску", "На табуретку" ] }, { "id": "lis-gulbenkian", "e": "🦆", "t": "Утки в саду Гюльбенкяна", "s": "В Лиссабоне жил человек по имени Галуст Гюльбенкян. Всю жизнь он собирал красивые вещи: картины, вазы, ковры и украшения. Свою коллекцию он оставил Португалии, и теперь в Лиссабоне есть его музей. Вокруг музея растёт большой сад с прудом, где плавают утки и рыбки. Кормить их нельзя, зато можно тихонько смотреть, как утки плавают и чистят пёрышки.", "q": "Кто плавает в пруду у музея Гюльбенкяна?", "a": [ "Утки и рыбки", "Табуретки и стулья", "Кастрюли и сковородки" ] }, { "id": "lis-aqueduto", "e": "💧", "t": "Каменная дорога для воды", "s": "Почти триста лет назад в Лиссабоне не хватало чистой воды. Тогда построили акведук Агуаш-Ливреш, что значит «Свободные воды». Это длинный каменный мост, только по нему ездят не машины: внутри по каменному жёлобу течёт вода. Через долину акведук шагает на высоких арках, как великан на ходулях, и самая большая арка выше двадцатиэтажного дома. Даже в сильное землетрясение 1755 года акведук устоял.", "q": "Что течёт внутри акведука?", "a": [ "Вода", "Компот", "Лимонад" ] }, { "id": "lis-padrao", "e": "🧭", "t": "Карта мира под ногами", "s": "В районе Белен на берегу реки Тежу стоит огромный светлый памятник, похожий на нос корабля. Это Памятник первооткрывателям: на нём из камня высечены мореплаватели, а впереди всех стоит Генрих Мореплаватель с маленьким кораблём в руках. Перед памятником на земле выложена огромная роза ветров — звезда, которая показывает, где север и юг. В её середине карта мира, и по ней можно ходить. От Португалии до Бразилии тут всего несколько шагов!", "q": "Что выложено на земле перед памятником?", "a": [ "Роза ветров и карта мира", "Огромная яичница", "Гигантский носок" ] }, { "id": "lis-telecabine", "e": "🚡", "t": "Кабинки над рекой", "s": "В Парке Наций маленькие кабинки висят на канате и едут вдоль реки Тежу. Эту канатную дорогу построили в 1998 году к большой всемирной выставке. В кабинках стеклянные окошки, и сверху видно реку, корабли и очень длинный мост Васко да Гама. Кабинки плывут по воздуху медленно, как облачка. Поездка длится всего около десяти минут, но кажется, будто летишь.", "q": "На чём висят кабинки канатной дороги?", "a": [ "На канате", "На макаронине", "На бельевой прищепке" ] }, { "id": "lis-colinas", "e": "⛰️", "t": "Город на семи холмах", "s": "Говорят, что Лиссабон стоит на семи холмах, как древний Рим. Поэтому в городе так много лестниц и крутых улиц. Чтобы не уставать, люди поднимаются наверх на трамваях, фуникулёрах и даже на лифтах. Зато с вершин открывается чудесный вид, и такие смотровые площадки называют мирадору. Сверху город похож на рассыпанные разноцветные кубики, а за ними блестит река.", "q": "На скольких холмах, говорят, стоит Лиссабон?", "a": [ "На семи", "На тысяче", "На полутора" ] }, { "id": "lis-tejo", "e": "🐬", "t": "Река Тежу", "s": "Лиссабон стоит на берегу реки Тежу. Это самая длинная река на полуострове, где лежат Испания и Португалия. Она начинается далеко в горах Испании, а возле Лиссабона разливается так широко, что похожа на море. Это место даже называют Соломенным морем. А летом в реку иногда заплывают из океана дельфины!", "q": "Кто летом иногда заплывает в реку Тежу?", "a": [ "Дельфины", "Жирафы", "Верблюды" ] }, { "id": "lis-calcada", "e": "🪨", "t": "Каменные волны", "s": "Тротуары Лиссабона выложены маленькими камешками, белыми и чёрными. Мастера укладывают их руками, камешек к камешку, как мозаику, а называется такая мостовая калсада. На площади Росиу из камешков сложены чёрные и белые волны. Идёшь по ним, и кажется, будто земля качается, как палуба корабля! Похожие волны потом выложили и в Бразилии, на знаменитом пляже Копакабана.", "q": "Что сложено из камешков на площади Росиу?", "a": [ "Волны", "Пельмени", "Носки" ] }, { "id": "lis-coches", "e": "🐎", "t": "Королевские кареты", "s": "В лиссабонском районе Белен есть Музей карет. Его открыла в 1905 году королева Амелия, жена короля Карлуша. Здесь стоят настоящие королевские кареты: золочёные, с резными фигурами и мягкими сиденьями. В такую карету запрягали несколько лошадей. Это одна из самых больших коллекций карет в мире, и кажется, что сейчас из кареты выйдет Золушка!", "q": "Кто открыл Музей карет?", "a": [ "Королева Амелия", "Кот в сапогах", "Серый волк" ] }, { "id": "lis-b-zemletryasenie-1755", "e": "🌅", "t": "Утро Дня всех святых", "s": "1 ноября 1755 года, утром, под Лиссабоном вздрогнула земля. Это было очень сильное землетрясение, и многие дома старого города рухнули. Но лиссабонцы не сдались: они стали строить город заново. Сегодня мы ходим по улицам, которые появились после того утра. Об этом дне помнят до сих пор, а историки пишут о нём книги.", "q": "В каком году было большое землетрясение в Лиссабоне?", "a": [ "В 1755 году", "В 1255 году", "В 1955 году" ] }, { "id": "lis-b-pombal-novyj-gorod", "e": "📐", "t": "Маркиз и линейка", "s": "После землетрясения главным помощником короля стал маркиз де Помбал. Он придумал отстроить центр Лиссабона по линейке: ровные улицы, как клетки в тетради, и одинаковые высокие дома. Этот район называется Байша, что значит «нижний». Дома делали с прочным деревянным каркасом, чтобы они лучше держали удары земли. Если пройтись по Байше, сразу видно, как ровно всё расчерчено.", "q": "Как по плану Помбала расчертили центр Лиссабона?", "a": [ "Ровными улицами, как клетки в тетради", "Кругами, как на мишени", "Одной длинной спиралью" ] }, { "id": "lis-b-rimskij-olisipo", "e": "🏛️", "t": "Олисипо — римский Лиссабон", "s": "Больше двух тысяч лет назад здесь уже жили люди, а потом пришли римляне. Свой город у реки они называли Олисипо. Римляне строили дороги, бани и даже театр. Остатки этого театра можно увидеть на склоне холма в районе Алфама, рядом со старыми улочками. Так что Лиссабон старше многих городов Европы, и в нём есть камни, которых касались ещё римские мастера.", "q": "Как римляне называли свой город на месте Лиссабона?", "a": [ "Олисипо", "Лютеция", "Помпеи" ] }, { "id": "lis-b-rimskie-galerei", "e": "🔦", "t": "Римские подвалы под улицей", "s": "Прямо под улицами центра Лиссабона спрятаны римские галереи. Это длинные каменные подземные ходы с арками. Их нашли случайно, когда после землетрясения люди рыли землю под новые дома. Историки до сих пор спорят, для чего римляне их построили. Галереи открывают для гостей только в особые дни, поэтому попасть туда — как найти маленький клад под ногами.", "q": "Где находятся римские галереи Лиссабона?", "a": [ "Под улицами центра города", "На вершине самой высокой горы", "На дне океана" ] }, { "id": "lis-b-mavry-zamok", "e": "🏰", "t": "Замок на холме", "s": "Много веков назад в этих местах жили мавры. Они пришли из Северной Африки, привезли новые знания о садах, воде и счёте, а ещё дали португальскому языку много слов. Мавры укрепили холм над городом и построили замок. Теперь его называют замком Сан-Жорже. С его стен видно всю красную черепицу Лиссабона и широкую реку, а по двору гуляют павлины.", "q": "Как называется замок на холме над Лиссабоном?", "a": [ "Замок Сан-Жорже", "Замок Нойшванштайн", "Замок Бран" ] }, { "id": "lis-b-ulisse-legenda", "e": "⛵", "t": "Легенда об Улиссе", "s": "Есть красивая старая легенда: будто город основал сам Улисс, герой древних греческих сказаний, когда плыл домой после долгих странствий. Учёные думают, что это только сказка, а имя города пришло от более древнего слова. Но легенда так нравится жителям, что героя на корабле можно увидеть на старых рисунках и даже в названиях улиц. Сказки тоже часть истории города.", "q": "Какой сказочный герой, по легенде, основал Лиссабон?", "a": [ "Улисс", "Робин Гуд", "Илья Муромец" ] }, { "id": "lis-b-stolica-portugalii", "e": "👑", "t": "Как Лиссабон стал столицей", "s": "Раньше королевский двор жил в другом городе, Коимбре, в самой середине страны. Но около 1255 года король Афонсу Третий решил жить в Лиссабоне. Тут был большой порт, куда заходили корабли, а значит, было много новостей и торговли. С тех пор Лиссабон остаётся главным городом Португалии. Больше семисот лет в нём живут короли, а позже президенты.", "q": "Кто решил сделать Лиссабон столицей около 1255 года?", "a": [ "Король Афонсу Третий", "Король Артур", "Король Людовик" ] }, { "id": "lis-b-sant-antonio", "e": "🕊️", "t": "Антониу из Лиссабона", "s": "Один из самых любимых святых в мире родился в Лиссабоне около 1195 года. Его называют святым Антонием Падуанским, потому что потом он жил в Италии, но лиссабонцы зовут его Антониу и считают своим. В середине июня в городе большой праздник: на улицах горят гирлянды, жарят сардины, а влюблённым дарят горшочки с базиликом и весёлые стихи.", "q": "Что дарят на лиссабонском празднике Святого Антония?", "a": [ "Горшочки с базиликом", "Воздушные шары в форме рыб", "Зонтики" ] }, { "id": "lis-b-zheronimush", "e": "⛪", "t": "Монастырь из пряностей", "s": "В 1501 году король Мануэл Первый начал строить в Белене огромный монастырь Жеронимуш. Деньги на него дала торговля пряностями, которые привозили на кораблях из далёкой Индии. Камень там украшен, будто сказочным резным кружевом: на колоннах вьются каменные канаты, ракушки и морские звери. В церкви монастыря покоится Васко да Гама, а строили монастырь долго, много лет.", "q": "Чем украшен монастырь Жеронимуш?", "a": [ "Каменными канатами и ракушками", "Золотыми колёсами", "Цветными стёклами из пластика" ] }, { "id": "lis-b-genrih-moreplavatel", "e": "🧭", "t": "Принц, который учил корабли", "s": "Принц Энрике родился в Португалии и всю жизнь интересовался морем. Его прозвали Генрихом Мореплавателем, хотя сам он в далёкие плавания почти не ходил. Зато поддерживал капитанов и корабелов, а при нём португальцы стали ходить на лёгких кораблях — каравеллах с косыми парусами. На таких каравеллах португальцы смело шли вдоль берегов Африки и рисовали всё новые карты.", "q": "На каких кораблях плавали португальские мореходы при Генрихе?", "a": [ "На каравеллах", "На пароходах", "На плотах из тростника" ] }, { "id": "lis-b-pamyatnik-otkrytiyam", "e": "🗿", "t": "Каменный корабль у реки", "s": "Над берегом реки Тежу стоит Памятник открытиям. Его построили в 1960 году, когда прошло пятьсот лет после смерти принца Генриха Мореплавателя. Памятник похож на нос огромного корабля, а на нём стоят фигуры мореплавателей, учёных и поэтов. Впереди, с маленьким корабликом в руках, шагает сам принц. Высота памятника — больше пятидесяти метров, как дом в семнадцать этажей.", "q": "На что похож Памятник открытиям?", "a": [ "На нос корабля", "На гигантский колокол", "На ракету" ] }, { "id": "lis-b-diash-mys", "e": "🌊", "t": "Мыс Бурь, который стал мысом Доброй Надежды", "s": "В 1487 году капитан Бартоломеу Диаш вышел из Лиссабона на небольших каравеллах и обогнул самый юг Африки. Бури там были сильными, поэтому он назвал мыс Бурным. Но король Жуан Второй сказал: теперь это дорога в Индию, и она даёт надежду. Так мыс получил имя, которое носит и сегодня, — мыс Доброй Надежды.", "q": "Как король переименовал мыс Бурь?", "a": [ "Мыс Доброй Надежды", "Мыс Тихого Ветра", "Мыс Золотого Солнца" ] }, { "id": "lis-b-kabral-brazilia", "e": "🦜", "t": "Корабли к Бразилии", "s": "В марте 1500 года из Лиссабона вышли тринадцать кораблей. Их вёл капитан Педру Алвариш Кабрал, и плыли они в Индию. Но корабли ушли далеко на запад и в апреле увидели незнакомый зелёный берег. Так португальцы пришли в землю, которую сегодня зовут Бразилией. Поэтому в Бразилии, самой большой стране Южной Америки, говорят по-португальски, как в Лиссабоне.", "q": "На каком языке говорят в Бразилии?", "a": [ "По-португальски", "По-итальянски", "По-японски" ] }, { "id": "lis-b-specii-ploshchad", "e": "🌶️", "t": "Площадь, куда плыли пряности", "s": "Давным-давно на берегу Тежу, там, где теперь большая площадь Праса-ду-Комерсиу, стоял королевский дворец. Рядом был склад, где разгружали товары с кораблей из далёких стран: перец, корицу, гвоздику, шёлк. Тут пахло, как на кухне у бабушки в праздник. Землетрясение 1755 года разрушило дворец, и площадь построили заново, но жители по-прежнему зовут её Терейру-ду-Пасу — «дворцовая площадь».", "q": "Что привозили на кораблях к этой площади?", "a": [ "Перец и корицу", "Лыжи и санки", "Тюльпановые луковицы" ] }, { "id": "lis-b-arka-augusta", "e": "🐎", "t": "Арка и конь на площади", "s": "На площади у реки стоит статуя короля Жозе Первого верхом на коне. Конь поднял копыто, будто хочет шагнуть к воде. А с другой стороны площади — Триумфальная арка на улице Аугуста. Она появилась позже, в 1873 году. Наверх арки можно подняться и посмотреть на крыши, реку и красивую площадь. А отсюда начинается та самая ровная улица Байши.", "q": "Кто сидит на коне на площади у реки?", "a": [ "Король Жозе Первый", "Васко да Гама", "Святой Антоний" ] }, { "id": "lis-b-ajuda-palatka", "e": "🏯", "t": "Дворец-шатёр", "s": "После землетрясения король Жозе Первый, как говорят, боялся жить в каменных дворцах. Ему построили деревянный королевский дворец-шатёр на холме Ажуда, подальше от центра. Позже на этом месте начали строить новый каменный дворец, Ажуда. Его строили долго и так и не закончили до конца. Сегодня он открыт для гостей, и в нём можно увидеть залы, большие люстры и королевскую посуду.", "q": "Из чего построили временный дворец короля Жозе?", "a": [ "Из дерева", "Из льда", "Из стекла" ] }, { "id": "lis-b-karmu-bez-kryshi", "e": "🌤️", "t": "Церковь с небом вместо крыши", "s": "В центре Лиссабона стоит церковь Карму, у которой нет крыши. Высокие каменные арки уходят прямо в небо. Крыша упала во время землетрясения 1755 года, и её так и не восстановили, чтобы помнить о том дне. Теперь внутри музей: там старые каменные гробницы, древние вазы и даже маленькая мумия из далёкой страны. А над головой летают птицы.", "q": "Чего нет у церкви Карму?", "a": [ "Крыши", "Окон", "Двери" ] }, { "id": "lis-b-universitet-1290", "e": "🎓", "t": "Первый университет Португалии", "s": "В 1290 году король Диниш подписал бумагу, и в Лиссабоне открылась первая в Португалии школа для взрослых учёных — университет. Студенты изучали право, медицину и разные науки. Позже университет много раз переезжал между Лиссабоном и Коимброй. Сегодня в Лиссабоне несколько университетов, а студенты в праздники надевают чёрные плащи, как в старину.", "q": "Какой король основал первый университет в Лиссабоне?", "a": [ "Король Диниш", "Король Эдуард", "Король Фридрих" ] }, { "id": "lis-b-vorony-vincent", "e": "🐦‍⬛", "t": "Два ворона на гербе", "s": "На гербе Лиссабона изображены парусный корабль и два ворона. По легенде, всё началось со святого Винсента. Много веков назад его останки везли морем в Лиссабон, а на корабле сидели два ворона и охраняли их. С тех пор вороны — любимые птицы города. Вы можете найти этот герб на фонарях, на городских бумагах и даже на плитке тротуаров.", "q": "Какие птицы изображены на гербе Лиссабона?", "a": [ "Два ворона", "Два аиста", "Две совы" ] }, { "id": "lis-b-pervyj-poezd", "e": "🚂", "t": "Первый поезд Португалии", "s": "В октябре 1856 года из Лиссабона вышел первый поезд Португалии. Он шёл от вокзала Санта-Аполония на север, вдоль реки Тежу, около тридцати шести километров. Люди пришли смотреть и удивлялись: паровоз пыхтел и тащил вагоны быстрее любой лошади. С того дня Португалия стала строить железные дороги, а вокзал Санта-Аполония работает и по сей день.", "q": "Что тащило вагоны первого португальского поезда?", "a": [ "Паровоз", "Лошади", "Быки" ] }, { "id": "lis-b-pessoa-poet", "e": "✒️", "t": "Поэт с множеством имён", "s": "Фернанду Пессоа родился в Лиссабоне в 1888 году и стал самым известным португальским поэтом. Он любил придумывать других писателей и писал стихи под их именами: у каждого был свой характер и своя манера. Таких придуманных поэтов набралось больше семидесяти. Сегодня перед кафе «Бразилейра» в районе Шиаду сидит его бронзовая статуя, и с ним любят фотографироваться туристы.", "q": "Что любил придумывать Фернанду Пессоа?", "a": [ "Других поэтов с разными именами", "Новые страны на карте", "Рецепты пирожных" ] }, { "id": "lis-b-gvozdiki-1974", "e": "🌷", "t": "Революция гвоздик", "s": "25 апреля 1974 года в Португалии произошла мирная революция, которую называют Революцией гвоздик. В тот день жители Лиссабона вышли на улицы, а гвоздик в городе было много: их дарили солдатам, и те вставляли цветы в стволы ружей. Всё прошло мирно. С тех пор 25 апреля — национальный праздник, День свободы, и в этот день по городу носят красные гвоздики.", "q": "Какие цветы стали знаком Революции гвоздик?", "a": [ "Красные гвоздики", "Жёлтые одуванчики", "Белые ромашки" ] }, { "id": "lis-b-grandola-pesnya", "e": "📻", "t": "Песня-сигнал по радио", "s": "Ночью перед Революцией гвоздик по радио прозвучала песня «Грандола, Вила Морена» — второй тайный сигнал. Её написал певец Зека Афонсу. Люди, которые готовили мирные перемены, договорились: когда эта песня зазвучит по радио, пора начинать. Услышав её, все поняли, что утро будет особенным. Сегодня «Грандолу» знают по всей стране, и её поют на праздничных площадях 25 апреля.", "q": "Что стало сигналом к началу Революции гвоздик?", "a": [ "Песня по радио", "Звон колокола", "Праздничный салют" ] }, { "id": "lis-b-most-25-aprelya", "e": "🌉", "t": "Красный мост через Тежу", "s": "Над широкой рекой Тежу висит красный мост. Его открыли в 1966 году, и он очень напоминает мост «Золотые ворота» в Сан-Франциско. После революции 1974 года мост получил новое имя — «Мост 25 апреля». По нему идут поезда и машины, а под ним проходят большие корабли. А рядом на берегу стоит огромная белая статуя Христа с раскрытыми руками.", "q": "Как называется красный мост над Тежу?", "a": [ "Мост 25 апреля", "Мост Вздохов", "Мост Белен" ] }, { "id": "lis-b-ekspo-98", "e": "🎡", "t": "Выставка об океанах", "s": "В 1998 году в Лиссабоне была большая всемирная выставка Экспо. Она рассказывала, как важно беречь океаны. На берегу Тежу построили целый район с павильонами, фонтанами и канатной дорогой над водой. Талисманом выставки был весёлый человечек по имени Жил. Позже этот район назвали Парком наций, и там осталась башня Васко да Гама и океанариум, куда любят ходить дети.", "q": "Какой теме была посвящена выставка Экспо 1998 в Лиссабоне?", "a": [ "Океанам", "Космосу", "Динозаврам" ] }, { "id": "lis-b-blochinyj-rynok", "e": "🧸", "t": "Рынок, которому сотни лет", "s": "Недалеко от монастыря Сан-Висенте рядом с Алфамой проходит Фейра-да-Ладра, блошиный рынок. Он работает по вторникам и субботам, а торговали здесь ещё много веков назад. На прилавках лежат старые часы, пуговицы, плитка азулежу, пластинки и фарфоровые куклы. Каждая вещь будто хранит свою историю. Продавцы любят рассказывать, откуда она, а покупатели — торговаться и шутить.", "q": "В какие дни работает блошиный рынок Ладра?", "a": [ "По вторникам и субботам", "Только в Новый год", "Каждую ночь" ] }, { "id": "lis-c-treska", "e": "🐟", "t": "Рыба, которая спит в соли", "s": "В Лиссабоне любят рыбу баккалау. Это треска, которую сначала засолили и высушили. На прилавке такая рыба лежит твёрдая, как доска, и почти не пахнет. Перед готовкой её долго мочат в воде, и она снова становится мягкой. Говорят, у португальцев столько рецептов баккалау, что хватит на каждый день года: рыбу жарят, запекают, варят с картошкой и лепят из неё пышные котлетки.", "q": "Что делают с высушенной треской перед готовкой?", "a": [ "Долго мочат в воде", "Сразу кладут в мороженое", "Раскрашивают красками" ] }, { "id": "lis-c-sardiny", "e": "🔥", "t": "Праздник сардин", "s": "Двенадцатого и тринадцатого июня Лиссабон празднует день святого Антония, который родился в этом городе. На улицах дымятся маленькие грили, и на ломтик хлеба кладут свежую жареную сардину. Дома украшены бумажными гирляндами и цветами, а люди гуляют допоздна. Есть сардину принято прямо с хлебом: сок от рыбы впитывается, и получается очень вкусно.", "q": "На чём в праздник подают жареную сардину?", "a": [ "На ломтике хлеба", "На блине с вареньем", "На палочке от мороженого" ] }, { "id": "lis-c-marshi", "e": "🎉", "t": "Парад кварталов", "s": "Каждый год в ночь на тринадцатое июня районы Лиссабона выходят на свои народные марши. Это не военный парад, а весёлое шествие с песнями и танцами. Люди в ярких костюмах несут арки из бумажных цветов и идут по широкой улице Авенида-да-Либердаде. Каждый квартал придумывает свою песню и свой наряд, а потом все смотрят, чей номер получился лучше. К шествию готовятся заранее и очень старательно.", "q": "Что придумывает для парада каждый квартал?", "a": [ "Свою песню и свой наряд", "Новый светофор", "Торт на колёсах" ] }, { "id": "lis-c-zelenyj-sup", "e": "🥣", "t": "Зелёный суп", "s": "Самый известный лиссабонский суп называется «калду верде», то есть «зелёный бульон». Его варят из картошки и тёмно-зелёной капусты, которую режут тонкими-тонкими полосками. Суп выходит густой и тёплый. Сверху кладут кружочек колбасы и капельку оливкового масла. Его часто едят вечером, и взрослые, и дети.", "q": "Из какого овоща суп зелёный?", "a": [ "Из капусты", "Из огурца", "Из свёклы" ] }, { "id": "lis-c-kofe-bika", "e": "☕", "t": "Кофейные слова", "s": "В кафе Лиссабона у кофе свои названия. Маленькую чашку крепкого эспрессо здесь зовут «бика». Кофе с молоком в высоком стакане называют «галан». А «мейя де лейте» — это половина кофе и половина молока, самый мягкий вариант. Дети обычно просят какао, а рядом на блюдце лежит пирожное. Утром в таком кафе обычно многолюдно.", "q": "Что такое «бика» в лиссабонском кафе?", "a": [ "Маленький крепкий эспрессо", "Большой торт", "Стакан сока" ] }, { "id": "lis-c-kashtany", "e": "🌰", "t": "Каштаны в бумажных кульках", "s": "Осенью на улицах Лиссабона стоят продавцы жареных каштанов. Над маленькой жаровней вьётся дымок и вкусно пахнет. Каштаны насыпают в бумажный кулёк, они горячие-прегорячие, и держать их надо осторожно. Одиннадцатого ноября в Португалии отмечают день святого Мартина: тогда принято есть каштаны и греться у огня. Скорлупу сначала чистят, а внутри мягкая жёлтая мякоть.", "q": "Что продают осенью из маленькой жаровни?", "a": [ "Жареные каштаны", "Мороженое", "Арбузы" ] }, { "id": "lis-c-pirog-korona", "e": "👑", "t": "Пирог-корона", "s": "На Рождество в лиссабонских пекарнях выставляют «болу-рей», что значит «королевский пирог». Он круглый, с дыркой посередине, и похож на корону. Сверху его украшают сахаром и засахаренными фруктами, будто драгоценными камнями. Режут такой пирог по кругу, на много ломтиков, чтобы хватило всей семье. Получается настоящий праздничный стол.", "q": "На что похож рождественский королевский пирог?", "a": [ "На корону", "На квадратную коробку", "На длинный батон" ] }, { "id": "lis-c-zoopark-kanatka", "e": "🚠", "t": "Канатка над зоопарком", "s": "В Лиссабоне есть зоопарк, и ему больше ста сорока лет: он открылся в 1884 году. Чтобы осмотреть его с высоты, можно прокатиться на канатной дороге. Маленькая кабинка плывёт над дорожками и вольерами, и сверху видно жирафов, зебр и других зверей. Хорошо показывать пальцем вниз и угадывать, кто там гуляет.", "q": "Как в лиссабонском зоопарке можно увидеть зверей сверху?", "a": [ "Прокатиться на канатной дороге", "Залезть на пальму", "Взлететь на воздушном шаре" ] }, { "id": "lis-c-nauka-dlya-detej", "e": "🔬", "t": "Музей, где всё можно трогать", "s": "В Лиссабоне, на берегу реки Тежу, стоит научный музей «Павильон знания». Почти всё там разрешено трогать руками. Дети нажимают на кнопки, крутят рычаги, строят из больших деталей и смотрят, как работает физика. Можно проверить, как течёт вода или как получается тень. Выходят оттуда усталые, но довольные, а мамы и папы тоже играют.", "q": "Что можно делать в научном музее у реки Тежу?", "a": [ "Трогать и пробовать", "Только смотреть издали", "Только слушать лекции" ] }, { "id": "lis-c-kukly", "e": "🎭", "t": "Музей марионеток", "s": "В Лиссабоне есть музей марионеток. Марионетки — это куклы на ниточках, которыми управляют сверху. В залах стоят куклы из Португалии, Азии, Африки и других стран. Рядом сидят маленькие куклы, которые надевают на руку, например весёлый Дон Роберту, любимец уличных спектаклей. Португальцы показывают такие спектакли давно, и дети всегда смеются, когда кукла кланяется или машет рукой.", "q": "На чём держатся марионетки?", "a": [ "На ниточках", "На магнитах", "На резинках" ] }, { "id": "lis-c-gitara-kapelka", "e": "🎸", "t": "Гитара-капелька", "s": "Песни фаду часто поют под португальскую гитару. Она совсем не похожа на обычную: корпус круглый, как груша или капелька. У неё двенадцать струн, собранных по две. Звук звонкий, будто капли воды падают на камень. Гитару держат на коленях и перебирают струны пальцами быстро-быстро. Мастера в Лиссабоне делают такие гитары вручную.", "q": "Сколько струн у португальской гитары?", "a": [ "Двенадцать", "Две", "Сто" ] }, { "id": "lis-c-tishina-fadu", "e": "🤫", "t": "Тише, сейчас фаду", "s": "В маленьких лиссабонских ресторанчиках фаду поют в тишине. Когда певица выходит и берёт гитару, зал замолкает: разговоры стихают, ложки больше не звенят. Португальцы шепчут: «Тише, сейчас будет фаду». Все хотят расслышать каждое слово песни. Когда песня закончится, зрители хлопают. Дети, которые сидели тихо, получают восхищённые улыбки взрослых.", "q": "Что делают гости, когда начинает петь фаду?", "a": [ "Замолкают и слушают", "Включают громкую музыку", "Выходят плясать на улицу" ] }, { "id": "lis-c-orel-benfika", "e": "🦅", "t": "Орёл над стадионом", "s": "Лиссабонская команда «Бенфика» играет на стадионе «Эштадиу да Луш». Её знак — орёл. Перед матчем настоящий орёл по имени Витория кружит над полем, а болельщики встречают его радостными криками. Орла приучают к людям и шуму с детства, поэтому он совсем не боится толпы. Красные цвета «Бенфики» видны по всему городу.", "q": "Какая птица летает над стадионом перед матчем «Бенфики»?", "a": [ "Орёл", "Пингвин", "Аист" ] }, { "id": "lis-c-lev-sporting", "e": "🦁", "t": "Зелёный лев", "s": "Вторая большая лиссабонская команда — «Спортинг». У неё зелёно-белая форма, а на эмблеме лев. Болельщиков тоже зовут львами. Здесь начинал играть Криштиану Роналду: он родился на острове Мадейра и мальчиком приехал тренироваться в Лиссабон. Дети в зелёных шарфах идут на стадион, держась за руку с родителями.", "q": "Какое животное на эмблеме «Спортинга»?", "a": [ "Лев", "Дельфин", "Медведь" ] }, { "id": "lis-c-popugai", "e": "🦜", "t": "Зелёные попугаи в парке", "s": "В лиссабонских парках живут дикие зелёные попугаи. У них яркие зелёные перья и красный клюв. Когда-то эти птицы жили только в жарких странах, а теперь целые стайки с криками носятся над деревьями Лиссабона: им здесь тепло. Услышать их можно издалека, ведь кричат они громко и звонко. Поднимешь голову и увидишь зелёную вспышку между ветками.", "q": "Какого цвета перья у попугаев в парках Лиссабона?", "a": [ "Зелёные", "Чёрные", "Фиолетовые" ] }, { "id": "lis-c-flamingo", "e": "🦩", "t": "Розовые птицы у реки", "s": "Недалеко от Лиссабона, там, где широкая река Тежу впадает в океан, есть заповедник. Осенью и зимой там отдыхают розовые фламинго. Они стоят на одной ноге в мелкой воде и ловят крошечных рачков. Розовыми птиц делает еда: в рачках есть красящее вещество. Если подойти тихонько, можно увидеть целую стаю, и все птицы будут стоять очень спокойно.", "q": "Почему фламинго розовые?", "a": [ "Из-за еды, которую они едят", "Их красят люди", "Они мёрзнут" ] }, { "id": "lis-c-chajki", "e": "🐦", "t": "Чайки-воришки", "s": "Над крышами Лиссабона всегда кричат чайки. Они большие, с жёлтым клювом и красным пятнышком. Город стоит у океана, и чайки здесь как дома. Они умные и быстро замечают, у кого в руках булочка. Бывает, чайка подлетает и хватает кусочек прямо у зазевавшегося туриста. Поэтому на террасе кафе лучше держать еду крепко.", "q": "Что любят красть лиссабонские чайки?", "a": [ "Еду у людей", "Шляпы", "Ключи от дома" ] }, { "id": "lis-c-vorony", "e": "⛵", "t": "Лодка с воронами", "s": "На гербе Лиссабона нарисована лодка, а на ней две чёрные птицы — вороны. Старая легенда рассказывает, что вороны охраняли тело святого Висенте на корабле, который плыл к берегу Лиссабона. Вороны с лодкой стали знаком города. Увидеть этот знак можно на фонарях, на флагах и на городских домах, нужно только внимательно смотреть по сторонам.", "q": "Какие птицы нарисованы на лодке на гербе Лиссабона?", "a": [ "Вороны", "Лебеди", "Попугаи" ] }, { "id": "lis-c-metro-chajka", "e": "🚇", "t": "Метро с чайкой", "s": "У лиссабонских линий метро есть красивые имена. Синюю линию называют «Гайвота», то есть «чайка». Жёлтую — «Жирасол», «подсолнух». А зелёную — «Каравела», как старинный парусный корабль. Эти значки нарисованы на указателях до сих пор. Во многих станциях стены украшены картинами художников, так что ехать можно будто по выставке.", "q": "Как зовут синюю линию лиссабонского метро по значку?", "a": [ "Чайка", "Подсолнух", "Каравелла" ] }, { "id": "lis-c-obrigado", "e": "🗣️", "t": "Спасибо для мальчиков и девочек", "s": "Португальцы говорят «спасибо» по-разному. Мужчина или мальчик говорит «обригаду», а женщина или девочка — «обригада». Слово значит «я вам обязан», и оно меняется в зависимости от того, кто говорит. Для взрослых туристов это сюрприз: надо помнить, кто ты. Продавцы в лиссабонских кафе улыбаются, когда слышат правильное слово.", "q": "Как говорит «спасибо» девочка в Лиссабоне?", "a": [ "Обригада", "Грасиас", "Данке" ] }, { "id": "lis-c-belyo", "e": "👕", "t": "Бельё над улицей", "s": "Идёшь по старому району Лиссабона и видишь: из окон на верёвках сушится бельё. Рубашки, полотенца и носки развеваются, как флаги. Улицы здесь узкие, и верёвки натянуты прямо над ними. Солнца в городе много, а ветер с океана быстро всё сушит. Для туристов это забавная картинка, а для жителей — обычная жизнь.", "q": "Где в старых кварталах Лиссабона сушат бельё?", "a": [ "На верёвках у окон", "В холодильнике", "На деревьях в лесу" ] }, { "id": "lis-c-bloshinyj-rynok", "e": "🛍️", "t": "Блошиный рынок", "s": "Дважды в неделю, по вторникам и субботам, в Лиссабоне работает блошиный рынок «Фейра да Ладра». Здесь продают старые вещи: чашки, монеты, книги, часы, плитку, игрушки. Можно торговаться и искать сокровища. Название значит «ярмарка воровки», но не пугайся: торговцы здесь добрые, а вещи ждут новых хозяев.", "q": "В какие дни работает рынок «Фейра да Ладра»?", "a": [ "По вторникам и субботам", "Только зимой", "Раз в год" ] }, { "id": "lis-c-probka", "e": "🍂", "t": "Дерево, с которого снимают кору", "s": "В лавках Лиссабона продают сумки, кошельки и открытки из пробки. Её делают из коры пробкового дуба. Кору аккуратно снимают, как одёжку, а дерево потом растёт дальше. Примерно через девять лет кору можно снимать снова. Пробка лёгкая и мягкая, и она почти не промокает. Поэтому из неё делают даже подставки под горячие чашки.", "q": "Из чего делают вещи из пробки?", "a": [ "Из коры дуба", "Из морских ракушек", "Из стекла" ] }, { "id": "lis-c-lica-na-stene", "e": "🎨", "t": "Лица на стене", "s": "В Лиссабоне на домах много уличных картин. Один известный художник, которого зовут Вхилс, делает портреты необычным способом: он не рисует, а выбивает рисунок на стене, убирая слои штукатурки и краски. Получаются большие лица, будто вырезанные из камня. Идёшь по улице и вдруг встречаешься взглядом с огромным человеком.", "q": "Как делает свои портреты уличный художник Вхилс?", "a": [ "Выбивает их на стене", "Рисует карандашом на бумаге", "Лепит из пластилина" ] }, { "id": "lis-c-rynok-obed", "e": "🍽️", "t": "Рынок, где можно пообедать", "s": "В Лиссабоне есть старый крытый рынок «Меркаду да Рибейра». С раннего утра там продают овощи, фрукты, рыбу и цветы. А ещё внутри есть большой зал с множеством маленьких кухонь. Встанешь в очередь, возьмёшь себе суп, рыбу или сладкое и садишься за общий длинный стол. Рядом сидят незнакомые люди, но здесь все дружелюбные.", "q": "Что можно сделать на лиссабонском рынке, кроме покупок?", "a": [ "Пообедать за общим столом", "Покататься на карусели", "Посмотреть кино" ] }, { "id": "lis-c-bola-na-plyazhe", "e": "🍩", "t": "Булка с кремом на пляже", "s": "Летом на пляжах рядом с Лиссабоном можно услышать крик: «Бола де Берлин!» Так зовут пышную круглую булочку, которую жарят и посыпают сахаром. Внутрь кладут сладкий яичный крем. Продавец ходит по горячему песку с большой корзиной и зовёт всех, кто проголодался после купания. Ешь осторожно, чтобы крем не потёк по пальцам.", "q": "Что кладут внутрь булочки «бола де Берлин»?", "a": [ "Сладкий крем", "Горячий суп", "Солёную рыбу" ] }, { "id": "lis-a-lift-santa-zhushta", "e": "🛗", "t": "Железная башня-лифт", "s": "В Лиссабоне есть настоящий лифт посреди улицы. Это высокая башня из тёмного железа с узорами, как кружево. Её высота — 45 метров, а открыли лифт в 1902 году. Он называется Санта-Жушта. Внутри — деревянные кабинки, и они возят людей из нижнего города Байши в верхний район Шиаду. Идти пешком пришлось бы по крутому холму! А сверху, на площадке, видны красные крыши, замок и широкая река.", "q": "Что соединяет лифт Санта-Жушта?", "a": [ "Нижний город Байшу и верхний Шиаду", "Два берега реки", "Вокзал и аэропорт" ] }, { "id": "lis-a-krasnyj-most", "e": "🌉", "t": "Красный мост над Тежу", "s": "Через реку Тежу перекинут огромный красный мост. Его называют Мост 25 Апреля. Он длинный: больше двух километров. Наверху едут машины, а под ними, этажом ниже, ходят поезда. Знаешь, на что он похож? На знаменитый мост Золотые Ворота в американском Сан-Франциско! Мост такого же оранжево-красного цвета, а строила его американская компания. Когда в Лиссабоне туман, башни моста тонут в белой дымке.", "q": "Что едет по нижнему этажу красного моста?", "a": [ "Поезда", "Корабли", "Трамваи" ] }, { "id": "lis-a-most-vasko-da-gama", "e": "🛤️", "t": "Самый длинный мост", "s": "Есть в Лиссабоне и другой мост — мост Васко да Гамы. Его открыли в 1998 году. Вместе с подходами он тянется примерно на семнадцать километров, это один из самых длинных мостов Европы! Мост идёт по самой широкой части реки Тежу, где вода похожа на море. Когда едешь по нему, кажется, что берегов нет совсем: только вода, небо и белые опоры. А рядом на воде отдыхают птицы.", "q": "Как называется самый длинный мост Лиссабона?", "a": [ "Мост Васко да Гамы", "Мост Золотые Ворота", "Мост Тауэр" ] }, { "id": "lis-a-pavliny-na-zamke", "e": "🦚", "t": "Павлины на замке", "s": "На холме над Алфамой стоит замок Святого Георгия. У него толстые каменные стены и одиннадцать башен. Но главные жители замка — павлины! Они гуляют по двору, важно тянут шеи и иногда раскрывают огромные хвосты-веера. А ещё из замка видно весь город: крыши, реку и мосты. Ребята любят взбираться на стену и искать сверху свой дом. Это один из лучших наблюдательных постов Лиссабона.", "q": "Какие птицы гуляют по двору замка Святого Георгия?", "a": [ "Павлины", "Пингвины", "Страусы" ] }, { "id": "lis-a-alfama-uzkie-ulochki", "e": "🧺", "t": "Алфама — город-лабиринт", "s": "Алфама — один из самых старых районов Лиссабона. Улочки здесь такие узкие, что двое взрослых еле разойдутся! Они вьются вверх и вниз, ныряют под арки и заканчиваются лесенками. Между домами на верёвках сушится бельё, на подоконниках стоят цветы, а в окнах сидят кошки. Из открытых дверей пахнет жареной рыбой. Заблудиться в Алфаме легко, но это совсем не страшно: все дороги потом всё равно ведут вниз, к реке.", "q": "Какой старый район Лиссабона славится узкими улочками?", "a": [ "Алфама", "Байша", "Парк Наций" ] }, { "id": "lis-a-bajsha-pryamye-ulicy", "e": "📐", "t": "Город по линейке", "s": "Байша — район в самом низу, между холмами. Его улицы прямые и ровные, как клетки в тетради. Так задумал министр маркиз де Помбал, когда город строили заново: он хотел, чтобы было просторно и понятно. Улицы так и называются: улица Золотая, улица Серебряная, улица Аугушта. Когда-то на них работали мастера по золоту и серебру. Название «Байша» значит «низкий». Здесь легко ходить пешком и не заблудиться.", "q": "Как выглядят улицы Байши?", "a": [ "Прямые, как клетки в тетради", "Закручены спиралью", "Все ведут вверх по лестницам" ] }, { "id": "lis-a-pessoa-za-stolikom", "e": "☕", "t": "Поэт за столиком", "s": "В районе Шиаду у входа в старое кафе «А Бразилейра» стоит бронзовый человек в шляпе и очках. Он сидит за столиком, как будто вышел выпить кофе. Это поэт Фернанду Пессоа. Он жил в Лиссабоне, любил свой город и писал стихи. Туристы подсаживаются к нему, обнимают за плечо и фотографируются. Ты тоже можешь присесть рядом — только не мешай ему думать о стихах.", "q": "Как выглядит поэт Фернанду Пессоа у кафе в Шиаду?", "a": [ "Бронзовый человек за столиком", "Каменный всадник на коне", "Ледяная скульптура на крыше" ] }, { "id": "lis-a-funikuler-bika", "e": "🚋", "t": "Вагончик на крутой улице", "s": "В Лиссабоне есть улица такая крутая, что по ней тяжело даже ехать. Для неё придумали маленький жёлтый вагончик — фуникулёр Бика. Он ходит с 1892 года. Вагончик очень короткий, как коробка на рельсах, а рельсы лежат прямо посреди мостовой. Едет он медленно, а вокруг цветные домики с бельём и вид на реку внизу. Фуникулёр тянет вверх трос, а один вагончик едет вверх, пока другой спускается вниз.", "q": "Какого цвета вагончик фуникулёра Бика?", "a": [ "Жёлтого", "Красного", "Синего" ] }, { "id": "lis-a-funikuler-gloriya", "e": "🎨", "t": "Вагончик в рисунках", "s": "Другой лиссабонский фуникулёр называется Глория. Его построили в 1885 году, и он поднимается от площади Рештаурадориш к району Байру-Алту. Вагончики жёлтые, а стены вдоль пути покрыты яркими рисунками и надписями: художники разрисовали их баллончиками. Подниматься приходится минуты три. Зато наверху тебя ждёт красивая смотровая площадка и сад с деревьями. А если очень устал — просто проедь на нём туда и обратно.", "q": "В каком районе Лиссабона заканчивается подъём на фуникулёре Глория?", "a": [ "Байру-Алту", "Белен", "Парк Наций" ] }, { "id": "lis-a-ploshchad-torgovli", "e": "🟡", "t": "Жёлтая площадь у реки", "s": "Если подойти к реке Тежу, попадёшь на огромную площадь с жёлтыми зданиями вокруг. Она называется Площадь Торговли. С трёх сторон — длинные галереи с арками, а с четвёртой — река, и ступени спускаются прямо к воде. Когда-то здесь стоял королевский дворец, поэтому площадь называли «двор у дворца». Посередине стоит бронзовый король на коне. Здесь можно бегать, кормить голубей и смотреть на корабли.", "q": "Какого цвета здания вокруг Площади Торговли?", "a": [ "Жёлтого", "Розового", "Серого" ] }, { "id": "lis-a-arka-ulitsy-augusta", "e": "🏛️", "t": "Арка с видом", "s": "От Площади Торговли начинается пешеходная улица Аугушта, а над ней стоит высокая каменная арка. Её украшают каменные фигуры и часы. Внутри арки есть лифт и лестница, так что наверх можно подняться! Там — маленькая площадка с круглыми колоннами. Отсюда видны улицы Байши, как прямые клетки, площадь с жёлтыми стенами и река. Внизу под аркой играют музыканты, и до тебя долетают звуки гитары.", "q": "Что можно сделать внутри арки на улице Аугушта?", "a": [ "Подняться наверх и посмотреть на город", "Покататься на лодке", "Искупаться в бассейне" ] }, { "id": "lis-a-monastyr-zheronimush", "e": "⚓", "t": "Монастырь с канатами на стенах", "s": "В районе Белен стоит огромный белый монастырь Жеронимуш. Его начали строить больше пятисот лет назад, в начале шестнадцатого века, когда португальские моряки возвращались из дальних плаваний. Поэтому мастера вырезали на камне не только цветы, но и верёвки-канаты, ракушки и морские узлы. Во дворе — длинная галерея с арками, будто кружевная. Здесь так тихо и светло, что слышно, как шуршат шаги. Попробуй найти среди каменных узоров морской канат или ракушку!", "q": "Что мастера вырезали на камне монастыря Жеронимуш?", "a": [ "Канаты, ракушки и морские узлы", "Слонов и пальмы", "Снежинки и ёлки" ] }, { "id": "lis-a-pamyatnik-korabl", "e": "🚢", "t": "Корабль из камня", "s": "На берегу реки в Белене стоит белый каменный памятник, похожий на нос корабля. Он поднимается вверх, как парус, и называется Памятник Первооткрывателям. Впереди стоит принц Энрике — тот, кто отправлял корабли в путь. За ним выстроились мореходы, учёные и мастера: больше тридцати фигур, и все смотрят на воду. Памятник высотой около пятидесяти метров, на нём можно подняться на самый верх и посмотреть на реку.", "q": "На что похож Памятник Первооткрывателям в Белене?", "a": [ "На нос корабля", "На огромную гору", "На самолёт" ] }, { "id": "lis-a-rozovyj-dvorets", "e": "🌸", "t": "Розовый дворец", "s": "Рядом с монастырём в Белене стоит розовый дворец с белыми окнами. Он называется дворец Белен. Сегодня здесь работает президент Португалии. Во дворе стоит караул, и иногда при входе виден офицер в красивой форме. А позади дворца — большой сад с аллеями, цветами и старыми деревьями. Не каждая страна красит свои главные дома в розовый, но Португалия смело красит! Этот цвет радует в солнечный день.", "q": "Какого цвета дворец Белен?", "a": [ "Розового", "Чёрного", "Зелёного" ] }, { "id": "lis-a-bashnya-vasko-da-gama", "e": "⛵", "t": "Башня-парус", "s": "Парк Наций построили на берегу Тежу в 1998 году к большой выставке «Экспо», посвящённой океанам. Это новый район с просторными площадями, фонтанами и садами у воды. Одна из самых высоких построек здесь — башня Васко да Гамы, около 145 метров. Она похожа на парус корабля. А рядом через реку тянется длинный мост Васко да Гамы, и его белые опоры уходят к самому горизонту. Вечером вдоль реки зажигаются огни, и вся набережная светится, как праздничная гирлянда.", "q": "На что похожа башня Васко да Гамы в Парке Наций?", "a": [ "На парус корабля", "На ракету", "На дерево" ] }, { "id": "lis-a-pavilhao-conhecimento", "e": "🔬", "t": "Музей, где всё трогают", "s": "В Парке Наций есть музей для детей и взрослых, где можно всё трогать. Он называется Павильон Знаний. Здесь можно крутить и нажимать, рассматривать, как всё устроено, и самому проводить опыты. А рядом стоит Павильон Португалии: его бетонная крыша висит над площадью, как огромный лист бумаги, подвешенный за два конца. Под ним удобно прятаться от солнца и дождя.", "q": "На что похожа крыша Павильона Португалии?", "a": [ "На подвешенный лист бумаги", "На купол цирка", "На пирамиду" ] }, { "id": "lis-a-santa-luzia", "e": "🌺", "t": "Терраса с цветами и плиткой", "s": "Смотровая площадка Санта-Лузия — это маленькая терраса на холме над Алфамой. Над ней — деревянная беседка, увитая ярко-розовыми цветами бугенвиллеи. На стенах висят большие картины из синей плитки, а вокруг стоят скамейки. Отсюда видны красные крыши Алфамы, белый купол церкви и река Тежу с кораблями. Здесь можно сесть в тени цветов и отдохнуть после долгого подъёма.", "q": "Какие цветы растут над террасой Санта-Лузия?", "a": [ "Розовые бугенвиллеи", "Подсолнухи", "Тюльпаны" ] }, { "id": "lis-a-gras-pod-sosnami", "e": "🌲", "t": "Площадка под соснами", "s": "На одном из самых высоких холмов, возле района Граса, есть смотровая площадка под высокими соснами. Здесь тень, тихо и вкусно пахнет хвоей. Стоят скамейки, и можно выпить сок на маленькой террасе кафе. Вид отсюда замечательный: прямо напротив — замок Святого Георгия на своём холме, а ниже — Алфама и река. Лиссабонцы любят приходить сюда вечером, когда небо розовеет. Здесь можно посидеть и даже поиграть в догонялки.", "q": "Какие деревья растут на площадке в районе Граса?", "a": [ "Сосны", "Пальмы", "Берёзы" ] }, { "id": "lis-a-senhora-do-monte", "e": "🏔️", "t": "Самая высокая площадка", "s": "Одна из самых высоких смотровых площадок Лиссабона называется Сеньора-ду-Монте. Она на вершине холма, куда ведёт крутая улица, так что подниматься придётся пешком. Рядом стоит маленькая белая часовня. С площадки город виден как на ладони: замок, мосты, река и холмы, на которых стоит Лиссабон. Говорят, что отсюда лучше всего смотреть на закат, когда крыши становятся оранжевыми. Если взять с собой бинокль, можно разглядеть корабли.", "q": "Что стоит рядом со смотровой площадкой Сеньора-ду-Монте?", "a": [ "Маленькая белая часовня", "Ледяной каток", "Большой аквапарк" ] }, { "id": "lis-a-bazilika-shtrela", "e": "⛪", "t": "Белый купол на холме", "s": "В районе Эштрела на холме блестит белый купол — это базилика Эштрела. Её построили по приказу королевы Марии Первой в конце восемнадцатого века. Фасад украшают статуи, а внутри — светлый мрамор разных цветов. Рядом — зелёный сад с аллеями, прудом и беседкой, где играет музыка. А ещё в базилике есть огромный вертеп: около пятисот маленьких фигурок из пробки и глины. Их можно рассматривать целый час.", "q": "Из чего сделаны маленькие фигурки в вертепе базилики?", "a": [ "Из пробки и глины", "Из шоколада", "Из стекла" ] }, { "id": "lis-a-sad-estufa-fria", "e": "🌿", "t": "Сад в бывшей каменоломне", "s": "В парке Эдуарда Седьмого, в самом центре Лиссабона, прячется сад «Холодная теплица». Когда-то на этом месте добывали камень, а потом в яме посадили растения. Теперь здесь прохладно, тенисто и зелено: папоротники, пальмы, бамбук, маленькие пруды и водопады. Над головой — деревянная крыша из реек, сквозь неё проходит свет. Идёшь по дорожкам, а рядом журчит вода. В жару здесь так приятно, что не хочется уходить.", "q": "Что было на месте сада «Холодная теплица» раньше?", "a": [ "Каменоломня", "Пустыня", "Каток" ] }, { "id": "lis-a-tramvaj-12", "e": "🔁", "t": "Трамвайчик-карусель", "s": "Если тебе не хватило длинного трамвая номер 28, прокатись на маленьком трамвае номер 12. Он ходит по кругу: начинает путь у площади Фигейра, поднимается по холмам Алфамы и возвращается туда же. Трамвайчик короткий, жёлтый, с деревянными скамейками. Он проезжает мимо замка, смотровых площадок и узких улочек. Рельсы так близко к домам, что кажется, будто можно потрогать стены. Круг занимает недолго, и никуда не нужно пересаживаться.", "q": "Как едет трамвай номер 12?", "a": [ "По кругу", "Прямо до моря", "Под землёй" ] }, { "id": "lis-a-funikuler-lavra", "e": "🛤️", "t": "Старейший вагончик", "s": "Фуникулёр Лавра — самый старый в Лиссабоне. Он начал ходить в 1884 году и считается национальным памятником. Вагончик ездит по очень крутой улице, а наверху его ждёт небольшой сад с видом. Он совсем короткий, жёлтый, с деревянными скамейками внутри. Как и у других лиссабонских фуникулёров, один вагончик поднимается, когда второй спускается: они уравновешивают друг друга, как два конца качелей. Такой механизм работает до сих пор.", "q": "Как называется самый старый лиссабонский фуникулёр?", "a": [ "Лавра", "Бика", "Глория" ] }, { "id": "lis-a-kristu-rej", "e": "✝️", "t": "Статуя с раскинутыми руками", "s": "На другом берегу Тежу, на высоком обрыве, стоит огромная статуя Кристу-Рей. Это человек с раскинутыми в стороны руками, будто он обнимает весь город. Вместе с постаментом статуя высотой около ста десяти метров, поэтому её видно издалека, даже из Лиссабона. Построили её в 1959 году. Внутри постамента ходит лифт, на котором можно подняться на смотровую площадку. Оттуда видны красный мост и устье реки, где Тежу впадает в океан.", "q": "Как стоит статуя Кристу-Рей?", "a": [ "С раскинутыми руками", "Сидя на троне", "Верхом на коне" ] }, { "id": "lis-a-kedr-printsipe-real", "e": "🌳", "t": "Дерево-шатёр", "s": "В саду Принсипи-Реал, на холме в самом центре Лиссабона, растёт огромный старый кедр. Его ветви раскинулись так широко, что их подпирают столбы, как у шатра. Под деревом — большая тень, там стоят скамейки и столики, а летом играют дети. Рядом на площади бывает ярмарка, а под самим садом спрятано большое подземное водохранилище. Попробуй обойти дерево по кругу и сосчитать столбы.", "q": "Что подпирает ветви старого кедра в саду Принсипи-Реал?", "a": [ "Столбы", "Верёвки", "Воздушные шары" ] }, { "id": "lis-a-adamastor", "e": "🗿", "t": "Каменный великан на скале", "s": "На смотровой площадке Санта-Катарина среди скал сидит каменный великан. Это Адамастор — чудище из старой поэмы о мореплавателях. Но здесь он выглядит не страшно: просто большая задумчивая голова, глядящая вдаль. Вокруг играют уличные музыканты, а люди сидят на ступеньках и смотрят, как садится солнце над рекой. Отсюда хорошо видны красный мост и корабли. А с площадки спускаются улочки к набережной.", "q": "Кого изображает каменная статуя на площадке Санта-Катарина?", "a": [ "Великана Адамастора", "Принцессу", "Морского конька" ] } ], "porto": [ { "id": "por-lello", "e": "📚", "t": "Красная лестница", "s": "В Порту есть книжный магазин Лелу, ему больше ста лет. Посреди зала поднимается красная лестница. Она закручивается и раздваивается, как ленточка на подарке. Над ней сияет потолок-окно из цветного стекла, а полки до самого верха заставлены книгами. Это один из самых красивых книжных магазинов в мире, и люди со всей земли стоят в очереди, чтобы туда заглянуть.", "q": "Какая лестница в магазине Лелу?", "a": [ "Красная", "Надувная", "Пластилиновая" ] }, { "id": "por-sao-bento", "e": "🚂", "t": "Вокзал-картинка", "s": "В Порту есть вокзал Сан-Бенту. Когда входишь в его главный зал, кажется, что попал в огромную книжку с картинками. Стены покрыты бело-синими плитками азулежу, их около двадцати тысяч! Из плиток сложены картины о старых временах: короли и рыцари, праздники в деревнях. А под самым потолком тянется цветная полоса. На ней видно, как люди путешествовали раньше: сначала на повозках, а потом и на поезде.", "q": "Сколько плиток на стенах вокзала Сан-Бенту?", "a": [ "Около двадцати тысяч", "Ровно три", "Ни одной" ] }, { "id": "por-clerigos", "e": "🗼", "t": "Башня-карандаш", "s": "Над крышами Порту поднимается башня Клеригуш, высокая и тонкая, как карандаш. Её придумал итальянский архитектор Николау Насони, а достроили башню в 1763 году. Тогда это было самое высокое здание во всей Португалии. Чтобы подняться наверх, нужно пройти больше двухсот ступенек по узкой винтовой лестнице. Зато сверху виден весь город: красные крыши, река Дору и лодки на воде.", "q": "Сколько ступенек в башне Клеригуш?", "a": [ "Больше двухсот", "Всего две", "Ни одной" ] }, { "id": "por-ribeira", "e": "🏘️", "t": "Разноцветная набережная", "s": "Старая набережная Порту называется Рибейра. Дома там узкие и высокие, и все разного цвета: жёлтые, голубые, розовые, оранжевые. Они стоят плотно-плотно, плечом к плечу, как фломастеры в коробке. Из окон сушится бельё, а внизу по реке Дору плывут лодки. Старый центр Порту так красив, что его берегут как сокровище всего мира.", "q": "На что похожи дома на набережной Рибейра?", "a": [ "На фломастеры в коробке", "На сосиски в тесте", "На ёжиков в тумане" ] }, { "id": "por-francesinha", "e": "🥪", "t": "Маленькая француженка", "s": "В Порту любят огромный бутерброд «франсезинья», что значит «маленькая француженка». Внутри хлеб, ветчина, колбаска и кусочек мяса. Сверху всё накрыто расплавленным сыром и полито горячим соусом, а на макушку часто кладут жареное яйцо, как шапочку. Такой бутерброд руками не возьмёшь, его едят ножом и вилкой. Говорят, его придумал человек, который долго жил во Франции и вернулся домой в Порту.", "q": "Что значит слово «франсезинья»?", "a": [ "Маленькая француженка", "Большая сосиска", "Летающая тарелка" ] }, { "id": "por-douro", "e": "🍇", "t": "Лестница для великана", "s": "В долине реки Дору крутые склоны гор превращены в огромные ступеньки. Их называют террасами. Каждую ступеньку люди много лет выкладывали из камней своими руками. На террасах растёт виноград, а осенью его собирают в корзины. Ступеньки тянутся вдоль реки далеко-далеко, и кажется, что великан построил себе лестницу до самого неба.", "q": "Что растёт на ступеньках-террасах в долине Дору?", "a": [ "Виноград", "Мармелад", "Носки" ] }, { "id": "por-guimaraes", "e": "🏰", "t": "Здесь родилась Португалия", "s": "Колыбель — это кроватка для малыша. А город Гимарайнш называют колыбелью Португалии, потому что отсюда страна начала свой путь. На старой городской стене большими буквами написано: «Здесь родилась Португалия». Над городом стоит каменный замок с зубчатыми башнями. Первую крепость на этом холме построили больше тысячи лет назад.", "q": "Что написано на стене в городе Гимарайнш?", "a": [ "Здесь родилась Португалия", "Не бегать по лужам", "Осторожно, злая собака" ] }, { "id": "por-braga", "e": "🚡", "t": "Вода катает вагончик", "s": "Возле города Брага на высокий холм ведёт огромная лестница. Она петляет зигзагом, как змейка, а на её площадках журчат фонтаны. Рядом в гору ездит вагончик-фуникулёр, и с 1882 года его двигает вода! В бак верхнего вагончика наливают воду, он становится тяжелее, катится вниз и на тросе тянет наверх второй вагончик. Это самый старый в мире водяной фуникулёр, который всё ещё работает.", "q": "Что двигает фуникулёр возле города Брага?", "a": [ "Вода", "Варенье", "Кошка" ] }, { "id": "por-viana", "e": "💛", "t": "Золотое кружево", "s": "Север Португалии славится украшениями из филиграни. Мастера скручивают золотые ниточки, тонкие, как волосок, и выкладывают из них узоры, похожие на кружево. Самое известное украшение — сердце Вианы, оно названо в честь города Виана-ду-Каштелу. На праздники девушки там надевают яркие наряды с вышивкой, чаще всего красные, и много золотых украшений. Когда они идут по улице, всё вокруг сверкает.", "q": "Из чего мастера делают узоры филиграни?", "a": [ "Из тонких золотых ниточек", "Из варёных макарон", "Из мыльных пузырей" ] }, { "id": "por-geres", "e": "🐴", "t": "Лошадки на воле", "s": "На севере Португалии есть единственный в стране национальный парк — Пенеда-Жереш. Там высокие горы, водопады и густые леса. По склонам свободно бродят лошадки гаррану: невысокие, коричневые, с густой гривой и чёлкой. Они очень крепкие и ловко ходят по камням. А ещё в этом парке живут орлы, косули и даже волки.", "q": "Какие лошадки бродят в парке Пенеда-Жереш?", "a": [ "Невысокие и коричневые", "Полосатые и зелёные", "Крылатые и розовые" ] }, { "id": "por-a-luis-two-floors", "e": "🌉", "t": "Мост с двумя этажами", "s": "Над рекой Дору в Порту висит большой железный мост Дом Луиша. У него два этажа! Внизу, почти у самой воды, ездят машины и ходят люди. А наверху, высоко-высоко, идут прохожие и бегут вагончики метро. Мост держится на огромной железной арке, а арка похожа на радугу из металла. Если встать на верхнем этаже, то видно весь город: красные крыши, лодки и цветные дома. Верхний этаж открыли очень давно, в 1886 году, а нижний годом позже. Мост работает до сих пор.", "q": "Что едет по верхнему этажу моста Дом Луиша?", "a": [ "Вагончики метро", "Поезда-экспрессы с грузом", "Большие корабли" ] }, { "id": "por-a-maria-pia", "e": "🚂", "t": "Мост королевы Марии Пии", "s": "Рядом с большим мостом Луиша стоит другой, поменьше, и очень тонкий, как кружево из железа. Его назвали в честь королевы Марии Пии. Построила его фирма француза Гюстава Эйфеля, того самого, чья башня стоит в Париже. По мосту много лет ходили поезда, и их было видно издалека. Сейчас поездов там нет: рядом построили новый мост. Но старый красавец остался над Дору стоять и радовать всех, кто плывёт по реке.", "q": "Чья фирма построила мост Марии Пии?", "a": [ "Гюстава Эйфеля", "Леонардо да Винчи", "Томаса Эдисона" ] }, { "id": "por-a-six-bridges", "e": "⛴️", "t": "Шесть мостов за одну прогулку", "s": "В Порту есть весёлая речная прогулка, которую называют «Шесть мостов». Маленький теплоход плывёт по Дору, а над головой по очереди проплывают мосты. Вот старый красавец Мария Пия, вот двухэтажный Дом Луиша, вот мост Аррабида с одной огромной бетонной аркой. Все мосты разные: у каждого своя форма и свой возраст. Дети на палубе машут людям на мостах, а те машут в ответ. Попробуй сосчитать мосты вместе с гидом!", "q": "Сколько мостов проплывает теплоход на прогулке «Шесть мостов»?", "a": [ "Шесть", "Два", "Двадцать" ] }, { "id": "por-a-douro-spain", "e": "🏞️", "t": "Река, которая пришла из Испании", "s": "Река Дору рождается не в Португалии, а в соседней стране — в Испании. Там она тоже есть, только зовётся Дуэро. Она течёт почти девятьсот километров: через поля, холмы и виноградники. По пути её берега становятся крутыми, как ступени для великана. А в Порту Дору наконец добирается до океана и вливается в него. Весь этот долгий путь река делает без отдыха. Вот такой неутомимый путешественник!", "q": "В какой стране начинается река Дору?", "a": [ "В Испании", "Во Франции", "В Швейцарии" ] }, { "id": "por-a-rabelo", "e": "⛵", "t": "Лодки рабелу", "s": "У набережной Порту стоят старинные лодки рабелу. Дно у них плоское, парус один и квадратный, а руль длинный, как весло великана. Раньше такие лодки возили по Дору тяжёлые бочки с вином из виноградников в город. Река там быстрая, камни, повороты, поэтому лодочники были очень ловкими. Сегодня рабелу уже не возят бочки каждый день, но их красиво украшают, и на каждой нарисовано название винного дома. Ими любуются туристы и дети.", "q": "Что возили на лодках рабелу в Порту?", "a": [ "Бочки с вином", "Арбузы и дыни", "Брёвна для кораблей" ] }, { "id": "por-a-gaia-cellars", "e": "🛢️", "t": "Погреба на том берегу", "s": "Напротив Порту, на другом берегу Дору, стоит городок Вила-Нова-ди-Гайя. Там много старинных погребов, где выдерживают портвейн. В погребе всегда темно и прохладно, а воздух пахнет деревом. Рядами лежат огромные бочки, и вино спит в них годами, а иногда и десятилетиями. Работники ходят между бочками и проверяют, как оно себя чувствует. Над крышами погребов видны большие надписи, а ещё оттуда видно весь Порту.", "q": "Где выдерживают портвейн в Гайе?", "a": [ "В погребах, в бочках", "На высоких чердаках", "В стеклянных башнях" ] }, { "id": "por-a-barrel-secret", "e": "🍇", "t": "Сладкий секрет портвейна", "s": "Портвейн делают из винограда, который растёт на склонах долины Дору. Есть у него секрет. Когда виноградный сок начинает бродить, в него добавляют крепкий напиток из винограда. Брожение тогда останавливается, а сладость остаётся. Поэтому портвейн получается сладким и густым. Потом его переливают в большие деревянные бочки, они называются «пипа», в такой бочке около пятисот пятидесяти литров. Детям портвейн не дают, а виноград с этих склонов они, конечно, пробуют охотно!", "q": "Как называется большая бочка, где выдерживают портвейн?", "a": [ "Пипа", "Кувшин", "Самовар" ] }, { "id": "por-a-sandeman-don", "e": "🎩", "t": "Дон в чёрном плаще", "s": "Над набережной в Гайе висит большая чёрная фигура. Человек в длинном плаще, как у студентов Порту, и в шляпе с широкими полями. Его зовут просто Дон. Это знак одного винного дома Сандеман, и нарисовали его ещё около 1928 года. Он такой знаменитый, что его знают даже те, кто никогда не был в Порту. Дон стоит неподвижно, как сказочный герой, и словно стережёт погреба. Дети любят искать его глазами издалека и фотографировать на фоне реки.", "q": "Во что одет Дон на вывеске?", "a": [ "В чёрный плащ и шляпу", "В красную куртку и кепку", "В белый халат и колпак" ] }, { "id": "por-a-lello-motto", "e": "📚", "t": "Книжный с девизом", "s": "Книжный магазин Лелу в Порту похож на сказочный зал. Дерево, резные колонны, лестница, а над головой цветной стеклянный потолок. На нём написан девиз по-латыни: «Декус ин лаборе». Это значит «Честь в труде». Его выбрали братья Лелу, которые открыли магазин в 1906 году. Они хотели, чтобы работа была почётной, а книги красивыми. Войди и посмотри вверх: свет из стёкол падает прямо на корешки, и кажется, что книги светятся.", "q": "Где в магазине Лелу написан девиз?", "a": [ "На стеклянном потолке", "На входной двери из железа", "На обложке каждой книги" ] }, { "id": "por-a-lello-rails", "e": "🛤️", "t": "Рельсы в книжном магазине", "s": "В книжном Лелу есть секрет под ногами. По полу проходят маленькие рельсы, как для игрушечного поезда! Говорят, раньше по ним катили тележки с книгами от входа к лестнице. Так работникам было легче носить тяжёлые стопки. Сейчас тележек почти не видно, а рельсы остались как память. Они напоминают, что магазин очень старый и что здесь о книгах заботились по-настоящему. Посмотри на пол, когда будешь там, и найди тоненькие дорожки.", "q": "Для чего были рельсы в книжном магазине?", "a": [ "Чтобы катить тележки с книгами", "Чтобы возить посетителей", "Чтобы открывать окна" ] }, { "id": "por-a-tram-sea", "e": "🚋", "t": "Трамвай едет к морю", "s": "В Порту есть трамвайная линия номер один, и она необычная. Старый деревянный вагончик выезжает от Рибейры и катится вдоль реки Дору. Колёса тихо стучат, на стенах скамейки из дерева, а окна открыты. Чем дальше, тем шире река, пока не покажется океан. Конечная остановка в районе Фош, где Дору встречается с морем. Пассажиры выходят и идут гулять по набережной, дышать солёным ветром и смотреть на волны.", "q": "Куда ведёт трамвайная линия номер один?", "a": [ "К океану, вдоль реки", "В горы на север", "В пустыню" ] }, { "id": "por-a-tram-museum", "e": "🏛️", "t": "Музей трамваев", "s": "В Порту живёт целый музей трамваев. Он помещается в бывшей электростанции у реки, в районе Массарелуш. Внутри стоят старые вагончики, блестит дерево и медные ручки. Раньше, ещё в 1872 году, по рельсам города вагончики тянули лошади и мулы, а потом пришло электричество. В музее можно потрогать скамейки и представить, как люди ехали на работу много лет назад. А рядом с музеем и сегодня ходят старинные трамваи!", "q": "Кто возил самые первые вагончики по Порту?", "a": [ "Лошади и мулы", "Слоны", "Собаки" ] }, { "id": "por-a-dragon-stadium", "e": "🐉", "t": "Стадион Дракона", "s": "У футбольного клуба «Порту» синие и белые цвета, а на эмблеме сидит дракон. Стадион команды тоже называется «Эстадиу ду Драгау», то есть «Стадион Дракона». Его открыли в 2003 году, и в нём помещается около пятидесяти тысяч зрителей. Когда играет команда, трибуны поют песни, машут флагами и шарфами. А на поле бегает весёлый талисман, он тоже дракон и зовётся Драку. Болельщиков в городе узнаешь сразу по сине-белым шарфам.", "q": "Какое животное на эмблеме клуба «Порту»?", "a": [ "Дракон", "Орёл", "Тигр" ] }, { "id": "por-a-boavista-chess", "e": "♟️", "t": "Шахматные футболки", "s": "В Порту есть и другая известная футбольная команда, она называется «Боавишта». Её игроки выходят на поле в необычной форме: чёрно-белые квадратики, как шахматная доска! Португальцы даже называют её «шахматной» командой. Стадион у неё называется Бессá, и он совсем не такой огромный, как у дракона, зато очень уютный. Болельщики Боавишты тоже ходят в клетчатом, и их видно издалека. Вот так в одном городе живут две совсем разные команды.", "q": "Какой рисунок на форме «Боавишты»?", "a": [ "Чёрно-белые квадраты", "Жёлтые и красные полосы", "Зелёные горошины" ] }, { "id": "por-a-tile-houses", "e": "🏠", "t": "Дома в плитке", "s": "В Порту много домов, которые одеты в плитку, как в яркую рубашку. Эта плитка называется азулежу. Она не только красивая, но и очень полезная. Здесь часто идут дожди, а с океана дует влажный ветер. Плитка не пускает воду в стены, и дом остаётся сухим и тёплым. Одни дома покрыты белой плиткой, другие синей, третьи с узорами. Если пройтись по улицам, получится целая выставка картин на стенах.", "q": "Для чего нужна плитка на стенах домов Порту?", "a": [ "Чтобы защитить стены от сырости", "Чтобы дом был тяжелее", "Чтобы птицы не садились" ] }, { "id": "por-a-carmo-wall", "e": "🔵", "t": "Синяя стена церкви Карму", "s": "Одна из церквей Порту, Карму, носит на боку огромную картину из синей плитки. Она появилась в начале 1900-х годов. На плитках нарисованы святые и сцены из жизни монахов-кармелитов, а вокруг блестят золотые рамки. Картина покрывает всю высокую боковую стену, поэтому прохожие часто останавливаются и поднимают головы. Дождь и солнце ей не страшны: плитка почти не меняется. Она такая яркая, что кажется, будто небо спустилось на стену.", "q": "Из чего сделана картина на стене церкви Карму?", "a": [ "Из синей плитки", "Из цветных ниток", "Из мелких ракушек" ] }, { "id": "por-a-thin-house", "e": "🏘️", "t": "Самый узкий дом", "s": "В Порту две церкви, Карму и Кармелитас, стоят совсем рядом. Говорят, раньше было правило, что у двух церквей не должно быть общей стены. Тогда между ними построили крошечный дом, чтобы стены не касались. Дом такой узкий, что его почти не заметить: ширина всего около метра. Фасад у него белый, окошки маленькие, как в кукольном домике. Если пройти мимо, можно удивиться: как там помещается человек? Но дом настоящий, и в нём когда-то жили.", "q": "Что построили между двумя церквями?", "a": [ "Узкий жилой дом", "Высокую башню с часами", "Фонтан с рыбками" ] }, { "id": "por-a-bolhao", "e": "🥕", "t": "Рынок Больян", "s": "В центре Порту стоит старый рынок Больян. Раньше в его проходах можно было купить всё: овощи, фрукты, рыбу, цветы, сыр и свежий хлеб. Продавцы громко зазывали покупателей и шутили. Над рядами высокие балконы с железными перилами, а внизу пахнет зеленью и морем. Несколько лет рынок ремонтировали, а в 2022 году открыли снова. И теперь здесь опять шумно и очень вкусно. Дети любят разглядывать яркие горки яблок и апельсинов.", "q": "Что продают на рынке Больян?", "a": [ "Овощи, фрукты, цветы и рыбу", "Только машины и запчасти", "Только игрушки и шары" ] }, { "id": "por-a-bolsa-arab", "e": "✨", "t": "Золотой зал в Биржевом дворце", "s": "В Порту есть Биржевой дворец, где когда-то работали торговцы. Самое красивое место в нём — Арабский зал. Его стены и потолок покрыты тонкими узорами и золотом, а свет от люстр блестит на каждом завитке. Зал строили очень много лет, и мастера вырезали каждый узор вручную. Здесь раньше принимали важных гостей, а сегодня на экскурсию приходят туристы. Дети, когда входят, обычно замирают и шепчут: «Как в сказке!».", "q": "Как называется самый красивый зал Биржевого дворца?", "a": [ "Арабский зал", "Морской зал", "Ледяной зал" ] }, { "id": "por-a-crystal-peacocks", "e": "🦚", "t": "Павлины в саду Хрустального дворца", "s": "В Порту есть большой сад вокруг бывшего Хрустального дворца. Дворец из стекла и железа когда-то построили для выставки, а потом его не стало, но сад остался. По дорожкам спокойно гуляют павлины. Они раскрывают огромные хвосты, как зелёно-синие веера, и важно кричат. Рядом растут высокие деревья и цветы, а с края сада видна река Дору. Дети любят приходить сюда, чтобы посмотреть на птиц и поиграть на траве. Только трогать павлинов нельзя!", "q": "Кто гуляет по саду Хрустального дворца?", "a": [ "Павлины", "Пингвины", "Верблюды" ] }, { "id": "por-a-casa-musica", "e": "🎼", "t": "Дом музыки", "s": "В Порту стоит необыкновенное здание. Оно называется Каза да Музика, то есть Дом музыки. Здание белое и угловатое, будто огромный драгоценный камень или ледяная глыба. Его открыли в 2005 году, а придумал его архитектор из Нидерландов. Внутри большие залы, где играют оркестры, пианисты и барабанщики. Иногда концерты устраивают для детей, а звук там такой чистый, что слышно каждую ноту. А на площадке перед домом любят кататься на самокатах и досках.", "q": "Как называется здание, похожее на белый драгоценный камень?", "a": [ "Дом музыки", "Дом ветра", "Дом снега" ] }, { "id": "por-a-henry-born", "e": "🧭", "t": "Мальчик из Порту", "s": "Более шестисот лет назад в Порту, как считается, родился мальчик по имени Энрике. Он был принцем, но больше любил не пиры, а карты и корабли. Став взрослым, он собирал мореходов, строителей и учёных, чтобы они искали новые морские дороги. Из-за этого его потом прозвали Мореплавателем. Сам он почти не ходил в дальние плавания, зато придумывал, как кораблям плыть дальше. В Порту до сих пор стоит старый дом, в котором, по преданию, он родился.", "q": "Как прозвали принца Энрике из Порту?", "a": [ "Мореплаватель", "Строитель мостов", "Хранитель маяка" ] }, { "id": "por-a-tripeiros", "e": "🥣", "t": "Почему жителей Порту зовут триперуш", "s": "Жителей Порту в Португалии шутливо называют «триперуш». Это слово звучит смешно, но обидного в нём нет. Рассказывают, что давным-давно горожане отдали всё лучшее мясо кораблям, которые уходили в дальнее плавание. Себе оставили только то, что осталось, и научились готовить из этого очень вкусные блюда. Одно такое блюдо стало знаменитым и в городе его любят до сих пор. А прозвище жители Порту носят гордо, как весёлый секрет.", "q": "Как шутливо называют жителей Порту?", "a": [ "Триперуш", "Лиссабонцы", "Водолазы" ] }, { "id": "por-a-matosinhos-sardines", "e": "🐟", "t": "Сардины Матозиньюша", "s": "Недалеко от Порту, у самого океана, лежит рыбацкий город Матозиньюш. Сюда рыбаки привозят свежую рыбу прямо с лодок. Особенно любят сардины. Их жарят на углях прямо на улице, и дым пахнет на весь квартал. Подают сардину на ломте хлеба, с печёной картошкой и перцем. Есть её надо руками, и никто не ругается, если пальцы стали солёными. Дети тоже пробуют, хотя сначала немного боятся косточек.", "q": "Что жарят на углях в Матозиньюше?", "a": [ "Сардины", "Пирожки с мёдом", "Каштановые торты" ] }, { "id": "por-a-foz-ocean", "e": "🌊", "t": "Где Дору встречается с океаном", "s": "В самом конце своего пути река Дору приходит к океану. Это место называется Фош-ду-Дору. Здесь река уже широкая и спокойная, а океан шумный и сильный. Волны бьются о каменный причал, вверх летят брызги, а чайки кричат над головой. На берегу стоит старый маяк и красивый форт. Можно сидеть на набережной и смотреть, как пресная вода смешивается с солёной. А вечером солнце садится прямо в океан, и всё вокруг становится розовым.", "q": "Куда впадает река Дору в Порту?", "a": [ "В океан", "В озеро", "В пустыню" ] }, { "id": "por-a-laundry-ribeira", "e": "👕", "t": "Бельё над улицей", "s": "В старом районе Рибейра в Порту улицы узкие, а дома стоят близко друг к другу. Из окон на верёвках сушится бельё: рубашки, платья, полотенца, носочки. Ветер раскачивает их, и кажется, что улицы украшены флажками. Это не праздник, а обычный день. Жители Порту привыкли сушить вещи на солнце и на ветру, как делали их бабушки. Туристы обычно удивляются, а потом фотографируют. Если смотреть снизу, получается самая весёлая гирлянда!", "q": "Что сушится на верёвках в районе Рибейра?", "a": [ "Бельё", "Рыба на продажу", "Бумажные змеи" ] }, { "id": "por-a-majestic-cafe", "e": "☕", "t": "Кафе с зеркалами и золотом", "s": "На улице Санта-Катарина в Порту есть кафе «Маджестик», которое открыли в 1921 году. Внутри большие зеркала, резное дерево, мягкие кресла и лепнина под потолком. Официанты в белых рубашках и чёрных жилетах ходят неспешно. Раньше сюда приходили поэты, художники и просто горожане, чтобы поговорить за чашкой кофе. Кафе похоже на дворец. Дети там пьют какао и смотрят на золотые завитки. А у входа часто стоит очередь, ведь всем хочется внутрь.", "q": "Что висит на стенах кафе «Маджестик»?", "a": [ "Большие зеркала", "Рыболовные сети", "Тарелки с птицами" ] }, { "id": "por-a-se-cathedral", "e": "⛪", "t": "Собор-крепость на холме", "s": "Высоко над рекой, на самом холме, стоит собор Порту, его называют Се. Он серый, толстый и крепкий, с двумя башнями, словно маленькая крепость. Построили его очень давно, около девятисот лет назад. Внутри прохладно и тихо, а рядом есть длинная галерея вокруг двора. Её стены украшены синими картинами из плитки. С площади перед собором видно Дору, мосты и красные крыши города. Много людей приходят сюда посмотреть на закат.", "q": "Как называют собор Порту?", "a": [ "Се", "Белен", "Пена" ] }, { "id": "por-a-serralves-pink", "e": "🌸", "t": "Розовый дом в большом парке", "s": "На окраине Порту стоит розовый дом, и он похож на замок из торта. Называется он Серралвиш, а построили его почти сто лет назад. У дома ровные линии и красивые окна, это стиль арт-деко. Вокруг огромный парк с высокими деревьями, прудом и зелёными лужайками. По дорожкам гуляют семьи, бегают дети, а в кронах поют птицы. Сегодня в доме и рядом в музее показывают современное искусство. Здесь здорово устроить пикник в хорошую погоду.", "q": "Какого цвета дом Серралвиш?", "a": [ "Розового", "Фиолетового", "Серого" ] }, { "id": "por-b-douro-terraces", "e": "🍇", "t": "Лесенки для винограда", "s": "Берега реки Дору такие крутые, что ровной земли там почти нет. А виноград любит солнце и тёплые склоны. Тогда люди придумали террасы: сложили из камня невысокие стенки и засыпали их землёй. Получились огромные зелёные ступеньки, которые поднимаются от воды к самому небу. Осенью листья желтеют и краснеют, и склоны становятся золотыми. Такую красоту охраняет ЮНЕСКО.", "q": "Что построили люди на крутых берегах Дору?", "a": [ "Каменные террасы-ступеньки", "Глубокие каналы", "Высокие заборы" ] }, { "id": "por-b-rabelo-boat", "e": "⛵", "t": "Лодка с огромным веслом", "s": "Раньше по реке Дору возили бочки с вином на особых лодках — рабелу. У рабелу широкое плоское дно, поэтому она не боится мелких мест, и один большой парус. А управляют ею не рулём, а длинным-предлинным веслом на корме. Рулевой стоит высоко и ловко ведёт лодку между камнями. Сейчас бочки возят иначе, а рабелу стоят у набережной Порту и катают туристов.", "q": "Чем управляли лодкой рабелу?", "a": [ "Длинным веслом на корме", "Маленьким мотором", "Верёвкой с берега" ] }, { "id": "por-b-grape-harvest", "e": "🦶", "t": "Виноград давят ногами", "s": "Осенью на склонах Дору начинается сбор винограда. Его режут ножницами и носят корзинами. А потом бывает смешное: виноград высыпают в низкий каменный бак — лагар — и люди давят его босыми ногами, а иногда даже под музыку. В некоторых хозяйствах так делают до сих пор, хотя есть и машины. Сок получается сладкий и густой, а ноги потом долго фиолетовые.", "q": "Как в старину давили виноград в каменных баках?", "a": [ "Босыми ногами", "Тяжёлыми валунами", "Деревянными молотками" ] }, { "id": "por-b-green-wine", "e": "🥂", "t": "Зелёное — значит молодое", "s": "На севере Португалии, в краю Минью, делают «зелёное вино» — винью верде. Оно совсем не зелёное: белое, розовое или красное. «Зелёное» здесь значит «юное»: его пьют сразу, пока оно свежее и чуть-чуть щекочет пузырьками. Это напиток для взрослых, дети пьют сок. Зато сам виноград в этих местах растёт густо, по всей зелёной стране.", "q": "Что значит слово «зелёное» в названии винью верде?", "a": [ "Юное, свежее", "Цвета травы", "Сделано из листьев" ] }, { "id": "por-b-vines-on-trees", "e": "🌳", "t": "Виноград выше деревьев", "s": "В Минью дождей много, и земля там сырая. Если виноград стелется низко, ягоды портятся. Поэтому раньше лозу сажали у деревьев и пускали вверх по стволам. Лоза карабкалась на ветки, а гроздья висели высоко, на ветру и на солнце. Кое-где такой виноград растёт до сих пор: он вьётся по столбам и жердям вдоль дорог и полей.", "q": "Куда в Минью пускали виноградную лозу, чтобы ягоды не отсырели?", "a": [ "Вверх по деревьям", "В глубокие ямы", "На крыши домов" ] }, { "id": "por-b-rainy-minho", "e": "🌧️", "t": "Самая зелёная земля", "s": "Минью — один из самых дождливых краёв Португалии. Тёплый влажный воздух приходит с океана, облака цепляются за горы и проливаются дождём. Поэтому здесь всё такое зелёное: луга, леса, мшистые каменные стены. Реки полны воды, и по склонам бегут ручейки. Если поедешь на север, возьми с собой зонтик, но не расстраивайся: после дождя пахнет травой и мокрой землёй.", "q": "Почему в Минью так зелено?", "a": [ "Там много дождей", "Там красят траву", "Там всегда снег" ] }, { "id": "por-b-caldo-verde", "e": "🥬", "t": "Суп с зелёной капустой", "s": "На севере Португалии любят «кальду верде» — зелёный суп. Его варят из картошки и особой капусты с большими листьями, которую режут очень-очень тонкими ниточками. В тарелку добавляют ложку оливкового масла, а иногда кружок колбасы. Суп получается тёплый, густой и душистый. Его подают на праздниках и просто дома, когда за окном холодно и моросит дождь.", "q": "Из чего варят суп кальду верде?", "a": [ "Из картошки и капусты", "Из риса и мандаринов", "Из лапши и сыра" ] }, { "id": "por-b-douro-lock", "e": "🚢", "t": "Лифт для кораблей", "s": "На реке Дору стоят плотины, и корабли не могут просто проплыть мимо. Для них построили шлюзы — как большие водяные лифты. Судно заходит в каменную камеру, ворота закрываются, и вода тихо поднимает его вверх или опускает вниз. Шлюз у Каррапателу — один из самых глубоких в Европе: судно меняет высоту примерно на тридцать пять метров, как в доме этажей на десять.", "q": "Как корабли преодолевают плотины на Дору?", "a": [ "Проходят через шлюз-лифт", "Едут по рельсам", "Их перевозят вертолёты" ] }, { "id": "por-b-pinhao-station", "e": "🚉", "t": "Вокзал в синих картинках", "s": "Вдоль реки Дору идёт железная дорога, и поезд всё время бежит рядом с водой. На вокзале в Пиньяне стены покрыты синей плиткой — азулежу. На ней нарисованы виноградники: как люди работают на склонах, собирают гроздья и везут их на лодках. Пока ждёшь поезд, можно рассматривать плитки, как книжку с картинками. А потом смотреть в окно на настоящие холмы.", "q": "Что нарисовано на плитке вокзала в Пиньяне?", "a": [ "Виноградники и работа на склонах", "Корабли в океане", "Кошки и собаки" ] }, { "id": "por-b-roman-braga", "e": "🏛️", "t": "Брага, которой две тысячи лет", "s": "Брага — один из самых старых городов Португалии. Его основали римляне и назвали Бракара Авгу́ста, в честь императора Августа. Тогда здесь были дороги, храмы и каменные дома. Теперь на месте римского города стоят церкви, площади и кафе. А в центре возвышается старинный собор, который называют одним из самых древних в стране. Идёшь по улице и шагаешь по земле, которой больше двух тысяч лет.", "q": "Кто основал город Брага?", "a": [ "Римляне", "Викинги", "Греки" ] }, { "id": "por-b-bom-jesus", "e": "⛲", "t": "Источник в скале", "s": "В старом центре Браги есть необычный источник. Его вырезали прямо в большой гранитной скале. На камне высечена фигурка человека в длинной одежде, а рядом выбиты надписи на латыни. Говорят, они посвящены местным богам воды. Источнику около двух тысяч лет, и теперь над ним построили светлый дом, чтобы дождь и ветер не стирали рисунок. Можно заглянуть и увидеть древний камень совсем близко.", "q": "Из чего вырезан древний источник в Браге?", "a": [ "Из гранитной скалы", "Из дерева", "Из льда" ] }, { "id": "por-b-guimaraes-palace", "e": "🏰", "t": "Дворец с множеством труб", "s": "В Гимарайнше стоит старинный дворец герцогов. Его начали строить давно, в пятнадцатом веке, из камня и кирпича. Издали он похож на сказочный замок: на крыше торчат высокие кирпичные трубы, и кажется, что в каждой комнате топится камин. Внутри — большие залы и старые ковры на стенах. А рядом стоит замок на скале, ещё старше.", "q": "Что торчит на крыше дворца в Гимарайнше?", "a": [ "Много высоких труб", "Золотые флюгеры", "Зелёные купола" ] }, { "id": "por-b-penha-cablecar", "e": "🚠", "t": "Кабинка к камням", "s": "Из Гимарайнша на гору Пенья ведёт канатная дорога. Кабинка плывёт над деревьями, и город внизу становится совсем маленьким. Наверху лес, тропинки и огромные круглые валуны, которые лежат, как будто великан рассыпал камешки. Можно залезть на камень и посмотреть вокруг. Гулять там приятно: пахнет хвоей, а на ветках поют птицы.", "q": "На чём люди поднимаются из Гимарайнша на гору Пенья?", "a": [ "На канатной дороге", "На воздушном шаре", "На лошади-качалке" ] }, { "id": "por-b-briteiros", "e": "🏚️", "t": "Круглые дома кельтов", "s": "Недалеко от Гимарайнша, на холме, лежит древний посёлок Бритейруш. Здесь около двух тысяч лет назад жили люди, которых обычно называют кельтами. Дома у них были круглыми, из камня, а крыши, скорее всего, соломенные. Сейчас крыш нет, но каменные кольца стен сохранились, и по ним можно ходить. Видны улицы и ступеньки, и кажется, что жители только что вышли.", "q": "Какой формы были дома в Бритейруше?", "a": [ "Круглой", "Квадратной", "Треугольной" ] }, { "id": "por-b-santa-luzia", "e": "⛰️", "t": "Холм над океаном", "s": "Город Виана-ду-Каштелу стоит там, где река Лима впадает в океан. Над ним поднимается холм Санта-Лузия. Наверху — белая церковь с большим куполом, а подняться можно на фуникулёре. С вершины видно всё сразу: крыши города, извилистую реку, синий океан и далёкие горы. В ясный день глаза не нарадуются. Спускаться вниз потом совсем не хочется.", "q": "Что видно с холма Санта-Лузия?", "a": [ "Город, реку и океан", "Только лес", "Снежные вулканы" ] }, { "id": "por-b-gil-eannes", "e": "🚢", "t": "Корабль-врач", "s": "В порту Виана-ду-Каштелу стоит старый корабль «Жил Эаниш». Раньше он плавал за рыбацкими лодками далеко в холодное море. Рыбаки подолгу жили вдали от дома, и если кто-то заболевал, корабль приходил на помощь, как плавучая больница. Теперь он больше не плавает, а превратился в музей: можно пройти по палубе, заглянуть в каюты и увидеть, как жили моряки.", "q": "Чем был корабль «Жил Эаниш» для рыбаков?", "a": [ "Плавучей больницей", "Плавучим цирком", "Школой для детей" ] }, { "id": "por-b-ponte-de-lima", "e": "🌉", "t": "Мост, который помнит римлян", "s": "В городе Понте-де-Лима через реку переброшен длинный каменный мост. Часть его построили ещё римляне, а потом, в средние века, достроили новыми арками. Поэтому арки разные: одни старше, другие моложе. По мосту ходят пешком, а вокруг растут цветочные сады. Название города так и переводится: «мост через Лиму». Это один из старейших городов Португалии.", "q": "Что означает название Понте-де-Лима?", "a": [ "Мост через реку Лиму", "Город цветов", "Гора у моря" ] }, { "id": "por-b-geres-park", "e": "🌲", "t": "Единственный в стране", "s": "В Португалии много природных парков, но национальный парк всего один — Пенеда-Жеражеш. Он на севере, у границы с Испанией, и создан в тысяча девятьсот семьдесят первом году. Там горы, леса, реки и водопады, а ещё старинные деревни из камня. Живут в парке волки, косули, орлы и дикие лошади. Люди приезжают сюда гулять, плавать и слушать тишину.", "q": "Сколько национальных парков в Португалии?", "a": [ "Один — Пенеда-Жеражеш", "Двадцать", "Ни одного" ] }, { "id": "por-b-granaries", "e": "🌽", "t": "Амбары на ножках", "s": "В деревне Соажу, в парке Пенеда-Жеражеш, стоят каменные амбары — эшпигейруш. Они длинные и узкие, и каждый стоит на толстых каменных ножках. Это сделано нарочно: снизу гуляет ветер и сушит зерно и кукурузу, а мыши не могут забраться наверх. Сверху на амбарах часто стоят маленькие кресты. Издали они похожи на ряд крошечных каменных домиков.", "q": "Зачем эшпигейруш поставили на каменные ножки?", "a": [ "Чтобы ветер сушил зерно, а мыши не забрались", "Чтобы не затопило снегом", "Чтобы выглядели высокими" ] }, { "id": "por-b-geres-springs", "e": "♨️", "t": "Тёплая вода из горы", "s": "В посёлке Жеражеш из-под земли бьёт тёплая вода. Говорят, горячие источники в этих горах знали ещё римляне: они приходили сюда купаться и лечиться. Теперь рядом построены современные купальни. Вода тёплая, прозрачная, без запаха. Вокруг горы покрыты зелёными лесами, а воздух чистый и свежий, так что греться особенно приятно.", "q": "Какая вода бьёт из-под земли в посёлке Жеражеш?", "a": [ "Тёплая", "Сладкая", "Цветная" ] }, { "id": "por-b-roman-milestones", "e": "🪨", "t": "Римские столбики-указатели", "s": "Через горы Жеражеш проходит римская дорога. Две тысячи лет назад по ней ходили путешественники, солдаты и торговцы. Вдоль дороги стояли каменные столбики-указатели с надписями, которые показывали расстояние до города. Многие из них стоят до сих пор, поросшие мхом. Идёшь по лесной тропе и вдруг видишь такой столбик. Это как письмо из глубины времён.", "q": "Что стояло вдоль римской дороги в горах Жеражеш?", "a": [ "Каменные столбики с расстоянием", "Фонари со свечами", "Деревянные скамейки" ] }, { "id": "por-b-fisgas-waterfall", "e": "💦", "t": "Высокий водопад Фижаш", "s": "В горах Алваном, на севере Португалии, есть водопад Фижаш-ду-Эрмелу. Его называют одним из самых больших водопадов страны. Вода спускается по скалам несколькими уступами, а вся высота, как говорят, около двухсот метров. Мелкие брызги висят в воздухе, а над ними иногда стоит радуга. Рядом проложена тропа, по которой можно подойти к воде. Внизу шумит так громко, что приходится говорить погромче.", "q": "Что иногда можно увидеть над водопадом из-за брызг?", "a": [ "Радугу", "Северное сияние", "Звёзды днём" ] }, { "id": "por-b-iberian-wolf", "e": "🐺", "t": "Осторожный волк", "s": "В горах севера Португалии живёт иберийский волк. Он серый, с тёмной полоской на лапах, и немного поменьше обычных волков. Волки живут семьями и осторожно держатся подальше от людей. Увидеть их почти невозможно, но иногда по ночам слышно, как они перекликаются воем. Волки следят за порядком в лесу: им достаются больные и слабые животные.", "q": "Как перекликаются волки по ночам?", "a": [ "Воем", "Свистом", "Громким лаем" ] }, { "id": "por-b-cows", "e": "🐄", "t": "Коровы с рогами-арфами", "s": "В горах севера пасутся коровы старых местных пород. У баррозанских коров длинные рога, изогнутые, как лира или арфа. А коровы породы кашена совсем небольшие, тёмно-рыжие, с красивыми рогами. Летом их часто пасут на высоких горных лугах, а на зиму возвращают в деревню. Местные жители гордятся такими коровами и бережно хранят их породу.", "q": "На что похожи рога баррозанских коров?", "a": [ "На лиру или арфу", "На колёса", "На прямые палки" ] }, { "id": "por-b-miranda-donkey", "e": "🫏", "t": "Мирандский ослик", "s": "На северо-востоке Португалии живут мирандские ослы. Они крупные, с густой шерстью и большими ушами. У них спокойный и добрый нрав. Раньше они возили людей и грузы по узким тропам, а теперь их осталось мало, и их берегут. Ослов можно погладить на ферме и покормить морковкой. Зимой густая шерсть спасает их от холода.", "q": "Какие уши у мирандских ослов?", "a": [ "Большие, длинные", "Совсем крошечные", "Круглые, как у мишки" ] }, { "id": "por-b-foz-coa", "e": "🦌", "t": "Рисунки на камне", "s": "У реки Коа, недалеко от того места, где она впадает в Дору, на скалах нашли рисунки. Их выцарапали люди, которые жили здесь очень давно — самым старым рисункам, говорят, около тридцати тысяч лет. Древние художники изобразили лошадей, оленей, быков и диких козлов тонкими линиями прямо на камне. Теперь это место называется Фош-Коа, там устроили парк для посетителей, а рисунки охраняет ЮНЕСКО.", "q": "Кого нарисовали на скалах Фош-Коа древние люди?", "a": [ "Лошадей, оленей и быков", "Кораблей", "Самолётов" ] }, { "id": "por-b-miranda-language", "e": "🗣️", "t": "Второй язык страны", "s": "В Португалии говорят по-португальски. Но возле города Миранда-ду-Дору, у границы с Испанией, жители говорят ещё и на мирандском языке. Он очень старый, и в нём можно услышать что-то и от португальского, и от испанского. Мирандский признали официальным языком в тысяча девятьсот девяносто девятом году. Теперь его учат в школах, чтобы он не пропал.", "q": "Где говорят на мирандском языке?", "a": [ "Возле города Миранда-ду-Дору", "В Лиссабоне", "На острове Мадейра" ] }, { "id": "por-b-braganca-domus", "e": "🔷", "t": "Пятиугольный дом", "s": "В городе Браганса, на северо-востоке Португалии, есть необычное старинное здание — Домус Мунисипалис. Его построили в средние века из камня, и точный год никто не знает наверняка. Стены у него не квадратные, а пятиугольные: их пять. Говорят, раньше в нём собирались жители города, чтобы решать важные дела. Рядом стоит замок с высокой башней. Такие здания очень редки.", "q": "Сколько стен у дома Домус Мунисипалис?", "a": [ "Пять", "Четыре", "Семь" ] }, { "id": "por-b-douro-train", "e": "🚂", "t": "Поезд у воды", "s": "Старый поезд идёт вдоль реки Дору и всё время виляет вместе с ней. Рельсы проложены почти у самой воды: за окном то виноградники на склонах, то тихая вода, то каменный мост. Поезд едет не торопясь, будто сам любуется видами. Кто едет в вагоне, может сидеть у окна и считать лодки на реке.", "q": "Что видно из окна поезда вдоль Дору?", "a": [ "Виноградники и реку", "Пустыню", "Снежные горы" ] }, { "id": "por-b-almond-blossom", "e": "🌸", "t": "Весной на севере цветёт миндаль", "s": "В конце зимы на северо-востоке Португалии, в краю Траз-уш-Монтеш, расцветают миндальные деревья. Их ветки покрываются белыми и розовыми цветами, пока вокруг ещё холодно. Издали кажется, что на земле лежит лёгкий снег. Люди приезжают гулять среди цветов. А позже на деревьях созревает миндаль.", "q": "Какие плоды потом появляются на этих деревьях?", "a": [ "Миндаль", "Апельсины", "Бананы" ] }, { "id": "por-c-sanzhuan-molotki", "e": "🔨", "t": "Молоточки Сан-Жуана", "s": "В ночь на 24 июня Порту празднует Сан-Жуан — день святого Иоанна. Улицы полны народу, и почти у каждого в руках игрушечный пластиковый молоточек, который смешно пищит. Прохожие в шутку легонько стучат им друг друга по макушке, а потом смеются и идут дальше. Раньше вместо молоточков, говорят, в ход шли пучки лука-порея. Такую шутку считают весёлой приметой.", "q": "Чем шутя стучат друг друга по голове в ночь Сан-Жуана?", "a": [ "Пищащими пластиковыми молоточками", "Мягкими подушками", "Бумажными веерами" ] }, { "id": "por-c-sanzhuan-manzheriku", "e": "🌿", "t": "Горшочек с четверостишием", "s": "К Сан-Жуану в Порту дарят горшочки с душистым базиликом — его называют манжерику. В землю воткнут бумажный цветочек, а к нему приколота бумажка со стишком из четырёх строк. В стишке пишут что-нибудь доброе или весёлое, часто про любовь. Горшочек ставят на подоконник, и вся комната пахнет летом. Нюхать листики можно, а вот есть такой базилик не принято.", "q": "Что приколото к горшочку с манжерику?", "a": [ "Бумажка со стишком из четырёх строк", "Маленький колокольчик", "Конфета на верёвочке" ] }, { "id": "por-c-sanzhuan-sardiny", "e": "🐟", "t": "Сардина на ломте хлеба", "s": "В ночь Сан-Жуана на улицах Порту пахнет дымом: прямо у домов на маленьких жаровнях жарят сардин. Рыбку не кладут на тарелку, а кладут на толстый ломоть хлеба — он впитывает сок и сам становится вкусным. Едят руками, сидя за длинными столами вместе с соседями. Сардину в Португалии любят так сильно, что в июне её едят почти все.", "q": "На чём подают жареную сардину в Сан-Жуан?", "a": [ "На ломте хлеба", "На большом листе капусты", "На палочке для мороженого" ] }, { "id": "por-c-sanzhuan-ogni", "e": "🎆", "t": "Огни над Дору", "s": "Ночью на Сан-Жуан над рекой Дору вспыхивает праздничный фейерверк. Смотреть его собираются тысячи людей: кто на набережной, кто на высоком мосту, кто на холме над городом. Огни отражаются в тёмной воде, и кажется, что салют идёт сразу и в небе, и под ним. Дети в эту ночь не спят дольше обычного, а утром город тихо отсыпается.", "q": "Над какой рекой Порту смотрит праздничный салют?", "a": [ "Над рекой Дору", "Над рекой Невой", "Над рекой Рейн" ] }, { "id": "por-c-barselush-petuh", "e": "🐓", "t": "Петух, который запел", "s": "Старая легенда рассказывает про город Барселуш. Одного путника несправедливо обвинили, и судья уже собирался вынести строгий приговор. Путник показал на жареного петуха на столе и сказал: «Если я прав, он запоёт». И петух встал на блюде и закукарекал! Судья поверил и отпустил путника. С тех пор петух из Барселуша стал знаком удачи, а потом и всей Португалии.", "q": "Что сделал жареный петух из легенды Барселуша?", "a": [ "Встал на блюде и закукарекал", "Улетел в окно", "Заговорил человеческим голосом" ] }, { "id": "por-c-barselush-yarmarka", "e": "🛍️", "t": "Четверговая ярмарка", "s": "В Барселуше каждый четверг на большой площади собирается ярмарка. Здесь продают глиняных петухов, посуду, кружева, корзины, сыры, хлеб и свежие овощи. Торговцы громко зазывают, а покупатели торгуются и пробуют угощение. Многие приезжают из соседних деревень ради этого дня. Из Барселуша часто увозят домой раскрашенного петуха — на счастье.", "q": "В какой день недели в Барселуше бывает ярмарка?", "a": [ "В четверг", "В воскресенье", "В среду" ] }, { "id": "por-c-barselush-rosa-ramalyu", "e": "🏺", "t": "Фигурки Розы Рамалю", "s": "Рядом с Барселушем жила гончарка Роза Рамалю. Она лепила из глины не только кувшины, но и фигурки: людей, зверей и придуманных существ с рогами. Фигурки у неё получались смешные и немного загадочные. Когда Роза была уже немолодой, о ней узнали художники, а потом и вся страна. Сегодня её работы показывают в музеях, а работать так же учатся её внуки и правнуки.", "q": "Что лепила Роза Рамалю из глины?", "a": [ "Людей, зверей и придуманных существ", "Только тарелки", "Маленькие домики" ] }, { "id": "por-c-viana-serdtse", "e": "💛", "t": "Сердечко из Виана", "s": "В городе Виана-ду-Каштелу делают знаменитые золотые сердечки. Мастер вытягивает тончайшую золотую проволоку, сплетает из неё узор и сгибает в форме сердца с завитками. Украшение выходит лёгким, как кружево, но из металла. Такие сердечки носят на шее, и на севере Португалии их считают знаком любви. Их часто передают от мамы к дочке.", "q": "Из чего мастера делают сердечко из Виана?", "a": [ "Из тонкой золотой проволоки", "Из цветного стекла", "Из деревянных бусин" ] }, { "id": "por-c-syr-za-gorami", "e": "🧀", "t": "Сыр «за горами»", "s": "На северо-востоке Португалии есть край Траз-уш-Монтеш. Его имя означает «за горами»: места там дальние и высокие. Пастухи пасут овец и делают из их молока сыр терриншу. Молодой сыр мягкий и сливочный, а когда он вылежится, вкус становится крепче. Вокруг тихо, а на лугах слышны колокольчики. Говорят, что в такой дали и сыр особенно вкусный.", "q": "Что означает название края Траз-уш-Монтеш?", "a": [ "«За горами»", "«Около моря»", "«У большой реки»" ] }, { "id": "por-c-hleb-broa", "e": "🍞", "t": "Хлеб из кукурузы", "s": "На севере Португалии пекут хлеб броа. Его месят из кукурузной и ржаной муки, поэтому он тёмный и плотный. Корка у него толстая и хрустящая, а мякиш чуть сладковатый. Особенно известна броа из Авинтеша, рядом с Порту. Её едят с супом, с сыром и с сардинами. Пахнет такой хлеб полем и тёплой печкой.", "q": "Какая мука есть в тесте хлеба броа?", "a": [ "Кукурузная", "Рисовая", "Картофельная" ] }, { "id": "por-c-pao-de-lo-ovar", "e": "🎂", "t": "Бисквит с серединкой-кремом", "s": "В городе Овар пекут особый бисквит пан-ди-ло. В него кладут много яиц, особенно желтков, и поэтому он жёлтый, как солнце. Его не допекают до конца, и серединка остаётся мягкой, почти как густой крем. Корочка сверху тонкая, а внутри всё течёт на ложку. Такой пирог часто пекут на праздники, и в большой семье он исчезает за минуты.", "q": "Какая серединка у бисквита пан-ди-ло из Овара?", "a": [ "Мягкая, как густой крем", "Твёрдая, как сухарь", "С орехом внутри" ] }, { "id": "por-c-aveyru-yaichnye", "e": "🥚", "t": "Сладости-ракушки", "s": "В городе Авейру делают сладости, которые называют овуш молеш. Внутри мягкая сладкая начинка из желтков и сахара, а снаружи тонкая хрустящая вафелька. Вафельки лепят в форме ракушек, рыбок и маленьких бочонков — ведь город стоит у воды. Такие сладости придумали давно, говорят, в монастырях, а теперь продают в красивых расписных коробочках.", "q": "В какой форме делают вафельки для сладостей из Авейру?", "a": [ "В форме ракушек и рыбок", "В форме звёзд и снежинок", "В форме колёс и шестерёнок" ] }, { "id": "por-c-aveyru-moliseyru", "e": "🚣", "t": "Лодки с картинками", "s": "По лагуне вокруг Авейру ходят длинные узкие лодки молисейру. У них высоко загнутый нос, а на бортах нарисованы весёлые картинки и подписи — иногда даже шутки. Раньше на таких лодках собирали водоросли, чтобы удобрять поля. Теперь на них катают туристов, и можно плыть медленно, пока вокруг скользят цапли и чайки. Лодки напоминают нарядные гондолы.", "q": "Для чего раньше использовали лодки молисейру?", "a": [ "Собирали водоросли для полей", "Возили почту", "Ловили китов" ] }, { "id": "por-c-eyro-dom", "e": "🏠", "t": "Амбар на ножках", "s": "В деревнях Соажу и Линдозу на севере Португалии стоят каменные амбары на ножках — их зовут эшпигейру. Они узкие и длинные, как маленькие домики. В них хранят початки кукурузы, чтобы те сохли и не гнили. Весь амбар сложен из камня, а в стенах оставлены щели. Через них гуляет ветер, и зёрна остаются сухими даже в сырую погоду.", "q": "Зачем в стенах эйро оставляют щели?", "a": [ "Чтобы ветер сушил кукурузу", "Чтобы светило солнце", "Чтобы видеть улицу" ] }, { "id": "por-c-eyro-kresty", "e": "✝️", "t": "Крестики на крышах", "s": "Если пройтись между амбарами эшпигейру, видно, что на крыше у многих стоит каменный крестик. Сверху амбар часто похож на маленькую церковь. В Линдозу их стоит целая деревня: по разным подсчётам, больше пятидесяти каменных домиков плечом к плечу. Самым старым из них, говорят, уже несколько сотен лет.", "q": "Что часто стоит на крыше амбара эшпигейру?", "a": [ "Каменный крестик", "Флюгер-петух", "Круглый колокол" ] }, { "id": "por-c-eyro-myshi", "e": "🐭", "t": "Каменные шляпки против мышей", "s": "Амбары эшпигейру стоят на каменных столбиках, а сверху на каждом столбике лежит плоский круглый камень, как шляпа. Мышь взбирается по столбику, доходит до шляпки — и дальше ей никак: камень выступает вперёд. Так зёрна кукурузы остаются целыми. Так люди придумали защиту от грызунов без замков и ловушек — и это работает до сих пор.", "q": "Что мешает мышам забраться в амбар эшпигейру?", "a": [ "Плоские камни-шляпки на столбиках", "Острые колючки", "Ров с водой" ] }, { "id": "por-c-kukuruza-iz-za-okeana", "e": "🌽", "t": "Кукуруза приплыла из-за океана", "s": "В Европе когда-то не знали кукурузы. Она выросла в Америке, а моряки привезли её на кораблях примерно пятьсот лет назад. В дождливом северо-западе Португалии кукуруза прижилась лучше, чем многие злаки. Из неё стали печь хлеб и варить густую кашу. Теперь жёлтые поля — такая же часть севера, как виноградники и холмы.", "q": "Откуда в Европу привезли кукурузу?", "a": [ "Из Америки", "Из Африки", "Из Австралии" ] }, { "id": "por-c-poveu-podpisi", "e": "⛵", "t": "Знаки рыбацких семей", "s": "В рыбацком городе Повуа-ди-Варзин у каждой семьи был свой знак из прямых линий и угольников, похожий на загадочную руну. Такой знак переходил от отца к сыну. Его вырезали или рисовали на лодках, на вёслах и на других вещах. Так сразу было видно, чья это вещь. Эти знаки называют «сиглаш повейраш», и о них до сих пор помнят.", "q": "Что рыбаки Повуа-ди-Варзин ставили вместо подписи?", "a": [ "Свой знак из линий", "Отпечаток ладони", "Нарисованную рыбку" ] }, { "id": "por-c-svitery-povua", "e": "🧶", "t": "Свитер с вышивкой", "s": "В Повуа-ди-Варзин рыбаки носили тёплые вязаные свитеры из шерсти. Поверх вязки вышивали узоры красной, белой или чёрной ниткой. Вышивали жёны, сёстры и мамы рыбаков, и в узорах прятали ласковые послания. Такой свитер называют «камизола повейра». Сейчас такие свитеры делают уже не так часто, и каждый похож на маленькое произведение искусства.", "q": "Какими нитками вышивали узоры на свитерах рыбаков?", "a": [ "Красными, белыми или чёрными", "Золотыми", "Радужными" ] }, { "id": "por-c-vila-du-konde-korabli", "e": "⚓", "t": "Корабль у музея", "s": "В городе Вила-ду-Конде, у реки Аве, с давних времён строили корабли. Об этом напоминает большой парусник у набережной. Это копия старинного португальского корабля шестнадцатого века, его поставили у музея около двадцати лет назад. На борт можно подняться, пройтись по палубе и заглянуть внутрь. Сразу представляешь, как моряки уходили на таком корабле в океан.", "q": "Что стоит у музея в Вила-ду-Конде?", "a": [ "Копия старинного парусника", "Настоящая подводная лодка", "Железный мост" ] }, { "id": "por-c-poezd-vdol-doru", "e": "🚂", "t": "Поезд вдоль Дору", "s": "Одна из самых красивых железных дорог Португалии идёт от Порту вдоль реки Дору. Рельсы бегут то у самой воды, то над ней, то по тоннелям. За окном — террасы с виноградом, лодки и белые домики. Ехать нужно не торопясь, и можно просто смотреть, как мимо плывёт речная долина. Многие едут нарочно ради одной только дороги.", "q": "Вдоль какой реки идёт красивая железная дорога из Порту?", "a": [ "Вдоль Дору", "Вдоль Волги", "Вдоль Дуная" ] }, { "id": "por-c-poezd-pinyan", "e": "🚉", "t": "Станция в картинках", "s": "На станции Пиньян, на севере Португалии, стены покрыты синими картинами из плитки. На них — виноградники, сборщики урожая и лодки на реке Дору. Пока ждёшь поезд, можно рассматривать целую историю. Картины сделали около девяноста лет назад, и они до сих пор яркие. Поезд приходит, но уезжать сразу не хочется.", "q": "Чем украшены стены станции Пиньян?", "a": [ "Картинами из плитки", "Рисунками мелом", "Деревянной резьбой" ] }, { "id": "por-c-poezd-vuga", "e": "🚃", "t": "Поезд-малыш", "s": "Недалеко от Авейру ходит малыш-поезд по линии Вуга. Рельсы здесь уже, чем обычно, поэтому и вагоны узкие и маленькие. Он неторопливо стучит по долинам, мимо полей и речек, и останавливается в маленьких деревнях. Кажется, что поезд в гости ходит к каждому. Узкоколейка работает и теперь, а ехать по ней — настоящее приключение.", "q": "Чем отличаются рельсы линии Вуга от обычных?", "a": [ "Они уже", "Они из дерева", "Они разноцветные" ] }, { "id": "por-c-poezd-parovoz", "e": "🚆", "t": "Старинный поезд", "s": "Летом по долине Дору ходит старинный поезд. У него вагоны начала двадцатого века, с деревянными скамейками, а тянет его старый локомотив. Раньше, бывало, это был настоящий паровоз, который пыхтел и пускал пар. Поезд едет от Регуа до Туа, не торопясь, мимо реки, виноградников и маленьких станций. Сидишь у окна и будто попадаешь на сто лет назад.", "q": "Какие вагоны у старинного поезда на Дору?", "a": [ "Старинные, начала двадцатого века", "Стеклянные, как аквариум", "Двухэтажные, красные" ] }, { "id": "por-c-karetush-podene", "e": "🎭", "t": "Карнавал в бахроме", "s": "В деревне Подене на карнавал выходят каретуш — ряженые в ярких костюмах. Костюм сшит из длинных цветных полос шерсти, а на лицо надета маска. На поясе у каретуш звенят колокольчики. Они бегут по деревне, гремят и шутя гоняются за людьми. Этот карнавал внесён в список нематериального наследия ЮНЕСКО.", "q": "Из чего сшиты костюмы каретуш?", "a": [ "Из цветных полос шерсти", "Из перьев", "Из бумаги" ] }, { "id": "por-c-lima-zabvenie", "e": "🌊", "t": "Река, из-за которой всё забывают", "s": "Старая легенда рассказывает, что древние римляне, придя на север Португалии, увидели реку Лима. Воины решили, что это река забвения: кто её перейдёт — забудет всё. Они боялись переходить. Тогда командир сам вошёл в воду и перешёл на другой берег. Потом позвал каждого воина по имени. Все поняли, что память на месте, и пошли за ним.", "q": "Что боялись забыть римляне у реки Лима?", "a": [ "Всё, что знали", "Дорогу домой", "Названия цветов" ] }, { "id": "por-c-mirandesh-yazyk", "e": "🗣️", "t": "Второй язык Португалии", "s": "Вы удивитесь, но в Португалии говорят не только по-португальски. На северо-востоке, в городе Миранда-ду-Дору, живёт язык мирандеш. Он похож на португальский, но звучит иначе, и на нём говорят дома и в школе. Его признали официальным языком в 1999 году. А ещё в Миранде танцуют танец с палками: танцоры в юбках стучат деревянными палками друг о друга в такт музыке.", "q": "Как называется второй официальный язык Португалии?", "a": [ "Мирандеш", "Каталанский", "Баскский" ] }, { "id": "por-c-viana-kovry", "e": "🌸", "t": "Цветочные ковры Виана", "s": "В августе в Виана-ду-Каштелу проходит праздник Сеньора-да-Агония. Улицы украшают ковры, но не из ниток, а из цветных опилок, лепестков и соли. Люди делают их ночью, перед праздником, и рисуют узоры прямо на мостовой. Утром улицы выглядят, как разноцветная сказка. Потом по коврам идёт шествие, но никто не расстраивается: на другой год будут новые.", "q": "Из чего делают ковры на улицах Виана?", "a": [ "Из цветных опилок и лепестков", "Из шерсти", "Из конфет" ] }, { "id": "por-c-treska-bakalau", "e": "🍽️", "t": "Треска, которая не из Португалии", "s": "Самая любимая рыба в Португалии — бакалау, то есть сушёная солёная треска. Её ловили далеко в холодных северных морях, засаливали и сушили, чтобы не испортилась в дороге. Перед готовкой её долго мочат в воде. Говорят, рецептов с бакалау столько, что хватит на каждый день года. Вот почему на севере и на юге страны есть свои любимые блюда с этой рыбой.", "q": "Что делают с бакалау перед готовкой?", "a": [ "Долго мочат в воде", "Замораживают", "Жарят на углях сырой" ] } ], "pt": [ { "id": "pt-n-estrela", "e": "🏔️", "t": "Звёздные горы", "s": "Серра-да-Эштрела значит «Звёздные горы». Это самые высокие горы Португалии на большой земле, если не считать островов. Зимой там лежит настоящий снег, и дети катаются на санках и лыжах. А ещё в этих горах живёт большая лохматая собака — эштрельская овчарка. Много веков она охраняла овец от волков, а со своей семьёй она ласковая и добрая.", "q": "Что значит Серра-да-Эштрела?", "a": [ "Звёздные горы", "Шоколадные горы", "Горы-невидимки" ] }, { "id": "pt-n-pico", "e": "🌋", "t": "Гора посреди океана", "s": "Самая высокая гора Португалии стоит посреди океана, на Азорских островах. Это вулкан Пику, он выше двух тысяч трёхсот метров, а остров вокруг него тоже называется Пику. На самой макушке горы есть ещё одна маленькая горка, её ласково зовут Пикинью. Зимой вершину покрывает снег, и гора похожа на мороженое в вафельном рожке. А облака часто плывут ниже вершины, как белое одеяло.", "q": "Где стоит самая высокая гора Португалии?", "a": [ "На острове посреди океана", "На крыше школы", "В бабушкином огороде" ] }, { "id": "pt-n-furnas", "e": "🍲", "t": "Обед из-под земли", "s": "На острове Сан-Мигел есть долина Фурнаш. Земля там такая горячая, что из неё идёт пар и булькают горячие источники. Повара кладут в большую кастрюлю мясо, колбаски, картошку и капусту, закрывают крышкой и закапывают в горячую землю у озера. Примерно через шесть часов кастрюлю достают, а внутри готов обед — кузиду. Его сварил сам вулкан!", "q": "Где варят кузиду в долине Фурнаш?", "a": [ "В горячей земле", "В холодильнике", "В ведре со снегом" ] }, { "id": "pt-n-cha", "e": "🍵", "t": "Чайный остров", "s": "Чаю нужны тепло и дожди, поэтому в Европе он почти нигде не растёт. А на острове Сан-Мигел на Азорских островах чай выращивают уже больше ста лет. Чайные кусты подстригают ровными рядами, и зелёные холмы становятся полосатыми, как свитер. Весной и летом собирают самые молодые листочки, сушат их, и получается чай.", "q": "Что растёт на полосатых холмах острова Сан-Мигел?", "a": [ "Чай", "Мороженое", "Пуговицы" ] }, { "id": "pt-n-cesto", "e": "🛷", "t": "Санки без снега", "s": "На острове Мадейра катаются на санках без всякого снега! Эти санки — плетёные кресла-корзинки на деревянных полозьях. Двое мужчин в белой одежде и соломенных шляпах толкают санки, бегут рядом и рулят. А тормозят они собственными ботинками на толстой резиновой подошве. Так санки мчатся по улицам около двух километров, от посёлка Монте вниз, в сторону Фуншала. Катаются так уже больше ста лет.", "q": "Чем тормозят санки на Мадейре?", "a": [ "Ботинками", "Зонтиками", "Бутербродами" ] }, { "id": "pt-n-lince", "e": "🐈", "t": "Рысь с кисточками", "s": "Иберийская рысь — дикая кошка с пятнистой шубкой, кисточками на ушах и пушистыми бакенбардами. Она живёт только в Португалии и Испании и больше всего любит охотиться на кроликов. Когда-то таких рысей осталось совсем мало, меньше ста. Люди стали их беречь, растить малышей и выпускать на волю. Теперь их уже больше двух тысяч, и рыси снова бегают по холмам Португалии.", "q": "На кого больше всего любит охотиться иберийская рысь?", "a": [ "На кроликов", "На бегемотов", "На пингвинов" ] }, { "id": "pt-n-konki", "e": "🐠", "t": "Папа морского конька", "s": "На юге Португалии, в Алгарве, есть тёплая лагуна Риа-Формоза. Среди подводной травы там живут морские коньки. Они плавают стоя и держатся хвостиком за травинки, как за верёвочку. А самое удивительное: малышей у них вынашивает папа! Он носит икринки в кармашке на животе, пока оттуда не выплывут крошечные коньки. Люди берегут эту лагуну, чтобы конькам было где жить.", "q": "Кто вынашивает малышей у морских коньков?", "a": [ "Папа", "Бабушка-черепаха", "Почтальон" ] }, { "id": "pt-n-batalha", "e": "🏛️", "t": "Зал без крыши", "s": "В городе Баталья стоит огромный монастырь, весь в каменных узорах, как в кружевах. Почти шестьсот лет назад король велел пристроить к нему ещё один большой зал с капеллами. Мастера вырезали из камня высокие арки и тонкие узоры, но крышу так и не построили. Поэтому эти капеллы называют Незавершёнными. Вместо потолка у них небо: туда залетают птицы, а дождик капает прямо внутрь.", "q": "Что у Незавершённых капелл вместо потолка?", "a": [ "Небо", "Зонтик", "Батут" ] }, { "id": "pt-n-tomar", "e": "🛡️", "t": "Круглая церковь рыцарей", "s": "В городе Томар на холме стоит крепость, которую построили рыцари-тамплиеры. Внутри неё прячется удивительная круглая церковь — Шарола. Ей больше восьмисот лет. Снаружи у неё шестнадцать стен, и она похожа на огромный барабан. А внутри всё расписано картинами и сияет золотом. Есть старая легенда, что рыцари заезжали туда прямо на конях.", "q": "Какая церковь спрятана в крепости Томара?", "a": [ "Круглая", "Пряничная", "Плавающая" ] }, { "id": "pt-n-marvao", "e": "🦅", "t": "Деревня-гнездо", "s": "Марван — маленькая деревня на вершине высокой скалы. Её со всех сторон окружают крепкие каменные стены, а на самом краю стоит замок. Издалека деревня похожа на орлиное гнездо. Отсюда видно очень далеко, даже соседнюю Испанию. А когда внизу в долинах лежит туман, кажется, что деревня плывёт по облакам.", "q": "На что похожа деревня Марван издалека?", "a": [ "На орлиное гнездо", "На кастрюлю с супом", "На резиновую уточку" ] }, { "id": "pt-n-berlengas", "e": "🐦", "t": "Крепость посреди моря", "s": "Недалеко от города Пенише, прямо в океане, лежат острова Берленгаш. На крошечном островке там стоит старая каменная крепость, а к ней ведёт узкий каменный мостик. Людей на островах почти нет, зато птиц — тысячи! Чайки кричат, вьют гнёзда прямо на скалах и строго смотрят на гостей. А вода вокруг такая прозрачная, что видно рыбок.", "q": "Кого на островах Берленгаш тысячи?", "a": [ "Птиц", "Жирафов", "Пожарных" ] }, { "id": "pt-n-pao-por-deus", "e": "🎒", "t": "Пан-пур-Деуш", "s": "Первого ноября дети в Португалии берут тканевые мешочки и ходят от двери к двери. Они стучат к соседям и говорят: «Пан-пур-Деуш!» Соседи кладут им в мешочки булочки, орехи, каштаны, гранаты и конфеты. Этот обычай очень старый, так делали ещё прабабушки и прадедушки нынешних детей. А свои мешочки дети часто украшают сами.", "q": "Что говорят дети у дверей первого ноября?", "a": [ "Пан-пур-Деуш", "Абракадабра", "Ку-ка-ре-ку" ] }, { "id": "pt-n-saudade", "e": "💙", "t": "Слово «саудаде»", "s": "В португальском языке есть особенное слово — «саудаде». Его очень трудно перевести на другие языки. Саудаде — это когда скучаешь по тому, кого любишь, или по месту, где тебе было хорошо. Немножко грустно, но и тепло, потому что вспоминаешь хорошее. Когда бабушка далеко, а ты вспоминаешь её пирожки и сказки, — это и есть саудаде. О саудаде португальцы поют песни фаду.", "q": "Что значит «саудаде»?", "a": [ "Скучать по тому, кого любишь", "Чихать от перца", "Прыгать на одной ножке" ] }, { "id": "pt-n-lingua", "e": "🌍", "t": "Язык на четырёх континентах", "s": "На португальском языке говорят не только в Португалии. Его можно услышать в Бразилии в Южной Америке, в Анголе и Мозамбике в Африке и даже в Восточном Тиморе в Азии. Всего на нём говорят больше двухсот миллионов человек, а больше всего — в Бразилии. Вот как далеко разлетелся язык маленькой страны! А пятого мая отмечают Всемирный день португальского языка.", "q": "Где больше всего людей говорят по-португальски?", "a": [ "В Бразилии", "На Луне", "В муравейнике" ] }, { "id": "pt-n-costa-nova", "e": "🏖️", "t": "Домики в пижамах", "s": "У океана, рядом с городом Авейру, есть посёлок Кошта-Нова. Его домики раскрашены широкими полосками: красными, синими, зелёными, жёлтыми — и обязательно белыми. Кажется, будто дома надели полосатые пижамы. Раньше здесь стояли деревянные сараи, где рыбаки хранили сети. Говорят, яркие полоски помогали рыбакам издалека узнать свой домик, даже в туман.", "q": "На что похожи домики в посёлке Кошта-Нова?", "a": [ "На полосатые пижамы", "На колючие кактусы", "На летающие тарелки" ] }, { "id": "pt-n-a-cork-number", "e": "🌳", "t": "Число на стволе", "s": "В Португалии растут пробковые дубы. С них снимают кору, как с апельсина, но дерево от этого не болеет. Новая кора отрастает, и снова её снимают только лет через девять. Чтобы не забыть, мастера пишут краской на стволе последнюю цифру года. Если на дереве стоит цифра 5, значит, его раздевали в году, который кончается на пять. Такой дуб может жить около двухсот лет и раз за разом дарить людям кору.", "q": "Для чего на стволе пробкового дуба пишут цифру?", "a": [ "Чтобы помнить, в каком году снимали кору", "Чтобы сосчитать листья", "Чтобы птицы не садились на ветки" ] }, { "id": "pt-n-a-cork-space", "e": "🚀", "t": "Пробка летит в космос", "s": "Знаешь, почему пробка не тонет в воде? Внутри неё очень много крошечных воздушных пузырьков. Из-за них кора пробкового дуба лёгкая, упругая и плохо пропускает тепло. Португальцы делают из неё не только затычки для бутылок, но и подошвы, сумки, шляпы и даже плитку для пола. А ещё тонкий слой пробки кладут на ракеты: он помогает им не перегреваться, когда они летят сквозь воздух. Так кусочек португальского леса отправляется к звёздам.", "q": "Почему пробка такая лёгкая и не тонет?", "a": [ "В ней много крошечных воздушных пузырьков", "Она сделана из железа", "Она полностью пустая внутри, как стекло" ] }, { "id": "pt-n-a-salt-castro", "e": "🧂", "t": "Соляной цветок", "s": "На юге Португалии, возле городка Кастру-Марин, море запускают в мелкие прудики. Летом солнце греет воду, она испаряется, а соль остаётся. Белые горки соли лежат прямо у воды и блестят, как снег. Самую нежную соль собирают сверху, с поверхности воды, лёгкими деревянными граблями. Её называют «флор-де-саль» — «соляной цветок». Пальцами её можно раскрошить в тонкие хрустящие хлопья.", "q": "Как называют самую нежную соль, которую собирают с поверхности воды?", "a": [ "Соляной цветок", "Морской снег", "Белый песок" ] }, { "id": "pt-n-a-flamingo-sapal", "e": "🦩", "t": "Розовые птицы на солёной воде", "s": "Рядом с соляными прудами Алгарве лежат болота, где всегда много птиц. Сюда прилетают розовые фламинго. Они ходят на тонких ногах по мелкой солёной воде и что-то ищут, опустив клюв вниз головой. Они добывают крошечных рачков и водоросли, и от этой еды перья становятся розовыми. Родившийся фламинго серый, а розовым он делается только потом. Птенцы хорошо видны, если смотреть издалека в бинокль.", "q": "От чего у фламинго розовеют перья?", "a": [ "От крошечных рачков и водорослей, которых они едят", "От розовой краски", "От заката, который их красит" ] }, { "id": "pt-n-a-madeira-levada", "e": "💧", "t": "Водяные тропинки", "s": "На острове Мадейра дожди идут в горах, а поля и сады лежат внизу, где суше. Давным-давно люди прорыли длинные узкие канавы, чтобы вода сама бежала с горы к полям. Их называют «левады». Рядом с каждой водой осталась ровная тропинка, и по ней сегодня гуляют туристы. Левады идут через лес, мимо водопадов и по краю обрывов. Идёшь по тропинке, а рядом журчит ручей, который сам показывает путь.", "q": "Зачем на Мадейре прорыли левады?", "a": [ "Чтобы вода из гор текла к полям и садам", "Чтобы по ним плавали лодки", "Чтобы отпугивать птиц от огорода" ] }, { "id": "pt-n-a-madeira-fanal", "e": "🌫️", "t": "Лес в тумане", "s": "На острове Мадейра сохранился очень старый лавровый лес. Он растёт здесь миллионы лет, и ЮНЕСКО берёт его под охрану. Одно из самых сказочных мест — лесная поляна Фанал. Там стоят старые кривые деревья, покрытые мхом, а часто между ними плывёт туман. Лес кажется волшебным, будто сейчас выйдет лесной великан. Само слово «Мадейра» значит «дерево»: когда-то остров был почти весь покрыт лесом.", "q": "Что значит слово «Мадейра» по-португальски?", "a": [ "Дерево", "Цветок", "Облако" ] }, { "id": "pt-n-a-desertas-seals", "e": "🦭", "t": "Тюлени из Дезерташ", "s": "Недалеко от Мадейры есть три необитаемых скалистых острова — Дезерташ. Там живут очень редкие морские тюлени-монахи. Говорят, их назвали так за круглую голову и складки на шее, похожие на капюшон монаха. Когда-то этих зверей осталось совсем мало, и острова объявили заповедником, чтобы никто не мешал тюленям. Люди берегут их, и малышей-тюленей теперь рождается всё больше. Тюлени греются на камнях и ныряют за рыбой.", "q": "Почему на островах Дезерташ берегут тюленей?", "a": [ "Эти тюлени очень редкие", "Они дают тёплую шерсть", "Они умеют разговаривать" ] }, { "id": "pt-n-a-cabo-girao", "e": "🪟", "t": "Стеклянный балкон", "s": "На острове Мадейра есть одна из самых высоких морских скал в Европе — Кабу-Жирау, около пятисот восьмидесяти метров. Там устроили смотровую площадку с прозрачным стеклянным полом. Встанешь на него и увидишь далеко внизу крошечные дома, лодочки и огороды на узких террасах. Кажется, что ты висишь в воздухе, как птица. Внизу, у самой воды, люди выращивают овощи на маленьких уступах, куда ведёт канатная дорога.", "q": "Из чего сделан пол на смотровой площадке у скалы Кабу-Жирау?", "a": [ "Из прозрачного стекла", "Из дерева", "Из мягкой пробки" ] }, { "id": "pt-n-a-porto-santo-sand", "e": "🏖️", "t": "Золотой остров", "s": "Рядом с Мадейрой лежит маленький остров Порту-Санту. Почти все пляжи на Мадейре из камешков, а здесь тянется золотой песок длиной около девяти километров. Можно идти по тёплому мелкому берегу очень долго и не дойти до конца. Вода у берега тихая и ясная, поэтому малыши плещутся там без страха. Люди говорят, что песок на острове полезен для здоровья, и многие лежат в нём, закопавшись по самую шею.", "q": "Какой пляж на острове Порту-Санту?", "a": [ "Длинный пляж с золотым песком", "Пляж из чёрных камней", "Пляж с белыми ракушками, где нельзя купаться" ] }, { "id": "pt-n-a-sete-cidades", "e": "💙", "t": "Два озера разного цвета", "s": "На острове Сан-Мигел, в Азорских островах, лежит огромная древняя чаша. В ней стоят два соседних озера, соединённые узкой полоской воды. Одно озеро синее, а другое зелёное. Рассказывают легенду, и в разных версиях она чуть разная: принцесса и пастух полюбили друг друга, но им нельзя было встречаться. Они плакали, и слёзы стали озёрами: в одной версии глаза принцессы были голубые, а глаза пастуха — зелёные. Место называется Сете-Сидадеш.", "q": "Какого цвета два озера в Сете-Сидадеш?", "a": [ "Одно синее, другое зелёное", "Оба красные", "Одно белое, другое чёрное" ] }, { "id": "pt-n-a-azores-hydrangea", "e": "💐", "t": "Голубые заборы", "s": "На Азорских островах каждое лето вдоль дорог вспыхивают гортензии. Это кусты с огромными шапками цветов: голубых, сиреневых, розовых. Их посадили вместо заборов, чтобы они защищали поля от ветра. Целые ряды цветов тянутся по склонам до самого океана. Цвет зависит от земли: в вулканической почве многие цветки становятся синими. Поэтому Азоры иногда называют «голубыми островами».", "q": "Зачем на Азорах посадили гортензии вдоль полей?", "a": [ "Вместо заборов, чтобы защищать от ветра", "Чтобы коровы не заблудились", "Чтобы корабли находили порт" ] }, { "id": "pt-n-a-azores-pineapple", "e": "🍍", "t": "Ананасы в теплицах", "s": "Ананасы любят жаркие страны, но на Азорских островах их выращивают даже при мягкой, прохладной погоде. Для этого их сажают в тёплые стеклянные теплицы. Ананас растёт очень медленно, около двух лет, пока не станет сладким и сочным. Азорский ананас получается маленьким, зато ароматным. На острове Сан-Мигел ты можешь увидеть длинные ряды колючих растений под стеклянными крышами и даже сам понюхать спелый плод.", "q": "Где на Азорах растут ананасы?", "a": [ "В стеклянных теплицах", "В океане, на плотах", "На вершине горы, под снегом" ] }, { "id": "pt-n-a-azores-whales", "e": "🐋", "t": "Кашалоты у Азор", "s": "Вокруг Азорских островов океан очень глубокий, и в нём живут киты и дельфины. Туристы выходят на лодках и наблюдают за ними издалека. Больше всего здесь кашалотов — зубатых китов с огромной квадратной головой. Они ныряют на огромную глубину за кальмарами и могут сидеть под водой долго. Над водой кашалот поднимает хвост, а потом выпускает фонтанчик. Дельфины часто плывут рядом с лодкой, будто здороваются.", "q": "Кого кашалоты ловят на глубине?", "a": [ "Кальмаров", "Бабочек", "Лягушек" ] }, { "id": "pt-n-a-algar-carvao", "e": "🕳️", "t": "Колодец в вулкан", "s": "На острове Терсейра есть пещера Алгар-ду-Карвау. Она похожа на гигантский колодец: когда-то по ней поднималась лава из вулкана. Теперь лава давно остыла, и внутрь можно спуститься по ступенькам, примерно на девяносто метров. Сверху в дыру светит небо, вокруг растут папоротники. Внизу видны каменные сосульки: это сосульки из кремнезёма, а не льда. Глубоко внизу лежит тихое озерцо, и туда в пещере собирается вода.", "q": "Что поднималось по Алгар-ду-Карвау много лет назад?", "a": [ "Лава из вулкана", "Морская вода", "Тёплый ветер" ] }, { "id": "pt-n-a-capelinhos-island", "e": "🌋", "t": "Остров вырос", "s": "В 1957 году у острова Файал в океане много месяцев поднимались дым и пепел из воды. Под водой проснулся вулкан, и рядом с островом появился новый кусочек земли. Остров стал больше! Место назвали Капелиньюш. Новая земля серая и пустая, как на другой планете, и стоит там маяк, наполовину засыпанный пеплом. Сегодня сюда приезжают смотреть, как рождаются острова, и ходить по этой земле.", "q": "Что случилось у острова Файал в 1957 году?", "a": [ "Остров стал больше, появилась новая земля", "Остров ушёл под воду", "На острове вырос лес за одну ночь" ] }, { "id": "pt-n-a-azores-flores", "e": "🌸", "t": "Остров цветов", "s": "Один из самых дальних Азорских островов зовётся Флореш. По-португальски «флореш» — «цветы». Здесь так много дождей, что остров похож на зелёный сад. С отвесных скал падают десятки водопадов, а между ними лежат озёра в круглых вулканических чашах. Вдоль дорог цветут гортензии. Остров маленький, и людей на нём мало. Здесь тихо, слышно, как падает вода и поют птицы.", "q": "Что значит название острова Флореш?", "a": [ "Цветы", "Водопады", "Облака" ] }, { "id": "pt-n-a-almond-blossom", "e": "🌸", "t": "Белая зима", "s": "В Алгарве зимой нет снега, зато в январе и феврале цветёт миндаль. Деревья покрываются бело-розовыми цветами, и кажется, что поля засыпаны снегом. Есть старая легенда. Один король-мавр взял себе в жёны северную принцессу, а она тосковала по снегу. Тогда король посадил на холмах множество миндальных деревьев, и когда они расцвели, принцесса улыбнулась: вокруг было белым-бело, как дома.", "q": "Что напоминают цветущие миндальные деревья в легенде?", "a": [ "Снег", "Облака на траве", "Белых овечек" ] }, { "id": "pt-n-a-ponta-piedade", "e": "🛶", "t": "Лодки среди скал", "s": "Недалеко от города Лагуш в Алгарве море выточило из золотистых скал настоящие замки. Волны веками работали над камнем: получились арки, башенки, узкие проходы и пещерки. Это место называют Понта-да-Пьедаде. Рыбаки и туристы плывут на маленьких лодках прямо между каменными стенами, а под днищем вода прозрачная, бирюзовая. Лодка тихо входит в сумрачный грот, где эхо повторяет каждое слово.", "q": "Кто выточил арки и грот в скалах Понта-да-Пьедаде?", "a": [ "Море, волны за много лет", "Рыбаки молотками", "Ветер, который дул один год" ] }, { "id": "pt-n-a-chameleon", "e": "🦎", "t": "Хамелеон из Алгарве", "s": "Не все знают, что в Алгарве живут хамелеоны. Они сидят на ветках сосен и кустов, и заметить их непросто: кожа меняет цвет, и зверёк сливается с листвой. Глаза хамелеона двигаются каждый сам по себе: один смотрит вперёд, другой назад. А язык у него длиннее тела, и им он ловит мух. Хамелеон ходит медленно, как будто очень боится упасть с ветки.", "q": "Чем хамелеон ловит мух?", "a": [ "Длинным языком", "Клювом", "Хвостом, как лассо" ] }, { "id": "pt-n-a-alqueva-stars", "e": "🔭", "t": "Небо без фонарей", "s": "На юге Португалии, в Алентежу, есть большое озеро Алькева. Рядом лежат поля и холмы, а городов с яркими огнями мало. Ночью здесь темно, поэтому видно очень много звёзд. Над головой раскинулась светлая полоса Млечного Пути, будто кто-то пролил молоко. Это место считается одним из лучших в Европе для наблюдения за звёздами. Люди приезжают сюда с телескопами и ложатся на траву, чтобы просто смотреть вверх.", "q": "Почему в Алентежу ночью видно так много звёзд?", "a": [ "Вокруг мало огней, и небо тёмное", "Звёзды там ближе к земле", "Там всегда полнолуние" ] }, { "id": "pt-n-a-storks-cliffs", "e": "🪹", "t": "Аисты на скалах", "s": "Белые аисты в Португалии обычно строят гнёзда на крышах, трубах и столбах. Но на юго-западе, у океана, в Алентежу они поселились на морских скалах. Это одно из очень немногих мест в мире, где аисты живут так: гнездо стоит на каменной вершине над волнами, а внизу шумит прибой. Каждый год птицы возвращаются в один и тот же дом и подновляют его новыми ветками. Гнездо с годами становится огромным.", "q": "Где на юго-западе Алентежу аисты строят гнёзда над океаном?", "a": [ "На морских скалах", "На пляже, в песке", "На мачтах кораблей" ] }, { "id": "pt-n-a-acorn-pigs", "e": "🐖", "t": "Пастбища с желудями", "s": "В Алентежу растут светлые рощи из пробковых и каменных дубов. Это называется «монтаду». Под деревьями гуляют чёрные иберийские свиньи. Осенью земля вся усыпана желудями, и свиньи ходят и едят их, пока гуляют по холмам. Желудей так много, что хватает всем. Рядом пасутся овцы, а на ветках дубов сидят птицы. Дубы дают тень, защиту и угощение, и все животные в роще живут дружно.", "q": "Чем осенью лакомятся свиньи в рощах Алентежу?", "a": [ "Желудями", "Орехами с кактусов", "Морскими ракушками" ] }, { "id": "pt-n-a-estrela-dog", "e": "🐕", "t": "Пастух с мохнатой шубой", "s": "В горах Серра-да-Эштрела живёт старинная порода собак. Её называют «собака Серра-да-Эштрела». Пёс большой, с густой тёплой шерстью, которая защищает от холода и ветра. Он охраняет стадо овец: идёт рядом с пастухом и не подпускает чужих к овцам. Хотя пёс огромный, с людьми он добрый и ласковый. Гора Эштрела — самая высокая на материке: почти две тысячи метров, а зимой лежит снег.", "q": "Что делает собака Серра-да-Эштрела в горах?", "a": [ "Охраняет овец", "Ловит рыбу", "Возит санки с детьми" ] }, { "id": "pt-n-a-dino-tracks", "e": "🦕", "t": "Следы динозавров", "s": "На мысе Эшпишел, недалеко от Лиссабона, у скал остались огромные следы. Это следы динозавров, которые ходили здесь больше ста миллионов лет назад. Тогда земля была мягкой, как ил, и лапы великанов оставляли глубокие вмятины. Потом ил затвердел, и следы превратились в камень. Теперь их можно увидеть на каменном склоне: длинные цепочки круглых ям, каждая шире тарелки. Такие следы оставили травоядные динозавры с длинными шеями.", "q": "Что оставили динозавры на мысе Эшпишел?", "a": [ "Следы лап в камне", "Огромные яйца", "Нарисованные картинки" ] }, { "id": "pt-n-a-mira-caves", "e": "🦇", "t": "Подземный каскад", "s": "Недалеко от города Мира-де-Айре есть самая большая в Португалии пещера, куда пускают гостей. Спускаешься по лестнице вниз, и тебя встречают залы с каменными сосульками, которые растут из потолка и пола. Внутри прохладно и сыро, всегда одинаково, зимой и летом. Подсветка делает стены розовыми и золотыми. Есть подземный каскад, по которому течёт вода, и маленькое озеро, где отражаются каменные арки.", "q": "Что растёт из потолка и пола в пещере Мира-де-Айре?", "a": [ "Каменные сосульки", "Грибы", "Корни деревьев" ] }, { "id": "pt-n-b-coimbra-bats", "e": "🦇", "t": "Ночные сторожа библиотеки", "s": "В Коимбре есть один из самых старых университетов Европы, а в нём — золотая библиотека Жоанина. Там стоят высокие шкафы с резьбой и очень старые книги. Охраняют их необычные сторожа — маленькие летучие мыши! Ночью они вылетают и ловят насекомых, которые любят грызть бумагу. А чтобы за ночь на столах не осталось следов, вечером сотрудники накрывают их кожаными покрывалами. Книги целы, а мыши сыты.", "q": "Кто ночью охраняет старые книги в библиотеке Коимбры?", "a": [ "Летучие мыши", "Совы", "Кошки" ] }, { "id": "pt-n-b-queen-isabel-roses", "e": "🌹", "t": "Хлеб, который стал розами", "s": "Давным-давно в Коимбре жила королева Изабел. Она была доброй и любила помогать бедным. Говорят, однажды она несла в подоле хлеб, чтобы раздать голодным. Навстречу вышел король и спросил: «Что у тебя там?» Королева ответила: «Розы». Она раскрыла подол — и вместо хлеба там лежали свежие розы! Это только красивая легенда, но в Португалии её рассказывают до сих пор.", "q": "Во что, по легенде, превратился хлеб в подоле королевы?", "a": [ "В розы", "В ромашки", "В камни" ] }, { "id": "pt-n-b-coimbra-ribbons", "e": "🎓", "t": "Праздник лент", "s": "В Коимбре студенты носят чёрные плащи и костюмы, а ещё у них есть красивая традиция. Весной в городе проходит праздник лент. У каждого факультета своя цветная ленточка, и студенты гордо носят её на портфеле. Улицы полны музыки, песен и шествий. Название праздника переводится как «сожжение лент»: когда учёба заканчивается, ленты по традиции сжигают на память.", "q": "Что у каждого факультета Коимбры своего цвета?", "a": [ "Ленточка", "Шапка", "Ботинки" ] }, { "id": "pt-n-b-evora-diana-temple", "e": "🏛️", "t": "Римский храм в Эворе", "s": "Город Эвора старше, чем многие думают: здесь жили ещё римляне. От них остался храм, который стоит почти две тысячи лет! Сохранились высокие колонны, а сверху лежат тяжёлые каменные балки. Храм называют храмом Дианы, но учёные не уверены, что он был именно её. Зато точно известно: построили его римляне, и стоит он в самом центре города.", "q": "Какой древний народ построил храм в Эворе?", "a": [ "Римляне", "Викинги", "Майя" ] }, { "id": "pt-n-b-cork-oak-years", "e": "🌳", "t": "Дерево, которое раздевают", "s": "Возле Эворы растут пробковые дубы, и люди берут у них кору. Кору аккуратно снимают топориком, а дерево при этом остаётся живым. Потом кора отрастает заново! Следующий раз её снимают примерно через девять лет. Чтобы не перепутать, на стволе краской пишут последнюю цифру года. Из такой коры делают пробки для бутылок, сумки и даже подошвы.", "q": "Что происходит с корой пробкового дуба после того, как её сняли?", "a": [ "Отрастает заново", "Дерево погибает", "Кора превращается в камень" ] }, { "id": "pt-n-b-tomar-tabuleiros", "e": "🍞", "t": "Корона из хлеба", "s": "В городе Томар раз в четыре года бывает праздник подносов — Табулейруш. По улицам идут девушки в белом, а на голове у каждой высокая башня из хлебов, ростом с саму девушку! Башню украшают колосьями и бумажными цветами, а сверху сидит белый голубь. Рядом идёт помощник и придерживает её. После шествия хлеб раздают тем, кому он нужен.", "q": "Из чего сделаны башни на головах у девушек на празднике в Томаре?", "a": [ "Из хлеба", "Из сыра", "Из камней" ] }, { "id": "pt-n-b-tomar-window", "e": "🪢", "t": "Окно с каменными канатами", "s": "В Томаре, в большом монастыре, есть окно, которое выглядит как морская сказка. Оно вырезано из камня, но на нём — толстые канаты, морские узлы, ракушки, водоросли и якоря. Мастера сделали его в то время, когда португальцы плавали по океанам и очень гордились кораблями. Такой стиль называют мануэлино. Смотришь на окно — и будто слышишь шум волн.", "q": "Что вырезано из камня на окне в Томаре?", "a": [ "Канаты и ракушки", "Снежинки", "Танцующие медведи" ] }, { "id": "pt-n-b-nazare-biggest-wave", "e": "🌊", "t": "Волна выше дома", "s": "В городе Назаре океан устраивает настоящее чудо. Рядом с берегом начинается глубокий подводный каньон, и волны перед пляжем растут до огромных размеров. Зимой сюда приезжают смелые сёрферы. В 2020 году немец Себастьян Штойдтнер проехал на волне высотой 26 метров 21 сантиметр — выше восьмиэтажного дома! Рекорд записали в книгу рекордов Гиннесса.", "q": "Что помогает волнам в Назаре вырасти такими большими?", "a": [ "Глубокий подводный каньон", "Подводный вулкан", "Ветряные мельницы" ] }, { "id": "pt-n-b-nazare-seven-skirts", "e": "👗", "t": "Рыбачки в семи юбках", "s": "Назаре — старая рыбацкая деревня, и женщины здесь носят особый наряд. Рассказывают, что рыбачки надевали семь юбок одна на другую! Юбки были яркие и тёплые. Пока мужья были в море, женщины сидели на песке, чинили сети и сушили рыбу, и, говорят, юбки согревали их на ветру. Объясняют число семь по-разному: семь дней недели, семь цветов радуги. Такой наряд до сих пор можно увидеть на праздниках.", "q": "Сколько юбок надевали рыбачки в Назаре по рассказам?", "a": [ "Семь", "Три", "Двенадцать" ] }, { "id": "pt-n-b-sagres-wind-rose", "e": "🧭", "t": "Каменное колесо в Сагреше", "s": "На мысе возле Сагреша лежит огромное каменное колесо диаметром около сорока трёх метров. От центра, как лучи, расходятся каменные линии. Это роза ветров, похожая на гигантский компас. Учёные до сих пор спорят, зачем она нужна была: может быть, чтобы изучать ветры и стороны света. Лучше всего её видно сверху, а на ветру там легко представить себя моряком.", "q": "На что похож каменный круг в Сагреше?", "a": [ "На огромный компас", "На шахматную доску", "На большие часы" ] }, { "id": "pt-n-b-eusebio-panther", "e": "⚽", "t": "Чёрная пантера", "s": "Эузебиу родился в Мозамбике, в Африке, а потом приехал играть в Португалию. Он бегал так быстро и бил по мячу так сильно, что его прозвали «Чёрная пантера». На чемпионате мира 1966 года он забил девять мячей и стал лучшим бомбардиром турнира. Сборная Португалии тогда получила бронзовые медали. Эузебиу любили все: и за игру, и за добрую улыбку.", "q": "Как прозвали футболиста Эузебиу?", "a": [ "Чёрная пантера", "Белый медведь", "Рыжий лис" ] }, { "id": "pt-n-b-ronaldo-madeira", "e": "🏝️", "t": "Футболист с острова", "s": "Криштиану Роналду родился на острове Мадейра, в городе Фуншал. Мальчишкой он играл в мяч на улице, а потом стал одним из самых известных футболистов мира. Он забил больше всех мячей за национальные сборные в истории. А аэропорт Фуншала сегодня носит его имя, и там стоит бронзовый бюст. Прилетаешь на остров и сразу видишь, чем гордятся жители.", "q": "На каком острове родился Роналду?", "a": [ "На Мадейре", "На Сицилии", "На Крите" ] }, { "id": "pt-n-b-cabral-brazil", "e": "🦜", "t": "Письмо о новой земле", "s": "В 1500 году капитан Кабрал вёл флот к Индии, но корабли отнесло далеко на запад. Моряки увидели высокую гору и назвали её Пасхальной, потому что это были дни Пасхи. Так они открыли Бразилию! Писарь Каминья написал королю длинное письмо. В нём он рассказал о зелёных лесах, ярких попугаях и людях, которые встретили гостей с любопытством.", "q": "Какую страну открыл Кабрал в 1500 году?", "a": [ "Бразилию", "Австралию", "Канаду" ] }, { "id": "pt-n-b-dias-cape-storms", "e": "⛵", "t": "Мыс, которому сменили имя", "s": "Португальский капитан Бартоломеу Диаш в 1488 году первым из европейцев обогнул самый юг Африки. Там дули сильные ветры и качало волнами, и он назвал мыс Бурь. Но король решил, что имя лучше изменить, ведь за этим мысом начинался путь в Индию. Он назвал его мысом Доброй Надежды. Это имя мыс носит до сих пор.", "q": "Как король переименовал мыс Бурь?", "a": [ "Мыс Доброй Надежды", "Мыс Сильных Ветров", "Мыс Радуги" ] }, { "id": "pt-n-b-gil-eanes-bojador", "e": "🗺️", "t": "За мысом нет ничего страшного", "s": "Давным-давно моряки боялись мыса Бохадор у берегов Африки. Рассказывали, что за ним море кипит и корабли не возвращаются. Но в 1434 году португальский мореплаватель Жил Эаниш всё-таки поплыл дальше. Он обогнул мыс и увидел самое обычное море и песчаный берег. Он вернулся и рассказал: бояться нечего! После этого моряки стали плавать дальше.", "q": "Что увидел Жил Эаниш за мысом Бохадор?", "a": [ "Самое обычное море и берег", "Огромный водопад", "Ледяные горы" ] }, { "id": "pt-n-b-caravel-ship", "e": "🚢", "t": "Лёгкий корабль-каравелла", "s": "Португальцы придумали и улучшили лёгкий корабль — каравеллу. Она небольшая, быстрая и маневренная, а на мачтах у неё треугольные паруса. Такие паруса позволяют идти почти против ветра, зигзагами. Благодаря каравеллам моряки могли плавать вдоль неизвестных берегов и возвращаться домой. Каравеллы были небольшими: в длину всего метров пятнадцать–двадцать.", "q": "Какой формы паруса были у каравеллы?", "a": [ "Треугольные", "Круглые, как мячи", "Шестиугольные" ] }, { "id": "pt-n-b-cante-alentejano", "e": "🎶", "t": "Хор без инструментов", "s": "В области Алентежу люди поют особую песню — канте алентежану. Поёт сразу много людей: мужчины и женщины встают рядом, и один начинает, а остальные подхватывают. Слышно только голоса, ни гитары, ни барабана! Раньше так пели на полях, чтобы работа шла веселее. Эта песня очень древняя, и в 2014 году её внесли в список всемирного наследия ЮНЕСКО.", "q": "Чем необычно пение канте алентежану?", "a": [ "Поют без инструментов", "Поют только под барабан", "Поют на бегу" ] }, { "id": "pt-n-b-portuguese-guitar", "e": "🎸", "t": "Гитара-груша", "s": "У португальской гитары корпус круглый и похож на грушу. А струн у неё не шесть, а целых двенадцать: они собраны в шесть пар. Звук получается звонкий и серебристый, будто капли дождя. Сбоку у гитары есть винтики для настройки в виде маленького веера. На ней играют в Португалии, когда поют грустные и красивые песни.", "q": "Сколько струн у португальской гитары?", "a": [ "Двенадцать", "Шесть", "Четыре" ] }, { "id": "pt-n-b-salvador-eurovision", "e": "🎤", "t": "Победа после долгого ожидания", "s": "Португалия участвует в песенном конкурсе Евровидение с 1964 года. Больше пятидесяти лет страна ждала победы! И вот в 2017 году молодой певец Салвадор Собрал выступил с тихой нежной песней «Любить за двоих». Он пел на португальском, без громких эффектов и танцев. Зрители из многих стран проголосовали за него, и Португалия впервые победила.", "q": "На каком языке Салвадор Собрал пел победную песню?", "a": [ "На португальском", "На английском", "На французском" ] }, { "id": "pt-n-b-bacalhau-cod", "e": "🐟", "t": "Рыба на каждый день года", "s": "В Португалии очень любят сушёную и солёную треску — бакальяу. Рыбу ловили в холодных северных морях, солили и сушили, чтобы она долго не портилась. А потом дома её надо было вымачивать в воде. Португальцы шутят, что у них есть рецепт бакальяу на каждый день года, а то и больше. Её варят, запекают и жарят с картошкой.", "q": "Из какой рыбы делают бакальяу?", "a": [ "Из трески", "Из тунца", "Из скумбрии" ] }, { "id": "pt-n-b-serra-estrela-cheese", "e": "🧀", "t": "Сыр, который едят ложкой", "s": "В горах Серра-да-Эштрела пастухи делают особенный овечий сыр. Чтобы молоко загустело, в него кладут колючий цветок чертополох. Сыр получается мягким и сливочным. Когда его разрежут, он течёт, как густой крем. Поэтому сыр не режут на ломтики, а срезают верхушку и едят ложкой, намазывая на хлеб. Вкус у него нежный и немного пряный.", "q": "Какой цветок помогает сыру в горах Серра-да-Эштрела загустеть?", "a": [ "Чертополох", "Одуванчик", "Клевер" ] }, { "id": "pt-n-b-bolo-rei", "e": "🎄", "t": "Рождественский пирог с бобом", "s": "На Рождество в Португалии пекут пирог в форме большого кольца — болу-рей. Он похож на корону: сверху лежат кусочки сухофруктов и орехов, будто драгоценные камни. Внутрь по традиции прячут боб. Кто найдёт боб в своём куске, на следующий год покупает пирог для всей семьи. Поэтому за столом все ищут его очень внимательно.", "q": "Что по традиции прячут внутри рождественского пирога?", "a": [ "Боб", "Маленький ключик", "Конфету" ] }, { "id": "pt-n-b-magusto-chestnuts", "e": "🌰", "t": "Праздник жареных каштанов", "s": "В ноябре в Португалии отмечают День святого Мартина. Говорят, что в это время часто стоят тёплые солнечные дни, их называют «лето святого Мартина». Люди собираются у костра на праздник магушту. Жарят каштаны, они трещат и пахнут дымом, и их едят прямо горячими. Кожуру кидают в общую корзину, а дети соревнуются, кто очистит быстрее.", "q": "Что жарят на португальском празднике магушту?", "a": [ "Каштаны", "Кукурузу", "Картошку" ] }, { "id": "pt-n-b-words-pan-marmalade", "e": "📖", "t": "Португальские слова в мире", "s": "Португальские моряки привозили не только товары, но и слова. Около пятисот лет назад они приплыли в Японию. Хлеб там был для японцев новинкой, и они стали называть его «пан», от португальского слова «пао». Так и осталось! А слово «мармелад» тоже пришло из португальского, где так называли варенье из айвы. Айва по-португальски — «мармелу».", "q": "Как японцы называют хлеб, взяв слово у португальцев?", "a": [ "Пан", "Рис", "Чай" ] }, { "id": "pt-n-b-aveiro-ovos-moles", "e": "🥚", "t": "Сладость в ракушке", "s": "В городе Авейру придумали сладость овуш молеш. Внутри мягкий сладкий крем из яичных желтков и сахара. А снаружи тонкая хрустящая оболочка из вафельного теста. Оболочки делают в виде ракушек, рыбок и маленьких бочонков. Так в сладостях видно, что город стоит рядом с морем. Рецепт хранят много лет, и его считают местной гордостью.", "q": "На что похожи оболочки у сладости овуш молеш?", "a": [ "На морские ракушки", "На ёлочки", "На кубики" ] } ], "spb": [ { "id": "spb-n-grand-maket", "e": "🚂", "t": "Вся Россия в одном зале", "s": "В Петербурге есть музей «Гранд Макет Россия». В огромном зале там построили игрушечную страну с горами, лесами, городами и железными дорогами. По ней бегут крошечные поезда, а машинки останавливаются на светофорах. Каждые тринадцать минут в этой стране наступает ночь: загораются тысячи маленьких огоньков, а потом снова приходит утро. А если нажать кнопку у края макета, что-нибудь оживёт и поедет!", "q": "Как часто на макете наступает ночь?", "a": [ "Каждые тринадцать минут", "Раз в сто лет", "Только по вторникам" ] }, { "id": "spb-n-lakhta", "e": "🏢", "t": "Самый высокий дом Европы", "s": "На берегу Финского залива стоит Лахта-центр. Его высота — 462 метра, это самое высокое здание в Европе. Он больше чем в четыре раза выше Исаакиевского собора! Башня почти вся покрыта стеклом и сверкает на солнце, как огромная игла. В ней больше восьмидесяти этажей, а в пасмурный день её макушка иногда прячется в облаках.", "q": "Какое здание самое высокое в Европе?", "a": [ "Лахта-центр", "Будка для собаки", "Песочный замок" ] }, { "id": "spb-n-zoo-bears", "e": "🐻‍❄️", "t": "Белый медведь — символ зоопарка", "s": "Ленинградский зоопарк открылся в 1865 году — это один из самых старых зоопарков России. Город с тех пор поменял имя, а зоопарк оставил прежнее. Его главный символ — белый медведь: он нарисован на эмблеме зоопарка. Белые медведи живут здесь очень давно, и у них много раз рождались медвежата. Летом медведи с удовольствием плещутся в своём бассейне.", "q": "Какой зверь нарисован на эмблеме зоопарка?", "a": [ "Белый медведь", "Рыжий таракан", "Лохматый комар" ] }, { "id": "spb-n-admiralty-ship", "e": "⛵", "t": "Кораблик на золотом шпиле", "s": "В самом центре Петербурга стоит Адмиралтейство. Когда-то здесь была верфь — место, где строили настоящие корабли. Над зданием поднимается высокий золотой шпиль, а на его макушке сверкает золотой кораблик-флюгер. Снизу он кажется крошечным, а на самом деле весит 65 килограммов — почти как взрослый человек! Этот кораблик стал знаком всего города.", "q": "Что сверкает на макушке шпиля Адмиралтейства?", "a": [ "Золотой кораблик", "Резиновый утёнок", "Бабушкин чайник" ] }, { "id": "spb-n-atlantes", "e": "🗿", "t": "Каменные великаны у Эрмитажа", "s": "У входа в Новый Эрмитаж стоят десять каменных великанов — атлантов. Кажется, будто они изо всех сил держат крышу над входом. Каждый атлант ростом около пяти метров — это как три папы, вставшие друг другу на плечи! Великанов высекли из серого гранита и поставили здесь в 1848 году. Есть такая примета: если потереть атланту большой палец на ноге, придёт удача.", "q": "Сколько атлантов стоит у входа в Новый Эрмитаж?", "a": [ "Десять", "Ни одного", "Целая тысяча" ] }, { "id": "spb-n-kazan-colonnade", "e": "🏛️", "t": "Собор, который раскинул руки", "s": "На Невском проспекте стоит Казанский собор. Перед ним полукругом выстроились 96 колонн — будто собор раскинул руки и обнимает площадь. Его построил архитектор Андрей Воронихин. В молодости Воронихин был крепостным, то есть не мог сам решать свою судьбу. Но он так хорошо рисовал, что его отправили учиться, а потом дали ему свободу. Собор строили десять лет, с 1801 по 1811 год.", "q": "На что похожа колоннада Казанского собора?", "a": [ "На раскинутые руки", "На хвост селёдки", "На дырявый носок" ] }, { "id": "spb-n-hare", "e": "🐇", "t": "Зайчик на свае", "s": "Возле Петропавловской крепости из воды торчат сваи, которые защищают мост от льдин. На одной из них сидит маленький зайчик из металла. Остров, где стоит крепость, называется Заячьим, и есть сказочная легенда: во время наводнения зайчик спасся, запрыгнув царю Петру на сапог. Зайчика поставили здесь в 2003 году. Люди бросают ему монетки: говорят, если монетка останется на свае, желание сбудется.", "q": "Где сидит зайчик у Петропавловской крепости?", "a": [ "На свае в воде", "На крыше трамвая", "В кармане у кота" ] }, { "id": "spb-n-globe-house", "e": "🌐", "t": "Дом со стеклянным глобусом", "s": "На Невском проспекте стоит красивый дом с башенкой, а на башенке — стеклянный глобус. Дом построили в 1904 году для фирмы, которая делала швейные машинки. Хозяева хотели дом повыше, но в старом Петербурге нельзя было строить выше царского Зимнего дворца. Зато над крышей поднялась башенка с глобусом, и дом видно издалека. Его называют Домом книги, потому что здесь много лет продают книги.", "q": "Что стоит на башенке Дома книги?", "a": [ "Стеклянный глобус", "Огромный арбуз", "Старая кастрюля" ] }, { "id": "spb-n-vokzal", "e": "🚉", "t": "Откуда взялось слово «вокзал»", "s": "В 1837 году из Петербурга в Царское Село пошёл первый в России поезд для пассажиров. Скоро дорогу продлили до Павловска и построили там красивый зал для музыки. Его назвали «воксал», как знаменитый сад в Лондоне, где люди гуляли и слушали музыку. Горожане ехали на поезде послушать оркестр, а играл там даже композитор Иоганн Штраус. С тех пор станции для поездов у нас зовут вокзалами.", "q": "В честь чего назвали зал для музыки в Павловске?", "a": [ "В честь сада в Лондоне", "В честь бабушкиного пирога", "В честь чихающего кота" ] }, { "id": "spb-n-rockets", "e": "🚀", "t": "Ракеты в старой крепости", "s": "В Петропавловской крепости есть Музей космонавтики и ракетной техники. Почти сто лет назад, в 1930-е годы, прямо здесь инженеры испытывали одни из первых в нашей стране ракетных двигателей. Только представь: в старой крепости гудели ракетные моторы! Сейчас в музее можно увидеть настоящую кабину космического корабля, в которой космонавты вернулись из космоса на Землю.", "q": "Что испытывали инженеры в крепости?", "a": [ "Ракетные двигатели", "Новые валенки", "Мыльные пузыри" ] }, { "id": "spb-n-kronstadt-zero", "e": "📏", "t": "Черта, от которой меряют горы", "s": "Недалеко от Петербурга, на острове в Финском заливе, стоит город Кронштадт. Там на каменной опоре Синего моста есть особая линейка с делениями — футшток. По ней уже очень давно следят, как поднимается и опускается вода в море. Самая главная черта на ней — ноль. От этой черты считают высоту гор, холмов и городов во всей нашей стране!", "q": "Что считают от черты в Кронштадте?", "a": [ "Высоту гор и городов", "Длину кошачьих хвостов", "Вес арбузов на рынке" ] }, { "id": "spb-n-jug-girl", "e": "🏺", "t": "Девушка с разбитым кувшином", "s": "В Царском Селе, в Екатерининском парке, на камне сидит бронзовая девушка. В руке у неё осколок, а рядом лежит разбитый кувшин, из которого всё течёт и течёт вода. Эту воду даёт подземный родник, и бежит она здесь уже больше 200 лет. Говорят, скульптор Павел Соколов придумал девушку по басне о молочнице, которая уронила кувшин. А поэт Пушкин написал про неё стихи.", "q": "Откуда берётся вода в разбитом кувшине?", "a": [ "Из подземного родника", "Из бабушкиного чайника", "Из облака на верёвочке" ] }, { "id": "spb-n-sphinxes", "e": "🏜️", "t": "Сфинксы из далёкого Египта", "s": "На Университетской набережной, у самой Невы, лежат два настоящих египетских сфинкса. Им больше трёх тысяч лет! У них тело льва, а лицо египетского царя — фараона Аменхотепа Третьего. Сфинксов нашли в Египте и привезли в Петербург на корабле в 1832 году. Каждый весит 23 тонны — почти как четыре больших слона.", "q": "Чьё лицо у сфинксов на набережной?", "a": [ "Египетского фараона", "Весёлого клоуна", "Соседского кота" ] }, { "id": "spb-n-shi-tsza", "e": "🦁", "t": "Каменные львы из Китая", "s": "На Петровской набережной, у спуска к Неве, сидят два необычных каменных льва — ши-цза. Их вырезали из гранита в Китае, где такие львы охраняют входы. В 1907 году львов привезли в Петербург: сначала на поезде, а потом на пароходе. Лев держит лапой шар, а львица положила лапу на маленького львёнка. Гривы у них закручены колечками, совсем как кудряшки.", "q": "Что держит лапой лев ши-цза?", "a": [ "Шар", "Бутерброд", "Тапочек" ] }, { "id": "spb-n-ladoga-seals", "e": "🦭", "t": "Тюлени в Ладожском озере", "s": "Рядом с Петербургом лежит Ладожское озеро — самое большое пресное озеро в Европе: вода в нём не солёная. Из Ладоги вытекает Нева и бежит через весь город к морю. А ещё в Ладоге живут настоящие тюлени — ладожские нерпы! Больше нигде на свете таких нет, и их бережно охраняют. Летом нерпы любят лежать на камнях у маленьких островков и греться на солнце.", "q": "Кто живёт в Ладожском озере?", "a": [ "Тюлени-нерпы", "Пингвины на самокатах", "Крокодилы в шарфах" ] }, { "id": "spb-a-pavlovsk", "e": "🌳", "t": "Павловск — подарок на рождение внука", "s": "В 1777 году у будущего царя Павла родился сын Александр. Бабушка, императрица Екатерина Вторая, очень обрадовалась и подарила родителям землю с лесом и речкой. Так появился Павловск: дворец с колоннами и огромный парк. В нём вьются дорожки, есть пруды, мостики, тенистые аллеи и маленькие павильоны. Парк делали как будто настоящую лесную картину, чтобы гулять в нём было приятно в любое время года. Зимой здесь катаются на лыжах.", "q": "Что подарила Екатерина Вторая сыну на рождение внука?", "a": [ "Землю, где вырос Павловск", "Корабль", "Золотую карету" ] }, { "id": "spb-a-ermitazh-name", "e": "🖼️", "t": "Как «домик отшельника» стал Эрмитажем", "s": "Слово «эрмитаж» французское и означает «уединённое место», где можно отдохнуть от шума. Императрица Екатерина Вторая в 1764 году купила несколько сотен картин и повесила их в маленьких залах рядом со своими комнатами. Показывала она их только друзьям и называла это место своим эрмитажем. Прошло много лет, залов стало очень много, и сегодня это один из самых больших музеев мира, а вход открыт всем.", "q": "Что означает слово «эрмитаж»?", "a": [ "Уединённое место", "Большой дом", "Музей кошек" ] }, { "id": "spb-a-gatchina", "e": "🕳️", "t": "Дворец с тайным ходом", "s": "Недалеко от Петербурга, в Гатчине, стоит серый дворец, похожий на крепость. В нём жил царь Павел Первый. Говорят, в этом дворце есть подземный ход, который ведёт к Серебряному озеру. Он сохранился до наших дней, но сейчас в нём тупик, и по нему не пройти. Зато вокруг дворца огромный парк с прудами и островами, где можно кататься на лодке. Можно представить себя исследователем подземелья.", "q": "Куда вёл подземный ход из Гатчинского дворца?", "a": [ "К озеру", "К морю", "К вокзалу" ] }, { "id": "spb-a-mramorny", "e": "🪨", "t": "Дворец из тридцати видов камня", "s": "На набережной Невы стоит Мраморный дворец. Строить его начали в 1768 году. Внутри и снаружи его украшал мрамор разного цвета: розовый, серый, зелёный, белый. Камень везли из разных мест: с Урала, из Карелии и даже из других стран. Всего видов камня около тридцати, в разных источниках называют немного разные числа. Дворец подарила императрица Екатерина Вторая своему другу графу Орлову. Теперь здесь работает музей.", "q": "Из какого камня украшен Мраморный дворец?", "a": [ "Из мрамора", "Из льда", "Из кирпича" ] }, { "id": "spb-a-pradedu", "e": "🗿", "t": "«Прадеду — правнук»", "s": "Перед Михайловским замком стоит памятник Петру Первому. На постаменте выбиты слова: «Прадеду — правнук». Их придумал царь Павел Первый, потому что он действительно был правнуком Петра. Он поставил памятник в 1800 году, чтобы отдать дань уважения своему прадедушке. Петра отлили в виде римского героя в венке из листьев, с конём без стремян. Это очень старая скульптура, она старше самого замка.", "q": "Кем был царь Павел Первый для Петра Первого?", "a": [ "Правнуком", "Сыном", "Соседом" ] }, { "id": "spb-a-nikolay-kon", "e": "🐴", "t": "Конь на двух ногах", "s": "На Исаакиевской площади стоит памятник царю Николаю Первому на коне. Конь поднялся на дыбы и стоит только на двух задних ногах. Открыли памятник в 1859 году. Такое встречается редко: тяжёлая бронзовая статуя держится всего на двух точках опоры. Чтобы она не упала, создатели точно рассчитали её вес и сделали мощный постамент. Вокруг памятника кружатся голуби.", "q": "На скольких ногах стоит конь памятника Николаю Первому?", "a": [ "На двух", "На четырёх", "На одной" ] }, { "id": "spb-a-lodzhii", "e": "🖌️", "t": "Копия, привезённая из Рима", "s": "В Эрмитаже есть длинная галерея, расписанная яркими картинками: цветы, птицы, сказочные узоры. Это копия знаменитых росписей художника Рафаэля из Ватикана. Екатерина Вторая в Петербурге пожелала иметь такую же красоту и отправила в Рим художников. Те срисовали узоры, и их перенесли на холсты, а потом развесили здесь. Теперь эту галерею зовут Лоджиями Рафаэля, и она очень нарядная.", "q": "Чью живопись скопировали в Лоджиях Рафаэля?", "a": [ "Рафаэля", "Рембрандта", "Репина" ] }, { "id": "spb-a-zimny", "e": "🟢", "t": "Зимний дворец меняет цвет", "s": "Сейчас Зимний дворец зелёно-белый, как мятная конфета. Но так было не всегда. За свою долгую жизнь он менял цвет: бывал охристым, терракотово-красным, серым. Краску выбирали по моде и по вкусу тех, кто решал. Если смотреть с Дворцовой площади, дворец кажется огромной нарядной шкатулкой.", "q": "Какого цвета сегодня Зимний дворец?", "a": [ "Зелёно-белого", "Синего", "Чёрного" ] }, { "id": "spb-b-popov", "e": "📻", "t": "Первое слово по радио", "s": "В Петербурге учёный Александр Попов придумал, как посылать сигналы без проводов. В марте 1896 года он показал это в университете: в одном здании передавали буквы, а в другом, примерно за двести пятьдесят метров, их принимали и записывали. Считается, что первыми словами были «Генрих Герц» — в честь учёного, который открыл радиоволны. Сегодня у нас радио, телефоны и интернет по воздуху, а начиналось всё с двух слов.", "q": "Какие слова передали по радио первыми?", "a": [ "Генрих Герц", "Добрый день", "Здравствуй, Петербург" ] }, { "id": "spb-b-cirk", "e": "🎪", "t": "Цирк на Фонтанке", "s": "На берегу Фонтанки стоит круглое здание — цирк. Его построили в 1877 году по заказу итальянца Гаэтано Чинизелли, и это один из самых старых цирков в России. Он сделал арену такой, чтобы можно было играть и наездникам, и акробатам, и клоунам. Почти сто пятьдесят лет там выступают артисты, а зрители смеются и хлопают. Когда пойдёте мимо, посмотрите на купол — внутри всегда праздник.", "q": "Какое здание стоит на берегу Фонтанки?", "a": [ "Цирк", "Зоопарк", "Вокзал" ] }, { "id": "spb-b-vaganova", "e": "🩰", "t": "Школа, которой почти триста лет", "s": "На улице Зодчего Росси стоит балетная школа — Академия русского балета имени Вагановой. Она началась в 1738 году, когда императрица Анна Иоанновна позвала детей учиться танцу. Сегодня там каждый день занимаются мальчики и девочки: станок, шаги, прыжки. Сама улица очень ровная: в ней двести двадцать метров длины, а ширина и высота домов — по двадцать два метра. Архитектор Росси хотел, чтобы всё было как в хорошем танце.", "q": "Чему учат детей в школе на улице Росси?", "a": [ "Балету", "Плаванию", "Рисованию красками" ] }, { "id": "spb-b-marshak", "e": "📖", "t": "Маршак и «Дом, который построил Джек»", "s": "Самуил Маршак писал детские стихи и жил в Петербурге, когда тот называли Ленинградом. Он переводил весёлые английские песенки на русский язык, и самая известная — «Дом, который построил Джек». Там каждая строчка тянет за собой следующую, как цепочка. В Ленинграде Маршак собрал молодых детских писателей, и они вместе делали книжки и журналы для ребят.", "q": "Кто построил дом в известном стихотворении Маршака?", "a": [ "Джек", "Том", "Билл" ] }, { "id": "spb-b-harms", "e": "🎩", "t": "Хармс — тот, у кого другая фамилия", "s": "Поэт родился в Петербурге в 1905 году, и по паспорту он был Даниил Ювачёв. А писать стал под смешным именем Хармс, в том числе для детей. Он любил выдумывать забавные стихи и рассказы про всякие нелепые случаи. Их печатали в детских журналах «Ёж» и «Чиж». Если читать Хармса вслух, обязательно хочется улыбаться.", "q": "Какую фамилию взял себе писатель для детских книг?", "a": [ "Хармс", "Ювачёв", "Маршак" ] }, { "id": "spb-b-repin", "e": "🎨", "t": "Художник, в чью честь назвали посёлок", "s": "Илья Репин учился в Академии художеств в Петербурге, а потом написал знаменитые картины: «Бурлаки на Волге» и «Запорожцы пишут письмо турецкому султану». Он поселился на берегу Финского залива в доме, который назвал «Пенаты». Позднее посёлок рядом получил название Репино — в честь художника. Туда и сейчас ходят гулять по дорожкам у залива.", "q": "Как назвали посёлок в честь художника?", "a": [ "Репино", "Ильинск", "Бурлаково" ] }, { "id": "spb-b-kruzenshtern", "e": "⛵", "t": "Вокруг света на «Надежде»", "s": "В 1803 году из Кронштадта, рядом с Петербургом, вышли в море два корабля: «Надежда» и «Нева». Капитаном «Надежды» был Иван Крузенштерн. Это было первое кругосветное плавание русских моряков. Они проплыли через океаны, повидали острова и новые земли и вернулись домой через три года. Моряки нарисовали карты и привезли рассказы о том, что видели.", "q": "Как назывался корабль Крузенштерна?", "a": [ "«Надежда»", "«Радость»", "«Дружба»" ] }, { "id": "spb-b-yablochkov", "e": "💡", "t": "Первые фонари на мосту", "s": "Раньше улицы освещали свечами, потом газом. А в Петербурге однажды зажглись электрические фонари — на Литейном мосту, одним из первых в городе. Их придумал изобретатель Павел Яблочков, и его лампы называли «русский свет». Они давали яркий белый свет и казались горожанам чудом. Сейчас электричество у нас везде, но тогда люди приходили к мосту, чтобы просто посмотреть на свет.", "q": "Какие огни зажглись на Литейном мосту?", "a": [ "Электрические", "Свечи", "Факелы" ] }, { "id": "spb-b-eiler", "e": "🔢", "t": "Математик с буквами вместо чисел", "s": "Леонард Эйлер приехал в Петербург из Швейцарии в 1727 году и работал в Академии наук. Он любил числа так сильно, что придумывал для них буквы. Например, «e» и «i» ввёл именно он, а значок «π» — число пи — благодаря ему стал известен по всему миру. Эйлер писал так много, что книги вышли в десятках томов. Рядом с ним всегда были дети: у него их было много.", "q": "Откуда приехал Эйлер в Петербург?", "a": [ "Из Швейцарии", "Из Италии", "Из Англии" ] }, { "id": "spb-c-neva-reka", "e": "🌊", "t": "Нева — короткая и могучая", "s": "Нева — совсем короткая река: всего семьдесят четыре километра. Но воды в ней очень много, потому что вытекает она из Ладожского озера, самого большого озера Европы. Нева несёт эту воду к Финскому заливу. У самого залива река делится на рукава, и город стоит на островах между ними. Вот почему в Петербурге столько мостов: без них острова остались бы сами по себе.", "q": "Откуда вытекает Нева?", "a": [ "Из Ладожского озера", "Из Байкала", "Из Финского залива" ] }, { "id": "spb-c-zaliv-presnyj", "e": "🐟", "t": "Море, где вода почти не солёная", "s": "Финский залив — часть Балтийского моря, но вода в нём совсем не такая солёная, как в океане. А возле города, там, где в залив впадает Нева, она и вовсе почти пресная: река каждую секунду приносит море воды без соли. Поэтому здесь, на мелководье, речные и морские рыбы живут по соседству. Если лизнуть каплю из залива, моря ты почти не почувствуешь!", "q": "Какая вода возле устья Невы в заливе?", "a": [ "Почти пресная", "Очень солёная", "Тёплая, как чай" ] }, { "id": "spb-c-damba-zaliv", "e": "🛡️", "t": "Дамба поперёк залива", "s": "Через Финский залив, от берега до берега, протянулась длинная дамба — около двадцати пяти километров. Она с воротами: когда ветер гонит в Неву слишком много воды, большие затворы закрываются и не пускают её в город. В обычные дни ворота открыты, и вода с кораблями ходит свободно. А по самой дамбе проложена дорога, и по ней едут обычные машины. Залив в этом месте мелкий — всего несколько метров глубины.", "q": "Для чего в дамбе есть ворота?", "a": [ "Чтобы закрыться, когда вода поднимается", "Чтобы пропускать поезда", "Чтобы ловить рыбу" ] }, { "id": "spb-c-ledyanoj-dom", "e": "🏰", "t": "Дворец из льда", "s": "Зимой 1739–1740 годов на Неве, недалеко от Адмиралтейства, построили настоящий дом из льда. Мастера вырезали изо льда окна, колонны и даже мебель. Во дворе стояли ледяные деревья, на них сидели ледяные птицы, а рядом — ледяной слон. Всю зиму горожане приходили на него любоваться. Но весной тепло сделало своё дело: дом растаял, и снова осталась просто река.", "q": "Из чего был построен дом на Неве?", "a": [ "Из льда", "Из дерева", "Из серебра" ] }, { "id": "spb-c-zoopark-1865", "e": "🦁", "t": "Зоопарк, которому больше ста лет", "s": "Ленинградский зоопарк — один из самых старых в России. Его открыли в 1865 году, первого августа по старому календарю. Начиналось всё скромно: Юлиус и София Гебгардт держали в небольшом саду зверинец и показывали животных всем желающим. Сегодня в зоопарке живут сотни видов зверей и птиц. И считается он одним из самых северных зоопарков мира.", "q": "Когда открыли Ленинградский зоопарк?", "a": [ "В 1865 году", "В 1999 году", "В 1703 году" ] }, { "id": "spb-c-pamyatnik-sobake", "e": "🐕", "t": "Памятник собаке", "s": "Во дворе Института экспериментальной медицины стоит бронзовый памятник собаке. Его открыли в 1935 году. Учёный Иван Павлов изучал, как работают мозг и организм, и в этом ему помогали собаки. Памятник сказал им спасибо: ведь без них не появилось бы многих открытий. Собака сидит спокойно, будто ждёт, когда ей что-нибудь скажут.", "q": "Кому поставили памятник во дворе института?", "a": [ "Собаке", "Кошке", "Лошади" ] }, { "id": "spb-c-nos-kovaleva", "e": "👃", "t": "Нос, который сбежал", "s": "На Вознесенском проспекте на стене дома есть удивительная плита: на ней вырезан нос. Это «Нос майора Ковалёва» — памятник герою повести Николая Гоголя. В книге нос однажды ушёл от хозяина и стал гулять по Петербургу сам по себе. Памятник появился в 1995 году. Придумал его Резо Габриадзе, грузинский художник и режиссёр. Редкий памятник: герой весёлый, а лица у него нет — только нос!", "q": "Кого изобразили на плите Вознесенского проспекта?", "a": [ "Нос из книги Гоголя", "Хвост кота", "Ухо слона" ] }, { "id": "spb-c-elisej-vasilisa", "e": "🐈", "t": "Кот Елисей и кошка Василиса", "s": "На Малой Садовой улице на карнизах домов сидят два бронзовых кота — вернее, кот и кошка. Кот Елисей устроился на доме номер восемь, а кошка Василиса — напротив, на третьем. Они появились в 2000 году, и сделал их скульптор Владимир Петровичев. Прохожие часто задирают голову и ищут их глазами. Говорят, что кот Елисей приносит удачу, но это не точно.", "q": "Где сидят кот Елисей и кошка Василиса?", "a": [ "На карнизах домов", "В зоопарке", "На мосту через Неву" ] }, { "id": "spb-d-narodovolets", "e": "🛟", "t": "Настоящая подводная лодка", "s": "На Васильевском острове, у самой воды, стоит настоящая подводная лодка «Народоволец». Теперь это музей. Лодка из первых подводных кораблей, которые строили у нас. Внутри тесно: узкие проходы, трубы и рычаги, а ещё тесные отсеки, в которые надо пролезать, пригнув голову. Зайдёшь — и сразу поймёшь, как непросто жилось морякам в таком железном доме под водой.", "q": "На каком острове стоит лодка-музей «Народоволец»?", "a": [ "На Васильевском", "На Котлине", "На Заячьем" ] }, { "id": "spb-d-kronshtadtskiy-sobor", "e": "⚓", "t": "Морской собор в Кронштадте", "s": "Город Кронштадт стоит на острове Котлин посреди Финского залива, как каменный кораблик. Главный храм там — Морской собор, построенный для моряков. Его купол покрыт алюминием и украшен якорями и спасательными кругами. Собор такой большой, что в нём могли поместиться около пяти тысяч человек, а вместе с крестом он почти семьдесят метров высотой. Освятили его в 1913 году.", "q": "Чем украшен купол Морского собора?", "a": [ "Якорями и спасательными кругами", "Звёздами и месяцами", "Рыбками и ракушками" ] }, { "id": "spb-d-linii", "e": "🔢", "t": "Улицы-линии Васильевского острова", "s": "На Васильевском острове улицы называют по-особому — линиями: Первая, Вторая, Третья... Пётр Первый мечтал прорыть здесь каналы, как в Венеции или Амстердаме, а дома поставить вдоль воды. Каналы так и не выкопали, а название осталось. И ещё одна странность: у одной улицы две стороны живут под разными номерами. На левой стороне, например, Третья линия, а на правой напротив — уже Четвёртая.", "q": "Как называют улицы на Васильевском острове?", "a": [ "Линиями", "Кольцами", "Лучами" ] }, { "id": "spb-d-smolnyy-sobor", "e": "💙", "t": "Бело-голубой Смольный собор", "s": "Смольный собор бело-голубой, будто сделан из неба и сахара. Его придумал архитектор Растрелли, а строить начали в 1748 году, при императрице Елизавете. Растрелли не увидел собор готовым: достроили его только в 1835 году. Слово «Смольный» пришло от смолы: раньше на этом месте был Смольный двор, где варили смолу для кораблей.", "q": "От какого слова пошло название «Смольный»?", "a": [ "От слова «смола»", "От слова «смех»", "От слова «смородина»" ] }, { "id": "spb-d-eliseevskiy", "e": "🍬", "t": "Магазин как дворец", "s": "На Невском проспекте стоит Елисеевский магазин. Его открыли в начале двадцатого века купцы Елисеевы, и он построен так красиво, что похож на дворец. Окна огромные, с цветными витражами. Под высоким потолком висят тяжёлые бронзовые люстры. Магазин работает до сих пор, и в нём можно купить сладости. Зайди — и как будто попал в сказку про конфеты.", "q": "Что за здание — Елисеевский на Невском проспекте?", "a": [ "Магазин, похожий на дворец", "Театр кукол", "Школа для принцесс" ] }, { "id": "spb-d-vyborg", "e": "🏰", "t": "Замок на острове в Выборге", "s": "Если поехать из Петербурга на северо-запад, примерно через сто тридцать километров увидишь Выборг. Там на маленьком острове стоит старый замок. Его заложили в 1293 году, значит, ему больше семисот лет. Главная башня замка названа в честь святого Олафа. Если подняться наверх, оттуда виден весь городок, залив и крыши вокруг.", "q": "Сколько лет примерно Выборгскому замку?", "a": [ "Больше семисот", "Около ста", "Около пятидесяти" ] }, { "id": "spb-d-kolesnitsa-slavy", "e": "🐴", "t": "Арка с шестёркой коней", "s": "На Дворцовую площадь можно попасть через огромную арку Главного штаба. Над аркой стоит колесница, на которой едет крылатая богиня победы. Колесницу везут шесть бронзовых коней, они шагают рядом, как настоящая упряжка. Идёшь по тесной улице, и вдруг арка раскрывается — а за ней огромная площадь с высокой колонной. Это очень красивый сюрприз.", "q": "Сколько бронзовых коней везут колесницу над аркой?", "a": [ "Шесть", "Два", "Десять" ] } ], "russia": [ { "id": "ru-big", "e": "🌏", "t": "Самая большая страна", "s": "Россия — самая большая страна на свете. В ней поместилось бы больше ста восьмидесяти таких стран, как Португалия! Россия такая широкая, что в ней одиннадцать часовых поясов. Когда дети в Калининграде ложатся спать, на Камчатке уже наступает утро. Там ребята в это время просыпаются и собираются в детский сад.", "q": "Что на Камчатке, когда дети в Калининграде ложатся спать?", "a": [ "Там уже утро", "Там идёт дождь из конфет", "Там пингвины поют колыбельную" ] }, { "id": "ru-transsib", "e": "🚂", "t": "Неделя в поезде", "s": "Через Россию проходит самая длинная железная дорога на свете — Транссиб. Поезд едет по ней из Москвы во Владивосток почти неделю! За окном мелькают леса, реки, горы и даже озеро Байкал. В вагоне можно спать на полке, пить чай и смотреть, как меняется страна. А во Владивостоке, у самого моря, стоит столбик с числом 9288: столько километров проехал поезд.", "q": "Сколько едет поезд из Москвы во Владивосток?", "a": [ "Почти неделю", "Пять минут", "Целых сто лет" ] }, { "id": "ru-baikal", "e": "🦭", "t": "Байкал и нерпа", "s": "Байкал — самое глубокое озеро на свете. Вода в нём такая чистая, что камушки на дне видно даже очень глубоко. Зимой Байкал замерзает, и лёд бывает прозрачным, как стекло: смотришь под ноги и видишь воду. А ещё здесь живёт нерпа — круглый тюлень с большими тёмными глазами. Таких нерп нет больше нигде в мире, только на Байкале.", "q": "Кто живёт только на Байкале?", "a": [ "Нерпа", "Жираф-водолаз", "Слон в тельняшке" ] }, { "id": "ru-geysers", "e": "🌋", "t": "Долина гейзеров", "s": "Камчатка — край вулканов. Там много огнедышащих гор, и некоторые из них иногда просыпаются и пыхтят дымом и пеплом. А ещё на Камчатке есть Долина гейзеров. Гейзер — это горячий источник, из которого вдруг вырывается фонтан кипятка и пара: пш-ш-ш! Дорог в долину нет, поэтому гостей привозят туда на вертолёте.", "q": "Что вырывается из гейзера?", "a": [ "Кипяток и пар", "Мороженое с вареньем", "Мыльные пузыри" ] }, { "id": "ru-bears", "e": "🐻", "t": "Медведи-рыболовы", "s": "На Камчатке живёт много больших бурых медведей. Летом из моря в реки приплывает очень много рыбы — лосося. Рыба плывёт против течения и даже прыгает через камни и маленькие водопады. А медведи стоят прямо в реке и ловят её лапами и зубами. Так они толстеют, чтобы потом спокойно проспать всю зиму в берлоге.", "q": "Зачем медведи ловят много рыбы?", "a": [ "Чтобы потолстеть к зиме", "Чтобы научить её танцевать", "Чтобы сложить её в шкаф" ] }, { "id": "ru-volga", "e": "🚢", "t": "Волга-матушка", "s": "Волга — самая длинная река в Европе. Она начинается маленьким ручейком, через который можно перешагнуть. А потом становится такой широкой, что другой берег еле видно. По Волге плывут теплоходы, а на её берегах стоят большие города. Свою долгую дорогу Волга заканчивает в Каспийском море. Её ласково называют Волгой-матушкой.", "q": "Где заканчивает свою дорогу Волга?", "a": [ "В Каспийском море", "В бабушкиной ванне", "На Луне" ] }, { "id": "ru-elbrus", "e": "🏔️", "t": "Эльбрус — выше всех", "s": "В горах Кавказа стоит Эльбрус — самая высокая гора в России и во всей Европе. Его высота — 5642 метра! У Эльбруса две белые вершины, похожие на два горба верблюда. Эльбрус — это спящий вулкан, укрытый снегом и льдом. Даже летом там лежит снег, и наверх поднимаются смелые альпинисты в тёплых куртках и тёмных очках.", "q": "Сколько вершин у Эльбруса?", "a": [ "Две", "Сто одна", "Ни одной" ] }, { "id": "ru-ustyug", "e": "🎅", "t": "Где живёт Дед Мороз", "s": "В старинном городе Великий Устюг живёт Дед Мороз. Его терем стоит в лесу, недалеко от города. Сюда дети со всей страны присылают письма — целые мешки писем! У Деда Мороза даже есть своя почта. А день рождения он празднует восемнадцатого ноября: считается, что как раз тогда в Великом Устюге начинаются настоящие морозы.", "q": "Когда у Деда Мороза день рождения?", "a": [ "Восемнадцатого ноября", "Первого июля, в жару", "Каждый вторник" ] }, { "id": "ru-kizhi", "e": "🪵", "t": "Деревянное чудо Кижей", "s": "На острове Кижи посреди Онежского озера стоит удивительная деревянная церковь. У неё двадцать две главки — круглые макушки, похожие на луковки. Её построили в 1714 году почти без гвоздей. Брёвна плотно соединяли друг с другом, как детали в деревянном конструкторе. А маленькие дощечки на главках блестят на солнце, как серебро.", "q": "Сколько главок у деревянной церкви в Кижах?", "a": [ "Двадцать две", "Ни одной", "Целый миллион" ] }, { "id": "ru-suzdal", "e": "🥒", "t": "Суздаль и День огурца", "s": "Суздаль — маленький старинный город Золотого кольца. Так называют путешествие по древним русским городам, которое складывается в кольцо. В Суздале есть музей под открытым небом: туда привезли из деревень старые деревянные избы и ветряные мельницы. В избу можно зайти и посмотреть на большую русскую печь. А летом в Суздале бывает весёлый праздник — День огурца!", "q": "Какой весёлый праздник бывает в Суздале?", "a": [ "День огурца", "День летающей кастрюли", "День зубной щётки" ] }, { "id": "ru-matryoshka", "e": "🪆", "t": "Первая матрёшка", "s": "Матрёшка — деревянная кукла, внутри которой прячутся другие куклы, одна меньше другой. Первую матрёшку сделали больше ста лет назад. В ней было восемь кукол: первая — девочка с чёрным петухом в руке, а самая маленькая — спелёнутый малыш. Эта матрёшка и сейчас хранится в музее игрушки в городе Сергиев Посад. Там до сих пор точат и расписывают матрёшек.", "q": "Кого держит в руке первая матрёшка?", "a": [ "Чёрного петуха", "Синего крокодила", "Розового слона" ] }, { "id": "ru-khokhloma", "e": "🥄", "t": "Золотая хохлома", "s": "Хохлома — это золотая роспись на деревянной посуде: ложках, мисках и чашках. Красные ягоды, чёрные листики и завитки будто горят на золотом фоне. Но настоящего золота там нет! Мастера натирают посуду серебристым порошком, рисуют узор, покрывают лаком и ставят в горячую печь. От жара лак желтеет, и серебристая посуда становится золотой.", "q": "Отчего хохломская посуда становится золотой?", "a": [ "От лака и жара печки", "От золотой рыбки", "От солнечного зайчика" ] }, { "id": "ru-gzhel", "e": "🫖", "t": "Синяя гжель", "s": "Гжель — это бело-синяя посуда и фигурки. Их делают в краю с таким же названием, недалеко от Москвы. Мастер кисточкой рисует на белой посуде цветы, птиц и завитки. Удивительно, но краска сначала тёмная, почти чёрная. А когда посуду обожгут в очень горячей печи, узор становится ярко-синим, как весеннее небо.", "q": "Какого цвета узор гжели после печки?", "a": [ "Ярко-синего", "Шоколадного", "Зелёного в крапинку" ] }, { "id": "ru-dymka", "e": "🦃", "t": "Дымковская игрушка", "s": "Дымковская игрушка родом из города Киров. Мастерицы лепят из глины барынь в пышных юбках, индюков, коней и козликов. Потом игрушку белят мелом, разведённым в молоке, и она становится белой-белой. Сверху рисуют яркие кружочки, полоски и клеточки: красные, жёлтые, синие. А раньше многие такие игрушки были свистульками.", "q": "Чем белят дымковскую игрушку?", "a": [ "Мелом в молоке", "Зубной пастой", "Сметаной с мёдом" ] }, { "id": "ru-tula", "e": "🍪", "t": "Самовары и пряники Тулы", "s": "Город Тула славится самоварами и пряниками. Самовар — это большой блестящий чайник с трубой внутри. Раньше в трубу клали горячие угольки или сосновые шишки, и вода быстро закипала. А тульский пряник — плоский, с начинкой из варенья. Сверху на нём выдавлен узор: его делают деревянной доской, будто печатью.", "q": "Чем славится Тула?", "a": [ "Самоварами и пряниками", "Летающими коровами", "Пингвинами и бананами" ] }, { "id": "ru-kazan", "e": "🍯", "t": "Казань и чак-чак", "s": "Казань стоит на берегу Волги. Здесь есть белый Кремль, а в нём — башня Сююмбике. Она немножко наклонилась, будто устала стоять. В Казани говорят на двух языках: на русском и на татарском. А самое известное татарское угощение — чак-чак. Это маленькие кусочки теста, которые обжаривают, заливают мёдом и складывают горкой.", "q": "Какое сладкое угощение готовят в Казани?", "a": [ "Чак-чак", "Тик-так", "Бум-бум" ] }, { "id": "ru-sochi", "e": "🌴", "t": "Пальмы и снег в Сочи", "s": "Сочи — тёплый город на берегу Чёрного моря, летом здесь все купаются и загорают. На его улицах растут пальмы, а снег в самом городе выпадает редко. Но совсем рядом, в горах Красной Поляны, зимой лежит много снега. Весной можно утром гулять под пальмами, а днём кататься на санках! В 2014 году в Сочи прошли зимние Олимпийские игры.", "q": "Что растёт на улицах Сочи?", "a": [ "Пальмы", "Леденцы", "Носки" ] }, { "id": "ru-amber", "e": "💛", "t": "Янтарный берег", "s": "Калининградская область — самый западный край России. Здесь, у Балтийского моря, добывают больше всего янтаря на свете. Янтарь — это смола древних деревьев, которая застыла и стала тёплым жёлто-медовым камешком. Иногда внутри видно мушку или муравья, которые прилипли к смоле очень-очень давно. А после шторма люди гуляют по пляжу и находят кусочки янтаря прямо в песке.", "q": "Из чего получился янтарь?", "a": [ "Из смолы древних деревьев", "Из застывшего лимонада", "Из бабушкиных пуговиц" ] }, { "id": "ru-oymyakon", "e": "🥶", "t": "Мороз в Оймяконе", "s": "Оймякон — посёлок в Якутии, одно из самых холодных мест на Земле, где живут люди. Зимой там бывает холоднее минус шестидесяти градусов! Если выплеснуть на морозе кружку кипятка, он тут же превратится в облачко снега. Якутские лошади живут прямо на улице: у них густая длинная шерсть, тёплая, как шуба. А летом в Оймяконе бывает даже жарко.", "q": "Во что превратится кипяток на морозе в Оймяконе?", "a": [ "В облачко снега", "В компот", "В золотую рыбку" ] }, { "id": "ru-polar-bears", "e": "🐻‍❄️", "t": "Остров белых медведей", "s": "Далеко на севере, в холодном океане, лежит остров Врангеля. Его называют родильным домом белых медведей. Осенью медведицы роют в снегу берлоги, а зимой там рождаются крошечные слепые медвежата. Весной мама выводит малышей наружу. А знаешь, у белого медведя кожа чёрная! Его шерстинки прозрачные и только кажутся белыми.", "q": "Какого цвета кожа у белого медведя?", "a": [ "Чёрного", "Розового в горошек", "Зелёного" ] }, { "id": "ru-tiger", "e": "🐅", "t": "Амурский тигр", "s": "В тайге, густом лесу на Дальнем Востоке, живёт амурский тигр. Это один из самых больших котов на свете. Он не боится снега и мороза: у него густая тёплая шерсть и толстый слой жира под кожей. Полоски у каждого тигра свои, как узор на пальчиках у людей. Поэтому учёные узнают тигров по снимкам, которые делают спрятанные в лесу фотоаппараты.", "q": "Как учёные узнают каждого тигра?", "a": [ "По полоскам", "По шляпе", "По любимой песенке" ] }, { "id": "ru-murmansk", "e": "🌌", "t": "Полярная ночь и северное сияние", "s": "Мурманск — самый большой город за Полярным кругом, далеко на севере. Зимой здесь наступает полярная ночь: больше месяца солнце совсем не показывается на небе. Зато иногда загорается северное сияние — зелёные ленты света, которые колышутся, как занавески на ветру. А летом всё наоборот: солнце светит круглые сутки и даже ночью не уходит спать.", "q": "Что бывает в Мурманске летом?", "a": [ "Солнце светит даже ночью", "С неба падают конфеты", "Медведи катаются на трамвае" ] }, { "id": "ru-altai", "e": "🏞️", "t": "Золотое озеро Алтая", "s": "Алтай — край высоких гор, быстрых рек и кедровых лесов. Среди гор лежит длинное и глубокое Телецкое озеро. Алтайцы называют его Алтын-Кёль, что значит Золотое озеро. В него впадает около семидесяти рек, а вытекает только одна — река Бия. Потом Бия встречается с рекой Катунь, и вместе они становятся большой рекой Обью. Вода в озере прозрачная и холодная даже летом.", "q": "Как алтайцы называют Телецкое озеро?", "a": [ "Золотое озеро", "Шоколадное озеро", "Озеро-пылесос" ] }, { "id": "ru-kungur", "e": "🧊", "t": "Ледяная пещера", "s": "Рядом с городом Кунгуром на Урале есть Ледяная пещера. В её первых залах даже летом мороз, а стены и потолок покрыты льдом и кристаллами, похожими на большие снежинки. Залы в пещере называют гротами, и их там очень много. А ещё внутри прячутся десятки подземных озёр с прозрачной-прозрачной водой. Гостей водят по пещере с фонариками и разноцветной подсветкой.", "q": "Что бывает в Кунгурской пещере даже летом?", "a": [ "Мороз и лёд", "Жара и пальмы", "Дождик из киселя" ] }, { "id": "ru-maslenitsa", "e": "🥞", "t": "Масленица и блины", "s": "Масленица — весёлый праздник, когда провожают зиму и встречают весну. Целую неделю пекут блины: круглые, золотистые и горячие, как маленькое солнышко. Их едят со сметаной, мёдом или вареньем. Люди катаются с горок, водят хороводы и играют в снежки. А в последний день провожают большую соломенную куклу-Масленицу — так говорят зиме «до свидания».", "q": "Что пекут на Масленицу?", "a": [ "Блины", "Кирпичи", "Валенки" ] }, { "id": "ru-a-tsar-pushka", "e": "🏰", "t": "Царь-пушка", "s": "В московском Кремле стоит пушка-великанша. Её зовут Царь-пушка. Ствол у неё длиннее легковой машины, больше пяти метров, а весит она около тридцати девяти тонн. Отлил её мастер Андрей Чохов в 1586 году. На стволе есть красивые узоры и даже всадник на коне. Рядом лежат огромные круглые ядра, но они здесь для красоты: сегодня Царь-пушка — просто старинное чудо мастерства, на которое приходят посмотреть со всего мира.", "q": "Какого размера ствол Царь-пушки?", "a": [ "Длиннее легковой машины", "Короче карандаша", "Ростом с малыша" ] }, { "id": "ru-a-tsar-kolokol", "e": "🔔", "t": "Царь-колокол, который не звонил", "s": "В Кремле стоит колокол, которого считают самым большим в мире. Он высотой с двухэтажный дом, больше шести метров, а весит больше двухсот тонн. Но Царь-колокол ни разу не прозвонил. Во время большого пожара в нём появилась трещина, и от него откололся кусок тяжелее десяти тонн. Колокол долго лежал в яме, а потом его подняли и поставили на каменный пьедестал. Теперь кусок стоит рядом, и все могут заглянуть внутрь колокола.", "q": "Что случилось с Царь-колоколом?", "a": [ "Он ни разу не прозвонил", "Он звонит каждое утро", "Он улетел на воздушном шаре" ] }, { "id": "ru-a-metro-dvortsy", "e": "🚇", "t": "Подземные дворцы метро", "s": "Московское метро — это не просто поезда. Многие станции похожи на дворцы: мрамор, люстры, цветные картинки из кусочков стекла на потолке. На станции «Площадь Революции» стоят бронзовые фигуры людей. Рядом с ними сидит бронзовая собака по имени Ингус. Пассажиры гладят ей нос на удачу, и поэтому нос блестит, как золотой. Можно ехать по делам, а можно кататься и разглядывать станции, как в музее под землёй.", "q": "Что блестит у бронзовой собаки Ингус?", "a": [ "Нос, который гладят на удачу", "Хвост, который красят", "Уши, которые моют" ] }, { "id": "ru-a-kreml-bashni", "e": "🧱", "t": "Башни Кремля", "s": "Кремль окружает красная кирпичная стена длиной больше двух километров. В ней двадцать башен, и почти все они разные: у одних высокие шатры, у других крыши как шапки. У каждой башни своё имя: Спасская, Боровицкая, Царская. А на самой стене сверху зубцы в форме ласточкиного хвоста, их больше тысячи. Если встать на Красной площади и посмотреть вверх, кажется, что башни тянутся к облакам.", "q": "На что похожи зубцы кремлёвской стены?", "a": [ "На ласточкин хвост", "На ёлочки", "На кошачьи ушки" ] }, { "id": "ru-a-tretyakovka", "e": "🖼️", "t": "Купец, подаривший картины", "s": "Давным-давно в Москве жил купец Павел Третьяков. Он очень любил русскую живопись и покупал картины художников, чтобы все могли на них смотреть. Собрал так много, что в 1892 году подарил своё собрание Москве. Так появилась Третьяковская галерея. Её сказочный фасад в русском стиле нарисовал художник Виктор Васнецов. Внутри висят знаменитые картины: «Алёнушка», «Богатыри», «Утро в сосновом лесу» с медвежатами.", "q": "Что Павел Третьяков подарил Москве?", "a": [ "Свою коллекцию картин", "Свой большой сад", "Свою коллекцию колоколов" ] }, { "id": "ru-a-novgorod-beresta", "e": "✉️", "t": "Письма на бересте", "s": "В Великом Новгороде около тысячи лет назад писали письма на берёзовой коре. Буквы выцарапывали острой палочкой. Археологи нашли такие письма в земле, и они сохранились! Среди них есть листки мальчика по имени Онфим. Ему было лет шесть или семь, он учился писать и тренировал буквы. А между буквами рисовал человечков и забавных зверей. Эти рисунки прожили в земле почти восемьсот лет.", "q": "На чём писали письма в Великом Новгороде?", "a": [ "На берёзовой коре", "На стеклянных пластинках", "На больших листьях лопуха" ] }, { "id": "ru-a-yaroslavl-medved", "e": "🐻", "t": "Медведь на гербе Ярославля", "s": "На гербе Ярославля нарисован медведь. Он стоит на задних лапах и держит секиру. По старой легенде, князь Ярослав Мудрый основал город на берегу Волги в том месте, где жил медведь, и справился с ним. Поэтому медведь стал знаком города. Сегодня в Ярославле медведь везде: на сувенирах, на улицах и на гербе. Если приедете, поищите его на домах и в витринах.", "q": "Кто нарисован на гербе Ярославля?", "a": [ "Медведь", "Заяц", "Журавль" ] }, { "id": "ru-a-vladimir-zolotye-vorota", "e": "🚪", "t": "Золотые ворота Владимира", "s": "Во Владимире стоят Золотые ворота. Их построил князь Андрей Боголюбский больше восьмисот пятидесяти лет назад из белого камня. Это были въездные ворота в город, а над проездом поместили небольшую церковь. Говорят, что створки покрыли золотистой медью, поэтому ворота и назвали золотыми. За столько веков ворота пережили дожди, морозы и перестройки, но по-прежнему стоят и пропускают прохожих и машины.", "q": "Из какого камня построены Золотые ворота?", "a": [ "Из белого камня", "Из розового гранита", "Из стекла" ] }, { "id": "ru-a-kaliningrad-ostrov-kanta", "e": "🏝️", "t": "Остров с собором", "s": "В Калининграде среди реки Преголи лежит остров, а на нём высокий кирпичный собор. Город раньше назывался Кёнигсберг. Здесь жил учёный Иммануил Кант. Говорят, он почти никогда не уезжал далеко от родного города и всё равно придумал много про весь мир. Его могила находится рядом с собором. Остров зовут островом Канта, там растёт парк. А в соборе слушают звуки большого органа.", "q": "Какой инструмент звучит в соборе на острове?", "a": [ "Орган", "Балалайка", "Барабан" ] }, { "id": "ru-a-nizhny-chkalovskaya", "e": "🪜", "t": "Чкаловская лестница", "s": "В Нижнем Новгороде есть длинная лестница, которая спускается к Волге. Она называется Чкаловской, в честь лётчика Валерия Чкалова. Сверху на неё интересно смотреть: она идёт зигзагом и похожа на цифру восемь. Ступенек примерно пятьсот шестьдесят, хотя считают по-разному. Дети любят пробовать их все пересчитать, а потом получают разные числа. Наверху можно остановиться и посмотреть на реку.", "q": "На какую цифру похожа лестница сверху?", "a": [ "На восьмёрку", "На единицу", "На тройку" ] }, { "id": "ru-a-ekaterinburg-granitsa", "e": "🌍", "t": "Одной ногой в Европе", "s": "Екатеринбург стоит на Урале, а Уральские горы — граница между Европой и Азией. За городом поставили большой памятник, обелиск «Европа — Азия». Посередине проходит линия границы. Если встать на неё одной ногой с одной стороны, а другой с другой, получится, что ты стоишь сразу в двух частях света. Туристы любят фотографироваться так: одна нога в Европе, а другая в Азии.", "q": "Что можно сделать у обелиска на границе?", "a": [ "Встать одной ногой в Европе, другой в Азии", "Пройти из Африки в Австралию", "Нырнуть в океан" ] }, { "id": "ru-a-vladivostok-most", "e": "🌉", "t": "Мост на Русский остров", "s": "Во Владивостоке есть остров, который называется Русский. Чтобы на него попасть, построили огромный Русский мост. Он висит на толстых стальных канатах, и между его высокими башнями расстояние больше километра: тысяча сто четыре метра. Это самый длинный пролёт среди таких мостов в мире. Мост построили в 2012 году. Внизу плывут корабли, а наверху едут машины, и с острова видно море.", "q": "На чём держится Русский мост?", "a": [ "На стальных канатах", "На деревянных столбах", "На воздушных шарах" ] }, { "id": "ru-a-salekhard-polyarny-krug", "e": "❄️", "t": "Город на Полярном круге", "s": "Салехард — северный город, который стоит почти на самой линии Полярного круга. Эту линию нарисовали на карте учёные, а в городе поставили памятный знак. Слово «Салехард» пришло от ненцев, оленеводов тундры. Оно значит «город на мысу». Летом здесь очень светлые ночи, а зимой бывают долгие тёмные дни. Люди в Салехарде носят тёплые меховые шапки, а на улицах можно встретить оленей.", "q": "Что значит слово «Салехард»?", "a": [ "Город на мысу", "Город среди пальм", "Город у моря" ] }, { "id": "ru-a-yakutsk-svai", "e": "🏠", "t": "Дома на сваях", "s": "В Якутске зимой бывает так холодно, что земля промерзает на сотни метров и никогда не оттаивает. Это называется вечная мерзлота. Если поставить обычный тёплый дом прямо на неё, лёд под ним начнёт таять и дом накренится. Поэтому в Якутске дома ставят на длинные сваи, вбитые глубоко в мерзлоту. Под домом остаётся воздух, ветер продувает его и держит землю холодной. Дом стоит прочно.", "q": "Почему в Якутске дома ставят на сваи?", "a": [ "Чтобы тепло не растопило мёрзлую землю", "Чтобы их не смыло морем", "Чтобы жить поближе к птицам" ] }, { "id": "ru-a-arkhangelsk-kozuli", "e": "🦌", "t": "Расписные козули", "s": "В Архангельске на Севере пекут особые пряники. Их называют козулями. Это не обычные пряники, а целые картинки: на них пекарь рисует оленей, коров, птиц, ёлочки и узоры цветной глазурью. Поморы, жители берегов Белого моря, раньше дарили козули детям на праздники. Такую козулю жалко есть сразу: ею можно любоваться. Но потом всё равно хочется попробовать, ведь она сладкая.", "q": "Что рисуют на козулях?", "a": [ "Оленей, птиц и узоры", "Только квадратики", "Только буквы" ] }, { "id": "ru-a-solovki-labirinty", "e": "🌀", "t": "Лабиринты Соловков", "s": "На Соловецких островах в Белом море есть удивительные каменные лабиринты. Это спирали, выложенные из камней прямо на земле. Им несколько тысяч лет. Зачем люди их делали, учёные до сих пор спорят. Может быть, это была игра, а может, древний знак. Если пройти по спирали до середины и обратно, можно загадать желание. Рядом летом почти не темнеет.", "q": "Из чего сложены лабиринты на Соловках?", "a": [ "Из камней", "Из деревянных брёвен", "Из конфет" ] }, { "id": "ru-a-vyborg-biblioteka", "e": "📚", "t": "Библиотека с волнистым потолком", "s": "В Выборге есть библиотека, построенная известным финским архитектором Алваром Аалто. Её открыли ещё в 1935 году. Внутри лекционный зал с потолком, который идёт волнами. А в читальном зале в потолке круглые окошки, через которые льётся свет, и сам зал устроен ступеньками, так что читатели сидят на разной высоте. Здесь каждый находит своё удобное место с книжкой. Эта библиотека знаменита среди архитекторов всего мира.", "q": "Какой формы потолок в лекционном зале?", "a": [ "Волнистый", "Квадратный и плоский", "Как острая башня" ] }, { "id": "ru-a-kalyazin-kolokolnya", "e": "⛪", "t": "Колокольня посреди воды", "s": "В городе Калязине на Волге стоит колокольня высотой около семидесяти пяти метров, а вокруг неё вода. Раньше она была частью большого собора. Когда на реке построили плотину и появилось море, часть города ушла под воду. Нижний ярус колокольни тоже оказался в воде, а вот остальная часть осталась. Теперь она стоит одна на маленьком островке. Мимо неё плывут корабли, а издалека кажется, что колокольня вырастает прямо из воды.", "q": "Что стало с колокольней в Калязине?", "a": [ "Она стоит посреди воды", "Она лежит на боку", "Её увезли на другую планету" ] }, { "id": "ru-a-myshkin-muzei-mishi", "e": "🐭", "t": "Музей мыши", "s": "На Волге стоит маленький городок с очень подходящим названием Мышкин. Здесь есть настоящий Музей мыши. Говорят, это единственный в мире музей, который посвящён только мышам. В нём собраны мышки из дерева, глины, стекла и ткани, мышиные картины и сказки. Игрушки привозят и присылают люди из разных стран. Поэтому Мышкин называют мышиной столицей. Если туда приедешь, можно сфотографироваться с большой мышкой.", "q": "Кому посвящён музей в Мышкине?", "a": [ "Мышам", "Слонам", "Лягушкам" ] }, { "id": "ru-b-lenskie-stolby", "e": "🪨", "t": "Ленские столбы", "s": "Над рекой Леной в Якутии стоят каменные стены, похожие на башни сказочного замка. Некоторые из них выше стометрового дома! Эти скалы очень древние: им около пятисот миллионов лет. А в их трещинах учёные находят окаменевших морских животных, которые жили, когда здесь было тёплое море. Теперь место вокруг холодное, и по реке плывут катера, а туристы смотрят на скалы снизу и крутят головой.", "q": "Над какой рекой стоят каменные столбы?", "a": [ "Над Леной", "Над Волгой", "Над Невой" ] }, { "id": "ru-b-kurshskaya-kosa", "e": "🌲", "t": "Танцующий лес", "s": "Куршская коса — тонкая полоска песка и сосен между морем и заливом. Она тянется почти на сто километров. В одном месте растёт «танцующий лес»: стволы сосен изогнуты, перекручены и свиваются в кольца, будто деревья пустились в пляс. Почему они выросли такими, учёные до сих пор спорят. А рядом поднимаются высокие песчаные дюны, и с дюны Эфа видно сразу и море, и залив.", "q": "Как называют лес с изогнутыми соснами на Куршской косе?", "a": [ "Танцующий лес", "Поющий лес", "Спящий лес" ] }, { "id": "ru-b-onezhskoe-ozero", "e": "🏝️", "t": "Онежское озеро и его острова", "s": "Онежское озеро в Карелии такое большое, что у него не видно другого берега, как у моря. Оно второе по величине в Европе. А ещё на нём больше полутора тысяч островов: и огромных, и совсем крошечных, где поместятся только три ёлки. Рядом с озером добывают чёрный блестящий камень шунгит. Из него делают красивые шарики, которые приятно держать в ладошках.", "q": "Сколько островов на Онежском озере?", "a": [ "Больше полутора тысяч", "Всего три", "Ровно десять" ] }, { "id": "ru-b-klyuchevskaya-sopka", "e": "🌋", "t": "Ключевская сопка", "s": "На Камчатке стоит самый высокий действующий вулкан Евразии — Ключевская сопка. Её вершина поднимается выше четырёх с половиной километров, и почти всегда она в шапке из снега и облаков. Время от времени вулкан просыпается: над ним поднимается лёгкий дымок, а иногда и тёмное облако пепла. Рядом стоят другие вулканы, и вместе они выглядят как семья великанов в белых шапках.", "q": "Где стоит вулкан Ключевская сопка?", "a": [ "На Камчатке", "В Карелии", "На Урале" ] }, { "id": "ru-b-kalan-kurily", "e": "🦦", "t": "Калан с Курильских островов", "s": "Курильские острова — длинная цепочка из полусотни островов между Камчаткой и Японией. В холодных волнах у берегов живёт калан, или морская выдра. Он спит на спине в воде и, чтобы его не унесло, оборачивается водорослями. Калан достаёт со дна ракушки и разбивает их камнем, который носит с собой в складке кожи. А мех у него такой густой, что вода до тела не добирается.", "q": "Чем калан разбивает ракушки?", "a": [ "Камнем", "Палкой", "Ложкой" ] }, { "id": "ru-b-ostrov-vrangelya-mamonty", "e": "🦣", "t": "Мамонты острова Врангеля", "s": "На острове Врангеля в Северном Ледовитом океане мамонты прожили дольше, чем где-либо на земле. Когда в Египте уже строили пирамиды, там ещё бродили небольшие мохнатые мамонты. Они были ниже своих материковых родственников. Теперь на острове живут овцебыки, северные олени и белые медведи, а на скалах гнездятся тысячи птиц. Остров — заповедник, и людям там можно только в гости.", "q": "Какие древние звери жили на острове Врангеля дольше всех?", "a": [ "Мамонты", "Динозавры", "Саблезубые тигры" ] }, { "id": "ru-b-atomny-ledokol", "e": "🚢", "t": "Атомный ледокол", "s": "В Арктике ходит атомный ледокол — корабль-великан, который сам прокладывает дорогу во льдах. Он въезжает носом на лёд и ломает его собственным весом, а лёд бывает толще двух метров. Корпус у ледокола особенно прочный. Топлива ему хватает надолго, и он доходит до самого Северного полюса. Пассажиры стоят на палубе и смотрят на белую пустыню, где только небо, лёд и иногда пробегает белый медведь.", "q": "Как ледокол ломает лёд?", "a": [ "Въезжает на него носом и давит весом", "Растапливает его огнём", "Взрывает его" ] }, { "id": "ru-b-kedrovka", "e": "🐦", "t": "Кедровка — птица-садовник", "s": "В сибирской тайге живёт птица кедровка. Осенью она собирает кедровые орешки и прячет их под мох и в землю, а в особом мешочке под языком носит сразу десятки орешков. Прятать приходится много запасов: зимой кедровка находит их даже под снегом. Но часть тайников она забывает. Из забытых орешков вырастают новые кедры. Получается, птица сама сажает лес, хотя вовсе об этом не думает.", "q": "Кто сажает кедры, забывая орешки?", "a": [ "Кедровка", "Сова", "Дятел" ] }, { "id": "ru-b-sobol", "e": "🦡", "t": "Соболь — хозяин тайги", "s": "Соболь — небольшой, ловкий зверёк с пушистым тёплым мехом. Он живёт в тайге, быстро бегает по снегу и лазает по деревьям. Любит ягоды и кедровые орешки, ловит мышей. В Сибири холодно, поэтому даже на лапах у соболя густая шерсть. На гербе города Иркутска изображён сказочный зверь бабр, и в зубах он держит соболя. Так город показал, чем славится его край.", "q": "Что держит бабр в зубах на гербе Иркутска?", "a": [ "Соболя", "Рыбу", "Орех" ] }, { "id": "ru-b-amurskiy-goral", "e": "🐐", "t": "Амурский горал", "s": "На Дальнем Востоке, на скалах у самого моря, живёт амурский горал. Он похож на маленького горного козла с короткими рожками. Копыта у него цепкие, поэтому горал ходит по отвесным обрывам так спокойно, как мы по тропинке. Увидеть его трудно: серо-бурая шёрстка сливается с камнями, и зверь стоит неподвижно, как скала. Таких животных мало, и их охраняют.", "q": "Где живёт амурский горал?", "a": [ "На скалах у моря", "В болоте", "В песчаной пустыне" ] }, { "id": "ru-b-dalnevostochny-leopard", "e": "🐆", "t": "Дальневосточный леопард", "s": "В лесах Приморья живёт самая редкая большая кошка на свете — дальневосточный леопард. Их осталось немного больше сотни, и людям очень хочется их сберечь. Шерсть у леопарда зимой густая и светлая, а по ней разбросаны тёмные кольца-пятна. У каждого зверя узор свой, как отпечатки пальцев. Учёные ставят в лесу камеры и по узорам узнают каждого леопарда.", "q": "По чему учёные узнают каждого леопарда?", "a": [ "По узору из пятен", "По цвету глаз", "По голосу" ] }, { "id": "ru-b-zubr", "e": "🦬", "t": "Зубр вернулся в лес", "s": "Зубр — самый тяжёлый наземный зверь Европы: он весит почти тонну. Когда-то люди чуть не потеряли зубров совсем, и остались они только в зоопарках. Потом зверей стали разводить и выпускать обратно в лес, в том числе на Кавказ и в Приокско-Террасный заповедник под Москвой. Теперь зубры снова бродят по чащам, жуют траву и кору, а у малышей-зубрят шёрстка кудрявая и тёмно-рыжая.", "q": "Где зубры жили, когда их оставалось очень мало?", "a": [ "В зоопарках", "В пустыне", "В море" ] }, { "id": "ru-b-saygak", "e": "🫎", "t": "Сайгак с необычным носом", "s": "В степях Калмыкии пасутся сайгаки — антилопы с огромным мягким носом, похожим на короткий хобот. Нос у них не для красоты: летом он фильтрует пыль, которую поднимает ветер, а зимой греет холодный воздух перед тем, как он попадёт внутрь. Сайгаки бегают очень быстро, а в стаде их бывает много. Говорят, их предки жили ещё рядом с мамонтами.", "q": "Для чего сайгаку нужен большой нос?", "a": [ "Чтобы фильтровать пыль и греть воздух", "Чтобы копать ямы", "Чтобы пить воду из реки" ] }, { "id": "ru-b-golomyanka", "e": "🐟", "t": "Голомянка — рыбка-невидимка", "s": "В Байкале на большой глубине живёт странная рыбка голомянка. Она почти прозрачная: сквозь тело можно разглядеть косточки. Рыбка очень жирная, и её жир не замерзает в холодной воде. Голомянка не откладывает икру, а рождает сразу живых мальков, как кошка котят. Если вытащить её на берег, на солнце она растает, как кусочек масла, поэтому увидеть её удаётся не каждому.", "q": "Какая рыбка в Байкале почти прозрачная?", "a": [ "Голомянка", "Щука", "Карась" ] }, { "id": "ru-b-goryachie-istochniki", "e": "♨️", "t": "Купание в снегу на Камчатке", "s": "На Камчатке из-под земли бьют горячие источники: там внутри вулканы, и они греют воду. Люди строят у источников бассейны и купаются даже зимой. Вокруг лежит снег, дует мороз, а в воде тепло, как в ванне. Над водой стоит пар, а у купальщиков шапки покрываются инеем. Так можно сидеть и смотреть на белые сопки, пока щёки не станут розовыми.", "q": "Почему на Камчатке вода из-под земли горячая?", "a": [ "Землю греют вулканы", "Её греет солнце", "Её нагревают котлы" ] }, { "id": "ru-b-ladozhskaya-nerpa", "e": "🦭", "t": "Ладога и пресная нерпа", "s": "Ладожское озеро — самое большое озеро Европы. Оно рядом с Петербургом и Карелией, а на нём бывают такие волны, будто это настоящее море. Но вода в нём пресная, а живут в ней нерпы! Нерп чаще встречают в морях, а в Ладоге они остались с давних времён. Зимой нерпы вскрывают во льду лунки и выглядывают, чтобы подышать. Малыши рождаются в снежных норках на льду.", "q": "Какие морские животные живут в пресной Ладоге?", "a": [ "Нерпы", "Дельфины", "Киты" ] }, { "id": "ru-b-chernoe-more-delfiny", "e": "🐬", "t": "Дельфины Чёрного моря", "s": "В Чёрном море плавают сразу три вида: афалины, белобочки и азовки. Афалина — самая большая и самая улыбчивая. Белобочка похожа на неё, только на боках у неё светлые пятна. Азовка совсем маленькая. Дельфины умеют перекликаться свистом и щелчками, а спят они по очереди: одна половинка мозга отдыхает, а другая следит, чтобы не утонуть.", "q": "Как спят дельфины?", "a": [ "Одной половинкой мозга по очереди", "Только на берегу", "Они совсем не спят" ] }, { "id": "ru-b-step-kovyl", "e": "🌾", "t": "Степь и ковыль", "s": "В южных степях России весной растёт ковыль. Его длинные серебристые метёлки гнутся от ветра, и по степи бегут волны, будто это не трава, а море. У каждого семечка ковыля есть острый хвостик-ость. Когда воздух влажный, он закручивается, как пружинка, и вкручивает семечко в землю. Поэтому трава сама себя сажает: никакого садовника ей не нужно.", "q": "Что делает хвостик семечка ковыля?", "a": [ "Закручивается и вкручивает семечко в землю", "Светится ночью", "Звенит как колокольчик" ] }, { "id": "ru-b-myskusny-byk", "e": "🐂", "t": "Овцебык на Таймыре", "s": "На севере Таймыра, где зимой холодно и бело, живёт овцебык, или мускусный бык. Он похож на мохнатый валенок с рогами. Длинная шерсть свисает почти до земли, а под ней растёт нежный и очень тёплый подшёрсток, поэтому морозы овцебыку не страшны. Много лет назад этих зверей привезли на Таймыр из другого края, и они прижились. Теперь стада бродят по тундре и ищут травку под снегом.", "q": "Почему овцебыку не страшен мороз?", "a": [ "У него очень тёплая шерсть", "Он живёт в тёплой берлоге", "Он носит шубу" ] }, { "id": "ru-c-pelmeni", "e": "🥟", "t": "Пельмени — «хлебное ухо»", "s": "Слово «пельмени» пришло к нам с Урала. Там жил народ коми-пермяки, и на их языке «пельнянь» значит «хлебное ухо». Посмотри на пельмень: он правда немного похож на маленькое ушко из теста! В Сибири их лепили сразу сотнями и выносили на мороз. Замёрзшие пельмени складывали в мешок, и охотник брал его с собой в дорогу. Вскипятил воду — и обед готов.", "q": "Что значит слово «пельнянь» на языке коми-пермяков?", "a": [ "Хлебное ухо", "Тесто с мясом", "Зимний обед" ] }, { "id": "ru-c-shchi-pech", "e": "🍲", "t": "Щи из русской печи", "s": "В старину щи варили не на плите, а в русской печи. Хозяйка ставила горшок ухватом — это такая железная рогулька с длинной ручкой — и задвигала в тёплое нутро печи. Щи часами томились, и вкус у них выходил особенный, мягкий. Про них даже поговорка есть: «Щи да каша — пища наша». А варили их из капусты, и ложки у всей семьи были деревянные, одна общая миска стояла посреди стола.", "q": "Чем ставили горшок со щами в печь?", "a": [ "Ухватом", "Ложкой", "Вилкой" ] }, { "id": "ru-c-yaytsa-luk", "e": "🥚", "t": "Яйца в луковой шелухе", "s": "Перед праздником Пасхи на Руси красят яйца. Самый простой краситель был на каждой кухне — луковая шелуха. Сваришь яйца в отваре из неё, и скорлупа станет красно-коричневой, как осенний лист. А ещё к празднику пекут высокий сладкий хлеб — кулич. Его делают в узкой форме, поэтому он вырастает как шапка повара. Сверху его поливают белой сладкой глазурью.", "q": "Чем красили яйца в старину?", "a": [ "Луковой шелухой", "Свекольным соком", "Морковной ботвой" ] }, { "id": "ru-c-sabantuy", "e": "🥄", "t": "Сабантуй — праздник плуга", "s": "Весной у татар и башкир бывает весёлый праздник Сабантуй. Его название значит «праздник плуга»: когда поля вспаханы и посеяны, можно и повеселиться. Там бегают с яйцом на ложке, прыгают в мешках и лезут на высокий гладкий столб. А ещё борются на поясах — это борьба курэш. Победителю дарят красивое вышитое полотенце, а иногда даже живого барашка.", "q": "Что значит слово «Сабантуй»?", "a": [ "Праздник плуга", "Праздник зимы", "Праздник урожая" ] }, { "id": "ru-c-yolka-petr", "e": "🎄", "t": "Как ёлка пришла в дома", "s": "Давным-давно, триста с лишним лет назад, царь Пётр Первый решил встречать Новый год зимой, первого января. Он велел украшать дома и улицы ветками ёлок, сосен и можжевельника. Сначала это были просто зелёные ветки у ворот. А потом люди стали ставить в доме целое дерево и вешать на него яблоки, орехи, свечи и бумажные игрушки. Так у нас появилась новогодняя ёлка.", "q": "Чем сначала украшали дома к Новому году?", "a": [ "Ветками ёлок и сосен", "Цветными шарами", "Электрическими лампочками" ] }, { "id": "ru-c-kvas", "e": "🍞", "t": "Квас из хлебных корок", "s": "Квас — один из самых старых русских напитков, а делают его из хлеба. Чёрные сухари заливают водой, добавляют закваску, и напиток начинает тихонько пузыриться. Через день-два он становится кисло-сладким и шипучим. Раньше квас пили и в жаркий день на сенокосе, и за обедом. А ещё на квасе готовят холодный летний суп — окрошку, в который крошат огурцы и зелёный лук.", "q": "Из чего делают квас?", "a": [ "Из хлеба", "Из яблок", "Из мёда" ] }, { "id": "ru-c-banya-venik", "e": "🌿", "t": "Баня и берёзовый веник", "s": "Русская баня — это тёплая деревянная избушка с горячим паром. Парятся там с веником, и он обязательно берёзовый или дубовый: зелёные листья пахнут летним лесом. Веники заготавливают летом, вяжут пучками и сушат под крышей. Перед баней его запаривают в кипятке, и по всему дому идёт душистый запах. А когда помылись, говорят добрые слова: «С лёгким паром!»", "q": "Что говорят человеку, который помылся в бане?", "a": [ "С лёгким паром!", "С добрым утром!", "Спокойной ночи!" ] }, { "id": "ru-c-nalichniki", "e": "🪟", "t": "Наличники — кружево на окнах", "s": "В русских деревнях вокруг окон прибивали резные деревянные рамки. Их называют наличники. Мастера вырезали на них солнце, птиц, цветы, русалок и волшебных зверей. Дерево получалось тонким, как кружево, и дом казался нарядным, будто в праздничном платье. А красили наличники в яркие цвета: синий, белый, голубой. Раньше люди верили, что узоры берегут дом и всех, кто в нём живёт.", "q": "Как называют резные рамки вокруг окон?", "a": [ "Наличники", "Ставни", "Карнизы" ] }, { "id": "ru-c-valenki", "e": "🧦", "t": "Валенки без единого шва", "s": "Валенки делают из овечьей шерсти, и у них нет ни одного шва. Мастер берёт мягкую шерсть, мочит горячей водой и долго мнёт и катает руками. Шерсть сама сваливается в плотный тёплый войлок. Получается ботинок, который не пускает холод даже в сильный мороз. Раньше валенки часто делали совсем одинаковыми, так что правый и левый не различались. Они сами подстраивались под ногу.", "q": "Из чего делают валенки?", "a": [ "Из овечьей шерсти", "Из кожи", "Из ткани" ] }, { "id": "ru-c-pavlovo-platki", "e": "🌹", "t": "Платки Павловского Посада", "s": "В городе Павловский Посад под Москвой делают знаменитые платки. Они из тонкой шерсти, а по краю у них длинная пушистая бахрома. Цветы на них огромные, как в сказочном саду: розы, маки, пионы. Раньше рисунок наносили на ткань вручную деревянными формами. Такой платок тёплый и очень нарядный, его носят на плечах или на голове. Каждый платок словно букет, который никогда не завянет.", "q": "Что украшает края платков из Павловского Посада?", "a": [ "Бахрома", "Кружева", "Бусины" ] }, { "id": "ru-c-palekh", "e": "🎨", "t": "Палехская шкатулка", "s": "В посёлке Палех рисуют на чёрных лаковых шкатулках. Шкатулку делают из папье-маше — это спрессованная бумага. Её покрывают чёрным лаком, и на нём краски горят ярко, будто драгоценные камни. Краски мастера разводят на яичном желтке, а кисточки делают из беличьего хвоста: такие тонкие, что можно нарисовать каждую ресничку. Герои палехских картинок — сказочные богатыри, птицы и тройки лошадей. Для узоров нередко берут настоящее золото.", "q": "Какого цвета фон на палехской шкатулке?", "a": [ "Чёрный", "Белый", "Синий" ] }, { "id": "ru-c-zhostovo", "e": "💐", "t": "Жостовские подносы", "s": "В подмосковной деревне Жостово расписывают металлические подносы. Фон у них чаще чёрный, но бывает и зелёный, красный, синий. А на нём — огромный букет: пионы, розы, тюльпаны, ягоды. Мастер рисует цветы широкими мазками прямо кистью, без карандашного рисунка. Потом подносы покрывают лаком, и они блестят, как зеркало. Двух одинаковых букетов не бывает: у каждого мастера своя рука.", "q": "Что рисуют на жостовских подносах?", "a": [ "Букеты цветов", "Зверей", "Города" ] }, { "id": "ru-c-vologda-kruzhevo", "e": "🧵", "t": "Кружево с Вологды", "s": "Вологодское кружево плетут не иголкой, а деревянными палочками-коклюшками. Их может быть несколько десятков! Кружевница сидит перед подушкой-валиком, на котором закреплён рисунок с булавками. Она быстро перекидывает коклюшки из руки в руку, и они тихонько постукивают. Нитки сплетаются в тонкий узор: цветы, листья, снежинки. Из такого кружева шьют воротнички, салфетки и скатерти. Говорят, оно похоже на морозные узоры на окне.", "q": "Чем плетут вологодское кружево?", "a": [ "Коклюшками", "Спицами", "Крючком" ] }, { "id": "ru-c-gorodets", "e": "🐴", "t": "Городецкий конь", "s": "В городе Городец на Волге расписывают деревянные доски, прялки и игрушки. Главные герои росписи — жёлтый конь, петух и огромные цветы с круглыми лепестками. Фон часто жёлтый, как солнце, или голубой. Мастера рисуют быстро и сразу кистью, а потом обводят узор чёрной и белой линией. Лошадка получается весёлая, словно танцует. Такие расписные доски раньше вешали на стены в домах.", "q": "Какого цвета конь на городецкой росписи?", "a": [ "Жёлтый", "Зелёный", "Красный" ] }, { "id": "ru-c-bogorodsk", "e": "🔨", "t": "Медведи-кузнецы из Богородского", "s": "В селе Богородское издавна режут из липы забавные игрушки. Самая известная — «Кузнецы»: мужичок и медведь стоят по обе стороны от наковальни. Под игрушкой есть планочка с шариком. Потянешь её туда-сюда, и они по очереди стучат молотками! Липовое дерево мягкое, резать легко, а игрушка получается тёплая на ощупь. Раньше такие игрушки возили на ярмарки в мешках, и дети в деревнях были счастливы.", "q": "Из какого дерева делают богородские игрушки?", "a": [ "Из липы", "Из берёзы", "Из дуба" ] }, { "id": "ru-c-troyka", "e": "🐎", "t": "Русская тройка", "s": "Тройка — это три лошади в одной упряжке. Средняя бежит ровной рысью, а две боковые скачут, и все вместе мчат сани или карету очень быстро. Над средней лошадью висит высокая дуга, а под ней — колокольчик. Он звенит на всю дорогу, и издалека слышно, что тройка едет. Лошадей украшали лентами, а зимой тройки с колокольцами катали по снегу на празднике. Звон разносился на всю деревню.", "q": "Сколько лошадей в тройке?", "a": [ "Три", "Две", "Четыре" ] }, { "id": "ru-c-tsar-kolokol", "e": "🔔", "t": "Царь-колокол", "s": "В Москве, в Кремле, стоит самый большой в мире колокол — Царь-колокол. Весит он около двухсот тонн, как несколько десятков слонов, а высотой почти с двухэтажный дом. Но он никогда не звонил: когда он ещё стоял в яме после отливки, случился пожар, и колокол треснул, а от него откололся огромный кусок. Теперь колокол стоит на каменной подставке, и в него можно заглянуть, как в комнату. Зато в соборах Кремля звонят другие колокола, и у каждого свой голос.", "q": "Почему Царь-колокол молчит?", "a": [ "В нём трещина", "Он слишком тихий", "Его украли" ] }, { "id": "ru-c-ilya-muromets", "e": "🛡️", "t": "Илья Муромец и былины", "s": "Былины — это старинные песни-сказания о русских богатырях. Их не читали, а пели под гусли. Самый известный герой — Илья Муромец. Он был родом из села под городом Муромом, и, по былине, тридцать лет и три года не мог встать на ноги. Потом странники дали ему испить воды, и он стал самым сильным богатырём. Он был добрым и защищал людей. Старые сказители передавали былины из уст в уста.", "q": "Под какой инструмент пели былины?", "a": [ "Под гусли", "Под гармонь", "Под барабан" ] }, { "id": "ru-c-khomus", "e": "🎶", "t": "Якутский хомус", "s": "У якутов есть удивительный музыкальный инструмент — хомус. Он совсем маленький, умещается в ладони. Это металлическая дужка с тонким язычком посередине. Музыкант прижимает хомус к зубам, дёргает язычок пальцем и меняет форму рта. Звучит нечто необычное: то ветер, то конский топот, то птичий щебет. Рот у играющего работает как маленький зал. В Якутии даже есть музей хомуса, а на нём играют люди всех возрастов.", "q": "Где музыкант держит хомус во время игры?", "a": [ "У зубов", "У уха", "Под подбородком" ] }, { "id": "ru-d-gagarin", "e": "🚀", "t": "Гагарин и Байконур", "s": "12 апреля 1961 года с космодрома Байконур поднялась ракета. В корабле «Восток» сидел Юрий Гагарин. Перед стартом он весело крикнул: «Поехали!» Он один раз облетел вокруг всей Земли и вернулся, а весь полёт занял 108 минут — меньше двух часов. Из космоса Гагарин увидел, что наша планета голубая, и рассказал об этом людям на Земле. Этот день теперь называют Днём космонавтики.", "q": "Что крикнул Гагарин перед стартом?", "a": [ "«Поехали!»", "«Привет!»", "«До свидания!»" ] }, { "id": "ru-d-ciolkovsky", "e": "🔭", "t": "Циолковский из Калуги", "s": "В городе Калуга жил школьный учитель Константин Циолковский. Он учил детей математике и физике, а по вечерам придумывал, как люди полетят к звёздам. Он первым предложил ракету из нескольких частей: когда одна часть сгорает, она отпадает, и ракете становится легче. Ещё он написал: «Земля — колыбель разума, но нельзя вечно жить в колыбели». В Калуге сохранился его дом, и туда приходят посмотреть.", "q": "Кем работал Циолковский в Калуге?", "a": [ "Школьным учителем", "Поваром", "Капитаном корабля" ] }, { "id": "ru-d-sputnik", "e": "🛰️", "t": "Первый спутник", "s": "4 октября 1957 года в небо ушла ракета Сергея Королёва. Она вынесла на орбиту первый в мире искусственный спутник Земли. Это был блестящий металлический шар размером с большой мяч, с четырьмя длинными усами-антеннами. Он облетал Землю и пищал: «бип-бип-бип». Эти сигналы слушали радиолюбители по всему свету. А слово «спутник» теперь знают на многих языках.", "q": "Какой звук подавал первый спутник?", "a": [ "«Бип-бип-бип»", "«Ку-ку»", "«Мяу»" ] }, { "id": "ru-d-belka-strelka", "e": "🐶", "t": "Белка и Стрелка", "s": "19 августа 1960 года в космос полетели две собаки — Белка и Стрелка. Они летели на корабле-спутнике, облетели Землю 17 раз и благополучно приземлились через сутки. Собаки были весёлые, их встречали как героинь. Позже у Стрелки родились щенки, и одного из них, Пушинку, подарили дочке американского президента Каролине. Белку и Стрелку помнят до сих пор, о них даже сняли мультфильм.", "q": "Сколько раз Белка и Стрелка облетели Землю?", "a": [ "17 раз", "1 раз", "100 раз" ] }, { "id": "ru-d-mendeleev", "e": "🧪", "t": "Таблица Менделеева", "s": "Дмитрий Менделеев придумал таблицу, где по порядку стоят все химические элементы. Было это в 1869 году. В таблице он оставил пустые клетки — для элементов, которых люди ещё не нашли! И даже рассказал, какими они будут. Через несколько лет учёные нашли галлий, скандий и германий, и они оказались почти такими, как он писал. А ещё Менделеев любил в свободное время клеить чемоданы.", "q": "Что Менделеев оставил в своей таблице?", "a": [ "Пустые клетки для будущих открытий", "Рисунки зверей", "Музыкальные ноты" ] }, { "id": "ru-d-lomonosov", "e": "🌟", "t": "Ломоносов и Венера", "s": "Михаил Ломоносов родился в северной деревне у моря, а стал великим учёным. По его предложению в Москве открыли университет, который теперь носит его имя. В 1761 году он смотрел в телескоп, как планета Венера проходит по диску Солнца, и заметил вокруг неё тонкий светящийся ободок. Ломоносов понял: у Венеры есть воздух — атмосфера! Он написал об этом, и открытие запомнили.", "q": "Что Ломоносов заметил у Венеры?", "a": [ "Светящийся ободок — атмосферу", "Кольца как у Сатурна", "Моря и корабли" ] }, { "id": "ru-d-lobachevsky", "e": "📐", "t": "Лобачевский и новая геометрия", "s": "Николай Лобачевский почти всю жизнь работал в Казани, в университете, и девятнадцать лет был там главным — ректором. Он придумал новую геометрию. В обычной геометрии две параллельные линии никогда не встречаются. А у него параллельные линии вели себя по-другому, как на изогнутой поверхности. Сначала многие удивлялись и не верили, но потом такая геометрия помогла учёным лучше понять мир. Его называют «Коперником геометрии».", "q": "В каком городе работал Лобачевский?", "a": [ "В Казани", "В Сочи", "В Туле" ] }, { "id": "ru-d-popov", "e": "📻", "t": "Попов и первое радио", "s": "Учитель и учёный Александр Попов построил прибор, который слышал далёкие грозы. А потом сделал из него первое в России радио. В 1896 году он передал по воздуху, без проводов, два слова: «Генрих Герц» — так звали учёного, который открыл радиоволны. Сигнал прошёл около двухсот пятидесяти метров, через двор университета. С тех пор радио стало звучать на весь мир, а 7 мая в России празднуют День радио.", "q": "Какие слова передал Попов без проводов?", "a": [ "«Генрих Герц»", "«Здравствуй, мир»", "«Идёт дождь»" ] }, { "id": "ru-d-kulibin", "e": "🥚", "t": "Часы-яйцо Кулибина", "s": "Мастер-самоучка Иван Кулибин жил в Нижнем Новгороде и умел делать всё: часы, мосты, даже коляску с педалями. Самое известное его чудо — часы в форме яйца, размером с гусиное. Он подарил их императрице Екатерине. Каждый час часы играли мелодию, открывались крошечные дверцы, и появлялись маленькие фигурки. Сегодня эти часы хранятся в Петербурге, в Эрмитаже.", "q": "Какой формы были часы Кулибина?", "a": [ "Как яйцо", "Как домик", "Как звезда" ] }, { "id": "ru-d-sikorsky", "e": "🚁", "t": "Сикорский и «Илья Муромец»", "s": "Игорь Сикорский с детства мечтал о полётах. В 1913 году он построил в России огромный самолёт «Илья Муромец» — с четырьмя моторами! Тогда многие не верили, что такой тяжёлый самолёт поднимется. А внутри был настоящий салон: по нему можно было ходить, а пассажиры сидели в удобных креслах. Позже Сикорский уехал в Америку и построил один из первых вертолётов, на которых можно было летать по-настоящему.", "q": "Сколько моторов было у «Ильи Муромца»?", "a": [ "Четыре", "Один", "Десять" ] }, { "id": "ru-d-balet", "e": "🩰", "t": "Русский балет", "s": "Балерины танцуют в особых туфлях — пуантах — и встают на самые кончики пальцев. Пара пуантов служит недолго: известным балеринам иногда нужна новая пара на каждый спектакль! В России есть знаменитые театры: Большой в Москве и Мариинский в Петербурге. В Петербурге учат танцевать в школе, которая носит имя Агриппины Вагановой. А «Лебединое озеро» и «Щелкунчик» на русской сцене ставят каждую зиму.", "q": "Как называются балетные туфли?", "a": [ "Пуанты", "Валенки", "Кроссовки" ] }, { "id": "ru-d-pushkin-licey", "e": "📜", "t": "Пушкин и Лицей", "s": "Когда Саше Пушкину было двенадцать, он поехал учиться в Лицей в Царском Селе под Петербургом. Лицей был особой школой: там жили и учились мальчики, и вместе с ними росли его друзья. В пятнадцать лет Пушкин читал на экзамене свои стихи, а слушал старый знаменитый поэт Державин. Говорят, он был так восхищён, что хотел обнять мальчика. Сегодня Царское Село — часть города Пушкин.", "q": "Как называется город, где был Лицей?", "a": [ "Пушкин", "Лицей", "Державин" ] }, { "id": "ru-d-tolstoy", "e": "🚲", "t": "Толстой и Ясная Поляна", "s": "Лев Толстой жил в усадьбе Ясная Поляна, где росли яблони и берёзы. Он открыл там школу для деревенских детей и сам писал для них книги: «Азбуку» и сказки вроде «Три медведя». А ещё он очень любил движение: ездил верхом, ходил пешком много вёрст и в 67 лет научился кататься на велосипеде! Дом и сад Ясной Поляны открыты для гостей, там можно гулять.", "q": "Чему Толстой научился в 67 лет?", "a": [ "Кататься на велосипеде", "Играть на скрипке", "Плавать" ] }, { "id": "ru-d-chekhov", "e": "🐕", "t": "Чехов и таксы Бром и Хина", "s": "Антон Чехов был врачом и писателем. Одно время он жил в усадьбе Мелихово, недалеко от Москвы. Он сажал деревья, лечил соседей и помогал строить школы для деревенских детей. А ещё у Чехова жили две таксы, и звали их смешно: Бром и Хина. Так называются два лекарства, а Чехов, как врач, любил шутить. Дом в Мелихове теперь музей, и там тоже ходят гости.", "q": "Как звали таксы Чехова?", "a": [ "Бром и Хина", "Шарик и Бобик", "Тузик и Мурка" ] }, { "id": "ru-d-chaikovsky", "e": "🎹", "t": "Чайковский и волшебная челеста", "s": "Композитор Пётр Чайковский написал музыку к балету «Щелкунчик». Для танца Феи Драже ему нужен был необыкновенный звук — как стеклянные капельки. Он привёз из Парижа новый инструмент, челесту, похожую на маленькое пианино с колокольчиками внутри. Говорят, Чайковский хотел, чтобы звук стал сюрпризом для зрителей, и до премьеры берёг новинку. В Клину, под Москвой, стоит дом, где он писал музыку, а теперь там музей.", "q": "Как называется инструмент, который привёз Чайковский?", "a": [ "Челеста", "Балалайка", "Барабан" ] }, { "id": "ru-d-tretyakov", "e": "🖼️", "t": "Третьяков и его галерея", "s": "Павел Третьяков жил в Москве и очень любил картины. Всю жизнь он покупал работы русских художников, и они висели у него дома. Однажды он решил подарить собрание всем людям и передал его городу Москве. Так появилась Третьяковская галерея. В ней можно увидеть грустную Алёнушку у пруда и трёх богатырей на конях. Каждый год туда приходят миллионы людей, и дети тоже.", "q": "Что сделал Третьяков со своей коллекцией картин?", "a": [ "Подарил городу", "Продал за море", "Спрятал в сундук" ] }, { "id": "ru-d-ledokol", "e": "🚢", "t": "Атомный ледокол «Ленин»", "s": "Ледокол — это корабль, который идёт сквозь лёд. Нос у него особой формы: он въезжает на лёд и ломает его своей тяжестью. В 1959 году в России построили первый в мире атомный ледокол — «Ленин». Ему не нужны были частые заправки, как обычным кораблям, поэтому он мог долго работать далеко на севере. Такие ледоколы стоят в Мурманске и помогают кораблям пройти по Северному Ледовитому океану.", "q": "Как ледокол ломает лёд?", "a": [ "Въезжает носом и давит весом", "Режет ножницами", "Растапливает огнём" ] }, { "id": "ru-d-russky-most", "e": "🌉", "t": "Русский мост во Владивостоке", "s": "Во Владивостоке построили мост на остров Русский. У него есть рекорд: пролёт между двумя башнями — 1104 метра, и это самый длинный такой пролёт у вантового моста в мире. Ванты — это толстые стальные канаты, они идут от высоких башен к дороге, как лучи. Башни выше трёхсот метров. Мост открыли в 2012 году, и по нему можно ехать над морем, а вокруг блестят волны.", "q": "Как называются канаты, которые держат дорогу этого моста?", "a": [ "Ванты", "Верёвки", "Цепочки" ] }, { "id": "ru-d-mir", "e": "🛸", "t": "Станция «Мир»", "s": "«Мир» — первая в мире модульная станция: её собирали на орбите по частям, как конструктор. Её начали строить в 1986 году, и работала она около пятнадцати лет. Станция летела над Землёй так быстро, что делала круг примерно за полтора часа, и космонавты видели много восходов и закатов за сутки. На «Мир» приезжали гости из разных стран. Ею гордились, а потом по её опыту построили Международную космическую станцию.", "q": "Как собирали станцию «Мир»?", "a": [ "По частям, на орбите", "Сразу целиком на Земле", "Из кубиков льда" ] } ], "ger": [ { "id": "de-berlin-bear", "e": "🐻", "t": "Медведь на гербе Берлина", "s": "Главный зверь Берлина — медведь. Он нарисован на гербе и на флаге города: большой чёрный медведь стоит на задних лапах и показывает красный язык. А ещё по улицам Берлина стоят скульптуры медведей, которых разрисовывают художники: один полосатый, другой цветочный, третий в звёздочках. Гуляешь по городу и всё время встречаешь новых медведей.", "q": "Какой зверь нарисован на гербе Берлина?", "a": [ "Медведь", "Крокодил", "Жираф в очках" ] }, { "id": "de-berlin-tower", "e": "🗼", "t": "Телебашня с вращающимся кафе", "s": "В центре Берлина вытянулась телебашня — самая высокая в Германии. Её высота — почти триста семьдесят метров! Наверху блестит большой шар, как мячик на длинной спице. В шаре есть кафе, и пол там медленно поворачивается: примерно за полчаса получается полный круг. Сидишь за столиком, пьёшь какао, а весь город сам проплывает мимо окна. Башню построили в 1969 году.", "q": "Что делает кафе в шаре телебашни?", "a": [ "Медленно поворачивается", "Летает по небу", "Плавает по реке" ] }, { "id": "de-berlin-museums", "e": "🏛️", "t": "Нефертити на Музейном острове", "s": "Посреди берлинской реки Шпрее лежит остров, на котором стоят целых пять музеев. Он так и называется — Музейный остров. В одном из музеев живёт египетская царица Нефертити. Точнее, её портрет: раскрашенная голова из камня, в высокой синей шапке. Ей больше трёх тысяч лет, а краски всё ещё яркие. Правда, у красавицы не хватает одного глаза, но смотреть на неё от этого не менее интересно.", "q": "Кто «живёт» в музее на Музейном острове?", "a": [ "Царица Нефертити", "Баба-яга", "Золушка" ] }, { "id": "de-munich-glockenspiel", "e": "🔔", "t": "Танцующие часы на Мариенплац", "s": "На главной площади Мюнхена, Мариенплац, на башне ратуши есть часы с оживающими фигурками. Каждый день в одиннадцать и в полдень там звонят сорок три колокола, а фигуры в человеческий рост выезжают и кружатся: рыцари сражаются на турнире, а бочары — мастера, которые делают бочки, — танцуют свой танец. В конце наверху кукарекает золотой петушок. Люди собираются заранее и задирают головы.", "q": "Кто кукарекает в конце представления?", "a": [ "Золотой петушок", "Зелёный крокодил", "Рыцарь в шляпе" ] }, { "id": "de-munich-oktoberfest", "e": "🎡", "t": "Праздник на лугу", "s": "Каждую осень в Мюнхене на большом лугу устраивают огромный праздник — Октоберфест. Первый такой праздник был в 1810 году: принц женился, и на свадьбу позвали всех горожан. Теперь там стоят карусели и колесо обозрения, продают жареный миндаль и пряничные сердца с надписями из сахара. Многие гости надевают праздничную одежду: мужчины — кожаные шорты на лямках, женщины — платья с фартуками. Праздник длится около двух недель.", "q": "С чего начался первый Октоберфест?", "a": [ "Со свадьбы принца", "С гонок на тележках с тыквами", "С дня рождения жирафа" ] }, { "id": "de-hamburg-port", "e": "🚢", "t": "Гамбургский порт", "s": "Гамбург — город-порт на реке Эльбе, и порт у него один из самых больших в Европе. Сюда приходят гигантские корабли с тысячами разноцветных контейнеров, а портовые краны, высокие, как жирафы, переставляют эти контейнеры с места на место. Смотреть на всё это лучше с воды. А ещё в Гамбурге на паром садятся по обычному билету, как на автобус, — на нём можно доехать до работы или до школы.", "q": "На чём в Гамбурге можно ехать по обычному билету?", "a": [ "На пароме", "На драконе", "На облаке" ] }, { "id": "de-hamburg-wunderland", "e": "🚂", "t": "Город размером с комнату", "s": "В Гамбурге есть Миниатюр-Вундерланд — самая большая в мире игрушечная железная дорога. Там уменьшенные города, горы и реки, а по ним едут сотни поездов. Есть даже крошечный аэропорт: самолётики сами выруливают на полосу и взлетают! Окошки в домиках светятся, а время от времени за стеклом наступает ночь, и во всех городках зажигаются огоньки. Людей-фигурок так много, что все не сосчитаешь.", "q": "Что взлетает в игрушечном аэропорту?", "a": [ "Самолётики", "Слоники", "Бутерброды" ] }, { "id": "de-cologne-4711", "e": "🌸", "t": "Кёльнская вода «4711»", "s": "В городе Кёльн придумали душистую воду, которая так и называется — «кёльнская вода». По-французски это одеколон, и слово знают во всём мире. Её создал в 1709 году итальянец Фарина. А у одной кёльнской воды смешное имя — «4711». Это просто номер дома, где её делали: когда в Кёльне пронумеровали дома, на этом появилась табличка с цифрами 4711. Так число стало названием.", "q": "Что означает «4711» в названии кёльнской воды?", "a": [ "Номер дома", "Возраст бабушки", "Размер ботинка" ] }, { "id": "de-dresden-stollen", "e": "🍞", "t": "Дрезденский штоллен", "s": "В Дрездене к Рождеству пекут особый сладкий хлеб — штоллен. Он длинный, как небольшое бревно, внутри у него изюм, миндаль и цукаты, а снаружи он густо посыпан сахарной пудрой, будто снегом. Настоящие дрезденские штоллены отмечают специальной печатью. А в декабре в городе бывает праздник штоллена: пекут огромный штоллен, везут по улицам, потом разрезают гигантским ножом, и каждому достаётся кусочек.", "q": "Чем посыпан штоллен снаружи?", "a": [ "Сахарной пудрой", "Песком", "Опилками" ] }, { "id": "de-heidelberg-barrel", "e": "🏰", "t": "Замок с огромной бочкой", "s": "Над городом Гейдельберг на высоком холме стоит красный замок. Красным он кажется потому, что построен из красноватого камня. Часть замка — красивые руины, по ним гуляют туристы, а между камнями растут цветы. А в большом погребе спрятана диковинка — огромная бочка для вина. В неё помещается больше двухсот тысяч литров! Чтобы заглянуть на её верх, надо подняться по лесенке.", "q": "Что спрятано в подвале Гейдельбергского замка?", "a": [ "Огромная бочка", "Ледяной каток", "Космический корабль" ] }, { "id": "de-rhine-lorelei", "e": "🧜‍♀️", "t": "Рейн и скала Лорелей", "s": "Рейн — самая известная река Германии. У неё есть участок, который называют долиной замков: на обоих берегах на холмах стоят старинные замки, почти сорок штук. Плывёшь на теплоходе, как по страницам книги сказок. А рядом высится скала Лорелей. По легенде, на ней сидела девушка с золотыми волосами и пела так красиво, что капитаны заслушивались и забывали смотреть на воду.", "q": "Кто, по легенде, сидел на скале Лорелей?", "a": [ "Девушка с золотыми волосами", "Крокодил с гитарой", "Бабушка с пирогом" ] }, { "id": "de-nuremberg-lebkuchen", "e": "🍪", "t": "Пряничные сердца Нюрнберга", "s": "В Нюрнберге пекут знаменитые пряники — лебкухены. В тесто кладут мёд, орехи и душистые пряности, поэтому по городу плывёт запах Рождества. Снизу пряник часто лежит на тонком съедобном листе, чтобы не прилип к противню. А на праздниках продают большие пряничные сердца на ленточке. На них пишут сахарной глазурью «Для мамы» или «Люблю тебя», и сердце можно повесить на шею.", "q": "Что кладут в тесто для лебкухенов?", "a": [ "Мёд и орехи", "Камешки и песок", "Мыло и лук" ] }, { "id": "de-nikolaus", "e": "👢", "t": "Сапожки для Николауса", "s": "Шестого декабря в Германии приходит Святой Николай. Накануне вечером дети чистят сапожки и ставят за дверь или у окна. А утром — сюрприз: в сапожках лежат орешки, мандарины, шоколадки и маленькие подарки! Говорят, настоящий Николай жил давным-давно и был добрым епископом, который очень любил помогать людям, особенно детям. Поэтому его вспоминают с улыбкой.", "q": "Что делают дети накануне шестого декабря?", "a": [ "Чистят сапожки и ставят за дверь", "Надувают сто шариков", "Строят лодку из снега" ] }, { "id": "de-easter-tree", "e": "🥚", "t": "Дерево с яйцами", "s": "Весной в немецких садах на ветках вдруг вырастают яйца! Это пасхальные деревья. Люди осторожно выдувают из яичек содержимое, красят скорлупки в яркие цвета и вешают на ленточках на ветки. А настоящие шоколадные яйца, как говорят детям, приносит пасхальный заяц. Он прячет их в саду, в траве и кустах, а утром ребята с корзинками отправляются на поиски.", "q": "Кто, по рассказам, прячет яйца в саду?", "a": [ "Пасхальный заяц", "Ёжик в сапогах", "Белый слон" ] }, { "id": "de-knut", "e": "🐻", "t": "Белый медвежонок Кнут", "s": "В берлинском зоопарке в декабре 2006 года родился белый медвежонок Кнут. Мама не стала его выкармливать, и малыша взял на попечение смотритель Томас. Он кормил его молоком из бутылочки, заботился о нём день и ночь. Кнут вырос в пушистого, игривого медвежонка, и о нём узнали во всём мире. Люди приезжали в зоопарк из разных стран, лишь бы на него посмотреть.", "q": "Чем кормил Кнута смотритель?", "a": [ "Молоком из бутылочки", "Мороженым с горохом", "Мармеладными червячками" ] }, { "id": "de-bremen-musicians", "e": "🫏", "t": "Бременские музыканты в Бремене", "s": "В городе Бремен у ратуши стоят четыре бронзовых друга: осёл, собака, кошка и петух. Они стоят друг у друга на спине, как в сказке братьев Гримм. В сказке они шли в Бремен, чтобы стать уличными музыкантами, но так и не дошли до города! Зато в Бремене у осла передние копыта блестят, как золотые: на счастье их гладят туристы и загадывают желание.", "q": "Какое животное стоит в самом низу?", "a": [ "Осёл", "Слон", "Мышь" ] }, { "id": "de-gutenberg", "e": "📖", "t": "Гутенберг и печатные книги", "s": "Давным-давно книги переписывали от руки, и на одну уходили месяцы. А потом в немецком городе Майнц мастер Иоганн Гутенберг придумал печатать книги металлическими буквами. Каждую букву отливали из металла, из них складывали слова и строчки, мазали краской и прижимали к бумаге — как печатью. Так одну страницу можно было отпечатать много раз. Книг стало больше, и читать научились многие. Это было больше пятисот лет назад.", "q": "Какими буквами Гутенберг печатал книги?", "a": [ "Металлическими", "Сахарными", "Бумажными, как облака" ] }, { "id": "de-benz-bertha", "e": "🚗", "t": "Первая дальняя поездка Берты Бенц", "s": "Карл Бенц построил один из первых автомобилей: у него три колеса и мотор. Но ездили на нём только рядом с домом. И вот однажды утром жена Бенца, Берта, взяла двух сыновей и поехала в гости к бабушке — за сто с лишним километров! Бензин кончился, и она купила его в аптеке: тогда его продавали там. Когда засорилась трубка, Берта прочистила её шпилькой для волос. Так все узнали, что автомобиль может ездить далеко.", "q": "Где Берта купила бензин?", "a": [ "В аптеке", "В булочной", "В цирке" ] }, { "id": "de-n-marzipan", "e": "🥜", "t": "Марципан из Любека", "s": "В северном городе Любеке делают знаменитый марципан. Его готовят из молотого миндаля и сахара, и получается мягкое сладкое тесто. Мастера лепят из него настоящие чудеса: крошечные груши и яблоки, поросят, хлебцы — всё как живое. Бывают даже целые картины из марципана. Для Любека эта сладость — главный гостинец: её увозят домой в красивых коробках.", "q": "Из чего делают марципан в Любеке?", "a": [ "Из миндаля и сахара", "Из шоколада и орехов кешью", "Из муки и мёда" ] }, { "id": "de-n-holstentor", "e": "🏰", "t": "Ворота Хольстентор", "s": "В Любеке стоят старинные кирпичные ворота с двумя круглыми башнями — Хольстентор. Им больше пятисот лет. Они такие тяжёлые, что со временем немного ушли в мягкую землю, и стены чуть наклонились. Над входом написано по-латыни: «Согласие дома — мир снаружи». Ворота так любят в Германии, что их рисовали на открытках и даже на деньгах. Входишь в город — будто в сказочную крепость.", "q": "Сколько башен у ворот Хольстентор?", "a": [ "Две круглые башни", "Одна квадратная", "Пять острых башен" ] }, { "id": "de-n-strandkorb", "e": "🏖️", "t": "Пляжная корзина", "s": "На берегах северных морей Германии стоят смешные плетёные кресла с крышей — страндкорбы. В них прячутся от ветра и песка: сидишь, как в маленьком домике, и смотришь на волны. Придумал их корзинных дел мастер из города Ростока больше ста сорока лет назад. Теперь они стоят на пляже рядами, и у каждой корзины свой номер, чтобы не перепутать, где чья.", "q": "Для чего нужна пляжная корзина — страндкорб?", "a": [ "Чтобы прятаться от ветра и песка", "Чтобы ловить рыбу", "Чтобы возить камни" ] }, { "id": "de-n-schwerin", "e": "🏯", "t": "Замок на острове", "s": "В городе Шверине замок стоит прямо на острове посреди озера. К нему ведёт мостик, а вокруг блестит вода. У замка башенки, зубцы и золотой купол, и всё это отражается в озере, как в зеркале. Когда-то тут жили герцоги, а теперь в замке работают депутаты земли и открыт музей. Идёшь по мостику и чувствуешь себя гостем из сказки про принцев.", "q": "Где стоит замок в Шверине?", "a": [ "На острове посреди озера", "На вершине горы", "В глубокой пещере" ] }, { "id": "de-n-ruegen", "e": "⛰️", "t": "Белые скалы Рюгена", "s": "Рюген — самый большой остров Германии, он лежит в Балтийском море. Больше всего он знаменит меловыми скалами. Они белые, как сахар, и высоко поднимаются над водой, а наверху шумит зелёный буковый лес. Самая высокая скала зовётся Кёнигсштуль — «королевский трон». Если смотреть с моря, белая стена, зелёные кроны и синяя вода кажутся нарисованными яркими красками.", "q": "Какого цвета скалы на острове Рюген?", "a": [ "Белые, меловые", "Красные, как кирпич", "Чёрные, вулканические" ] }, { "id": "de-n-watt", "e": "🦭", "t": "Дно, которое уходит", "s": "У берегов Северного моря вода два раза в сутки уходит далеко-далеко. Это отлив. Остаётся мокрое дно — ватты, и по нему можно гулять пешком в резиновых сапогах. Под ногами песок, ракушки и маленькие червячки, а на отмелях лежат тюлени. Потом вода возвращается — это прилив. Поэтому по дну гуляют только со взрослым проводником, который знает время приливов.", "q": "Что происходит с водой на севере Германии два раза в сутки?", "a": [ "Отлив и прилив", "Она замерзает и тает", "Она становится зелёной" ] }, { "id": "de-n-kiel", "e": "🚢", "t": "Корабли среди полей", "s": "В городе Киле начинается Кильский канал. Он соединяет Северное и Балтийское моря и тянется почти на сто километров. Идёшь по берегу и вдруг видишь: за зелёными лугами с коровами плывёт огромный корабль! Кажется, что он едет прямо по траве. Канал построили, чтобы кораблям не пришлось долго плыть вокруг Дании. Это один из самых оживлённых искусственных морских каналов в мире.", "q": "Какие два моря соединяет Кильский канал?", "a": [ "Северное и Балтийское", "Чёрное и Средиземное", "Красное и Жёлтое" ] }, { "id": "de-n-leibniz", "e": "🍪", "t": "Печенье с 52 зубчиками", "s": "В городе Ганновере в 1891 году придумали печенье, которое знают во всей Германии. Оно прямоугольное, золотистое и хрустящее, а по краям у него ровно 52 зубчика. Называется оно «Лейбниц» — в честь учёного, который давно жил в Ганновере. Печенье продают в коробках по всему миру. Попробуй сосчитать зубчики: говорят, их столько же, сколько недель в году.", "q": "Сколько зубчиков у печенья «Лейбниц»?", "a": [ "52", "12", "100" ] }, { "id": "de-n-goose", "e": "🦢", "t": "Гусятница из Гёттингена", "s": "В Гёттингене перед старой ратушей стоит фонтан с маленькой девочкой, а рядом с ней — гуси. Её зовут Гусятница. В Германии шутят, что она самая целованная девушка на свете: когда студент заканчивает учёбу и получает высшее учёное звание, он поднимается к фонтану, целует бронзовую девочку в щёку и дарит ей цветы. Поэтому в фонтане часто лежат букеты.", "q": "Кто стоит рядом с девочкой у фонтана в Гёттингене?", "a": [ "Гуси", "Овечки", "Котята" ] }, { "id": "de-n-hameln", "e": "🐀", "t": "Крысолов из Хамельна", "s": "В городе Хамельне живёт старая легенда. Много веков назад по улицам бегало слишком много крыс. Пришёл музыкант в пёстрой одежде, заиграл на дудочке, и крысы потянулись за ним прочь из города. Эту легенду записали и братья Гримм, и теперь Хамельн знают все дети Германии. Летом на улицах играют спектакли про Крысолова, а на витринах сидят игрушечные крысы.", "q": "На чём играл музыкант из легенды о Хамельне?", "a": [ "На дудочке", "На барабане", "На скрипке" ] }, { "id": "de-n-brocken", "e": "👻", "t": "Тень-великан на Броккене", "s": "Горы Гарц — самые высокие на севере Германии, а главная вершина там — Броккен. На неё поднимается старый паровозик: пыхтит, пускает пар и тащит вагончики вверх. На Броккене часто стоят туманы. Если солнце светит за спиной, на тумане вдруг появляется огромная тень человека, а вокруг неё радужный круг. Это твоя собственная тень! Её называют «броккенским призраком». Бояться нечего, это просто игра света.", "q": "Чья тень появляется в тумане на Броккене?", "a": [ "Твоя собственная", "Горного лешего", "Большого медведя" ] }, { "id": "de-n-goslar", "e": "⛏️", "t": "Шахта в Госларе", "s": "Возле города Гослара есть шахта Раммельсберг. В ней много столетий добывали руду: из неё получали серебро, медь и свинец. Шахта работала почти тысячу лет и закрылась только в 1988 году. Теперь это музей. Туристы надевают каски, едут на поезде под землёй и видят старые туннели и инструменты горняков. Старый город Гослар и шахта записаны во всемирное наследие ЮНЕСКО.", "q": "Что надевают туристы, когда идут в шахту?", "a": [ "Каски", "Скафандры", "Ласты" ] }, { "id": "de-n-phaeno", "e": "🔬", "t": "Музей опытов Фэно", "s": "В городе Вольфсбурге есть музей Фэно, где почти всё можно потрогать руками. Здание необычное: оно стоит на огромных бетонных «ногах», а внутри нет привычных прямых стен. Здесь сотни опытов: можно увидеть огненный смерч, покрутить колёса, посмотреть в хитрые зеркала и проверить, как работают свет и ветер. Здание придумала архитектор Заха Хадид. Дети уходят домой с кучей вопросов и идей.", "q": "Что можно делать в музее Фэно?", "a": [ "Трогать руками и делать опыты", "Только смотреть на картины", "Только слушать лекции" ] }, { "id": "de-n-kale", "e": "🥬", "t": "Поход за капустой", "s": "Зимой на севере Германии, особенно возле Ольденбурга, любят тёмно-зелёную кудрявую капусту — грюнколь. Её тушат с колбасками и картошкой. А ещё в холодные дни компании устраивают «капустный поход»: гуляют по полям и лесам, играют в весёлые игры, возят за собой тележку, а потом все садятся за стол. В конце выбирают «капустного короля» или «королеву». Вот такая вкусная прогулка!", "q": "Кого выбирают в конце «капустного похода»?", "a": [ "Капустного короля или королеву", "Самого быстрого бегуна", "Лучшего певца" ] }, { "id": "de-n-tee", "e": "🍵", "t": "Чай по-фризски", "s": "В Восточной Фризии, на северо-западе Германии, пьют больше чая, чем почти где-либо на свете. Говорят, каждый житель выпивает около трёхсот литров чая в год! Пьют его так: в чашку кладут большой кусок белого сахара — клунтье, наливают горячий чай, и сахар тихонько потрескивает. Потом по краю льют сливки, и в чашке плывёт маленькое облачко. Мешать не надо. Когда напился, ложечку оставляют в чашке.", "q": "Что делают в Восточной Фризии, когда больше не хотят чая?", "a": [ "Оставляют ложечку в чашке", "Переворачивают чашку", "Ставят чашку на голову" ] }, { "id": "de-n-ozeaneum", "e": "🐟", "t": "Озеанеум в Штральзунде", "s": "В городе Штральзунде, на берегу Балтийского моря, стоит огромный аквариум — Озеанеум. Там можно увидеть, кто живёт в северных морях: проплывают стаи сельди, медленно плавают медузы. В большом зале под потолком висят модели китов — настоящего размера, как будто они плывут над твоей головой. А ещё там есть пингвины. День пролетает как один час.", "q": "Что висит под потолком большого зала Озеанеума?", "a": [ "Модели китов", "Люстры из ракушек", "Настоящие лодки" ] }, { "id": "de-n-storch", "e": "🐦", "t": "Аисты на крыше", "s": "В северной и восточной Германии на крышах и столбах видны большие гнёзда из веток. В них живут белые аисты. Весной они прилетают из далёкой Африки, чинят своё гнездо и выводят птенцов. Одно гнездо птицы могут использовать много лет и каждую весну достраивать, так что оно становится огромным. В деревнях говорят: если аист поселился на твоём доме, это к счастью. А ещё взрослые шутят, что аист приносит малышей.", "q": "Откуда весной прилетают аисты?", "a": [ "Из Африки", "С Северного полюса", "С Луны" ] }, { "id": "de-s-zugspitze", "e": "🏔️", "t": "Цугшпитце", "s": "Самая высокая гора Германии называется Цугшпитце. Она в Альпах, её вершина поднимается почти на три тысячи метров. Наверх можно доехать на зубчатой железной дороге, а можно подняться на канатной дороге в кабинке. На самой вершине проходит граница с Австрией: одной ногой ты в Германии, а другой — уже в другой стране. Там, наверху, даже летом лежит снег, а ещё есть маленькая церковь.", "q": "Какая гора самая высокая в Германии?", "a": [ "Цугшпитце", "Фудзияма", "Эльбрус" ] }, { "id": "de-s-koenigssee", "e": "🚣", "t": "Королевское озеро", "s": "В Баварских Альпах лежит Кёнигсзее — Королевское озеро. Вода в нём чистая и зелёная, а горы вокруг стоят как стены. Чтобы не пугать природу, по озеру ходят только лодки на электричестве, без шума и дыма. На середине пути лодочник достаёт трубу и играет. Горы отвечают эхом, и кажется, что в скалах прячется целый оркестр. На берегу стоит церковь с красными луковками куполов.", "q": "Какие лодки плавают по Королевскому озеру?", "a": [ "Электрические", "Парусные с мотором", "Надувные с вёслами из бумаги" ] }, { "id": "de-s-berchtesgaden-salt", "e": "🧂", "t": "Соляная шахта в Берхтесгадене", "s": "Рядом с городом Берхтесгаден люди давно добывают соль прямо из горы. Туда пускают и гостей. Всем выдают тёмную рабочую одежду шахтёров, и взрослые с детьми становятся похожи на весёлых гномов. Потом поезд-малышка везёт всех в тёмный тоннель, а вниз ведут деревянные горки: садишься и съезжаешь, как с горки во дворе, только внутри горы. А в глубине есть подземное озеро с солёной водой.", "q": "Что добывают в шахте возле Берхтесгадена?", "a": [ "Соль", "Золото", "Уголь для печки" ] }, { "id": "de-s-linderhof", "e": "🦚", "t": "Дворец Линдерхоф", "s": "Король Людвиг Второй любил строить замки, и один из них — Линдерхоф — совсем небольшой и уютный. Он спрятан среди гор и леса. Рядом с дворцом бьёт фонтан: струя взлетает высоко, как многоэтажный дом. А в скале устроена пещера с озером. Там плавала лодка в виде золотой раковины, а стены подсвечивали разноцветными огнями. Король хотел, чтобы всё было как в сказке, и у него получилось.", "q": "Что устроил король Людвиг рядом с дворцом Линдерхоф?", "a": [ "Пещеру с озером и лодкой-раковиной", "Каток из соли", "Зоопарк с жирафами" ] }, { "id": "de-s-mainau", "e": "🌴", "t": "Остров цветов Майнау", "s": "На Боденском озере есть остров Майнау, и его зовут островом цветов. Там зимой теплее, чем на берегу, поэтому растут пальмы и апельсиновые деревья в кадках. Весной цветут миллионы тюльпанов, а летом — розы и георгины. Есть даже дом бабочек: ты заходишь, а вокруг порхают сотни разноцветных крыльев, и одна может сесть тебе на рукав. На остров можно приехать по мосту или приплыть на кораблике.", "q": "Как называют остров Майнау?", "a": [ "Остров цветов", "Остров ёжиков", "Остров мороженого" ] }, { "id": "de-s-zeppelin", "e": "🎈", "t": "Цеппелины над Боденским озером", "s": "Город Фридрихсхафен на Боденском озере — родина цеппелинов. Так называют огромные воздушные корабли, похожие на длинную сигару. Их придумал граф Цеппелин, и первый его корабль поднялся над озером больше ста двадцати лет назад. Теперь в городе есть музей цеппелинов. А ещё над озером и сегодня летают современные цеппелины с пассажирами. Они плывут тихо и медленно, и из окон видно воду, лодки и далёкие горы.", "q": "Что такое цеппелин?", "a": [ "Большой воздушный корабль", "Колокольня на озере", "Рыба из Боденского озера" ] }, { "id": "de-s-black-forest-cake", "e": "🍒", "t": "Шварцвальдский торт", "s": "Шварцвальд — это Чёрный лес: ёлки там растут так густо, что в чаще темно даже днём. Отсюда пошёл знаменитый торт. Его слои — тёмный шоколадный бисквит, взбитые сливки и спелая вишня. Сверху торт посыпают шоколадной стружкой и кладут красные вишенки. Получается, будто на белом снегу под чёрными ёлками лежат ягоды. Торт так и называют: «Шварцвальдская вишня».", "q": "Какая ягода лежит на шварцвальдском торте?", "a": [ "Вишня", "Малина из тундры", "Арбуз" ] }, { "id": "de-s-freiburg-baechle", "e": "💧", "t": "Ручейки Фрайбурга", "s": "В старом городе Фрайбурге вдоль мостовой бегут узкие ручейки. По-немецки они называются «бэхле». Раньше в них брали воду, а сегодня по ним пускают бумажные кораблики. У горожан есть весёлая примета: кто нечаянно наступит в ручеёк, тот станет фрайбуржцем или выйдет замуж за фрайбуржца. Поэтому приезжие смотрят под ноги и всё равно иногда мочат ботинки.", "q": "Что течёт по улицам старого Фрайбурга?", "a": [ "Маленькие ручейки", "Тёплое молоко", "Лавовые реки" ] }, { "id": "de-s-rothenburg", "e": "🏰", "t": "Ротенбург и городская стена", "s": "Ротенбург-об-дер-Таубер выглядит как город из книжки сказок. Дома там разноцветные, с острыми крышами, а улицы вымощены камнем. Вокруг города стоит старая каменная стена, и по ней можно пройтись наверху, как стражник: на одну сторону видны крыши, на другую — поля. А на одном перекрёстке есть узкий жёлтый дом и две башни рядом — туристы всегда фотографируются именно там.", "q": "Что можно делать на старой стене Ротенбурга?", "a": [ "Гулять по ней поверху", "Кататься на коньках", "Сажать картошку" ] }, { "id": "de-s-bamberg", "e": "🧚", "t": "Ратуша на мосту в Бамберге", "s": "В Бамберге ратуша построена прямо посреди реки, на маленьком острове. К ней ведут два моста, и здание кажется кораблём. Стены расписаны картинами, а на одной нарисован ангелочек, у которого нога торчит наружу: она сделана объёмной и выступает из стены. Если прищуриться, можно подумать, что малыш вылезает из картины. Дети любят искать эту ногу.", "q": "Где стоит старая ратуша Бамберга?", "a": [ "На острове посреди реки", "На вершине горы", "В пещере" ] }, { "id": "de-s-regensburg-bridge", "e": "🌉", "t": "Каменный мост Регенсбурга", "s": "В Регенсбурге через реку Дунай перекинут каменный мост, которому больше восьмисот лет. Его построили в двенадцатом веке, и он до сих пор целый. Мост держится на шестнадцати арках, а ходят по нему и сегодня, только машинам туда нельзя. Люди говорят, что он был одним из чудес своего времени. Прогуляйся — и пройдёшь по дороге, по которой гуляли люди сотни лет назад.", "q": "Сколько лет каменному мосту в Регенсбурге?", "a": [ "Больше восьмисот", "Три года", "Всего двадцать" ] }, { "id": "de-s-fuggerei", "e": "🏘️", "t": "Фуггерай — город в городе", "s": "В Аугсбурге есть маленький жилой квартал, который называется Фуггерай. Его построили больше пятисот лет назад для жителей, которым нужна была помощь. Это самый старый в мире квартал такого рода, он действует до сих пор. Плата за дом там почти не изменилась: за год платят меньше одного евро. Только просят каждый день помолиться за тех, кто построил квартал. В Фуггерае есть свои ворота, церковь и улицы.", "q": "Сколько стоит год жизни в Фуггерае?", "a": [ "Меньше одного евро", "Тысячу золотых монет", "Целый чемодан яблок" ] }, { "id": "de-s-aachen-karl", "e": "👑", "t": "Карл Великий в Ахене", "s": "Больше тысячи лет назад в городе Ахене жил император Карл Великий. Ему нравился этот город, потому что там из-под земли бьют тёплые источники. Император любил купаться в них и звал друзей поплавать вместе. Он построил в Ахене красивую капеллу, и она стоит до сих пор. В ней хранится его каменный трон. А горячие источники в городе есть и сейчас — их можно увидеть и даже потрогать воду.", "q": "Почему Карлу Великому нравился Ахен?", "a": [ "Там были тёплые источники", "Там круглый год снег", "Там жили его драконы" ] }, { "id": "de-s-trier-porta-nigra", "e": "🚪", "t": "Чёрные ворота Трира", "s": "Город Трир основали римляне, и до сих пор там стоят римские ворота — Порта Нигра, то есть «Чёрные ворота». Они такие огромные, что рядом люди кажутся муравьями. Их построили почти две тысячи лет назад из тяжёлых каменных блоков, а скреплены блоки железными скобами. Раньше камень был светлым, но за много веков потемнел. Отсюда и название. Сегодня можно подняться наверх и посмотреть на город из окон ворот.", "q": "Почему ворота Трира называют чёрными?", "a": [ "Камень потемнел от времени", "Их покрасили сажей", "Они сделаны из угля" ] }, { "id": "de-s-ruhr-park", "e": "🏭", "t": "Рур: завод стал парком", "s": "В Рурской области раньше было много заводов и шахт. Потом многие из них закрылись, но их не стали ломать. В городе Дуйсбурге старый металлический завод превратили в парк. Огромные трубы подсвечивают по вечерам разными цветами. В старых бетонных бункерах устроили площадки для скалолазания, а в бывшем газгольдере, огромном железном баке, ныряют с аквалангом. Вот как удивительно можно подарить старому месту новую жизнь.", "q": "Что устроили в старом металлическом заводе в Дуйсбурге?", "a": [ "Парк со скалодромом", "Птичий базар", "Огород для динозавров" ] }, { "id": "de-s-stuttgart-horse", "e": "🐴", "t": "Конь на гербе Штутгарта", "s": "Название Штутгарт придумали давно, и в нём прячется слово «Stuten» — так называют кобыл. Когда-то на этом месте был сад, где пасли лошадей. Поэтому конь живёт на гербе Штутгарта до сих пор. Он чёрный, стоит на задних ногах на жёлтом щите. Современный Штутгарт любят за автомобили: здесь делают «Мерседес» и «Порше», и в городе есть музеи, где стоят самые старые машины.", "q": "Какое животное нарисовано на гербе Штутгарта?", "a": [ "Конь", "Верблюд", "Пингвин" ] }, { "id": "de-s-ulm-minster", "e": "🔔", "t": "Самая высокая колокольня в мире", "s": "В городе Ульме стоит собор с колокольней выше ста шестидесяти метров. Она считается самой высокой церковной колокольней в мире. Чтобы подняться на смотровую площадку, нужно одолеть почти семьсот восемьдесят ступенек. Зато оттуда видно весь город, реку Дунай, а в ясную погоду — даже далёкие Альпы. Ульм — родной город учёного Альберта Эйнштейна, но он родился там совсем малышом и вскоре уехал.", "q": "Чем знаменит собор в Ульме?", "a": [ "Самой высокой колокольней", "Кукушкой в часах", "Хрустальной крышей" ] }, { "id": "de-p-thomaner", "e": "🎶", "t": "Хор мальчиков в Томаскирхе", "s": "В Лейпциге стоит церковь Святого Фомы — Томаскирхе. При ней живёт хор мальчиков, которому больше восьмисот лет. Мальчишки учатся в особой школе, много поют и ездят по свету с концертами. Когда-то хором руководил Бах, и сегодня его музыку здесь поют каждую неделю. А ещё в церкви есть памятная плита с его именем. Представь: те же стены, та же музыка, а голоса всё новые и новые.", "q": "Кто поёт в лейпцигском Томаскирхе уже больше восьмисот лет?", "a": [ "Хор мальчиков", "Хор бабушек", "Хор лягушек" ] }, { "id": "de-p-mendelson", "e": "🎼", "t": "Мендельсон и летняя ночь", "s": "Феликс Мендельсон был вундеркиндом. Ему было всего семнадцать, когда он прочитал пьесу Шекспира про лес, эльфов и волшебный сон — и написал к ней музыку. В ней слышно, как порхают лёгкие феи и кричит упрямый осёл. Потом Мендельсон поселился в Лейпциге и открыл там школу музыки, которая работает до сих пор. Музыка получилась такой весёлой, что её до сих пор играют на праздниках.", "q": "Сколько лет было Мендельсону, когда он написал музыку к «Сну в летнюю ночь»?", "a": [ "Семнадцать", "Семьдесят", "Три года" ] }, { "id": "de-p-gete-kamni", "e": "🪨", "t": "Гёте и камни", "s": "Иоганн Вольфганг Гёте жил в Веймаре и писал стихи, пьесы и сказки. Но его любимым занятием было собирать камни. Он привозил их из поездок, обменивался ими с друзьями и раскладывал по ящичкам в своём доме. Камней набрались тысячи! Гёте разглядывал их, как другие читают книги, и придумывал, как они появились. Его дом в Веймаре можно посмотреть до сих пор, там осталась и часть коллекции.", "q": "Что любил собирать поэт Гёте?", "a": [ "Камни", "Фантики", "Наклейки с машинками" ] }, { "id": "de-p-vartburg", "e": "🏰", "t": "Вартбург: тайный переводчик", "s": "Высоко над городом Эйзенах стоит замок Вартбург. Давным-давно там спрятался учёный Мартин Лютер. Он отрастил бороду, надел плащ и называл себя «юнкер Йорг», чтобы никто не узнал. В тихой комнате он взялся переводить Новый Завет на немецкий, чтобы любой человек мог прочитать его сам. Теперь эту комнату показывают гостям: простой стол, печка и маленькое окошко.", "q": "Под каким именем жил в Вартбурге Лютер?", "a": [ "Юнкер Йорг", "Барон Карл", "Рыцарь Ганс" ] }, { "id": "de-p-sanssouci", "e": "🥔", "t": "Сан-Суси и картошка", "s": "В Потсдаме стоит дворец с французским названием Сан-Суси — «без забот». Его построили для короля Фридриха Второго, который любил музыку, собак и флейту. Перед дворцом растут виноградные террасы. Фридрих хотел, чтобы в Пруссии выращивали картошку, и убеждал в этом крестьян. Поэтому на его могиле возле дворца до сих пор лежат клубни. Посетители кладут их в знак благодарности.", "q": "Что лежит на могиле короля Фридриха у дворца Сан-Суси?", "a": [ "Картошка", "Конфеты", "Шишки" ] }, { "id": "de-p-cwinger", "e": "🖼️", "t": "Цвингер и ангелочки", "s": "В Дрездене есть большой нарядный двор — Цвингер. Король Август Сильный построил его для праздников, а теперь здесь музеи. В одном из них висит картина Рафаэля «Сикстинская мадонна». Внизу на ней двое маленьких ангелов опираются на рамку и задумчиво смотрят вверх. Их так полюбили, что теперь они нарисованы на открытках, чашках и даже на конфетных коробках.", "q": "Кто задумчиво смотрит вверх на картине в дрезденском Цвингере?", "a": [ "Два маленьких ангела", "Два кота", "Два рыцаря" ] }, { "id": "de-p-bastei", "e": "⛰️", "t": "Саксонская Швейцария", "s": "Возле Дрездена есть горы, которые называются Саксонская Швейцария. Название придумали два художника из настоящей Швейцарии: они приехали в Дрезден и увидели скалы, похожие на родные. Самые известные из них — Бастай, там над пропастью лежит каменный мост. Скалы из песчаника торчат из леса, как огромные башни. По ним гуляют туристы, а по реке внизу плывут пароходики.", "q": "Откуда были художники, назвавшие горы возле Дрездена Швейцарией?", "a": [ "Из Швейцарии", "Из Африки", "Из Японии" ] }, { "id": "de-p-munhgauzen", "e": "🎩", "t": "Настоящий Мюнхгаузен", "s": "Барон Мюнхгаузен жил на самом деле! Его звали Карл Фридрих Иероним, а жил он в городке Боденвердер. Барон был мастером рассказывать невероятные истории — гостям очень нравилось его слушать. Потом писатели записали эти небылицы в книгу, и барон стал героем сказки: про коня, разрезанного пополам, и про то, как он вытащил сам себя из болота за волосы. В Боденвердере ему стоят памятники, а в бывшем доме барона музей.", "q": "Где жил настоящий барон Мюнхгаузен?", "a": [ "В городке Боденвердер", "В Берлине", "В Гамбурге" ] }, { "id": "de-p-rentgen", "e": "🦴", "t": "Рентген и невидимые лучи", "s": "Однажды вечером физик Вильгельм Рентген заметил в тёмной комнате, что экран светится, хотя рядом нет света. Значит, существуют невидимые лучи! Он не знал, что это такое, и назвал их «икс-лучами». Потом он сделал первый снимок — руку своей жены с кольцом, где были видны косточки. Теперь такие снимки делают врачи, и в Германии их зовут рентгеновскими.", "q": "Как Рентген назвал неизвестные лучи?", "a": [ "Икс-лучи", "Лучи Солнца", "Лучи ночи" ] }, { "id": "de-p-lilientaly", "e": "🪂", "t": "Лилиенталь и аисты", "s": "Отто Лилиенталь смотрел на аистов и мечтал летать. Он изучал, как птицы держат крылья, и сделал крылья из ивовых прутьев и ткани. Рядом с Берлином он насыпал холм, разбегался с него против ветра и парил по воздуху. Так он совершил около двух тысяч полётов. Газеты печатали его снимки, и люди во многих странах узнали, что человек может планировать, как птица.", "q": "За какими птицами наблюдал Лилиенталь?", "a": [ "За аистами", "За пингвинами", "За страусами" ] }, { "id": "de-p-cuze", "e": "💻", "t": "Конрад Цузе и первая машина", "s": "Молодой инженер Конрад Цузе не любил долго считать, и решил, что машина должна считать за него. Он построил её из тонких металлических пластинок прямо в гостиной у родителей в Берлине. Его машины называли Z1, Z2, Z3, а Z3 умела работать по программе. Так появились первые настоящие компьютеры. Цузе ещё и рисовал картины: он любил искусство не меньше чисел.", "q": "Где Цузе собрал свою первую счётную машину?", "a": [ "В гостиной у родителей", "На космодроме", "В магазине игрушек" ] }, { "id": "de-p-gumboldt", "e": "🌋", "t": "Гумбольдт и вулкан", "s": "Александр фон Гумбольдт родился в Берлине, а отправился исследовать самые далёкие места: джунгли, реки и горы Южной Америки. Он взбирался на вулкан Чимборасо почти до самой вершины. Гумбольдт заметил, что растения на склонах меняются по высоте: внизу пальмы, выше — трава, а на самом верху — мох. В его честь назвали горы, реки и даже пингвина, который живёт у берегов Южной Америки.", "q": "Кого назвали в честь Гумбольдта?", "a": [ "Пингвина", "Бабочку-капустницу", "Домашнего хомячка" ] }, { "id": "de-p-shuman", "e": "🎹", "t": "Шуман пишет про детей", "s": "Композитор Роберт Шуман родился в Саксонии, в городе Цвиккау. Он сочинил альбом «Детские сцены» — тринадцать коротких пьес о том, как ребёнок играет, засыпает или мечтает. Среди них — «Грёзы», нежная мелодия, которую до сих пор играют на пианино. Шуман писал её не для малышей, а для взрослых, чтобы они вспомнили, как сами были детьми.", "q": "О ком Шуман написал «Детские сцены»?", "a": [ "О детях", "О слонах", "О поварах" ] }, { "id": "de-p-gendel", "e": "⛵", "t": "Гендель и музыка на воде", "s": "Георг Фридрих Гендель родился в городе Галле, в один год с Бахом, но потом уехал в Англию. Однажды король Георг плыл по Темзе на нарядной барже, а за ним плыли лодки с музыкантами. Для этой прогулки Гендель сочинил «Музыку на воде». Играли её, говорят, прямо на реке. Мелодии так понравились королю, что он просил повторить их ещё раз.", "q": "Для какой прогулки Гендель сочинил «Музыку на воде»?", "a": [ "Для плавания по Темзе", "Для поездки на санях", "Для полёта на шаре" ] }, { "id": "de-p-meyssen", "e": "🍵", "t": "Мейсенский фарфор", "s": "Когда-то в Европе не умели делать фарфор: его привозили издалека, и он стоил очень дорого. Король Август Сильный велел алхимику Бёттгеру искать способ. Бёттгер мечтал сделать золото, а вместо него получил белую звонкую посуду. Её стали делать в городе Мейсен возле Дрездена. На чашках рисуют два скрещённых синих меча — по ним узнают настоящий мейсенский фарфор.", "q": "Что нарисовано на мейсенском фарфоре как знак?", "a": [ "Два синих меча", "Красное сердце", "Жёлтая птичка" ] }, { "id": "de-p-erzgebirge", "e": "🎄", "t": "Рождественская пирамида", "s": "В горах Рудных, которые по-немецки зовутся Эрцгебирге, зимой делают игрушки из дерева. Здесь родились щелкунчики и ангелы со свечками. А ещё — рождественские пирамиды: на их этажах стоят деревянные фигурки, а сверху вертится пропеллер. Пропеллер вертится от тепла свечей: пламя греет воздух, и тот толкает лопасти, а вместе с ними фигурки идут по кругу.", "q": "Что заставляет вертеться пропеллер рождественской пирамиды?", "a": [ "Тепло свечей", "Батарейка", "Ветер из окна" ] }, { "id": "de-p-shpreevald", "e": "🛶", "t": "Шпреевальд: лодки вместо дорог", "s": "К юго-востоку от Берлина река Шпрее распадается на сотни маленьких речек и каналов. Это Шпреевальд — лесной край, где дома стоят на островках. Раньше туда нельзя было добраться на машине. Люди ездили по каналам на длинных плоскодонных лодках, и почтальон тоже плыл на лодке. Здесь выращивают хрустящие огурцы, и их продают по всей Германии. Здесь даже малыши умеют грести.", "q": "На чём в Шпреевальде возят людей и почту?", "a": [ "На лодках", "На верблюдах", "На самокатах" ] }, { "id": "de-p-dizel", "e": "⚙️", "t": "Дизель и арахисовое масло", "s": "Инженер Рудольф Дизель придумал новый двигатель, который сейчас называют его именем. Он хотел, чтобы двигатель был экономным и мог работать на разном топливе. На большой выставке в Париже его показали публике, и он ехал на арахисовом масле! Позже такие двигатели поставили на корабли и грузовики. Дизель родился в Париже, но его родители были из Германии, а учился он в Мюнхене.", "q": "На каком масле работал двигатель Дизеля на выставке?", "a": [ "На арахисовом", "На оливковом", "На сливочном" ] }, { "id": "de-f-sababurg", "e": "🌹", "t": "Замок Спящей красавицы", "s": "В Германии есть настоящий замок Спящей красавицы. Он называется Забабург и стоит в густом лесу Рейнхардсвальд, недалеко от города Кассель. Говорят, сказку братьев Гримм связывают именно с ним. Вокруг замка растут розы, как в сказке про шиповник, который скрыл дворец. Сегодня в старых стенах можно переночевать: там гостиница. А в саду гуляют гости и ищут розы.", "q": "Как называется замок Спящей красавицы в немецком лесу?", "a": [ "Забабург", "Нойшванштайн", "Версаль" ] }, { "id": "de-f-rapunzel-salat", "e": "🥬", "t": "Рапунцель — это салат", "s": "Знаешь, откуда у девочки с длинными косами имя Рапунцель? В сказке братьев Гримм её маме очень захотелось съесть травку из соседнего сада. Эту травку и называют «рапунцель». Так девочку и назвали. В Германии так до сих пор зовут полевой салат: у него маленькие мягкие листики. Выходит, героиню сказки назвали в честь зелени для салата, а не в честь красивого цветка.", "q": "В честь чего назвали Рапунцель в сказке?", "a": [ "В честь зелёной травки, которую хотела мама", "В честь башни", "В честь птицы в лесу" ] }, { "id": "de-f-gnomy-snow", "e": "⛏️", "t": "Семь гномов без имён", "s": "У семи гномов из сказки про Белоснежку есть смешные имена: Весельчак, Соня, Ворчун… Но в сказке братьев Гримм у них вообще нет имён! Там просто «семь гномов за семью горами». Они работают в горе и добывают руду. Имена придумали позже, для мультфильма. А вот Белоснежку в немецком оригинале зовут Шнеевиттхен. Это значит «беленькая, как снег».", "q": "Были ли имена у семи гномов в сказке братьев Гримм?", "a": [ "Нет, имена придумали позже", "Да, их звали Весельчак и Соня", "Да, их звали Ганс и Фриц" ] }, { "id": "de-f-rumpelshtilzhen", "e": "🔥", "t": "Как угадали имя Румпельштильцхена", "s": "В сказке про Румпельштильцхена маленький человечек прял солому в золото. Взамен он хотел ребёнка, но согласился подождать: пусть королева угадает его имя. Она называла Каспар, Мельхиор, Бальтазар. Но человечек говорил: «Нет!» Потом слуга увидел его в лесу. Человечек прыгал у костра и пел своё имя. Королева его узнала и всё закончилось хорошо. Имя означает «маленький шумный домовой».", "q": "Что просил у королевы человечек, чтобы оставить ей ребёнка?", "a": [ "Угадать его имя", "Дать ему мешок орехов", "Спеть песню" ] }, { "id": "de-f-aschenputtel", "e": "🌰", "t": "Золушка и орешник", "s": "В немецкой сказке про Золушку нет доброй феи. Золушку по-немецки зовут Ашенпуттель. Платья ей дарит деревце орешник на могиле мамы. Золушка посадила веточку и поливала её слезами. Дерево выросло, а на нём жила белая птичка. Голуби и горлицы помогли разобрать чечевицу из золы. А в декабре немцы смотрят старый фильм «Три орешка для Золушки», его показывают каждый год.", "q": "Кто подарил Золушке платья в сказке братьев Гримм?", "a": [ "Птичка с дерева орешника", "Добрая фея", "Принц" ] }, { "id": "de-f-skazochnaya-doroga", "e": "🗺️", "t": "Сказочная дорога", "s": "В Германии есть дорога для туристов, которая называется Сказочная. Она идёт от города Ханау, где родились братья Гримм, до города Бремен. Это больше шестисот километров. На пути лежат города из сказок: Кассель, где хранят их рукописи, Хамельн с Крысоловом и Бремен с музыкантами. В городах стоят памятники, а в кукольных театрах играют сказки.", "q": "Где родились братья Гримм?", "a": [ "В городе Ханау", "В Берлине", "В Мюнхене" ] }, { "id": "de-f-khleb", "e": "🍞", "t": "Три тысячи сортов хлеба", "s": "Немцы считают себя главными хлебными мастерами. В пекарнях Германии больше трёх тысяч сортов хлеба: чёрный, с семечками, с тмином, с орехами. Даже булочки в разных местах называют по-разному: в одном городе «шриппе», в другом «земмель», в третьем «веке». Люди из разных земель спорят, как правильно. Есть даже музей хлеба в городе Ульм. Хлеб здесь хорошо пахнет и очень вкусный.", "q": "Сколько сортов хлеба в Германии?", "a": [ "Больше трёх тысяч", "Всего три", "Около десяти" ] }, { "id": "de-f-karrivurst", "e": "🌭", "t": "Карривурст из Берлина", "s": "Карривурст — это жареная колбаска, которую режут на кусочки и поливают красным соусом с карри. В Германии её очень любят, а изобрели в Берлине. В 1949 году продавщица Герта Хойвер открыла маленький киоск. Она смешала томатный соус с карри, полила им колбаску, и берлинцы выстроились в очередь. Колбаску едят с картошкой фри, прямо стоя у киоска, и берут вилочку.", "q": "В каком городе придумали карривурст?", "a": [ "В Берлине", "В Париже", "В Лондоне" ] }, { "id": "de-f-baumkukhen", "e": "🎂", "t": "Пирог-дерево", "s": "Баумкухен по-немецки значит «пирог-дерево». Его пекут очень необычно. Тонкий слой теста наливают на вращающийся вал над жаром, и он золотится. Потом льют следующий, и так много раз. Когда пирог режут, внутри видны кольца, как на спиле дерева. Самый известный баумкухен делают в городе Зальцведель. Его обычно покрывают глазурью или шоколадом и едят на праздники.", "q": "Что видно внутри разрезанного баумкухена?", "a": [ "Кольца, как на спиле дерева", "Звёздочки", "Зубчики, как у шестерёнки" ] }, { "id": "de-f-haribo", "e": "🧸", "t": "Мармеладные мишки Харибо", "s": "Название Харибо — это секретный код. Мастер Ханс Ригель жил в городе Бонн и открыл там в 1920 году фабрику сладостей. Взял первые две буквы своего имени и фамилии и название города: ХАнс, РИгель, БОнн. Получилось ХАРИБО. Через два года он сварил первых мармеладных медвежат. Их называли «танцующий медведь»: в то время на ярмарках часто показывали танцующих медведей.", "q": "Откуда взялось слово Харибо?", "a": [ "Из имени мастера и названия города", "От названия медового цветка", "От слова «хорошо»" ] }, { "id": "de-f-advent", "e": "🕯️", "t": "Календарь ожидания", "s": "Адвент-календарь придумали в Германии. Это календарь, в котором ждут Рождество, а в каждом окошке сюрприз. Раньше дети просто рисовали мелом чёрточки на двери, по одной в день. Потом в Мюнхене напечатали календарь с двадцатью четырьмя картинками. Теперь в окошках лежат шоколадки, маленькие игрушки или стишки. Каждое утро в декабре ребёнок открывает одно окошко, и до чуда становится на день ближе.", "q": "Сколько окошек в адвент-календаре?", "a": [ "Двадцать четыре", "Семь", "Сто" ] }, { "id": "de-f-martin", "e": "🏮", "t": "Мартинов день и фонарики", "s": "Одиннадцатого ноября в Германии устраивают шествие с фонариками. Дети делают их сами из бумаги и идут вечером по улице с песней. Это день святого Мартина. Рассказывают, что он ехал верхом, увидел замёрзшего человека и отдал ему половину своего плаща. Поэтому в этот день принято делиться, и в школах детям дарят сладкие булочки в виде человечка.", "q": "Чем поделился святой Мартин с замёрзшим человеком?", "a": [ "Половиной плаща", "Своим конём", "Шапкой с фонариком" ] }, { "id": "de-f-shultyute", "e": "🎒", "t": "Школьный кулёк", "s": "В Германии в первый день школы детям дарят огромный бумажный кулёк, шультюте. Он бывает почти такой же высоты, как сам первоклассник. Внутрь родители кладут сладости, карандаши, ластики и маленькие игрушки. Этой традиции лет двести. Старая сказка говорит, что в подвале у учителя растёт дерево, на котором созревают такие кульки. Когда они поспели, пора начинать учиться.", "q": "Что дарят детям в первый день школы в Германии?", "a": [ "Большой кулёк со сладостями", "Живую птичку", "Книжку без картинок" ] }, { "id": "de-f-ampelmann", "e": "🚦", "t": "Светофорный человечек Ампельмэнн", "s": "В Берлине на светофорах стоит человечек в шляпе. Его зовут Ампельмэнн. Придумал его в 1961 году дорожный психолог Карл Пеглау: детям проще понять человечка, чем просто цветной кружок. Когда Берлин объединился, хотели заменить его на обычного. Но берлинцы так его полюбили, что человечка оставили. Теперь он на майках, кружках и конфетах. В некоторых городах поселились и девочки-светофорчики с косичками.", "q": "Как выглядит Ампельмэнн?", "a": [ "Человечек в шляпе на светофоре", "Медведь с зонтом", "Птица в очках" ] }, { "id": "de-f-shvebebahn", "e": "🚝", "t": "Поезд над рекой и слонёнок Туффи", "s": "В городе Вупперталь поезд ходит по воздуху. Его называют Шведебан. Вагончики висят на рельсе над рекой Вуппер, а внизу плывут лодки. Эта дорога открыта в 1901 году и работает до сих пор. В 1950 году цирк придумал шутку и посадил в вагон слонёнка Туффи. Он испугался шума, прыгнул из окна в реку и поплыл. Туффи вылез на берег с парой царапин и жил долго.", "q": "Где ходит поезд Шведебан?", "a": [ "Висит над рекой в Вуппертале", "Под землёй в Берлине", "По горе в Баварии" ] }, { "id": "de-f-shtayf", "e": "🧶", "t": "Штайф и мишка с пуговицей", "s": "Игрушечных мишек Штайф делают в маленьком городе Гингене. Основала фирму Маргарета Штайф: она не могла ходить из-за болезни и сидела в коляске, но шила очень ловко. Сначала Маргарета шила из мягкого фетра подушечки для иголок в виде слонов, потом подарила миру плюшевых мишек. С 1904 года у каждого настоящего мишки Штайф в ухе пуговка. Так отличают мишек, сделанных на этой фабрике.", "q": "Как отличить мишку Штайф от других?", "a": [ "У него пуговка в ухе", "У него красный бант", "У него шарф с буквой" ] }, { "id": "de-f-gartenzwerg", "e": "🧙", "t": "Гномы в садах", "s": "В немецких садах и огородах часто стоят садовые гномы. Они с острыми красными шапками, а у некоторых ещё лопатка или тачка. Первых гномов из глины в городе Грефенрода лепил мастер Филипп Гибель. Это было около полутора веков назад. Говорят, у немцев их миллионы. В Грефенроде работает музей гномов, там стоят сотни таких фигурок.", "q": "Из чего первые садовые гномы были сделаны?", "a": [ "Из глины", "Из дерева с мхом", "Из стекла" ] }, { "id": "de-f-hagenbek", "e": "🦁", "t": "Зоопарк без решёток", "s": "В Гамбурге есть зоопарк Хагенбек. Его основал Карл Хагенбек и в 1907 году открыл для гостей. Тогда зоопарки были с клетками, а он придумал иначе. Животные жили на больших лужайках и скалах, а от гостей их отделяли глубокие рвы с водой. Рвы прятали за кустами и камнями, и казалось, что зверь рядом, а решёток нет. Теперь так делают во многих зоопарках мира.", "q": "Чем в Хагенбеке отделяли зверей от гостей?", "a": [ "Рвами с водой, спрятанными за кустами", "Высокими решётками", "Стеклянными стенами" ] } ], "esp": [ { "id": "es-madrid-bear", "e": "🐻", "t": "Медведь у дерева", "s": "На гербе Мадрида нарисован медведь, который тянется лапой к дереву. А в самом городе, на главной площади, стоит его бронзовая фигура! Дерево называется земляничным: на нём растут красные бугристые ягоды, похожие на маленькие клубнички. Жители Мадрида любят своего медведя, и дети часто фотографируются рядом с ним.", "q": "К какому дереву тянется медведь на гербе Мадрида?", "a": [ "К земляничному дереву", "К дереву с макаронами", "К дереву с воздушными шариками" ] }, { "id": "es-madrid-palace", "e": "👑", "t": "Дворец с тремя тысячами комнат", "s": "В Мадриде стоит Королевский дворец, один из самых больших дворцов Европы. В нём больше трёх тысяч комнат! Если заглядывать в одну комнату каждую минуту, придётся ходить несколько дней. Сам король живёт в другом доме, за городом, а во дворце проходят праздничные встречи, и туда можно прийти на экскурсию. Там даже хранятся старинные скрипки, которым несколько сотен лет.", "q": "Сколько комнат в Королевском дворце Мадрида?", "a": [ "Больше трёх тысяч", "Только одна", "Ровно три" ] }, { "id": "es-barcelona-boqueria", "e": "🍓", "t": "Самый яркий рынок", "s": "В Барселоне есть широкая пешеходная улица Рамбла, а рядом с ней — рынок Бокерия. Там горками лежат клубника, манго, лимоны и красные перцы, а в прозрачных стаканчиках продают свежие фруктовые соки. Продавцы выкладывают фрукты так красиво, что рынок похож на огромную цветную картину. Здесь не нужно ничего покупать, чтобы порадоваться: достаточно пройтись и посмотреть.", "q": "Что продают на рынке Бокерия в Барселоне?", "a": [ "Фрукты, овощи и соки", "Только резиновые сапоги", "Только воздушных змеев" ] }, { "id": "es-barcelona-fountain", "e": "⛲", "t": "Фонтан, который танцует", "s": "На холме Монжуик в Барселоне есть Волшебный фонтан. Его построили почти сто лет назад, для большой выставки. По вечерам вода взлетает вверх, переливается красным, синим, зелёным и танцует под музыку. Струи то высокие, как дома, то совсем маленькие. Люди садятся на ступеньки перед фонтаном и смотрят, как вода показывает свой спектакль.", "q": "Что делает Волшебный фонтан в Барселоне?", "a": [ "Танцует под музыку и светится", "Рассказывает сказки вслух", "Печёт булочки" ] }, { "id": "es-barcelona-batllo", "e": "🐉", "t": "Дом-дракон", "s": "В Барселоне есть дом, который придумал архитектор Гауди. Называется он Каса-Бальо. Его крыша выгнута, как спина дракона, и покрыта блестящей разноцветной плиткой, будто чешуёй. А башенка с крестом — это меч святого Георгия, который победил дракона в старой легенде. Окна и балконы у дома такие плавные, что кажется, будто стены сделаны не из камня, а из волн.", "q": "На что похожа крыша дома Каса-Бальо?", "a": [ "На спину дракона", "На большой арбуз", "На шляпу волшебника из картона" ] }, { "id": "es-seville-oranges", "e": "🍊", "t": "Апельсины на улицах Севильи", "s": "На улицах Севильи растут апельсиновые деревья, и осенью их ветки полны оранжевых шаров. Но срывать их не надо: эти апельсины очень кислые и горькие, поэтому сырыми их почти не едят. Из них варят густой джем — мармелад, который любят в других странах. А весной цветы апельсинов пахнут так сладко, что весь город словно умылся духами.", "q": "Почему севильские апельсины не едят сырыми?", "a": [ "Они слишком кислые", "Они каменные", "Они слишком быстро убегают" ] }, { "id": "es-valencia-fallas", "e": "🎎", "t": "Праздник огромных кукол", "s": "Каждую весну в Валенсии проходит праздник Фальяс. Улицы украшают огромные фигуры из картона, дерева и папье-маше, некоторые выше дома! Есть и маленькие, которые делают дети. В последнюю ночь большие фигуры сжигают с фейерверком, но по одной самой любимой куколке-ниоту спасают и отправляют в музей. Так что у этого праздника есть и своя история.", "q": "Из чего делают фигуры праздника Фальяс?", "a": [ "Из картона, дерева и папье-маше", "Из мороженого", "Из тёплого снега" ] }, { "id": "es-granada-lions", "e": "🦁", "t": "Двенадцать львов", "s": "В Гранаде, во дворце Альгамбра, есть Львиный дворик. В середине него стоит фонтан, а вокруг фонтана — двенадцать каменных львов. Вода течёт из их пастей, и по маленьким каналам разбегается по всему дворику. Вокруг тянутся лёгкие арки на тонких колоннах, будто кружево из камня. Здесь всегда тихо и прохладно, даже когда на улице жарко.", "q": "Сколько каменных львов в Львином дворике?", "a": [ "Двенадцать", "Один", "Сто" ] }, { "id": "es-food-churros", "e": "🍫", "t": "Чуррос с шоколадом", "s": "В Испании на завтрак или полдник любят чуррос. Это длинные золотистые палочки из теста, которые жарят в масле. Их макают в густой тёплый шоколад, такой, что ложка в нём почти стоит. Чуррос хрустят снаружи и мягкие внутри. Продают их в маленьких кафе, а иногда прямо на ярмарках, и дети идут домой с шоколадными усами.", "q": "Во что макают чуррос?", "a": [ "В густой тёплый шоколад", "В томатный суп", "В тёплую зубную пасту" ] }, { "id": "es-food-olive-oil", "e": "🫒", "t": "Жидкое золото", "s": "Испания дарит миру больше оливкового масла, чем любая другая страна. На юге, в Андалусии, оливковые рощи тянутся до самого горизонта, как зелёное море. Некоторым деревьям сотни лет. Оливки собирают зимой, а потом отжимают из них золотистое масло. В Испании его называют жидким золотом. Им поливают хлеб, и получается простой, но очень вкусный завтрак.", "q": "Что отжимают из оливок?", "a": [ "Золотистое масло", "Лимонад", "Клей для бумаги" ] }, { "id": "es-holiday-kings", "e": "🎁", "t": "Три короля приходят с подарками", "s": "В Испании подарки детям приносят Три короля: Мельхиор, Гаспар и Бальтасар. Вечером пятого января по улицам проходит парад, и короли бросают в толпу конфеты. Дети оставляют у двери обувь, а для верблюдов короля ставят воду. Утром шестого января рядом лежат подарки! К чаю подают круглый пирог с сюрпризом: кому достанется фигурка короля, тот надевает бумажную корону.", "q": "Кто приносит детям подарки шестого января в Испании?", "a": [ "Три короля", "Три поросёнка", "Три медведя" ] }, { "id": "es-holiday-grapes", "e": "🍇", "t": "Двенадцать виноградинок", "s": "В новогоднюю ночь в Испании едят виноград. Когда часы бьют двенадцать раз, нужно успеть съесть двенадцать ягод, по одной на каждый удар. Это непросто: ягоды надо жевать быстро! Считается, что каждая ягода приносит удачу на один месяц нового года. Поэтому в магазинах перед праздником продают виноград в маленьких баночках: по двенадцать ягод.", "q": "Сколько ягод винограда едят под бой часов?", "a": [ "Двенадцать", "Две", "Целую тонну" ] }, { "id": "es-animals-lynx", "e": "🐱", "t": "Рысь с кисточками", "s": "В южной Испании живёт иберийская рысь. Это дикая кошка с пятнистой шубкой, короткими хвостом и кисточками на ушах, а по бокам морды у неё пушистые бакенбарды. Больше всего она любит кроликов. Раньше таких рысей осталось очень мало, но люди стали о них заботиться, и теперь их снова больше. Увидеть её трудно: рысь осторожная и любит прятаться в кустах.", "q": "Кого больше всего любит иберийская рысь?", "a": [ "Кроликов", "Арбузы", "Воздушные шарики" ] }, { "id": "es-people-chess-machine", "e": "♟️", "t": "Автомат играет в шахматы", "s": "Больше ста лет назад испанский инженер Леонардо Торрес Кеведо построил машину, которая играла в шахматы. Называлась она «Ахедресиста». У неё были только король и ладья, а против них играл человек. Машина двигала фигуры с помощью электромагнитов и сама ставила мат. Если человек делал неправильный ход, машина не отвечала, как будто говорила: «Так нельзя!» Это одна из первых в мире машин, которая сама решала шахматную задачу.", "q": "Какие фигуры были у шахматного автомата?", "a": [ "Король и ладья", "Только пешки", "Девять слонов" ] }, { "id": "es-people-picasso", "e": "🎨", "t": "Пикассо рисует по-своему", "s": "Художник Пабло Пикассо родился в испанском городе Малага. Он рисовал так хорошо, что ещё мальчиком писал картины, как взрослые. А потом придумал рисовать по-другому: лицо у него видно и спереди, и сбоку сразу, а нос и глаза бывают в самых неожиданных местах. Многим сначала казалось это смешным, а потом все поняли, как это интересно.", "q": "Как рисовал лица Пикассо?", "a": [ "Видно и спереди, и сбоку сразу", "Только в виде квадратиков из ваты", "Он вообще не рисовал лица" ] }, { "id": "es-mallorca-cave", "e": "🚣", "t": "Подземное озеро на Майорке", "s": "На острове Майорка есть пещеры Драк. В них из потолка и со дна растут каменные сосульки: сталактиты и сталагмиты. А ещё там спрятано подземное озеро! Туристы плывут по нему на лодках, а музыканты иногда играют прямо на воде, и музыка эхом разносится по пещере. Лампы подсвечивают камень, и пещера кажется сказочным подземным дворцом.", "q": "Что спрятано в пещерах Драк на Майорке?", "a": [ "Подземное озеро", "Футбольное поле", "Стадо жирафов" ] }, { "id": "es-camino-shell", "e": "🐚", "t": "Ракушка на рюкзаке", "s": "В Испании есть длинная дорога к городу Сантьяго-де-Компостела. Люди идут по ней пешком, иногда много недель. Чтобы не заблудиться, они ищут жёлтые стрелки на камнях и деревьях. А на рюкзак каждый привязывает ракушку: она стала знаком путников. На ней линии сходятся в одну точку, как дороги, которые приводят к одному городу.", "q": "Что привязывают путники к рюкзаку по дороге в Сантьяго?", "a": [ "Ракушку", "Колокольчик от коровы", "Маленький зонтик из теста" ] }, { "id": "es-language-hola", "e": "👋", "t": "Испанские слова", "s": "На испанском говорят в Испании и во многих других странах: у него больше полумиллиарда носителей. Только на китайском родном языком говорят ещё больше людей. Вот первые слова. Привет по-испански — «ола». Спасибо — «гра́сиас». До свидания — «адьо́с». Первая буква в слове «ола» не произносится совсем. Попробуйте сказать «ола» соседу, и он улыбнётся.", "q": "Что значит «ола» по-испански?", "a": [ "Привет", "Спокойной ночи", "Приятного аппетита" ] }, { "id": "es-bilbao-guggenheim", "e": "🏛️", "t": "Музей, похожий на корабль", "s": "В городе Бильбао стоит музей Гуггенхайма, и он совсем не похож на обычный дом. Его стены изгибаются, как волны, а покрыты они тонкими пластинами титана, похожими на рыбью чешую. Каждая пластина тоньше монетки, а всего их десятки тысяч. Музей блестит серебром, а в разную погоду меняет оттенок. Рядом течёт река, и кажется, будто огромный корабль плывёт прямо по городу.", "q": "Чем покрыты стены музея Гуггенхайма в Бильбао?", "a": [ "Тонкими пластинами титана", "Сладкой глазурью", "Мягкими подушками" ] }, { "id": "es-bilbao-puppy", "e": "🐶", "t": "Щенок из живых цветов", "s": "Перед музеем в Бильбао сидит гигантский щенок по имени Паппи. Он высотой с четырёхэтажный дом, около двенадцати метров. Но самое удивительное — его «шерсть» сделана из живых цветов! Садовники сажают в металлический каркас десятки тысяч растений, а внутри спрятаны трубки, по которым щенка поливают. Весной и летом он яркий и пёстрый, а цветы в нём время от времени меняют.", "q": "Из чего сделана «шерсть» щенка Паппи?", "a": [ "Из живых цветов", "Из ваты", "Из спагетти" ] }, { "id": "es-sansebastian-concha", "e": "🐚", "t": "Бухта-ракушка", "s": "В Сан-Себастьяне есть пляж прямо в центре города, и называется он Ла-Конча. Это слово по-испански значит «ракушка». Если посмотреть сверху, бухта и правда изогнута, как половинка большой раковины. Посреди неё лежит островок Санта-Клара, а вдоль берега тянется набережная с белой узорной оградой. Здесь гуляют, купаются и катаются на велосипедах и жители, и гости города.", "q": "Что означает слово «конча» по-испански?", "a": [ "Ракушка", "Мороженое", "Парус" ] }, { "id": "es-sansebastian-pintxos", "e": "🍢", "t": "Закуски на палочках", "s": "В барах Сан-Себастьяна на стойках лежат маленькие закуски — пинчос. Кусочек хлеба, а сверху рыбка, сыр, оливка или ветчина. Чтобы закуска не развалилась, её накалывают на палочку. Слово «пинчос» как раз и пришло от испанского слова, которое значит «шип» или «колышек». Одна из самых простых закусок: олива, анчоус и маленький зелёный перчик на шпажке. Попробовать много разных пинчос можно, ходя из бара в бар.", "q": "Что втыкают в пинчос, чтобы он держался?", "a": [ "Палочку", "Ложку", "Свечку" ] }, { "id": "es-toledo-swords", "e": "⚔️", "t": "Город на петле реки", "s": "Город Толедо стоит на холме, а вокруг него почти кольцом изогнулась река Тахо. Много веков здесь жили рядом христиане, мусульмане и евреи, поэтому в городе есть храмы трёх вер. А ещё Толедо знаменит своей сталью: здешние мастера делали прочные и гибкие мечи. Их знали во многих странах. И сегодня в лавках города продают красивые мечи и рыцарские доспехи, но уже как сувениры.", "q": "Какая река огибает Толедо?", "a": [ "Тахо", "Молочная река", "Река Шоколадка" ] }, { "id": "es-toledo-marzipan", "e": "🌰", "t": "Сладости из миндаля", "s": "Толедо любят не только за стены и башни, но и за сладости. Здесь делают марципан: его мнут из тёртого миндаля и сахара. Из сладкого теста лепят маленькие фигурки разной формы, а потом слегка запекают, и сверху получается золотистая корочка. Особенно много марципана едят зимой, перед Рождеством. Его до сих пор продают в кондитерских лавках, в которых сладости делают по старым рецептам.", "q": "Из чего делают толедский марципан?", "a": [ "Из миндаля и сахара", "Из снега и соли", "Из мармеладных медведей" ] }, { "id": "es-salamanca-frog", "e": "🐸", "t": "Найди лягушку", "s": "В Саламанке стоит один из старейших университетов Европы, ему больше восьмисот лет. Его каменный фасад покрыт тончайшими узорами, как кружевом. И где-то среди них спрятана крошечная каменная лягушка! Говорят, что студент, который сумеет найти её сам, без подсказок, будет удачлив в учёбе. Поэтому у стены всегда стоят туристы и дети, задрав головы, и ищут лягушку среди камней.", "q": "Кого прячут на фасаде университета в Саламанке?", "a": [ "Каменную лягушку", "Золотого слона", "Каменного кита" ] }, { "id": "es-cordoba-mezquita", "e": "🕌", "t": "Каменный лес в Меските", "s": "В Кордове есть огромный храм, который называется Мескита. Ему больше тысячи лет. Если зайти внутрь, окажешься как будто в каменном лесу: там больше восьмисот колонн, а над ними вырастают арки с красно-белыми полосками, похожие на полосатые конфеты. Колонны стоят рядами, и кажется, что они уходят вдаль без конца. Позже в середине храма построили ещё и собор, поэтому он такой необычный.", "q": "Какого цвета полоски на арках Мескиты?", "a": [ "Красные и белые", "Зелёные и фиолетовые", "Розовые и голубые в горошек" ] }, { "id": "es-cordoba-patios", "e": "🌺", "t": "Дворики, полные цветов", "s": "В Кордове у многих домов есть тихие дворики — патио. Белые стены там увешаны горшками с цветами: красной геранью, синими цветами и зелёным плющом. В серединке часто журчит фонтан или стоит колодец. Каждую весну, в мае, жители открывают двери и показывают патио всем желающим, и выбирают самый красивый двор. Этот праздник так знаменит, что его внесли в список нематериального наследия ЮНЕСКО.", "q": "Чем украшают белые стены кордовских патио?", "a": [ "Горшками с цветами", "Новогодними игрушками", "Ракушками" ] }, { "id": "es-malaga-sun", "e": "🐟", "t": "Сардины на углях", "s": "Малага стоит на берегу тёплого моря, и солнца здесь очень много: говорят, около трёхсот ясных дней в году. На пляже можно увидеть необычную картину. Свежие сардины нанизывают на тростниковые палочки и жарят на огне прямо у воды, в старой деревянной лодке, насыпанной песком. А над городом, на холме, стоит старый замок Гибральфаро. Его название сложено из арабского слова «гора» и греческого слова «маяк».", "q": "Где в Малаге жарят сардины?", "a": [ "На пляже, на огне", "На вершине вулкана", "В космической ракете" ] }, { "id": "es-zaragoza-pilar", "e": "⛪", "t": "Храм с голубыми куполами", "s": "В городе Сарагосе, на берегу реки Эбро, стоит огромный храм — базилика дель Пилар. У неё одиннадцать куполов, а многие из них покрыты блестящей плиткой голубого, зелёного, жёлтого и белого цвета. Они сияют на солнце, как мозаика. Слово «пилар» значит «столб»: внутри храма хранится небольшой каменный столб, и люди приходят к нему, чтобы прикоснуться. Храм виден издалека, ещё с другого берега реки.", "q": "Что означает слово «пилар»?", "a": [ "Столб", "Мороженое", "Облако" ] }, { "id": "es-lanzarote-vines", "e": "🍇", "t": "Виноград в ямках", "s": "На острове Лансароте земля чёрная, потому что остров вырос из вулканов. Здесь почти не бывает дождей, но люди придумали, как растить виноград. Каждый куст сажают в отдельную ямку в чёрном вулканическом песке, а вокруг складывают низкую каменную стенку в виде полукруга, чтобы ветер не сломал лозу. Чёрный песок собирает по ночам влагу из воздуха, и кусту хватает воды. Сверху это похоже на тысячи маленьких кратеров.", "q": "Как на Лансароте защищают кусты винограда от ветра?", "a": [ "Низкой каменной стенкой вокруг ямки", "Надевают им шапки", "Накрывают зонтиками" ] }, { "id": "es-grancanaria-dunes", "e": "🏜️", "t": "Пустыня у океана", "s": "На острове Гран-Канария, рядом с городком Маспаломас, есть настоящие песчаные дюны. Золотистые холмы лежат прямо у океана, будто кусочек Сахары. Ветер гладит песок и рисует на нём волнистые узоры, а дюны потихоньку меняют форму. Это охраняемое место, где нельзя оставлять мусор. Рядом растут пальмы и стоит старый маяк, а туристы иногда катаются здесь на верблюдах.", "q": "На ком туристы иногда катаются у дюн Маспаломас?", "a": [ "На верблюдах", "На пингвинах", "На жирафах" ] }, { "id": "es-pyrenees-vulture", "e": "🦅", "t": "Ягнятник над Ордесой", "s": "Пиренеи — это высокие горы на границе Испании и Франции. В долине Ордеса скалы стоят, как гигантские стены, а в небе кружит ягнятник — одна из самых больших птиц Европы. Размах его крыльев больше двух с половиной метров — шире, чем рост взрослого человека. Ягнятник питается костями! Он поднимает кость высоко и роняет на камни, чтобы она раскололась. А грудь у него рыжеватая, как будто он испачкал перья в глине.", "q": "Чем питается ягнятник?", "a": [ "Костями", "Мороженым", "Яблоками" ] }, { "id": "es-segovia-aqueduct", "e": "🌉", "t": "Мост из камней без клея", "s": "В городе Сеговия посреди улиц стоит римский акведук. Его построили почти две тысячи лет назад, а нужен он был, чтобы водой из гор поить город. Высота акведука около двадцати восьми метров, а арок у него больше ста шестидесяти. Самое удивительное, что тяжёлые гранитные камни лежат друг на друге без раствора и клея, их держит только собственный вес. И стоит акведук до сих пор, крепкий и красивый.", "q": "Что скрепляет камни Сеговийского акведука?", "a": [ "Только собственный вес камней", "Жвачка", "Мёд" ] }, { "id": "es-avila-walls", "e": "🏰", "t": "Город в каменном кольце", "s": "Город Авила окружён стеной, как в сказке про рыцарей. Её начали строить около девятисот лет назад, и она тянется примерно на два с половиной километра. В стене почти девяносто башен и девять больших ворот. Что особенно здорово, стена сохранилась целиком, без больших дыр. По верху одной её части можно пройтись и посмотреть вниз на крыши. Авила стоит высоко в горах, и ветер здесь свежий.", "q": "Что окружает старый город Авила?", "a": [ "Каменная стена с башнями", "Забор из конфет", "Глубокий снежный ров" ] }, { "id": "es-cuenca-houses", "e": "🏠", "t": "Дома над пропастью", "s": "В городе Куэнка есть дома, которые будто повисли в воздухе. Их построили много веков назад на краю скалы, и деревянные балконы выходят прямо над глубоким ущельем реки Уэкар. Поэтому их называют висячими домами. Снизу они выглядят как рисунок из сказки, а сверху видны горы и леса. Внутри одного из домов сегодня устроен музей, где выставлены картины современных художников.", "q": "Почему дома в Куэнке называют висячими?", "a": [ "Их балконы висят над ущельем", "Они подвешены на воздушных шарах", "Они растут вниз головой" ] }, { "id": "es-ronda-bridge", "e": "🌁", "t": "Мост над ущельем", "s": "Город Ронда разрезан надвое глубоким ущельем, которое называется Эль-Тахо. Чтобы пройти с одной стороны на другую, людям построили высокий каменный мост. Его назвали Новым, хотя ему уже больше двухсот тридцати лет. Строили мост больше тридцати лет, а высота его около ста метров. Если встать на мосту и посмотреть вниз, видно ущелье, маленькие деревья и птиц, которые летают гораздо ниже тебя.", "q": "Как называется знаменитый мост в Ронде?", "a": [ "Новый мост", "Конфетный мост", "Мост Радуги" ] }, { "id": "es-gaudi-pedrera", "e": "🏠", "t": "Дом-каменоломня", "s": "В Барселоне есть дом, у которого почти нет прямых стен. Фасад изогнулся волнами, как скала, которую долго обтачивало море. Поэтому люди прозвали дом Педрера, это значит «каменоломня». А на крыше стоят трубы и вентиляционные башенки, закутанные в каменные шлемы. Они похожи на воинов, которые охраняют дом. Построил этот дом Антонио Гауди для семьи Мила, и по крыше сегодня можно погулять.", "q": "На кого похожи трубы на крыше дома Каса Мила?", "a": [ "На воинов в шлемах", "На огромные мороженые", "На стаканы с компотом" ] }, { "id": "es-gaudi-vicens", "e": "🌼", "t": "Дом с жёлтыми цветами", "s": "Первый большой дом Гауди называется Каса Висенс. Говорят, на участке росли маленькие жёлтые цветы и стояла пальма. Гауди узор из этих цветов повторил на плитках, и ими выложили стены. А железную калитку украсил узором из пальмовых листьев. Дом строили как летний, а теперь в нём музей, и в него можно зайти.", "q": "Какой узор Гауди повторил на плитках Каса Висенс?", "a": [ "Жёлтые цветы", "Весёлых пингвинов", "Морковки и огурцы" ] }, { "id": "es-gaudi-chains", "e": "🔗", "t": "Арки вверх ногами", "s": "Как построить арку, которая не упадёт? Гауди придумал хитрый способ. Он подвешивал цепочки и привязывал к ним маленькие мешочки с грузиками. Цепочки провисали красивыми плавными дугами. А потом Гауди смотрел на них в зеркало или переворачивал рисунок вверх ногами, и получалась арка, которая крепко держится. Так цепочки помогали ему проектировать своды церкви.", "q": "Что подвешивал Гауди, чтобы придумать арки?", "a": [ "Цепочки с грузиками", "Сосиски на верёвочках", "Воздушные шарики" ] }, { "id": "es-gaudi-trees", "e": "🌳", "t": "Лес внутри храма", "s": "Гауди говорил, что лучший учитель — природа. Поэтому внутри храма Саграда Фамилия колонны не просто торчат, как палки. Они поднимаются вверх, а потом ветвятся, как стволы деревьев. Потолок над ними похож на кроны, и кажется, что стоишь в каменном лесу. Солнце заглядывает в цветные окна, и на полу играют красные, жёлтые и синие пятна, как под настоящими листьями.", "q": "На что похожи колонны внутри Саграда Фамилия?", "a": [ "На деревья с ветвями", "На длинные макаронины", "На ледяные сосульки" ] }, { "id": "es-gaudi-workshop", "e": "🛠️", "t": "Мастерская архитектора", "s": "В последние годы Гауди работал совсем рядом с храмом Саграда Фамилия, в мастерской, и жил там же, в маленькой простой комнате. Вокруг стояли белые гипсовые модели колонн, окон и кусочков башен. Архитектор брал модель в руки, поворачивал, рассматривал при свете и решал, что нужно изменить. Так он видел, как будет выглядеть настоящая башня, ещё до того, как её построят из камня.", "q": "Из чего были модели в мастерской Гауди?", "a": [ "Из белого гипса", "Из снега", "Из мягкого мармелада" ] }, { "id": "es-quixote-sancho", "e": "🫏", "t": "Санчо Панса и его осёл", "s": "У Дон Кихота был верный друг Санчо Панса. Он не рыцарь, а простой крестьянин: круглый, добродушный и очень практичный. Санчо ездит не на коне, а на сером осле, и в книге это почти что третий герой. Он любит поесть, любит пословицы и мечтает однажды стать правителем острова. В Мадриде на площади Испании стоит памятник Сервантесу, а перед ним бронзовые Дон Кихот и Санчо Панса.", "q": "На ком ездил Санчо Панса?", "a": [ "На осле", "На страусе", "На большом слоне" ] }, { "id": "es-quixote-rocinante", "e": "🐴", "t": "Конь Росинант", "s": "Конь Дон Кихота был очень худой, с торчащими рёбрами. Но рыцарь решил, что у такого отважного героя имя коня должно быть громким. Он долго думал и придумал Росинант. В этом имени спрятана шутка: «росин» по-испански значит рабочая лошадка, а всё слово будто говорит, что прежде это была простая лошадка, а теперь она первая среди всех. Дон Кихот очень любил своего коня.", "q": "Какой конь был у Дон Кихота?", "a": [ "Худой, по имени Росинант", "Золотой, с крыльями", "Полосатый, как зебра" ] }, { "id": "es-quixote-cervantes", "e": "📚", "t": "Как появилась книга о Дон Кихоте", "s": "Книгу о Дон Кихоте написал испанец Сервантес. Первая часть вышла в 1605 году, больше четырёхсот лет назад, а вторая — ещё через десять лет. И Сервантес придумал забавную игру. Он написал, что историю будто бы записал какой-то арабский мудрец по имени Сид Ахмет Бененхели, а он только перевёл. Сегодня книгу читают на очень многих языках, а в Испании её знают почти все.", "q": "Когда вышла первая часть книги о Дон Кихоте?", "a": [ "Больше четырёхсот лет назад", "Вчера утром", "Во времена динозавров" ] }, { "id": "es-quixote-helmet", "e": "🪣", "t": "Шлем из таза", "s": "У Дон Кихота был старый шлем, и забрало к нему он сделал из картона. Проверил его мечом, и картон сломался. Рыцарь сделал новое и проверять уже не стал. Потом он увидел цирюльника, который под дождём шёл с блестящим медным тазиком на голове. Дон Кихот решил, что это золотой шлем из старой сказки, и забрал тазик. Санчо Панса видел только тазик и посмеивался.", "q": "Что Дон Кихот принял за золотой шлем?", "a": [ "Медный тазик цирюльника", "Большую кастрюлю с супом", "Ведро для песка" ] }, { "id": "es-flamenco-guitar", "e": "🎸", "t": "Гитара, которая стучит", "s": "В фламенко гитара не просто играет, она ещё и стучит. У испанской гитары шесть струн и лёгкий деревянный корпус. Гитарист может ударить пальцами по верхней деревянной деке, и получается звонкий щелчок, как у маленького барабана. Это называется «гольпе». Так в одной гитаре живут и мелодия, и ритм. Танцоры и певцы слушают гитару и подстраиваются под её настроение.", "q": "Как гитарист фламенко добавляет в музыку барабанный звук?", "a": [ "Стучит пальцами по корпусу", "Бьёт по гитаре ложкой", "Дует в гитару, как в трубу" ] }, { "id": "es-flamenco-castanets", "e": "🥁", "t": "Кастаньеты", "s": "Кастаньеты делают из твёрдого дерева, и каждая похожа на две выпуклые ракушки. Их соединяет шнурок, который надевают на большой палец, а остальными пальцами щёлкают. Название пошло от испанского слова «каштан», потому что форма напоминает этот орех. В каждой паре одна кастаньета звучит выше, другая ниже. Танцор в такт музыке будто разговаривает руками.", "q": "Откуда пошло название «кастаньеты»?", "a": [ "От слова «каштан»", "От слова «кастрюля»", "От слова «кактус»" ] }, { "id": "es-flamenco-palmas", "e": "👏", "t": "Хлопки и каблуки", "s": "Во фламенко можно сделать музыку без инструментов. Хлопки ладонями называются «пальмас». Бывают звонкие хлопки, когда ударяешь пальцами по ладони, и глухие, когда ладони сложены лодочкой. А ещё танцор стучит каблуками по полу, и в каблуках и носках его туфель вбиты маленькие гвоздики, поэтому слышен громкий дробный стук. Зрители тоже хлопают в такт и кричат «оле!».", "q": "Как называются хлопки ладонями во фламенко?", "a": [ "Пальмас", "Кастаньеты", "Ламбада" ] }, { "id": "es-art-velazquez", "e": "🖌️", "t": "Картина, которая меняется", "s": "Диего Веласкес был придворным художником испанского короля, и его картины висят в музее Прадо в Мадриде. У него есть волшебство: подойди к картине совсем близко, и увидишь только мазки краски, будто кто-то брызнул кистью. Но отойди на несколько шагов, и мазки складываются в блестящее платье, кружево и живые глаза. Художники до сих пор приходят к нему учиться этому фокусу.", "q": "Что видно, если подойти к картине Веласкеса совсем близко?", "a": [ "Отдельные мазки краски", "Только белую стену", "Надпись «Не подходить»" ] }, { "id": "es-art-goya", "e": "🪁", "t": "Воздушный змей Гойи", "s": "Франсиско Гойя рисовал не только королей. Когда-то он делал большие картины-образцы, по которым ткали гобелены для королевских дворцов. На них — обычные люди и их игры. Дети запускают воздушного змея, друзья играют в жмурки, а девушки подбрасывают на одеяле соломенную куклу. Позже Гойя стал плохо слышать, а потом совсем оглох. Но он продолжал рисовать, и многие его работы можно увидеть в музее Прадо.", "q": "Во что играют люди на картинах Гойи для гобеленов?", "a": [ "В жмурки и запускают змея", "В космических пиратов", "В хоккей на льду" ] }, { "id": "es-art-dali", "e": "🥚", "t": "Дали и его усы", "s": "Сальвадор Дали носил тонкие усы, которые торчали вверх, как стрелки часов. Он брал пример с художника Веласкеса, которого очень уважал. А в городе Фигерас у Дали есть музей, и он выглядит как сказка: на крыше стоят огромные яйца, на стенах прилеплены золотые булки, а над старым театром поднимается стеклянный купол. Дали сам придумал, как украсить этот дом.", "q": "Что стоит на крыше музея Дали в Фигерасе?", "a": [ "Огромные яйца", "Настоящие коровы", "Ёлочные шишки" ] }, { "id": "es-art-miro", "e": "🎨", "t": "Картина под ногами", "s": "В Барселоне, на улице Рамбла, можно пройтись по картине. Художник Жоан Миро подарил городу большую круглую мозаику, и она лежит прямо на тротуаре. Яркие пятна, чёрные линии, глаз и звезда — будто детский рисунок, но придуманный взрослым. Миро любил смелые цвета и простые фигурки: птиц, звёзды, луны. Так у каждого прохожего есть картина, на которую можно просто наступить и ничего не платить.", "q": "Где в Барселоне можно пройти по картине Миро?", "a": [ "На тротуаре улицы Рамбла", "На ледяном катке", "На крыше самолёта" ] }, { "id": "es-art-elgreco", "e": "🖼️", "t": "Художник по прозвищу Грек", "s": "Настоящее имя художника — Доменикос Теотокопулос, но в Испании его зовут Эль Греко, это значит «грек». Он родился на острове Крит, а жил в городе Толедо. Люди на его картинах вытянутые, высокие, тонкие, как язычки пламени. Он даже подписывал картины греческими буквами. Одну из них, «Вид Толедо», он написал с таким небом, будто вот-вот начнётся гроза.", "q": "Что значит прозвище «Эль Греко»?", "a": [ "«Грек»", "«Высокий гриб»", "«Великий кот»" ] }, { "id": "es-art-sorolla", "e": "🏖️", "t": "Художник солнца и моря", "s": "Хоакин Соролья родился в Валенсии, у моря, и рисовал самое солнечное: пляж, мокрый песок, белые паруса и детей, которые плещутся в воде. Он писал картины на открытом воздухе, чтобы поймать настоящий свет. Белые платья и рубашки у него искрятся, а вода в волнах переливается розовым, зелёным и голубым. Дом Сорольи в Мадриде теперь музей, там есть и его сад.", "q": "Что рисовал Соролья на своих картинах?", "a": [ "Море, пляж и яркое солнце", "Снежные горы и пингвинов", "Космические корабли" ] }, { "id": "es-food-gazpacho", "e": "🍅", "t": "Суп, который едят холодным", "s": "В жаркой Андалусии придумали суп, который не нужно варить. Это гаспачо. Спелые помидоры, огурец, сладкий перец, чеснок и кусочек хлеба взбивают вместе, и получается густой красный суп. Его ставят в холодильник, а потом подают холодным. В самый жаркий день его даже пьют из стакана, как сок. Летом в Испании это настоящее спасение от жары.", "q": "Каким подают гаспачо?", "a": [ "Холодным", "Горячим, как кипяток", "Замороженным, как мороженое на палочке" ] }, { "id": "es-food-tortilla", "e": "🍳", "t": "Картофельный пирог из сковородки", "s": "Испанская тортилья совсем не похожа на лепёшку, как в других странах. Это толстый круглый омлет с жареной картошкой. Его жарят на сковороде, а потом ловко переворачивают на тарелке, чтобы подрумянился второй бок. Тортилью режут на треугольные кусочки, как торт. Её едят дома, берут с собой на пикник и кладут в булочку. А повара в Испании до сих пор спорят, нужен ли в неё лук!", "q": "Что главное в испанской тортилье?", "a": [ "Яйца и картошка", "Мёд и ананасы", "Шоколад и макароны" ] }, { "id": "es-food-jamon", "e": "🥓", "t": "Хамон на потолке", "s": "Зайдите в испанский магазинчик, и вы увидите: под потолком висят целые свиные ноги! Это хамон. Его солят и долго сушат на воздухе, иногда больше года, и он становится тёмно-красным и очень ароматным. Потом ногу ставят на специальную подставку, и мастер длинным тонким ножом срезает ломтики такие тонкие, что через них почти видно свет. Хамон кладут на хлеб или едят просто так.", "q": "Как режут хамон?", "a": [ "Очень тонкими ломтиками", "Толстыми кубиками, как сахар", "Ложкой, как кашу" ] }, { "id": "es-food-turron", "e": "🍬", "t": "Рождественский туррон", "s": "Когда в Испании приближается Рождество, в магазинах появляются плитки туррона. Это сладость из миндаля и мёда. Бывает твёрдый туррон, который нужно ломать на кусочки, и мягкий, который можно резать ножом. Его делают в городе Хихона и в городе Аликанте уже много лет. Дома туррон выкладывают на красивое блюдо, и каждый берёт кусочек к чаю или горячему шоколаду.", "q": "Из чего делают туррон?", "a": [ "Из миндаля и мёда", "Из сухарей и горчицы", "Из снега и ваты" ] }, { "id": "es-food-horchata", "e": "🥛", "t": "Молоко из земляного миндаля", "s": "В Валенсии в жаркий день пьют орчату, белый холодный напиток со сладким вкусом. Её готовят из чуфы. Чуфа — это маленькие клубеньки, которые растут прямо под землёй, как крошечная картошка. На вкус они немного похожи на орех. Их моют, растирают с водой и процеживают, и получается напиток, похожий на молоко. К нему подают длинные мягкие сладкие булочки фартоны, и их макают в стакан.", "q": "Где растёт чуфа, из которой делают орчату?", "a": [ "Под землёй", "На высокой пальме", "На морском дне" ] }, { "id": "es-food-tapas", "e": "🌶️", "t": "Перчики, которые играют в прятки", "s": "В Испании любят тапас — маленькие порции еды, которые заказывают на всю семью. Одно блюдо — жареные зелёные перчики из города Падрон. Они небольшие, их жарят в масле и посыпают крупной солью. Почти все перчики мягкие, но изредка попадается острый! Заранее не угадать, какой достанется. В Испании даже говорят: «одни острые, другие нет». Поэтому есть их — целая игра.", "q": "Чем интересны перчики из Падрона?", "a": [ "Иногда попадается острый", "Они все синего цвета", "Они поют, когда их жарят" ] }, { "id": "es-holiday-sanfermin", "e": "🎺", "t": "Красные платки в Памплоне", "s": "Каждый год в июле город Памплона превращается в большой праздник Сан-Фермин. Все надевают белую одежду и повязывают на шею красный платок. В полдень шестого июля с балкона ратуши взлетает ракета, которая называется чупинасо. Тогда вся площадь поднимает красные платки вверх. Девять дней подряд на улицах играют оркестры, ходят шествия, по городу идут огромные куклы-великаны, а вечером в небе вспыхивает фейерверк.", "q": "Какого цвета платки у участников Сан-Фермина?", "a": [ "Красного", "Зелёного в горошек", "Золотого с бубенцами" ] }, { "id": "es-holiday-tenerife-carnival", "e": "🎭", "t": "Карнавал на острове Тенерифе", "s": "На острове Тенерифе, в городе Санта-Крус, зимой устраивают огромный карнавал. Он считается одним из самых больших в мире. На улицы выходят тысячи людей в ярких костюмах: кто-то в перьях, кто-то в блёстках, кто-то переодет в динозавра. Каждый год выбирают королеву карнавала. Её наряд такой громадный и тяжёлый, что его возят на колёсиках, а внутри стоит девушка и машет всем рукой. Улицы поют и танцуют до утра.", "q": "На чём везут огромный наряд королевы карнавала?", "a": [ "На колёсиках", "На спине слона", "На воздушном шаре" ] }, { "id": "es-holiday-elgordo", "e": "🎄", "t": "Дети поют лотерею", "s": "Двадцать второго декабря вся Испания замирает у телевизора. Начинается рождественская лотерея, которую все называют Эль Гордо. Её номера не объявляет диктор. Их поют дети из школы Сан-Ильдефонсо на сцене театра в Мадриде! Из больших барабанов достают шарики с числами и выигрышными суммами, а ребята звонко выпевают их, как песню. «Гордо» значит «толстый»: так зовут самый большой приз.", "q": "Кто поёт выигрышные номера на Эль Гордо?", "a": [ "Дети из школы", "Попугаи в клетках", "Музыканты в космосе" ] }, { "id": "es-holiday-giants", "e": "🪆", "t": "Великаны гуляют по Барселоне", "s": "В конце сентября в Барселоне праздник Ла Мерсе, и по улицам гуляют гигантес — огромные куклы, намного выше любого взрослого. Это короли и королевы в пышных нарядах, а рядом шагают сказочные звери. Внутри каждой куклы спрятан человек: он держит её на плечах и осторожно кружится в танце под музыку. Дети бегут рядом и машут великанам. Многие такие куклы живут по много лет, их хранят и бережно чинят.", "q": "Кто прячется внутри кукол-гигантес?", "a": [ "Человек, который их несёт", "Большая собака", "Стая голубей" ] }, { "id": "es-holiday-alcoy", "e": "🎆", "t": "Парад костюмов в Алькое", "s": "В городе Алькой каждый апрель проходит праздник Мавры и христиане. Три дня жители шагают по улицам в необычных нарядах: кто-то в блестящих шлемах и плащах, кто-то в длинных цветных халатах и тюрбанах. Играют оркестры, друг за другом проходят целые отряды в одинаковых костюмах. Всё это похоже на огромный театр под открытым небом, а устраивают его в честь святого Георгия, покровителя города.", "q": "Что устраивают в Алькое весной?", "a": [ "Парад костюмов", "Гонки на улитках", "Соревнование по лепке снеговиков" ] }, { "id": "es-holiday-sanjuan", "e": "🔥", "t": "Ночь Сан-Хуана на пляже", "s": "В ночь на двадцать четвёртое июня Испания встречает лето праздником Сан-Хуан. На пляжах загораются костры, и вся семья собирается у воды. Люди пишут желания на бумажках и бросают их в огонь, чтобы желание сбылось. А в полночь во многих местах заходят в море и прыгают через волны, считая до семи. Костры разводят взрослые, а дети смотрят на них с безопасного расстояния. В Каталонии в эту ночь ещё едят сладкий пирог — коку.", "q": "Что делают с желаниями в ночь Сан-Хуана?", "a": [ "Бросают бумажки в костёр", "Прячут их в варежки", "Отправляют по почте на Луну" ] }, { "id": "es-animals-brownbear", "e": "🐻", "t": "Медведи Кантабрийских гор", "s": "На севере Испании тянутся Кантабрийские горы, где среди густых лесов живёт бурый медведь. Он очень большой, но осторожный, поэтому встретить его почти невозможно. Летом он лакомится ягодами, осенью собирает жёлуди и каштаны, а ещё очень любит мёд. Зимой многие медведи отсыпаются в берлогах и пещерах. Когда-то их осталось совсем мало, но люди стали их охранять, и теперь в горах живёт больше трёхсот медведей.", "q": "Что любит бурый медведь на севере Испании?", "a": [ "Ягоды, каштаны и мёд", "Мороженое и пирожные", "Печенье и лимонад" ] }, { "id": "es-animals-eagle", "e": "🦅", "t": "Орёл с белыми погонами", "s": "В Испании живёт испанский императорский орёл, а ещё он живёт в соседней Португалии, и больше почти нигде в мире. Он тёмно-коричневый, а на плечах у него белые пятна, похожие на погоны. Крылья у него широкие, размахом около двух метров. Орлы строят гнездо на высоком дереве, например на пробковом дубе или сосне. Они добавляют новые ветки, и гнездо с годами становится огромным.", "q": "Что у испанского императорского орла на плечах?", "a": [ "Белые пятна, как погоны", "Золотые пуговицы", "Красные банты" ] }, { "id": "es-animals-donana", "e": "🦩", "t": "Розовые гости Доньяны", "s": "На юге Испании, там, где река Гвадалкивир впадает в океан, раскинулся национальный парк Доньяна. Это огромное царство воды, песка и болот. Каждый год здесь отдыхает множество птиц, и среди них — розовые фламинго. Розовыми их делает еда: мелкие рачки, которых они ловят в воде. А фламинго-малыши рождаются серыми и розовеют только через несколько лет. Поэтому в стае есть и розовые, и серые птицы.", "q": "Какого цвета рождаются фламинго?", "a": [ "Серого", "Ярко-розового", "Голубого в клетку" ] }, { "id": "es-animals-stork", "e": "🔔", "t": "Аисты на колокольне", "s": "В испанских городках и деревнях на колокольнях и крышах церквей часто сидят белые аисты. Они строят огромные гнёзда из толстых веток и возвращаются в них много лет подряд. Гнездо с каждым годом растёт: бывает шире метра и тяжелее взрослого человека! Голоса у аистов нет, поэтому, встречая друга, они громко щёлкают клювом. Над колокольней слышится весёлый стук.", "q": "Как аист здоровается с партнёром?", "a": [ "Щёлкает клювом", "Поёт песню", "Звонит в колокольчик" ] }, { "id": "es-animals-hierro", "e": "🦎", "t": "Ящерица, которую считали пропавшей", "s": "На маленьком острове Эль-Йерро, на краю Канарских островов, живёт гигантская ящерица. Вместе с хвостом она бывает около полуметра, а на вид — настоящий маленький дракон. Люди думали, что такие ящерицы давно исчезли. Но в тысяча девятьсот семьдесят четвёртом году на крутой скале нашли несколько живых ящериц! Теперь их разводят в специальном центре и выпускают на волю, чтобы они снова жили на острове.", "q": "Где нашли ящериц, которых считали пропавшими?", "a": [ "На крутой скале", "На дне морском", "На вершине облака" ] }, { "id": "es-castle-segovia", "e": "🏰", "t": "Замок с носом корабля", "s": "В городе Сеговия на высокой скале, где сходятся две речки, стоит замок Алькасар. Скала узкая, и замок вытянулся вдоль неё, а его острый конец торчит вперёд, как нос корабля. Над стенами поднимаются башенки с острыми крышами-колпачками. Говорят, такие башни напоминают замки из мультиков, и многие туристы узнают их с первого взгляда. Внутри есть залы с нарядными потолками.", "q": "На что похож острый конец замка Алькасар?", "a": [ "На нос корабля", "На хвост дракона-повара", "На огромную морковку" ] }, { "id": "es-castle-coca", "e": "🧱", "t": "Замок из красного кирпича", "s": "Недалеко от Сеговии стоит замок Кока, и он совсем не серый, как многие замки, а тёплого рыже-красного цвета. Его построили из кирпича много сотен лет назад. Стены украшены башенками и узорами, а вокруг замка выкопан глубокий ров. Когда на кирпич падает вечернее солнце, замок будто светится. Сейчас внутри можно ходить на экскурсии и рассматривать залы.", "q": "Из чего построен замок Кока?", "a": [ "Из красного кирпича", "Из шоколадных плиток", "Из снега и льда" ] }, { "id": "es-castle-loarre", "e": "⛰️", "t": "Замок, выросший из скалы", "s": "В Испании, у подножия гор Пиренеев, на скалистом холме стоит замок Лоарре. Он такого же серого цвета, как камни вокруг, и издали кажется, что он сам вырос из горы. Его начали строить почти тысячу лет назад, и это один из лучше всего сохранившихся замков той далёкой эпохи. Внутри замка есть даже своя маленькая каменная церковь, а вокруг — просторные горные долины.", "q": "Где стоит замок Лоарре?", "a": [ "На скалистом холме у гор", "На дне озера", "На спине слона" ] }, { "id": "es-castle-peniscola", "e": "🌊", "t": "Город-замок на скале у моря", "s": "На берегу тёплого Средиземного моря торчит из воды скалистый мыс, и на самой его вершине стоит белый городок Пеньискола с огромным замком. Мыс соединён с берегом узкой песчаной полоской, так что издали кажется, что замок плывёт по волнам. Узкие улочки города спускаются к воде, а с башен видно море во все стороны. Говорят, в этом замке снимали фильмы и сериалы.", "q": "Что стоит на скалистом мысе в Пеньисколе?", "a": [ "Замок и белый городок", "Подводная лодка с крышей", "Ледяной дворец" ] }, { "id": "es-columbus-palos", "e": "⛵", "t": "Три корабля из порта Палос", "s": "Давным-давно, в августе 1492 года, из маленького испанского порта Палос вышли в море три корабля: «Санта-Мария», «Пинта» и «Нинья». «Санта-Мария» была самой большой из них. Командовал отрядом моряк по имени Колумб. Он хотел найти новый путь по океану, но вместо этого, после долгих недель плавания, увидел острова, которых европейцы раньше не знали. Это случилось осенью того же года.", "q": "Как назывался самый большой корабль Колумба?", "a": [ "«Санта-Мария»", "«Золотая рыбка»", "«Летучая тыква»" ] }, { "id": "es-columbus-tomb", "e": "⚰️", "t": "Гробница на плечах у четырёх фигур", "s": "В большом соборе города Севилья стоит необычная гробница. Считается, что в ней хранится прах Колумба. Тяжёлый саркофаг не стоит на земле, а поднят высоко: его на плечах несут четыре большие бронзовые фигуры. Они изображают четыре королевства, из которых когда-то состояла Испания. Люди приходят в собор не только помолиться, но и посмотреть на эту необычную гробницу.", "q": "Кто несёт на плечах гробницу Колумба в Севилье?", "a": [ "Четыре бронзовые фигуры", "Четыре живых слона", "Два каменных кота" ] }, { "id": "es-magellan-victoria", "e": "🌍", "t": "Вокруг света на одном корабле", "s": "В 1519 году из Испании вышли в море пять парусных кораблей под началом Магеллана. Они хотели добраться до островов с пряностями, плывя на запад. Путь вышел очень длинным и трудным. Сам Магеллан до дома не добрался, а вернулся лишь один корабль, «Виктория», в 1522 году. Им командовал Элькано. Это было первое в истории путешествие вокруг света.", "q": "Какой корабль вернулся из первого кругосветного плавания?", "a": [ "«Виктория»", "«Золотой кит»", "«Красный самокат»" ] }, { "id": "es-balboa-ocean", "e": "🌅", "t": "Океан, увиденный с горы", "s": "Испанский путешественник Бальбоа в 1513 году прошёл через жаркие зелёные леса Панамы. Он поднялся на гору и увидел вдали огромную воду, которую европейцы ещё никогда не видели. Это был Тихий океан! Бальбоа вошёл в воду по колено и назвал это море Южным. Позже мореплаватель Магеллан дал ему другое имя: за спокойную погоду океан назвали Тихим.", "q": "Какой океан увидел Бальбоа с горы в Панаме?", "a": [ "Тихий океан", "Океан лимонада", "Молочный океан" ] }, { "id": "es-elcano-ship", "e": "🎓", "t": "Парусник с именем Элькано", "s": "Элькано, моряк, который довёл корабль «Виктория» домой, остался в памяти испанцев надолго. Сегодня большой четырёхмачтовый парусник носит его имя: «Хуан Себастьян де Элькано». Его спустили на воду в 1927 году, и на нём до сих пор учатся будущие морские офицеры Испании. Они поднимают паруса, учатся вязать узлы и ходят в дальние плавания по морям и океанам.", "q": "Кто учится на парусном корабле имени Элькано?", "a": [ "Будущие морские офицеры", "Только повара-акробаты", "Только цирковые лошади" ] }, { "id": "es-peral-submarine", "e": "🚤", "t": "Первая лодка под водой с электричеством", "s": "Больше ста тридцати лет назад испанский морской офицер Исаак Перал придумал подводную лодку. Она двигалась не на пару, а на электричестве от больших батарей, и в ней была труба для торпед. Лодку спустили на воду в 1888 году в городе Кадис. Длиной она была около двадцати двух метров. Сегодня лодка Перала стоит на набережной города Картахена, и на неё можно посмотреть.", "q": "На чём двигалась подводная лодка Исаака Перала?", "a": [ "На электричестве от батарей", "На парусах под водой", "На велосипедных педалях" ] }, { "id": "es-cierva-autogiro", "e": "🚁", "t": "Предок вертолёта", "s": "Испанский инженер Хуан де ла Сьерва придумал машину, которая называется автожир. У неё есть пропеллер впереди, как у самолёта, а ещё большой винт сверху. Этот верхний винт сам крутится от встречного воздуха. Первый удачный полёт автожира случился в январе 1923 года недалеко от Мадрида, в местечке Хетафе. Изобретение Сьервы помогло учёным позже создать вертолёты.", "q": "Что крутится сверху у автожира?", "a": [ "Большой винт от встречного воздуха", "Огромный вентилятор-зонтик", "Крылья бабочки" ] }, { "id": "es-cajal-drawings", "e": "🧠", "t": "Врач, который рисовал мозг", "s": "Испанец Рамон-и-Кахаль в детстве очень любил рисовать. Став врачом, он стал смотреть в микроскоп на крошечные клетки мозга и зарисовывал их пером и чернилами. Рисунки получились такие точные и красивые, что похожи на ветки деревьев. В 1906 году учёный получил Нобелевскую премию, а его рисунки показывают в музеях и до сих пор публикуют в учебниках.", "q": "Что рисовал Рамон-и-Кахаль в микроскоп?", "a": [ "Клетки мозга", "Облака и радуги", "Маленьких драконов" ] }, { "id": "es-altamira-bison", "e": "🦬", "t": "Бизоны на потолке пещеры", "s": "На севере Испании, в пещере Альтамира, на потолке нарисованы бизоны. Рисовали их люди каменного века, очень-очень давно, возможно больше пятнадцати тысяч лет назад. Художники использовали красную и чёрную краску и учли выпуклости камня, поэтому бизоны выглядят как объёмные. Рисунки на потолке заметила маленькая девочка, дочка исследователя пещеры. Сегодня рядом сделали точную копию, чтобы настоящие рисунки не портились.", "q": "Что нарисовано на потолке пещеры Альтамира?", "a": [ "Бизоны", "Космические ракеты", "Белые медведи на лыжах" ] }, { "id": "es-hercules-tower", "e": "🗼", "t": "Римский маяк, который ещё светит", "s": "В городе Ла-Корунья на берегу океана стоит высокая каменная Башня Геракла. Её построили римляне почти две тысячи лет назад, и это единственный римский маяк, который до сих пор работает. Башня высотой около пятидесяти пяти метров, верх её позже подновили. Есть легенда, что здесь герой Геракл победил великана Гериона и поставил башню над его могилой. Каждую ночь она по-прежнему подаёт сигнал кораблям.", "q": "Что делает Башня Геракла каждую ночь?", "a": [ "Светит кораблям, как маяк", "Рассказывает сказки", "Поёт колыбельные" ] }, { "id": "es-basque-language", "e": "💬", "t": "Язык, который ни на что не похож", "s": "В Испании, на севере, живут баски, и их язык называется эускара. Он не похож ни на испанский, ни на французский, ни на другие языки вокруг, и учёные до сих пор спорят, откуда он взялся. Слова в нём звучат необычно. Например, «привет» по-баскски будет «кайшо». Баскский язык очень древний: на нём говорили здесь ещё до того, как пришли римляне.", "q": "Как по-баскски «привет»?", "a": [ "Кайшо", "Бульк-бульк", "Мяу-мяу" ] }, { "id": "es-siesta-dinner", "e": "🌙", "t": "Сиеста и поздний ужин", "s": "В Испании главный обед бывает поздно, около двух-трёх часов дня. В жаркий день многие после обеда отдыхают: это называется сиеста. Некоторые маленькие магазины в это время даже закрываются на несколько часов. А ужинают в Испании тоже поздно, часов в девять вечера или ещё позже. Поэтому вечером на улицах и площадях много людей, а дети тоже иногда гуляют допоздна.", "q": "Как называется послеобеденный отдых в Испании?", "a": [ "Сиеста", "Паэлья", "Фламенко" ] }, { "id": "es-ave-trains", "e": "🚄", "t": "Поезд-птица", "s": "В Испании ходят очень быстрые поезда, и называются они АВЕ. Эти три буквы расшифровываются как «Испанская высокая скорость», а ещё по-испански «аве» значит «птица». Поезд с острым носом разгоняется примерно до трёхсот километров в час. Из Мадрида в Барселону он домчит примерно за два с половиной часа. По длине скоростных дорог Испания в Европе на первом месте.", "q": "Что ещё значит слово «аве» по-испански?", "a": [ "Птица", "Мороженое", "Облако" ] }, { "id": "es-enie-question", "e": "❓", "t": "Волнистая Ñ и перевёрнутый вопрос", "s": "В испанском алфавите есть особая буква Ñ, она читается «энье». Над обычной N у неё волнистая чёрточка. Так пишется «año» — год и «niño» — ребёнок. А ещё в испанском вопросы начинаются перевёрнутым знаком ¿ и заканчиваются обычным. Так читающий сразу видит: впереди вопрос. Перед восклицанием ставят перевёрнутый знак ¡.", "q": "Каким знаком в испанском начинается вопрос?", "a": [ "Перевёрнутым ¿", "Рисунком звезды", "Смайликом-жуком" ] } ], "old": [ { "id": "old-first-lascaux", "e": "🐂", "t": "Пещера Ласко и собака", "s": "В 1940 году во Франции ребята увидели в земле тёмную дыру. По рассказам, туда вслед за собакой по имени Робот они и заглянули. Они спустились вниз с фонарём и ахнули: по стенам бежали быки, олени и лошади! Их нарисовали люди около 17 тысяч лет назад. Краски были красные, жёлтые и чёрные, а светили художникам каменные лампы с жиром. Рисунки такие живые, что кажется: звери вот-вот поскачут дальше.", "q": "Кто, по рассказам, привёл ребят к пещере Ласко?", "a": [ "Собака Робот", "Говорящий попугай", "Маленький слонёнок" ], "sec": "first" }, { "id": "old-first-hands", "e": "🖐️", "t": "Ладошки на стене", "s": "В пещерах по всему миру остались отпечатки ладоней, которым много тысяч лет. Например, в Аргентине, в пещере, которую так и назвали — Пещера рук. Как их делали? Человек прикладывал руку к скале и выдувал краску изо рта через трубочку из косточки. Краска разлеталась брызгами, а под ладонью оставалось чистое место — получался контур руки. Есть и совсем маленькие ладошки: значит, малыши тоже участвовали в этом художестве!", "q": "Как древние люди делали отпечаток ладони на скале?", "a": [ "Выдували краску вокруг руки", "Макали руку в мёд", "Рисовали карандашом из шоколада" ], "sec": "first" }, { "id": "old-first-flute", "e": "🎶", "t": "Самая старая флейта", "s": "Больше 35 тысяч лет назад в пещере в Германии кто-то сделал флейту. Её вырезали из крыла большой птицы, из косточки грифа, и сделали в ней пять дырочек для пальцев. Флейта сломалась на кусочки, но учёные нашли их и сложили вместе. Длиной она почти как линейка в двадцать с лишним сантиметров. Значит, музыка звучала ещё в то время, когда люди жили в пещерах и охотились на мамонтов.", "q": "Из чего древние люди сделали флейту?", "a": [ "Из косточки большой птицы", "Из стеклянной бутылки", "Из железной трубы" ], "sec": "first" }, { "id": "old-first-mammoth-house", "e": "🦣", "t": "Дом из костей мамонта", "s": "На Украине учёные раскопали странные круглые дома. Их стены сложили из костей и бивней мамонтов! Это сделали примерно 18 тысяч лет назад, когда кругом была холодная ледниковая пора. Кости клали друг на друга, как кирпичи, а сверху, наверное, натягивали шкуры. Внутри разводили костёр, и было тепло. Дом из мамонта — это придумать надо! Но брёвен в холодной степи почти не было, зато кости лежали повсюду.", "q": "Из чего сложили стены этих древних домов?", "a": [ "Из костей мамонтов", "Из конфет", "Из больших ракушек" ], "sec": "first" }, { "id": "old-first-needle", "e": "🪡", "t": "Иголка старше всех", "s": "В Денисовой пещере в Сибири нашли иголку. Ей около 50 тысяч лет! Она тоненькая, длиной с семь сантиметров, и сделана из птичьей косточки. А ещё у неё есть ушко, совсем как у нашей иголки, — значит, в него вдевали нитку. Выходит, люди умели шить одежду очень давно. Тёплая шуба из шкур помогала им не мёрзнуть, а иголка помогала сшивать куски шкур.", "q": "Из чего сделана самая древняя иголка из Денисовой пещеры?", "a": [ "Из птичьей косточки", "Из пластмассы", "Из сосновой шишки" ], "sec": "first" }, { "id": "old-first-footprints", "e": "👣", "t": "Следы детей", "s": "В Америке, в штате Нью-Мексико, на месте высохшего озера нашли следы. Следы босых ног, и оставили их около 23 тысяч лет назад! Многие из них маленькие, значит, по мягкой грязи шли дети и подростки. Грязь потом высохла, окаменела, и следы сохранились до наших дней. Представьте: ребёнок шлёпал по лужам, как вы, и не знал, что мы будем разглядывать его следы так много лет спустя.", "q": "Чьи следы нашли на месте высохшего озера?", "a": [ "Босых людей, в том числе детей", "Динозавров с рюкзаками", "Огромных морских черепах" ], "sec": "first" }, { "id": "old-first-lamps", "e": "🪔", "t": "Лампа из камня", "s": "В глубине пещеры совсем темно, как же рисовать? Древние художники придумали лампы! В Ласко нашли каменные плошки с ручкой. В плошку клали жир животных, вставляли фитиль из мха или травы и поджигали. Лампа горела тихо и давала тёплый жёлтый свет. При таком свете художники и рисовали быков и лошадей на потолке. Ну а мох и жир всегда были под рукой.", "q": "Чем освещали пещеру художники?", "a": [ "Лампами с жиром и фитилём", "Электрическими фонариками", "Светлячками в банке" ], "sec": "first" }, { "id": "old-egypt-cleopatra", "e": "👑", "t": "Клеопатра и Луна", "s": "Великую пирамиду построили около 4500 лет назад. Царица Клеопатра жила много позже, около 2000 лет назад. А на Луну люди прилетели в 1969 году. Выходит удивительное: Клеопатра жила ближе по времени к высадке на Луну, чем к строительству Великой пирамиды! Для самой Клеопатры пирамиды были такой же глубокой древностью, как для нас её собственные времена. Вот как долго стоят пирамиды!", "q": "Что ближе по времени к Клеопатре?", "a": [ "Высадка людей на Луну", "Рождение динозавров", "Постройка Великой пирамиды" ], "sec": "egypt" }, { "id": "old-egypt-pyramid", "e": "🔺", "t": "Самая высокая в мире", "s": "Великая пирамида в Гизе была задумана как гробница фараона Хеопса. Сначала она была высотой около 146 метров. Её сложили примерно из 2 миллионов 300 тысяч каменных блоков! Больше 3800 лет это было самое высокое сооружение на Земле: никто не мог построить выше. Рекорд побил только собор в Англии, который достроили уже в Средние века. Подумайте: целых 3800 лет рекорд держала куча камней!", "q": "Сколько лет Великая пирамида была самым высоким сооружением на Земле?", "a": [ "Больше трёх тысяч лет", "Всего одну неделю", "Ровно один год" ], "sec": "egypt" }, { "id": "old-egypt-hieroglyphs", "e": "📜", "t": "Камень-переводчик", "s": "Египетские иероглифы — это рисунки-буквы: птичка, глаз, змейка. Потом люди забыли, как их читать, и почти 1500 лет никто не понимал надписей. В 1799 году солдаты нашли Розеттский камень. На нём один и тот же текст записан тремя разными письменами, и одно из них — греческое, которое учёные читали. Через много лет, в 1822 году, француз Шампольон сравнил их и смог прочитать иероглифы. Камень стал настоящим переводчиком!", "q": "Что помогло учёным прочитать иероглифы?", "a": [ "Камень с одним текстом в трёх письменах", "Говорящая мумия", "Волшебная лупа" ], "sec": "egypt" }, { "id": "old-egypt-cats", "e": "🐈", "t": "Кошки — любимцы", "s": "В Древнем Египте кошек очень любили. Они ловили мышей в амбарах, и зерно оставалось целым. Была даже богиня с кошачьей головой по имени Бастет. Египтяне часто лепили кошек из глины и рисовали на стенах. А когда умирала домашняя кошка, хозяева грустили, и, по рассказу Геродота, даже сбривали себе брови. Кошек бережно заворачивали, как мумии. Таких кошачьих мумий нашли очень много.", "q": "За что египтяне особенно любили кошек?", "a": [ "Они ловили мышей и берегли зерно", "Они возили людей на телегах", "Они умели плавать в Ниле на спине" ], "sec": "egypt" }, { "id": "old-egypt-tutankhamun", "e": "🏺", "t": "Мальчик-фараон", "s": "Фараон Тутанхамон стал правителем, когда был совсем ребёнком, лет девяти. Жил он около 3300 лет назад и правил недолго. Его гробницу нашёл в 1922 году англичанин Говард Картер, и она оказалась полна сокровищ: золотая маска, колесницы, кресла, сандалии. Там было несколько тысяч вещей. Для малыша это целая комната игрушек и одежды, которая ждала его очень долго и дождалась учёных.", "q": "Сколько лет было Тутанхамону, когда он стал фараоном?", "a": [ "Около девяти", "Сто двадцать", "Совсем несколько дней" ], "sec": "egypt" }, { "id": "old-egypt-senet", "e": "🎲", "t": "Сенет — настольная игра", "s": "Египтяне любили играть. Одна из любимых игр называлась сенет: доска с тремя рядами клеток по десять штук и фишки. Игроки по очереди кидали палочки, как кубик, и двигали фишки. В гробнице Тутанхамона нашли несколько досок для сенета! Но правила потерялись, и учёные до сих пор спорят, как же играли. Теперь в сенет играют по придуманным правилам. Представьте: игре тысячи лет, а правил никто точно не знает!", "q": "Что кидали в игре сенет вместо кубика?", "a": [ "Палочки", "Маленькие арбузы", "Мячик на верёвке" ], "sec": "egypt" }, { "id": "old-egypt-sphinx", "e": "🦁", "t": "Большой Сфинкс", "s": "Сфинкс в Гизе — это лев с человеческой головой. Он огромный: длиной около 73 метров, как шесть автобусов подряд, и высотой около 20 метров. Его вырубили прямо из скалы, которая тут же, в земле. Столетиями песок засыпал его почти до плеч, и торчала одна голова. Потом песок расчистили, и вновь показались мощные лапы. Сфинкс стоит рядом с пирамидами уже около 4500 лет и всё смотрит вдаль.", "q": "Из чего вырубили Большого Сфинкса?", "a": [ "Из скалы прямо на месте", "Из кусков льда", "Из одного огромного бревна" ], "sec": "egypt" }, { "id": "old-egypt-mummy", "e": "🧻", "t": "Как делали мумии", "s": "Мумия — это тело, которое сохранили на долгие-долгие годы. Египтяне делали это не быстро: примерно 70 дней! Тело высушивали особой солью, которая называется натрон, потом пропитывали душистыми маслами и туго заворачивали в длинные полосы льняной ткани. Ткани уходило столько, что хватило бы на целый ковёр! Египтяне верили, что так человек сможет жить и в другом мире. Мумии стоят в музеях и поныне.", "q": "Сколько примерно дней египтяне делали мумию?", "a": [ "Около семидесяти", "Всего один час", "Ровно одну минуту" ], "sec": "egypt" }, { "id": "old-egypt-toys", "e": "🪀", "t": "Игрушки египетских детей", "s": "Дети Древнего Египта играли так же, как и вы! Для них делали куклы из дерева и ткани, мячи из кожи и тростника, волчки и погремушки. Были игрушки-звери, например, деревянный крокодил или лев, у которых открывалась и закрывалась пасть, если дёрнуть за верёвочку. Такие игрушки нашли в земле через тысячи лет. Значит, и тогда дети любили весёлые игры, а взрослые любили мастерить для них.", "q": "Что умели делать некоторые египетские игрушки-звери?", "a": [ "Открывать и закрывать пасть", "Громко петь песни", "Ездить на колёсиках по дороге с мотором" ], "sec": "egypt" }, { "id": "old-gr-olympia", "e": "🏅", "t": "Первые Олимпийские игры", "s": "По преданию, первые Олимпийские игры устроили в Греции около 2800 лет назад. Проходили они в местечке Олимпия, и не каждый год, а раз в четыре года. Бегуны, борцы и метатели диска съезжались со всех греческих городов. Золотых медалей тогда не было! Победителю надевали на голову венок из веточек оливы. Для грека это была самая большая честь, и дома его встречали как героя.", "q": "Что получал победитель древних Олимпийских игр?", "a": [ "Венок из веточек оливы", "Золотую медаль на ленте", "Корзину мороженого" ], "sec": "greece" }, { "id": "old-gr-marathon", "e": "🏃", "t": "Откуда взялся марафон", "s": "Есть старая легенда. Около 2500 лет назад греки победили врагов в битве возле города Марафон. Гонец по имени Фидиппид побежал в Афины, чтобы скорее рассказать радостную весть: «Мы победили!» Бежал он очень далеко. В память об этой легенде самый длинный бег назвали марафоном. Сегодня его длина — 42 километра 195 метров. Это почти как сорок два раза обойти большой стадион.", "q": "Как назвали длинный бег в память о легенде?", "a": [ "Марафон", "Макарон", "Мармелад" ], "sec": "greece" }, { "id": "old-gr-epidavr", "e": "🎭", "t": "Театр на склоне холма", "s": "Греки любили театр. Около 2300 лет назад в городе Эпидавр построили огромный театр прямо на склоне холма: каменные ряды идут вверх, как гигантская лестница. Там помещалось около 14 тысяч зрителей! Актёры выходили в масках: по маске даже с последнего ряда было видно, кто весёлый, а кто грустный. Театр стоит до сих пор, и летом в нём снова играют спектакли.", "q": "Где стоит древний театр в Эпидавре?", "a": [ "На склоне холма", "На дне озера", "На крыше дворца" ], "sec": "greece" }, { "id": "old-gr-persefona", "e": "🌷", "t": "Миф о Персефоне и временах года", "s": "Греки придумали миф, чтобы объяснить, откуда берётся зима. У богини урожая Деметры была дочка Персефона. Каждый год на несколько месяцев Персефона уходила далеко под землю. Деметра тосковала без дочки, и на земле ничего не росло: наступала зима. А когда Персефона возвращалась, мама радовалась, и приходила весна: всё зеленело и цвело.", "q": "Почему, по греческому мифу, наступает зима?", "a": [ "Деметра тоскует, пока дочки нет", "Зевс забывает включить солнце", "Все медведи засыпают и тянут за собой холод" ], "sec": "greece" }, { "id": "old-gr-antikitera", "e": "⚙️", "t": "Механизм из моря", "s": "В 1901 году ныряльщики за губками нашли у греческого острова Антикитера затонувший корабль. Среди вещей был комок позеленевшей бронзы. Учёные поняли, что внутри — шестерёнки! Это прибор возрастом больше 2000 лет. Он показывал, где на небе Солнце и Луна, подсказывал, когда будет затмение, и даже отсчитывал годы до следующих Олимпийских игр. Часы и календарь в одной коробке.", "q": "Что показывал древний прибор с шестерёнками?", "a": [ "Движение Солнца и Луны и затмения", "Погоду на завтра", "Сколько печенья осталось в кладовой" ], "sec": "greece" }, { "id": "old-gr-alfavit", "e": "🔤", "t": "Слово «алфавит»", "s": "Слово «алфавит» пришло к нам из Греции. Греки около 2800 лет назад стали записывать слова буквами и добавили в письмо буквы для гласных звуков. Первая буква у них называлась «альфа», вторая — «бета». Если их сложить, получится «алфавит». Так что, когда вы учите буквы, вы повторяете слова, которые придумали люди много-много веков назад.", "q": "Из каких двух названий букв сложилось слово «алфавит»?", "a": [ "Альфа и бета", "Эй и би", "Арбуз и банан" ], "sec": "greece" }, { "id": "old-gr-igrushki", "e": "🪀", "t": "Игрушки греческих детей", "s": "Дети в Древней Греции тоже любили играть. Для девочек мастера лепили из глины куклы, у которых двигались руки и ноги. А на одной вазе, нарисованной около 2400 лет назад, мальчик играет с диском на верёвочке: он раскручивает его вверх и вниз, совсем как йо-йо. Ещё греческие дети играли в кости и катали обручи. Игрушки менялись, а радость осталась той же.", "q": "Что было у греческих кукол из глины?", "a": [ "Двигались руки и ноги", "Мигали глаза от батарейки", "Они пели песенки" ], "sec": "greece" }, { "id": "old-rm-kolizey", "e": "🏟️", "t": "Колизей и огромный навес", "s": "Колизей в Риме открыли около 2000 лет назад, в 80 году. Это огромный круглый стадион, где помещалось около 50 тысяч зрителей. А чтобы им не пекло солнце, над трибунами натягивали гигантский холщовый навес. Считается, что тянули его моряки: они умели работать с парусами и канатами. Выходит, у римлян над стадионом был настоящий парус вместо крыши.", "q": "Что римляне натягивали над Колизеем в жару?", "a": [ "Огромный холщовый навес", "Ледяной купол", "Зонтики для каждого зрителя" ], "sec": "rome" }, { "id": "old-rm-dorogi", "e": "🛣️", "t": "Дороги, которые живут тысячи лет", "s": "Римляне строили дороги так крепко, что некоторые служат до сих пор. Самая известная — Аппиева дорога, её начали строить больше 2300 лет назад. Сначала копали канаву, потом насыпали слои камней и песка, а сверху клали большие плоские плиты. Вода с такой дороги стекала в стороны. Поэтому говорят: «Все дороги ведут в Рим». И сегодня по старым плитам можно пройтись пешком.", "q": "Что римляне клали сверху на дорогу?", "a": [ "Большие плоские каменные плиты", "Мягкие подушки", "Деревянные лыжи" ], "sec": "rome" }, { "id": "old-rm-akveduk", "e": "🌉", "t": "Водопровод на высоких арках", "s": "В Риме не было кранов, но воду в город привозили издалека: по каменным трубам и каналам, которые шли чуть-чуть под уклон. Вода текла сама, без насосов, ведь вода всегда стремится вниз. Чтобы канал не прерывался над долинами, римляне строили высокие арки. Один такой мост, Пон-дю-Гар во Франции, высотой почти 50 метров, стоит уже около 2000 лет.", "q": "Как вода текла по римскому водопроводу?", "a": [ "Сама, потому что канал шёл под уклон", "Её качали гигантскими вёдрами", "Её несли в кувшинах по цепочке" ], "sec": "rome" }, { "id": "old-rm-piramida", "e": "🔺", "t": "Пирамида посреди Рима", "s": "В Риме стоит настоящая пирамида! Её построили около 2000 лет назад для богатого римлянина Гая Цестия. Он любил Египет и в завещании велел сделать себе такую гробницу. Построить её нужно было быстро: надпись говорит, что хватило 330 дней, меньше года. Высота пирамиды — около 36 метров, как у двенадцатиэтажного дома. А позже её даже включили в городскую стену.", "q": "За сколько дней, по надписи, построили римскую пирамиду?", "a": [ "За 330 дней", "За три дня", "За сто лет" ], "sec": "rome" }, { "id": "old-rm-termopolii", "e": "🍲", "t": "Быстрая еда в Помпеях", "s": "В городе Помпеи на улицах были лавки быстрой еды, их называли термополиями. Прилавок с круглыми отверстиями, а в них вделаны большие горшки с горячей едой. Недавно археологи откопали такую лавку целиком. На прилавке нарисованы утки и петух. Учёные думают, что это было вместо меню: что нарисовано, то и продавали. Остатки костей в горшках это подтверждают.", "q": "Что нарисовали на прилавке помпейской лавки?", "a": [ "Уток и петуха, как меню", "Космический корабль", "Таблицу умножения" ], "sec": "rome" }, { "id": "old-rm-beton", "e": "🏛️", "t": "Римский бетон и Пантеон", "s": "Римляне придумали очень прочный бетон из извести, вулканического песка и камней. Из него построили Пантеон — храм с огромным куполом шириной около 43 метров. Купол без железа стоит уже около 1900 лет и до сих пор остаётся самым большим в мире куполом из такого бетона. А в самой его середине — круглое отверстие, через которое заглядывает небо. Учёные даже думают, что трещинки в таком бетоне умеют зарастать сами.", "q": "Что находится в самой середине купола Пантеона?", "a": [ "Круглое отверстие, открытое небу", "Огромная люстра", "Стеклянная лампа-шар" ], "sec": "rome" }, { "id": "old-rm-teplyj-pol", "e": "♨️", "t": "Тёплый пол по-римски", "s": "Римляне не мёрзли даже зимой в богатых домах и банях. Пол у них стоял на низких кирпичных столбиках, а под ним в печи разжигали огонь. Горячий воздух гулял в пустоте под полом и по трубам в стенах. Такую систему назвали гипокаустом. Выходит, тёплый пол придумали не недавно, а больше 2000 лет назад. Только топить печь приходилось вручную.", "q": "Что находилось под полом римского дома с гипокаустом?", "a": [ "Столбики и горячий воздух", "Бассейн с рыбками", "Мягкие ковры" ], "sec": "rome" }, { "id": "old-rm-priglashenie", "e": "💌", "t": "Приглашение на день рождения", "s": "Около 100 года в римском форте Виндоланда, на севере Британии, жила женщина по имени Клавдия Севера. Она написала подруге Сульпиции Лепидине приглашение на свой день рождения. Писала чернилами на тонкой деревянной дощечке. А в конце своей рукой добавила: «Я буду ждать тебя, сестра». Дощечка сохранилась до наших дней, и мы можем прочитать самое старое приглашение на праздник.", "q": "На чём римлянка написала приглашение на день рождения?", "a": [ "На тонкой деревянной дощечке", "На открытке с котиком", "На листе бумаги из тетради" ], "sec": "rome" }, { "id": "old-rm-mesyatsy", "e": "📅", "t": "Месяцы в честь римлян", "s": "Римляне оставили нам названия месяцев. Июль назвали в честь Юлия Цезаря, а август — в честь императора Августа. А ещё у римлян год раньше начинался с марта. Поэтому сентябрь, «септем» по-латински, значит «седьмой», хотя сейчас это девятый месяц. Так что, когда вы называете месяц, вы говорите по-римски.", "q": "В честь кого назвали месяц июль?", "a": [ "В честь Юлия Цезаря", "В честь повара Юлика", "В честь римского осла" ], "sec": "rome" }, { "id": "old-china-wall-rice", "e": "🧱", "t": "Стена с рисовой кашей", "s": "Великая Китайская стена строилась много веков, а её каменные участки времён династии Мин появились около шестисот лет назад. Мастера придумали хитрый секрет: в строительный раствор они добавляли клейкий рис. Рис варили в густую кашу и смешивали с известью. Раствор становился прочнее и хуже пропускал воду. Поэтому многие части стены стоят до сих пор, хотя по ним шли дожди и зимние ветры.", "q": "Что строители добавляли в раствор для прочности?", "a": [ "Кашу из клейкого риса", "Малиновое варенье", "Взбитые сливки" ], "sec": "china" }, { "id": "old-china-silk-thread", "e": "🐛", "t": "Шёлк из одной нитки", "s": "Шёлк делают гусеницы, которых называют шелкопрядами. Они едят листья тутового дерева, а потом заворачиваются в кокон. Самое удивительное: кокон сделан из одной-единственной нитки, и она тянется на сотни метров! В Древнем Китае люди научились разматывать коконы и ткать из этих ниток нежную блестящую ткань. Китайцы много лет хранили секрет шёлка, и ткань возили в далёкие страны по Великому шёлковому пути.", "q": "Из чего состоит кокон шелкопряда?", "a": [ "Из одной очень длинной нитки", "Из сотни маленьких перьев", "Из застывшего мёда" ], "sec": "china" }, { "id": "old-china-paper", "e": "📜", "t": "Бумага из тряпок", "s": "Раньше китайцы писали на полосках бамбука и на шёлке. Бамбук был тяжёлым, а шёлк очень дорогим. Около двух тысяч лет назад в Китае научились делать бумагу. Тряпки, кору деревьев и старые рыболовные сети размачивали и разминали в кашицу. Потом кашицу тонким слоем выливали на сито и сушили. Получался лёгкий дешёвый лист, на котором удобно писать. Часто изобретение бумаги связывают с именем придворного Цай Луня.", "q": "Из чего древние китайцы делали бумагу?", "a": [ "Из тряпок, коры и старых сетей", "Из сухих бабочек", "Из камней и песка" ], "sec": "china" }, { "id": "old-china-terracotta", "e": "🗿", "t": "Глиняная армия", "s": "В 1974 году китайские крестьяне копали колодец недалеко от города Сиань и нашли в земле глиняную голову. Так открыли целую армию из глины! Её сделали около двух тысяч двухсот лет назад для императора Цинь Шихуана. Солдат там тысячи, ростом они почти как настоящие люди. Лица у воинов разные: у одних усы, у других строгий взгляд. А ещё раньше фигуры были раскрашены яркими красками.", "q": "Как нашли глиняную армию?", "a": [ "Крестьяне копали колодец", "Дети строили песочный замок", "Рыбак вытащил её сетью" ], "sec": "china" }, { "id": "old-china-kites", "e": "🪁", "t": "Первые воздушные змеи", "s": "Воздушных змеев придумали в Китае больше двух тысяч лет назад. Тогда их делали из лёгкого шёлка и тонких бамбуковых палочек, а бумага появилась позже. Змеи были не только игрушкой: с ними устраивали праздники, а на огромных змеев вешали рисунки драконов и птиц. Сейчас змеев запускают на всех континентах. Но самые первые полетели над китайскими полями, привязанные к длинной шёлковой нитке.", "q": "Из чего делали первых воздушных змеев?", "a": [ "Из шёлка и бамбука", "Из железа и стекла", "Из листьев капусты" ], "sec": "china" }, { "id": "old-knights-slits", "e": "🏰", "t": "Окна-щёлочки", "s": "В стенах замков были очень узкие окна-щёлочки. Они назывались бойницами. Снаружи щель такая тонкая, что в неё трудно попасть стрелой. А внутри она расширялась, и лучнику хватало места, чтобы встать и прицелиться. Ещё узкие окна не пускали в замок холодный ветер. Зато внутри было темно, поэтому в замке зажигали свечи и факелы даже днём.", "q": "Как выглядели бойницы в стенах замка?", "a": [ "Узкие снаружи и шире внутри", "Круглые и огромные, как колёса", "Все из разноцветного стекла" ], "sec": "knights" }, { "id": "old-knights-armour", "e": "🛡️", "t": "Сколько весили доспехи", "s": "Многие думают, что рыцарь в латах еле двигался. На самом деле полный доспех весил около двадцати–двадцати пяти килограммов — как школьный ребёнок. Но его делали по фигуре, и вес распределялся по всему телу, а не лежал на плечах. Мастера собирали доспех из множества пластин, поэтому рыцарь мог сгибать руки и ноги и даже сам садился на коня. Части доспеха двигались на заклёпках и ремешках.", "q": "Как делали доспех, чтобы в нём можно было двигаться?", "a": [ "Из множества подвижных пластин", "Из одного цельного куска камня", "Из мягких одеял" ], "sec": "knights" }, { "id": "old-knights-page", "e": "⚔️", "t": "Как мальчик становился рыцарем", "s": "Рыцарями не рождались, этому долго учились. Мальчика часто в семь лет отправляли в замок другого господина, и он становился пажом. Паж прислуживал за столом, носил поручения и учился хорошим манерам. Подросшего юношу брали оруженосцем: он ухаживал за конём, чистил доспехи и учился владеть мечом и копьём. Только лет в двадцать с небольшим его посвящали в рыцари. Учёба занимала целых четырнадцать лет.", "q": "Кем сначала становился мальчик, которого учили на рыцаря?", "a": [ "Пажом", "Королём", "Кузнецом драконов" ], "sec": "knights" }, { "id": "old-knights-tournament", "e": "🏇", "t": "Турнир — праздник для всех", "s": "Рыцарские турниры были похожи на большой праздник. Съезжались гости, играли музыканты, торговцы продавали сладости и ленты. Рыцари скакали навстречу друг другу и пытались копьём выбить соперника из седла. Чтобы никого не ранить, на концы копий надевали тупые наконечники, а сами копья делали из дерева и они ломались с громким треском. Зрители кричали и махали платками. Победитель получал награду и славу.", "q": "Что надевали на концы копий, чтобы не ранить соперника?", "a": [ "Тупые наконечники", "Мягкие игрушки", "Лепестки роз" ], "sec": "knights" }, { "id": "old-knights-drawbridge", "e": "🌉", "t": "Мост, который поднимается", "s": "Вокруг многих замков выкапывали глубокий ров и иногда наполняли его водой. Через ров к воротам вёл подъёмный мост. Днём его опускали, и по нему въезжали телеги и гости. А когда приближалась опасность, стражники тянули за толстые цепи или верёвки, и мост поднимался вверх. Он закрывал ворота, как большая деревянная дверь. Перейти ров без моста было непросто, поэтому в замке чувствовали себя спокойно.", "q": "Что делали с подъёмным мостом при опасности?", "a": [ "Поднимали вверх на цепях", "Красили в зелёный цвет", "Отправляли гулять" ], "sec": "knights" }, { "id": "old-knights-toilet", "e": "🧣", "t": "Тёплый камень и холодный ветер", "s": "В каменном замке было прохладно, даже когда горел огромный камин. Чтобы стало теплее, на стены вешали толстые ковры и гобелены, а на пол стелили солому с душистыми травами. Уборная в замке была простой: маленькая комнатка в толще стены с дыркой, выходившей наружу. Зимой сквозняк был ледяной, и никто там не засиживался! Зато комнатку строили у самой стены, подальше от пиршественного зала.", "q": "Чем согревали холодные каменные стены замка?", "a": [ "Вешали на них ковры и гобелены", "Обклеивали шоколадом", "Накрывали большим одеялом из облаков" ], "sec": "knights" }, { "id": "old-knights-heraldry", "e": "🦁", "t": "Герб — подпись рыцаря", "s": "Шлем закрывал рыцарю лицо, и в бою друзей было трудно отличить от чужих. Поэтому рыцари стали рисовать знаки на щитах и одежде. Так появились гербы. На гербе могли быть лев, орёл, башня или цветок, и у каждого рода был свой рисунок. Герб часто передавали детям. Глядя на щит, люди сразу узнавали, кто этот всадник. Многие города и страны до сих пор хранят старинные гербы.", "q": "Зачем рыцарям понадобились гербы?", "a": [ "Чтобы узнавать рыцаря в закрытом шлеме", "Чтобы щит был тяжелее", "Чтобы кормить на нём птиц" ], "sec": "knights" }, { "id": "old-vik-longship", "e": "⛵", "t": "Корабль-дракон", "s": "Викинги плавали на длинных узких кораблях. На носу у некоторых сидела резная голова дракона. Дно у корабля было неглубокое, поэтому он мог заходить не только в море, но и в мелкие реки. А если путь преграждала суша, викинги вытаскивали корабль на берег и тащили по брёвнам к другой реке. Вот так лодка шагала по земле! Парус был один, большой, а когда ветра не было, брались за вёсла.", "q": "Что делали викинги, если на пути оказывалась суша между реками?", "a": [ "Тащили корабль по земле на брёвнах", "Ждали, пока река сама приплывёт", "Разбирали корабль и несли в рюкзаках" ], "sec": "vikings" }, { "id": "old-vik-horns", "e": "🪖", "t": "Шлем без рогов", "s": "Ты, наверное, видел картинки: викинг в шлеме с большими рогами. Но на самом деле таких шлемов у них не было! Рога бы мешали в тесной лодке и цеплялись за ветки. Шлем викинга был простой, круглый, с защитой для носа. Рогатые шлемы придумали художники и театр примерно полтора века назад, для красивых костюмов в опере. А настоящий шлем викинга нашли в Норвегии. Он гладкий, совсем без рогов.", "q": "Были ли у викингов шлемы с рогами?", "a": [ "Нет, рога придумали художники и театр", "Да, рогами они пугали коров", "Да, в рогах они носили воду" ], "sec": "vikings" }, { "id": "old-vik-runes", "e": "🪨", "t": "Руны и «Здесь был Халфдан»", "s": "Буквы у викингов назывались рунами. Они были из прямых палочек, потому что их легко вырезать ножом на дереве или камне. Руны писали на больших камнях, чтобы помнить о людях. А ещё викинги любили оставлять надписи на память. В огромном соборе Святой Софии в городе Стамбуле на каменных перилах до сих пор видна руническая надпись. Историки считают, что её оставил кто-то из викингов, и там написано имя Халфдан.", "q": "Почему руны состоят из прямых палочек?", "a": [ "Их легко вырезать ножом на дереве и камне", "Их рисовали линейкой", "Так красивее выглядят на парусе" ], "sec": "vikings" }, { "id": "old-vik-america", "e": "🌎", "t": "Кто приплыл в Америку первым", "s": "За пятьсот лет до Колумба в Америку приплыли викинги! Их вёл Лейф Эрикссон, около тысячного года. Он увидел берег с лесом и диким виноградом и назвал его Винланд, то есть «земля винограда». Учёные нашли в Канаде, на острове Ньюфаундленд, остатки домиков викингов. А по годовым кольцам брёвен выяснили, что деревья там срубили металлическим топором в 1021 году.", "q": "Как Лейф Эрикссон назвал найденную землю?", "a": [ "Винланд, земля винограда", "Яблоневая гора", "Остров рыбьих хвостов" ], "sec": "vikings" }, { "id": "old-vik-weekdays", "e": "🔨", "t": "Дни недели от богов", "s": "Знаешь, откуда английские названия дней недели? От богов викингов! Вторник по-английски Tuesday — день бога Тюра. Среда, Wednesday, — день Одина, главного бога. Четверг, Thursday, — день Тора, который бил молотом и вызывал гром. А пятница, Friday, — день богини Фригг. Так что, когда англичане говорят «в четверг», они вспоминают громовержца с молотом.", "q": "Чей день — четверг, Thursday, по-английски?", "a": [ "Тора, бога с молотом и громом", "Тюра, который любил кашу", "Одина, который не любил ездить на санках" ], "sec": "vikings" }, { "id": "old-vik-combs", "e": "🪮", "t": "Чистюли-викинги", "s": "Викингов часто рисуют грязными и лохматыми, но это неправда. Они любили чистоту! Археологи находят у них много гребней из оленьего рога и кости, часто в красивых футлярах. А ещё пинцеты и крошечные ложечки для чистки ушей. В Исландии субботу до сих пор называют «днём мытья»: по субботам викинги мылись в тёплой воде. Так что аккуратно причёсанный викинг — это вполне настоящий викинг.", "q": "Из чего делали гребни викинги?", "a": [ "Из оленьего рога и кости", "Из сосулек", "Из хлебной корки" ], "sec": "vikings" }, { "id": "old-vik-rurik", "e": "👑", "t": "Зов к викингам", "s": "Давным-давно, около тысячи ста лет назад, славяне и другие племена на севере спорили, кто будет у них главным. Тогда, как рассказывает летопись, они послали за море гонцов к варягам с такими словами: «Земля наша велика и обильна, а порядка в ней нет. Приходите править нами». Пришёл варяг по имени Рюрик. Он поселился в Ладоге, а потом в Новгороде. Так начинается Древняя Русь.", "q": "К кому славяне послали за море гонцов, по рассказу летописи?", "a": [ "К варягам", "К драконам", "К морским черепахам" ], "sec": "vikings" }, { "id": "old-rus-onfim", "e": "🖍️", "t": "Мальчик Онфим", "s": "Около семисот пятидесяти лет назад в Новгороде жил мальчик Онфим. Ему было лет шесть или семь, и он ходил в школу. Онфим учил буквы и царапал их на кусочках бересты, а ещё рисовал: рыцаря на коне, который побеждает врага, и страшного зверя. Под зверем подписал: «Я зверь». Эти листочки лежали в земле почти семь веков, и археологи нашли их. Теперь мы видим, как мальчик из давних времён любил рисовать.", "q": "Что делал на бересте мальчик Онфим?", "a": [ "Учил буквы и рисовал картинки", "Варил кашу", "Строил лодки" ], "sec": "rus" }, { "id": "old-rus-bereste", "e": "📜", "t": "Письма на коре", "s": "В Древней Руси бумаги не было. Писали на бересте, то есть на коре берёзы. Только не чернилами, а острой костяной или железной палочкой, писалом: буквы не рисовали, а выцарапывали. В 1951 году в Новгороде археологи нашли первую такую грамоту. Земля там сырая, глинистая, и береста не сгнила. Сейчас найдено больше тысячи берестяных грамот. В них люди передавали приветы, просили в долг, звали в гости, и даже писали шутки.", "q": "Чем писали на бересте в Древней Руси?", "a": [ "Острой палочкой, выцарапывали буквы", "Фломастером", "Куриным пером с чернилами из ягод" ], "sec": "rus" }, { "id": "old-rus-street", "e": "🪵", "t": "Деревянные улицы", "s": "Новгород стоял на болотистой земле, и по ней трудно ходить после дождя. Поэтому жители замостили улицы брёвнами. Сначала клали в основу длинные брёвна, а сверху пол из половинок брёвен, плоской стороной вверх. Когда мостовая гнила, делали новую прямо сверху. Археологи, копая землю, нашли много слоёв старых деревянных мостовых, одна на другой, как слоёный пирог. Самые старые лежат под землёй уже около тысячи лет.", "q": "Из чего были сделаны улицы Новгорода?", "a": [ "Из брёвен", "Из пряников", "Из гладкого стекла" ], "sec": "rus" }, { "id": "old-rus-anna", "e": "👸", "t": "Королева из Киева", "s": "Ярослав Мудрый правил в Киеве около тысячи лет назад. У него была дочка Анна. Её выдали замуж за короля Франции, и она стала французской королевой. В Киеве она училась читать и писать, а во Франции многие вельможи этого не умели. Под одной из французских грамот сохранилась подпись Анны русскими буквами. Историки читают её как «Ана ръина»: «Анна королева». Две другие дочери Ярослава тоже стали королевами в других странах.", "q": "Какими буквами подписалась королева Анна во Франции?", "a": [ "Русскими, славянскими буквами", "Только крестиками", "Картинками с яблоками" ], "sec": "rus" }, { "id": "old-rus-byliny", "e": "🎶", "t": "Песни про богатырей", "s": "О богатырях Илье Муромце, Добрыне Никитиче и Алёше Поповиче рассказывали не просто так, а пели нараспев. Эти старинные песни-рассказы мы называем былинами. Но сами сказители говорили «старина», то есть то, что было давно. А слово «былина» учёные придумали и стали использовать совсем недавно, около двухсот лет назад. Былины долго передавали из уст в уста, пока их не записали.", "q": "Как былины передавали много лет, пока их не записали?", "a": [ "Пели и рассказывали из уст в уста", "Присылали по почте", "Вырезали на облаках" ], "sec": "rus" }, { "id": "old-rus-bortniki", "e": "🐝", "t": "Бортники и дикие пчёлы", "s": "Мёд на Руси добывали у диких пчёл. Люди, которых звали бортниками, находили в лесу толстое дерево с дуплом или выдалбливали дупло сами. Пчёлы поселялись там и делали мёд. Дупло могло быть очень высоко, метров десять от земли. Бортник лез на дерево, привязавшись верёвкой, и брал мёд осторожно, чтобы пчёлам хватило на зиму. Мёд был главной сладостью: сахара тогда не знали.", "q": "Как называли людей, добывавших мёд диких пчёл из дупла?", "a": [ "Бортниками", "Мёдоедами", "Жужжалами" ], "sec": "rus" } ], "space": [ { "id": "sp-sputnik", "e": "🛰️", "t": "Бип-бип из космоса", "s": "4 октября 1957 года в небо поднялась ракета и вынесла за облака первый в мире спутник. Он был совсем небольшой — блестящий шар с четырьмя длинными усами-антеннами. Спутник летел вокруг Земли и посылал сигнал: «бип-бип-бип». Люди во многих странах включали радио и слушали, как звучит космос. Спутник облетал Землю примерно за полтора часа. С него началась космическая эра.", "q": "Какой сигнал посылал первый спутник?", "a": [ "Бип-бип", "Ку-ку", "Динь-дон" ] }, { "id": "sp-belka-strelka", "e": "🐕", "t": "Белка и Стрелка", "s": "19 августа 1960 года в космос полетели две собаки — Белка и Стрелка. С ними были мыши, насекомые и даже растения. Корабль облетел Землю 17 раз, а потом мягко приземлился, и все вернулись домой здоровыми. Белка и Стрелка стали знаменитыми на весь мир. А у Стрелки потом родились щенки. Одного щенка, которого звали Пушинка, подарили в Америке семье президента Кеннеди, и он жил у них дома.", "q": "Как звали щенка Стрелки, которого подарили семье Кеннеди?", "a": [ "Пушинка", "Снежинка", "Белочка" ] }, { "id": "sp-gagarin", "e": "🚀", "t": "«Поехали!»", "s": "12 апреля 1961 года Юрий Гагарин стал первым человеком в космосе. Он родился в деревне, а в детстве мечтал о самолётах. Корабль назывался «Восток». Перед стартом Гагарин весело сказал: «Поехали!» Он облетел вокруг Земли один раз, и весь полёт занял 108 минут. Из космоса он увидел нашу планету и сказал, что она голубая. Потом он благополучно вернулся на Землю.", "q": "Что сказал Гагарин перед стартом?", "a": [ "Поехали!", "Полетели!", "Привет!" ] }, { "id": "sp-den-kosmonavtiki", "e": "🎈", "t": "День космонавтики", "s": "Каждый год 12 апреля в нашей стране отмечают День космонавтики. Это день, когда полетел Гагарин. В школах и садиках рисуют ракеты и звёзды, а дети мастерят шлемы из бумаги и играют в космонавтов. Космонавты и инженеры рассказывают, как устроены корабли. В этот день хорошо выйти вечером на улицу, посмотреть на небо и подумать: а что там дальше, за звёздами?", "q": "Какого числа и месяца отмечают День космонавтики?", "a": [ "12 апреля", "1 июня", "9 мая" ] }, { "id": "sp-tereshkova", "e": "🕊️", "t": "Чайка летит", "s": "Валентина Терешкова выросла у реки Волги. Она работала на фабрике и в свободное время прыгала с парашютом. 16 июня 1963 года Валентина стала первой в мире женщиной-космонавтом. Её позывной был «Чайка». Она летала почти трое суток, облетела Землю 48 раз и смотрела на планету в иллюминатор. Валентина фотографировала горизонт, а потом благополучно вернулась домой.", "q": "Какой позывной был у Терешковой?", "a": [ "Чайка", "Ласточка", "Звёздочка" ] }, { "id": "sp-leonov", "e": "🎨", "t": "Космонавт с карандашами", "s": "Алексей Леонов любил рисовать с детства. 18 марта 1965 года он первым в мире вышел из корабля в открытый космос. Он больше десяти минут плавал рядом с кораблём на длинном тросе, а внизу медленно проплывала Земля. Скафандр немного раздулся, как шарик, но Леонов справился и вернулся. А потом он взял цветные карандаши и нарисовал то, что видел: восход Солнца над Землёй.", "q": "Что нарисовал Леонов после полёта?", "a": [ "Восход Солнца над Землёй", "Своего друга-собаку", "Большой дом" ] }, { "id": "sp-ciolkovsky", "e": "🔭", "t": "Мечтатель из Калуги", "s": "Константин Циолковский жил в городе Калуге. В детстве он заболел и почти перестал слышать, поэтому не мог учиться в обычной школе. Но он много читал, считал и придумывал. Циолковский первым подробно рассказал, как ракета может долететь до космоса. Он писал книги о полётах к звёздам, когда ещё не было ни одной ракеты. Люди слушали его и улыбались, а потом его мечта сбылась.", "q": "В каком городе жил Циолковский?", "a": [ "В Калуге", "В Москве", "В Казани" ] }, { "id": "sp-korolev", "e": "📐", "t": "Главный конструктор", "s": "Сергей Королёв был главным конструктором. Это человек, который вместе с большой командой придумывает ракеты и корабли. Он с юности увлёкся самолётами и ракетами. Ракеты Королёва вынесли в космос первый спутник и Гагарина. Имя главного конструктора долго не называли, и о нём знали не все. Зато он знал каждый винтик в своих ракетах, а рядом с ним работали тысячи инженеров.", "q": "Кем был Сергей Королёв?", "a": [ "Главным конструктором ракет", "Капитаном корабля", "Лесником" ] }, { "id": "sp-baikonur", "e": "🏜️", "t": "Байконур", "s": "Байконур — это космодром, место, откуда стартуют ракеты. Он стоит в степи в Казахстане, где много солнца и ровной земли. Ракету привозят на поезде. Она едет лёжа, а потом на стартовой площадке её поднимают, и она встаёт вертикально, готовая к полёту. Отсюда улетели первый спутник и Гагарин. Космонавты и сегодня стартуют с Байконура.", "q": "Как ракету привозят на космодром?", "a": [ "На поезде, лёжа", "На лодке", "Она летит сама" ] }, { "id": "sp-armstrong", "e": "👣", "t": "Следы на Луне", "s": "20 июля 1969 года американский корабль «Аполлон-11» прилунился. Нил Армстронг спустился по лесенке и сказал: «Маленький шаг для человека — огромный скачок для всех людей». Так он стал первым человеком на Луне. Вместе с ним по лунной пыли ходил Базз Олдрин. Они собирали камни и ставили приборы. На Луне нет ни ветра, ни дождя, и следы там не стираются. Они могут остаться очень надолго.", "q": "Почему следы на Луне не стираются?", "a": [ "Там нет ветра и дождя", "Их убирают роботы", "Там всегда снег" ] }, { "id": "sp-lunohod", "e": "🚙", "t": "Луноход", "s": "17 ноября 1970 года по Луне поехал «Луноход-1». Это была машина на восьми колёсах, а сверху у неё была крышка, как у кастрюли. Водителей в ней не было. Ими были люди на Земле. Они смотрели на телевизионные картинки с Луны и нажимали кнопки. Луноход ехал медленно и осторожно, объезжал камни и ямы. Он проработал около одиннадцати месяцев и проехал больше десяти километров.", "q": "Кто управлял Луноходом?", "a": [ "Люди на Земле", "Космонавты внутри", "Лунные жители" ] }, { "id": "sp-skafandr", "e": "🧑‍🚀", "t": "Скафандр", "s": "Скафандр — это космический костюм, и он похож на маленький космический домик, в который можно залезть. В космосе нет воздуха, и очень сильно меняется температура. Поэтому в скафандре есть воздух для дыхания, а в шлеме — особое стекло, которое защищает глаза от яркого Солнца. Под костюмом космонавт надевает специальное бельё с тонкими трубочками, по ним течёт прохладная вода. Перчатки у скафандра толстые, но в них можно держать инструменты.", "q": "Для чего в скафандре воздух?", "a": [ "Чтобы космонавт мог дышать", "Чтобы он был круглым", "Чтобы он плавал" ] }, { "id": "sp-eda", "e": "🥫", "t": "Что едят космонавты", "s": "Раньше космонавты ели из тюбиков, как зубную пасту, только вкусно: суп, пюре и даже сок. Сейчас у них есть и обычные блюда в упаковках. Хлеб космонавты берут редко, потому что от него бывают крошки. В невесомости крошки не падают, а парят в воздухе и могут попасть в глаза или в приборы. Поэтому космонавты едят аккуратно и закрывают упаковки.", "q": "Почему в космосе опасны крошки?", "a": [ "Они парят в воздухе", "Они очень горячие", "Они громко шумят" ] }, { "id": "sp-nevesomost", "e": "🛌", "t": "Сон и умывание в невесомости", "s": "В невесомости нет «верха» и «низа», поэтому космонавты спят в спальных мешках, привязанных к стене. Руки у спящего иногда плавают перед ним. Умываются космонавты по-особому: вода в космосе не стекает, а собирается в шарики. Поэтому они пользуются мокрыми полотенцами и влажными салфетками. Зубную пасту после чистки зубов можно аккуратно вытереть салфеткой.", "q": "Где спят космонавты в невесомости?", "a": [ "В спальных мешках у стены", "В кроватях с одеялами", "На потолке без мешка" ] }, { "id": "sp-mks", "e": "🛰️", "t": "Космический дом", "s": "Международная космическая станция — это огромный дом, который летит над Землёй. Там по очереди живут космонавты из разных стран. Станция облетает Землю примерно за полтора часа, поэтому за сутки они видят около шестнадцати рассветов. Если небо ясное, станцию можно увидеть и с Земли. Это яркая точка, которая быстро движется по небу и не мигает. Помашите ей, когда увидите!", "q": "Как выглядит станция, если смотреть на неё с Земли?", "a": [ "Как яркая движущаяся точка", "Как большая луна", "Как падающий снег" ] }, { "id": "sp-galilei", "e": "🔭", "t": "Галилей и подзорная труба", "s": "Давным-давно, в 1609 году, учёный Галилео Галилей сделал подзорную трубу и посмотрел ночью на небо. Он увидел горы на Луне! А рядом с Юпитером — четыре маленькие звёздочки. Это оказались спутники Юпитера. Каждую ночь они стояли чуть по-другому: значит, кружились вокруг планеты. Галилей зарисовал всё в тетради и показал людям. Так начались наблюдения за небом в телескоп.", "q": "Что Галилей увидел на Луне?", "a": [ "Горы", "Моря с рыбами", "Города" ] }, { "id": "sp-hubble", "e": "🛰️", "t": "Телескоп «Хаббл»", "s": "Телескоп «Хаббл» летает вокруг Земли высоко над облаками и воздухом. Оттуда звёзды видно очень чётко, ведь воздух им не мешает. Его запустили в 1990 году, и он назван в честь учёного Эдвина Хаббла. Телескоп сделал тысячи снимков: далёкие планеты, облака пыли и огромные звёздные острова. Фотографии «Хаббла» похожи на яркие картины. Многие из них висят в музеях и книгах.", "q": "Где летает телескоп «Хаббл»?", "a": [ "Вокруг Земли, высоко над воздухом", "На вершине горы", "На Луне" ] }, { "id": "sp-webb", "e": "🌟", "t": "Телескоп «Джеймс Уэбб»", "s": "У телескопа «Джеймс Уэбб» золотое зеркало. Оно состоит из восемнадцати шестиугольных кусочков, а сверху покрыто тонким слоем золота: так оно лучше ловит свет далёких звёзд. Телескоп запустили на Рождество 2021 года. Он летает намного дальше Луны, в полутора миллионах километров от Земли. Там у него есть большой щит от солнечных лучей. Уэбб смотрит на самые далёкие и древние звёзды.", "q": "Какого цвета зеркало у телескопа «Джеймс Уэбб»?", "a": [ "Золотого", "Красного", "Зелёного" ] }, { "id": "sp-halley", "e": "☄️", "t": "Комета Галлея", "s": "Комета — это большой ком льда и пыли. Когда она подлетает к Солнцу, лёд нагревается и вокруг неё появляется светлый хвост. Хвост всегда направлен от Солнца, как лёгкий дымок на ветру. Самую известную комету назвали в честь учёного Галлея. Она возвращается к Земле примерно раз в семьдесят шесть лет. Последний раз её видели в 1986 году, а в следующий раз увидят в 2061-м.", "q": "Как часто возвращается комета Галлея?", "a": [ "Примерно раз в 76 лет", "Каждый год", "Каждую неделю" ] }, { "id": "sp-meteors", "e": "🌠", "t": "Падающие звёзды", "s": "Иногда ночью по небу быстро пролетает светлая чёрточка. Люди зовут её падающей звездой, но это не звезда. Это метеор: крошечная песчинка из космоса влетает в воздух Земли и ярко вспыхивает высоко над нами. Она сгорает, не долетев до земли. Особенно много их бывает в августе, этот звёздный дождь называют персеидами. Есть добрая примета: успей загадать желание, пока линия не погасла!", "q": "Чем на самом деле является падающая звезда?", "a": [ "Крошечной песчинкой, которая вспыхнула в воздухе", "Большой звездой", "Огоньком от самолёта" ] }, { "id": "sp-meteorites", "e": "🪨", "t": "Камни с неба", "s": "Иногда космический камень долетает до земли. Такой камень называют метеоритом. Он тёмный, тяжёлый, часто с гладкими ямками на боках, будто его кто-то лепил пальцами. Многие метеориты состоят из железа, поэтому к ним прилипает магнит. Самый большой найденный железный метеорит лежит в Намибии, в Африке, и весит около шестидесяти тонн. Его не увезли: он так и лежит на месте, и к нему приезжают смотреть.", "q": "К чему прилипает железный метеорит?", "a": [ "К магниту", "К воде", "К луне" ] }, { "id": "sp-sun-star", "e": "☀️", "t": "Солнце — тоже звезда", "s": "Солнце — это звезда, такая же, как ночные звёзды. Просто оно к нам ближе всех, поэтому светит так ярко и греет. Свет от Солнца летит до Земли около восьми минут. Оно огромное: в него поместилось бы больше миллиона таких планет, как наша. Это шар из очень горячего газа. Днём яркое Солнце затмевает остальные звёзды, и мы видим только голубое небо.", "q": "Почему Солнце светит ярче других звёзд?", "a": [ "Оно ближе всех к нам", "Оно больше всех звёзд на свете", "Оно красное" ] }, { "id": "sp-star-colors", "e": "🌈", "t": "Разноцветные звёзды", "s": "Если приглядеться, звёзды разного цвета. Одни белые, другие голубоватые, третьи жёлтые или оранжевые, а есть и красноватые. Цвет рассказывает, какая звезда горячая. Голубые звёзды самые горячие, жёлтые, как наше Солнце, горячие поменьше, а красные звёзды холоднее всех. Это как с костром: самое горячее пламя — синеватое, а тлеющие угольки красные. Попробуй найти на небе красноватую звезду!", "q": "Какие звёзды самые горячие?", "a": [ "Голубые", "Красные", "Оранжевые" ] }, { "id": "sp-constellations", "e": "🐻", "t": "Картинки из звёзд", "s": "Давным-давно люди соединяли звёзды воображаемыми линиями и получались картинки. Их назвали созвездиями. Есть Лев, Лебедь, Скорпион и Большая Медведица. В ней семь ярких звёзд складываются в большой ковш с ручкой. Его легко найти на северном небе. Звёзды в созвездии на самом деле далеко друг от друга, просто с Земли кажется, что они рядом.", "q": "Что напоминают семь ярких звёзд Большой Медведицы?", "a": [ "Ковш с ручкой", "Домик", "Ёлочку" ] }, { "id": "sp-polaris", "e": "🧭", "t": "Полярная звезда", "s": "Полярная звезда помогает найти север. Она почти не двигается по небу, пока другие звёзды медленно кружатся вокруг неё. Как её найти? Посмотри на Большую Медведицу. Проведи линию через две крайние звезды ковша и отмерь пять таких расстояний. Там и будет Полярная звезда. Она не самая яркая, зато очень полезная. Моряки и путешественники давно находят по ней дорогу.", "q": "Что помогает найти Полярная звезда?", "a": [ "Север", "Море", "Луну" ] }, { "id": "sp-milky-way", "e": "🌌", "t": "Млечный Путь", "s": "Далеко от городов, в тёмную ночь, на небе видна светлая полоса, как будто пролили молоко. Это Млечный Путь. На самом деле это очень много звёзд, которые так далеко, что сливаются в туманную дорожку. Наше Солнце и вся Земля живут в этой огромной звёздной семье, она называется галактикой. В ней сотни миллиардов звёзд. Если смотреть сверху, галактика похожа на вертушку с закрученными рукавами.", "q": "Что такое Млечный Путь?", "a": [ "Наша галактика, огромное скопление звёзд", "Облако из молока", "Дорога на Луне" ] }, { "id": "sp-mars-rovers", "e": "🚙", "t": "Марсоходы и вертолётик", "s": "На Марсе работают роботы на колёсах — марсоходы. «Кьюриосити» сел на Марс в 2012 году, а «Персеверанс» — в 2021-м. У них есть камеры, руки и инструменты, чтобы изучать красные камни и пыль. С «Персеверансом» прилетел и маленький вертолётик «Инджиньюити». Он стал первым вертолётом, который поднялся в воздух над другой планетой. Он летал совсем невысоко, но это был настоящий полёт!", "q": "Кто первым полетал над Марсом?", "a": [ "Вертолётик «Инджиньюити»", "Космонавт", "Самолёт" ] }, { "id": "sp-voyagers", "e": "💿", "t": "«Вояджеры» с золотой пластинкой", "s": "Два космических корабля «Вояджер» отправились в путь в 1977 году и до сих пор летят. Они дальше всех от Земли: целых двадцать с лишним миллиардов километров. На каждом закреплена золотая пластинка с записями. На ней приветствия на разных языках, шум дождя и волн, пение птиц и музыка. Это как письмо в бутылке, брошенной в космос: вдруг кто-нибудь когда-нибудь его найдёт и послушает.", "q": "Что записано на золотой пластинке «Вояджера»?", "a": [ "Приветствия, звуки природы и музыка", "Школьные уроки", "Мультфильмы" ] }, { "id": "sp-aurora", "e": "🌌", "t": "Северное сияние", "s": "В холодных северных краях, например в Мурманске или Норвегии, иногда по небу разливаются зелёные и розовые ленты света. Они двигаются, как огромные занавески. Это северное сияние. Солнце посылает к Земле крохотные частички, а высоко над нами они сталкиваются с воздухом, и воздух начинает светиться. Чаще всего сияние зелёное. Смотреть на него лучше всего зимой, тёмной морозной ночью.", "q": "Какого цвета чаще всего бывает северное сияние?", "a": [ "Зелёного", "Чёрного", "Коричневого" ] }, { "id": "sp-eclipse", "e": "🌑", "t": "Солнечное затмение", "s": "Иногда Луна проплывает перед Солнцем и закрывает его. Это солнечное затмение. Днём вдруг становится сумрачно, как вечером, и птицы затихают. Луна намного меньше Солнца, но и ближе к нам, поэтому может закрыть его целиком. Но помни главное правило: смотреть на Солнце без защиты нельзя никогда, даже во время затмения. Нужны специальные тёмные очки, и их выдают взрослые.", "q": "Что закрывает Солнце во время затмения?", "a": [ "Луна", "Облако", "Тучка из звёзд" ] } ], "nyc": [ { "id": "us-ny-subway", "e": "🚇", "t": "Метро, которое не спит", "s": "Метро Нью-Йорка открыли в тысяча девятьсот четвёртом году — больше ста лет назад. Сейчас в нём больше четырёхсот станций, а поезда ходят круглые сутки: и днём, и посреди ночи. А на некоторых станциях сидят музыканты с гитарами и скрипками. Едешь куда-нибудь, а на платформе вдруг играет настоящий оркестрик. Ждать поезда совсем не скучно.", "q": "Когда ходят поезда нью-йоркского метро?", "a": [ "Круглые сутки", "Только по средам", "Только когда светит солнце" ] }, { "id": "us-ny-timessq-ball", "e": "🎆", "t": "Сверкающий шар на Таймс-сквер", "s": "На площади Таймс-сквер в Нью-Йорке в новогоднюю ночь все ждут шар. Он огромный: около четырёх метров в поперечнике, а весит больше пяти тонн. Шар весь покрыт хрусталём и огоньками. Последнюю минуту старого года он медленно спускается по высокому шесту, а когда доезжает донизу, наступает Новый год. Тысячи людей кричат: «Ура!» — и в небо летит конфетти.", "q": "Что спускается по шесту на Таймс-сквер в Новый год?", "a": [ "Сверкающий шар", "Огромная ёлка", "Дед Мороз на верёвке" ] }, { "id": "us-ny-highline", "e": "🌿", "t": "Парк на старой железной дороге", "s": "Когда-то над улицами Нью-Йорка шла железная дорога на высоких опорах. По ней возили мясо, молоко и овощи прямо к фабрикам. Потом поезда перестали ездить, и на рельсах выросла трава. Люди придумали: пусть тут будет парк! Теперь это Хай-лайн, «Высокая линия». Длина парка — больше двух километров. Гуляешь над улицей среди цветов и травы, а старые рельсы всё ещё видны под ногами.", "q": "Что было на месте парка Хай-лайн раньше?", "a": [ "Железная дорога", "Взлётная полоса", "Футбольное поле" ] }, { "id": "us-ny-statenferry", "e": "⛴️", "t": "Бесплатный оранжевый паром", "s": "В Нью-Йорке можно покататься по морю, не заплатив ни копейки. Оранжевый паром ходит с Манхэттена на остров Стейтен-Айленд, и проезд на нём бесплатный. Плыть примерно двадцать пять минут. По дороге паром проходит рядом со статуей Свободы, а за кормой остаются небоскрёбы. Чайки летят следом, ветер треплет волосы, и все пассажиры, большие и маленькие, фотографируют город с воды.", "q": "Сколько стоит проезд на пароме до Стейтен-Айленда?", "a": [ "Ничего, он бесплатный", "Одну конфету", "Один мешок монет" ] }, { "id": "us-dc-whitehouse", "e": "🏛️", "t": "Дом, в котором сто тридцать две комнаты", "s": "В городе Вашингтоне стоит Белый дом, где работает президент и где он живёт. Дом белый, как и называется, и очень большой. В нём шесть этажей и сто тридцать две комнаты. Дверей — четыреста двенадцать, окон — сто сорок семь, а ванных комнат целых тридцать пять! Есть и двадцать восемь каминов. Чтобы всё это найти, пришлось бы взять карту.", "q": "Сколько этажей в Белом доме?", "a": [ "Шесть", "Один", "Двадцать" ] }, { "id": "us-dc-smithsonian", "e": "👠", "t": "Музеи, куда вход бесплатный", "s": "В Вашингтоне стоят музеи Смитсоновского института, и вход во все бесплатный! В музее американской истории выставлены красные туфельки Дороти из старого фильма «Волшебник страны Оз». А в музее природы лежит знаменитый большой синий алмаз по имени «Надежда». Сколько ни ходи, всё не обойдёшь. Можно зайти на часок, а потом вернуться на следующий день.", "q": "Сколько стоит вход в музеи Смитсоновского института?", "a": [ "Ничего, он бесплатный", "Одну шишку", "Три золотые монеты" ] }, { "id": "us-dc-cherry", "e": "🌸", "t": "Вишни — подарок из Японии", "s": "Каждую весну в Вашингтоне цветут тысячи вишен, и весь город становится розово-белым. Деревья привезли из Японии: в тысяча девятьсот двенадцатом году эта страна подарила Вашингтону около трёх тысяч деревьев. Первые два саженца посадили на берегу озера жена президента и японская гостья. Некоторые из тех самых деревьев цветут до сих пор. Вишни кругом — как будто повсюду сахарная вата.", "q": "Откуда привезли вашингтонские вишни?", "a": [ "Из Японии", "Из Антарктиды", "С Луны" ] }, { "id": "us-sf-goldengate", "e": "🌉", "t": "Оранжевый мост и туман Карл", "s": "Мост Золотые Ворота в Сан-Франциско вовсе не золотой, а красновато-оранжевый. Такой цвет выбрали, чтобы мост было видно в тумане. А туман в этом городе частый: жители в шутку назвали его Карлом и говорят о нём, как о соседе. Мост открыли в тысяча девятьсот тридцать седьмом году, а длина его — около двух с половиной километров. Когда Карл обнимает башни, над белой ватой торчат только оранжевые верхушки.", "q": "Какого цвета мост Золотые Ворота?", "a": [ "Оранжевого", "Зелёного", "Голубого" ] }, { "id": "us-sf-cablecar", "e": "🚋", "t": "Вагончики, которых тянет трос", "s": "По крутым холмам Сан-Франциско ездят маленькие деревянные вагончики. У них нет мотора на крыше: под мостовой всё время бежит длинный стальной трос, а вагончик цепляется за него специальной хваткой и едет. Первый такой вагончик пустили в тысяча восемьсот семьдесят третьем году. Водитель дёргает рычаг, звенит колокольчик — и вагончик то взбирается на горку, то спускается, а пассажиры стоят на подножках.", "q": "Что тянет вагончик в Сан-Франциско вверх по холму?", "a": [ "Трос под мостовой", "Невидимые лошади", "Воздушный шар" ] }, { "id": "us-sf-sealions", "e": "🦭", "t": "Морские львы на пирсе", "s": "Возле пирса тридцать девять в Сан-Франциско живут морские львы. В конце тысяча девятьсот восемьдесят девятого года сюда приплыл один, а потом к нему присоединились десятки, и к началу следующего года их было больше трёхсот. Они лежат на деревянных плотах у лодочной стоянки, толкаются, громко лают и ни капельки не боятся людей. Самые большие — взрослые самцы, они весят до четырёхсот килограммов.", "q": "Где лежат морские львы на пирсе тридцать девять?", "a": [ "На плотах у лодочной стоянки", "На крыше трамвая", "На скамейках в парке" ] }, { "id": "us-fl-apollo", "e": "🚀", "t": "Ракета со Флориды на Луну", "s": "Во Флориде на мысе Канаверал есть космодром, а рядом — космический центр Кеннеди. Отсюда шестнадцатого июля тысяча девятьсот шестьдесят девятого года улетел «Аполлон-11» с тремя астронавтами. Их ракету «Сатурн» было видно издалека: она вытянулась почти на сто десять метров, как дом в тридцать с лишним этажей. А потом люди впервые пошли по Луне. Старт ракеты слышали на много километров вокруг.", "q": "Откуда стартовал «Аполлон-11» к Луне?", "a": [ "Из Флориды", "Из Аляски", "Из Нью-Йорка с моста" ] }, { "id": "us-fl-disney", "e": "🏰", "t": "Сказочный городок размером с Манхэттен", "s": "Недалеко от города Орландо во Флориде — Диснейуорлд. Его открыли первого октября тысяча девятьсот семьдесят первого года. Сначала там было только Волшебное королевство с замком Золушки, а потом выросло много парков, гостиниц и озёр. Всё вместе занимает больше места, чем остров Манхэттен в Нью-Йорке! Между аттракционами ходят поезда и ездят лодочки, потому что пешком такое не обойдёшь.", "q": "Какой замок стоит в Волшебном королевстве?", "a": [ "Замок Золушки", "Замок Бабы-яги", "Ледяной замок Деда Мороза" ] }, { "id": "us-fl-everglades", "e": "🐊", "t": "Река травы и крокодилы с аллигаторами", "s": "На юге Флориды лежит заповедник Эверглейдс, «река травы»: вода течёт здесь очень медленно прямо через высокую траву. Ездят по ней на аэролодках с большим пропеллером сзади. Это единственное место в мире, где в дикой природе вместе живут аллигаторы и крокодилы. Аллигаторов можно узнать по широкой, закруглённой морде, а у крокодилов она узкая и острая. Кругом цапли, черепахи и ленивое солнце.", "q": "Кто вместе живёт в Эверглейдсе?", "a": [ "Аллигаторы и крокодилы", "Пингвины и белые медведи", "Слоны и жирафы" ] }, { "id": "us-fl-manatee", "e": "🌊", "t": "Ламантин — морская корова", "s": "У берегов Флориды плавают добрые великаны — ламантины. Их называют морскими коровами, потому что они жуют траву, только подводную: водоросли и морские травы. Ламантин огромный, весит несколько сотен килограммов, но очень спокойный. Он медленно плывёт, а каждые несколько минут поднимается к поверхности вздохнуть. Зимой, когда вода холодеет, ламантины собираются в тёплых источниках и речках, чтобы согреться.", "q": "Чем питается ламантин?", "a": [ "Водорослями и морской травой", "Рыбой и крабами", "Мороженым" ] }, { "id": "us-hi-kilauea", "e": "🌋", "t": "Килауэа и чёрный песок", "s": "На Гавайях есть вулкан Килауэа. Гавайцы рассказывают, что в его кратере живёт богиня огня Пеле. Когда вулкан просыпается, из него бьют огненные фонтаны, а раскалённая лава ползёт к океану. Попав в холодную воду, она застывает и разбивается на мелкие кусочки. Из них получается чёрный песок. На таком пляже, например на Пуналуу, любят греться на солнышке зелёные морские черепахи.", "q": "Из чего получается чёрный песок на Гавайях?", "a": [ "Из застывшей лавы", "Из угольков от костра", "Из шоколадной крошки" ] }, { "id": "us-hi-alphabet", "e": "🌺", "t": "Алфавит почти без согласных", "s": "Гавайский язык очень короткий в буквах: в алфавите всего двенадцать букв и ещё один значок. Гласных пять — а, е, и, о, у, а согласных всего семь, и звучат они как «х», «к», «л», «м», «н», «п» и «в». Значок называется окина, он обозначает маленькую паузу в слове. Поэтому слова звучат плавно и певуче, как «алоха», которое значит и «здравствуй», и «до свидания».", "q": "Что значит гавайское слово «алоха»?", "a": [ "«Здравствуй» и «до свидания»", "«Приятного аппетита»", "«Большая волна»" ] }, { "id": "us-hi-surf", "e": "🏄", "t": "Волна, на которой катаются стоя", "s": "Сёрфинг придумали давным-давно на островах Тихого океана, и особенно полюбили его на Гавайях. Гавайцы катались на длинных деревянных досках много веков назад. Занятие называлось «хее налу» — «скольжение по волне». Ждёшь большую волну, быстро встаёшь на доску — и летишь к берегу, как на волшебном ковре. Сейчас сёрферы со всего мира приезжают на Гавайи, чтобы поймать лучшую волну.", "q": "Как называется занятие «хее налу» по-русски?", "a": [ "Сёрфинг", "Прятки", "Игра в мяч" ] }, { "id": "us-ak-denali", "e": "🏔️", "t": "Денали — Высокая гора", "s": "На Аляске поднимается самая высокая гора Северной Америки — Денали. Её высота — шесть тысяч сто девяносто метров. Название пришло от коренных жителей Аляски, и оно значит «высокая». Вершина всегда в снегу, а внизу, в национальном парке, живут лоси, волки и медведи гризли. Иногда облака закрывают гору, и только самым терпеливым путешественникам удаётся увидеть её макушку.", "q": "Что значит слово «Денали»?", "a": [ "«Высокая»", "«Холодная булочка»", "«Белый медведь»" ] }, { "id": "us-ak-iditarod", "e": "🐕", "t": "Собачьи упряжки бегут в Ном", "s": "Зимой на Аляске проходит гонка Идитарод. Упряжки бегут от города Анкориджа до города Ном, больше тысячи миль. В каждой упряжке от двенадцати до шестнадцати собак, а погонщик стоит на санях. Ночуют команды прямо в снегу, а до финиша должны добежать минимум пять собак. Есть и старая правдивая история: в тысяча девятьсот двадцать пятом году упряжки передавали друг другу лекарство для жителей Нома.", "q": "Кто везёт сани на гонке Идитарод?", "a": [ "Собаки", "Белые медведи", "Олимпийские лошади" ] }, { "id": "us-ak-bears", "e": "🐻", "t": "Медведи у водопада", "s": "На Аляске, в парке Катмай, есть небольшой водопад Брукс. Каждое лето по реке идёт красная рыба лосось, и ей приходится прыгать через водопад. Бурые медведи стоят на краю и ловят её прямо в воздухе. Бывает, что у водопада рыбачат больше двадцати медведей сразу. К осени, наевшись, самые толстые из них весят около шестисот килограммов, и тогда они ложатся спать до весны.", "q": "Кого ловят медведи у водопада Брукс?", "a": [ "Лосося", "Воздушные шарики", "Бабочек" ] }, { "id": "us-b-totem", "e": "🪵", "t": "Столб, который рассказывает", "s": "На северо-западе Америки, у Тихого океана, живут народы, которые вырезают тотемные столбы. Берут огромное бревно кедра и вырезают на нём одно над другим лица животных: ворона, медведя, орла, косатки. Столб рассказывает историю семьи, как книжка с картинками, только вся из дерева. Потом его раскрашивают яркой краской и ставят у дома. Такие столбы — не идолы, а память и гордость рода. Некоторые из них выше дома!", "q": "Что чаще всего вырезают на тотемном столбе?", "a": [ "Лица животных одно над другим", "Часы с кукушкой", "Карту с дорогами" ] }, { "id": "us-b-tipi", "e": "⛺", "t": "Дом, который можно свернуть", "s": "Индейцы Великих равнин жили в домах-палатках — типи. Каменных стен у них не было: из длинных шестов складывали конус, а сверху обтягивали шкурами бизонов. Наверху оставляли дырку для дыма от очага, а внутри было тепло и уютно. Когда стадо бизонов уходило дальше, семья снимала шкуры, связывала шесты и переезжала вместе со своим домом. Так что дом ездил за хозяевами, как улитка со своей раковиной!", "q": "Чем обтягивали шесты типи?", "a": [ "Шкурами бизонов", "Соломой и конфетами", "Железными листами" ] }, { "id": "us-b-navajo-code", "e": "📻", "t": "Тайный язык навахо", "s": "Более восьмидесяти лет назад, во Вторую мировую войну, американским морякам понадобился язык, который не поймёт никто чужой. Тогда позвали молодых людей из народа навахо. Их язык тогда почти не записывали, и посторонние его не знали. Для слов, которых в нём не было, придумали свои: танк назвали «черепаха», а самолёт-истребитель — «колибри». Таких радистов было около четырёхсот, и их шифр так никто и не разгадал. Их работу долго держали в секрете.", "q": "Как на языке навахо в шифре назвали танк?", "a": [ "Черепаха", "Слон", "Утюг" ] }, { "id": "us-b-sign-talk", "e": "🤟", "t": "Разговор руками", "s": "На Великих равнинах жили много индейских народов, и говорили они на разных языках. Как же им договориться, если встретились незнакомцы? Они придумали язык жестов. Руки рассказывали целые истории: кто ты, откуда пришёл, куда идёшь и с миром ли. Знаки были такими понятными, что люди из разных племён могли поболтать, не сказав ни слова вслух. Вот так у тишины тоже бывает свой язык!", "q": "Зачем равнинным индейцам был нужен язык жестов?", "a": [ "Чтобы понимать людей с другим языком", "Чтобы не будить бизонов", "Чтобы разговаривать с луной" ] }, { "id": "us-b-mesa-verde", "e": "🏜️", "t": "Каменный дом в скале", "s": "В штате Колорадо, в парке Мэса-Верде, в глубоких нишах скал спрятаны каменные дома. Их построили древние индейцы примерно восемьсот лет назад. Самый большой называется Каменный дворец: в нём около ста пятидесяти комнат! Строили из песчаника, который складывали блоками, как кирпичи. Потом люди ушли, а дома остались. Современные люди нашли их, когда двое всадников искали потерявшихся коров. Теперь по лестницам к ним поднимаются туристы.", "q": "Где построены дома в парке Мэса-Верде?", "a": [ "В нишах скал", "На верхушках деревьев", "На дне озера" ] }, { "id": "us-b-bison", "e": "🦬", "t": "Бизон — не буйвол", "s": "Огромный лохматый зверь с горбом на плечах, который живёт в Америке, на самом деле называется бизон. Буйволы — другие звери, они живут в Африке и Азии. Но американцы всё равно часто зовут бизона буйволом, так сложилось давно. Бизон весит как маленькая машина, а бегает быстро, до пятидесяти километров в час! Малыши рождаются рыжими, и только потом темнеют. Сегодня бизонов можно увидеть в Йеллоустоуне и на равнинах.", "q": "Какого цвета рождаются бизонята?", "a": [ "Рыжего", "Голубого", "В красную клетку" ] }, { "id": "us-b-death-valley", "e": "🌡️", "t": "Самый жаркий воздух на Земле", "s": "Долина Смерти в Калифорнии — одно из самых жарких мест на планете. Там записали рекорд: в июле тысяча девятьсот тринадцатого года термометр показал почти пятьдесят семь градусов тепла. Это официальный мировой рекорд для воздуха! А ещё в этой долине находится самая низкая точка Северной Америки: она на восемьдесят шесть метров ниже уровня моря. Днём там жарко, поэтому звери выходят гулять по вечерам и ночью.", "q": "Когда в Долине Смерти бродят звери?", "a": [ "Вечером и ночью, когда прохладнее", "Только в полдень", "Только на Новый год" ] }, { "id": "us-b-sequoia", "e": "🌲", "t": "Дерево-великан и крошечная шишка", "s": "В Калифорнии растёт секвойя по имени «генерал Шерман». Это самое большое по объёму живое дерево на Земле: оно высотой с тридцатиэтажный дом, а возраст ему — около двух тысяч лет. Удивительнее всего, что шишки такого великана не больше куриного яйца, а семена совсем крошечные, как маленькие чешуйки. Из такого семечка вырастает дерево-гора. Кора у секвойи такая толстая, что почти не горит.", "q": "Какого размера шишки у секвойи-великана?", "a": [ "Не больше куриного яйца", "С арбуз", "С ведро" ] }, { "id": "us-b-saguaro", "e": "🌵", "t": "Кактус с руками", "s": "В пустыне Аризоны растёт кактус сагуаро. Он вытягивается до двенадцати метров, как четырёхэтажный дом, и похож на человека, поднявшего руки. Только руки у него появляются поздно: первая ветка вырастает лет через семьдесят, а то и больше. После дождя кактус впитывает воду и раздувается, как гармошка. Цветёт он белыми цветами, которые открываются ночью. А в стволе дятлы выдалбливают себе уютные дупла!", "q": "Кто живёт в дуплах кактуса сагуаро?", "a": [ "Дятлы", "Пингвины", "Белые медведи" ] }, { "id": "us-b-niagara", "e": "💦", "t": "Гром из воды", "s": "Ниагарский водопад — это три водопада рядом: Подкова, Американский и маленький водопад Фата. На американской стороне у самой воды ставят смотровые площадки, а на лодке можно подплыть так близко, что тебя обдаст брызгами. Всем выдают плащи. Вода падает с высоты почти в пятьдесят метров, и грохот слышно издалека. Граница между США и Канадой проходит прямо по реке над водопадом, так что на водопад можно смотреть из двух стран.", "q": "Что проходит по реке над Ниагарским водопадом?", "a": [ "Граница двух стран", "Железная дорога", "Шоколадная плотина" ] }, { "id": "us-b-wright", "e": "✈️", "t": "Двенадцать секунд над песком", "s": "Братья Райт чинили и делали велосипеды в городе Дейтон. А ещё они мечтали о полёте. Для опытов выбрали Китти-Хок: там дуют сильные ветры, а вокруг мягкий песок. Семнадцатого декабря тысяча девятьсот третьего года Орвилл взлетел на их самолёте, а Уилбур бежал рядом. Полёт продлился двенадцать секунд и закончился в тридцати семи метрах от старта. Зато в тот день было ещё три полёта, и самый долгий длился почти минуту.", "q": "Сколько секунд продлился первый полёт братьев Райт?", "a": [ "Двенадцать", "Двенадцать часов", "Две минуты" ] }, { "id": "us-b-edison", "e": "💡", "t": "Нитка, которая светилась", "s": "Томас Эдисон хотел сделать лампочку, которая долго горит. Внутри стеклянной колбы нужна тоненькая светящаяся нить. Эдисон и его помощники перепробовали много разных материалов. В тысяча восемьсот семьдесят девятом году обугленная хлопковая нитка светилась больше тринадцати часов. Потом попробовали бамбук, и такая лампочка уже горела больше тысячи часов. Так вечера стали светлее, а уроки при свете — удобнее.", "q": "Из чего Эдисон делал нить для лампочки?", "a": [ "Из обугленной нитки и бамбука", "Из макарон", "Из лакрицы" ] }, { "id": "us-b-ford", "e": "🚗", "t": "Машины ездят по цеху", "s": "Раньше автомобиль собирали на одном месте, и на это уходил целый день. Генри Форд придумал по-другому: машина медленно едет по цеху на ленте, а возле неё стоят рабочие. Каждый делает только свою часть: один ставит колесо, другой закручивает гайки. Так основу машины стали собирать всего за полтора часа вместо двенадцати! Машины стали дешевле, и покупать их смогли обычные семьи. Ленту назвали конвейером.", "q": "Как называется лента, по которой машина едет по цеху?", "a": [ "Конвейер", "Карусель", "Эскалатор" ] }, { "id": "us-b-halloween", "e": "🎃", "t": "Тыква вместо репы", "s": "Хэллоуин в Америке любят за костюмы и тыквы. Праздник привезли из Ирландии. Там раньше вырезали страшные рожицы на репе и ставили с огоньком внутри. В Америке репы было меньше, зато тыкв — целые поля. Тыква большая, мягкая и вырезать её легко, так что теперь в каждом доме светится тыква-фонарь. Дети в костюмах ходят по соседям и говорят «сладость или гадость», а им дают конфеты.", "q": "Что вырезали в Ирландии до тыквы?", "a": [ "Репу", "Арбуз", "Огурец" ] }, { "id": "us-b-fourth-july", "e": "🎆", "t": "День рождения страны", "s": "Четвёртого июля американцы отмечают день рождения своей страны. В тысяча семьсот семьдесят шестом году в Филадельфии приняли Декларацию независимости: тринадцать колоний объявили, что теперь они — отдельная страна. В этот день по улицам идут парады с оркестрами, на столах стоят арбузы, а все вывешивают флаги. А вечером в небе вспыхивают праздничные огни фейерверков. Тринадцать красно-белых полос на флаге — это те самые первые колонии.", "q": "Что означают тринадцать полос на флаге?", "a": [ "Первые тринадцать колоний", "Тринадцать видов мороженого", "Тринадцать гор" ] }, { "id": "us-b-santa-norad", "e": "🎅", "t": "Ошибка в телефонном номере", "s": "В тысяча девятьсот пятьдесят пятом году в Колорадо-Спрингс одна газета напечатала объявление: «Позвоните Санта-Клаусу». Но там ошиблись в номере, и звонки пошли прямо к лётчикам, которые следили за небом над страной. Дети спрашивали, где Санта. Лётчик не растерялся и стал отвечать, где его олени. С тех пор каждый год в канун Рождества лётчики рассказывают по телефону и в интернете, где сейчас летит Санта-Клаус.", "q": "Кому по ошибке звонили дети?", "a": [ "Лётчикам, следившим за небом", "Пожарным", "Булочникам" ] }, { "id": "us-b-groundhog", "e": "🦫", "t": "Сурок-синоптик", "s": "Каждый год второго февраля в городке Панксатони, в Пенсильвании, ждут сурка по имени Фил. Все собираются рано утром, а сурка вынимают из норки. Если он увидит свою тень, говорят, что зима продлится ещё шесть недель. Если тень не увидит — весна близко. Праздник придумали очень давно, больше ста тридцати лет назад. Сурок, конечно, не синоптик, но праздник такой весёлый, что приезжают тысячи людей.", "q": "Что должен увидеть сурок Фил, чтобы зима продлилась ещё шесть недель?", "a": [ "Свою тень", "Свой завтрак", "Снеговика" ] }, { "id": "us-b-popcorn", "e": "🍿", "t": "Зёрнышко, которое взрывается", "s": "Почему кукурузное зёрнышко в горячей сковородке подпрыгивает и превращается в белое облачко? Внутри твёрдой оболочки у него капелька воды. От жара она превращается в пар, пар давит изнутри, и оболочка вдруг лопается: пух! Попкорн в Америке ели индейцы много тысяч лет назад. Сегодня попкорн любят есть в кино. Но не всякая кукуруза умеет лопаться, для попкорна нужен особый сорт.", "q": "Что лопается внутри зёрнышка попкорна?", "a": [ "Капелька воды превращается в пар", "Маленький шарик", "Свистящая пружинка" ] }, { "id": "us-b-peanut", "e": "🥜", "t": "Арахис растёт под землёй", "s": "Американцы очень любят арахисовую пасту. Её намазывают на хлеб, а сверху кладут варенье. Но откуда берётся арахис? Он растёт под землёй! Сначала на кустике появляется маленький жёлтый цветок. Потом цветочная ножка наклоняется, прячется в землю, и там зреет стручок. На самом деле арахис — не орех, а родственник гороха и фасоли. Поэтому собирают его, выкапывая из земли, как картошку.", "q": "Где зреют стручки арахиса?", "a": [ "Под землёй", "На высокой пальме", "В воде" ] }, { "id": "us-b-icecream-cone", "e": "🍦", "t": "Мороженое в вафле", "s": "Мороженое в вафельном рожке придумали не сразу. По одной из историй, в тысяча девятьсот четвёртом году на большой ярмарке в городе Сент-Луис у продавца мороженого закончились тарелочки. Рядом стоял человек, который продавал тонкие вафли. Он свернул вафлю в трубочку, а продавец положил в неё шарик мороженого. Все решили, что рожок удобный и вкусный, ведь его можно есть вместе с «тарелкой».", "q": "Что свернули в трубочку для мороженого?", "a": [ "Тонкую вафлю", "Блин с луком", "Газету" ] } ], "can": [ { "id": "ca-a-igloo", "e": "🧊", "t": "Дом из снега", "s": "Иглу — это дом из снежных кирпичей. Инуиты, северный народ, вырезают плотные снежные блоки и кладут их по кругу, а каждый следующий ряд — чуть ближе к середине. Получается спираль, а в конце — круглая крыша-купол. Щели замазывают снегом. Снег полон воздуха, а воздух хорошо держит тепло. Поэтому в иглу, даже когда на улице сильный мороз, заметно теплее, чем снаружи. Раньше охотники строили такой дом за пару часов, когда нужно было переночевать в пути.", "q": "Из чего строят иглу?", "a": [ "Из снежных блоков", "Из ледяных шаров", "Из белых одеял" ] }, { "id": "ca-a-inuktitut", "e": "💬", "t": "Язык «инуктитут»", "s": "На севере Канады многие говорят на языке инуктитут. Слово «инуит» значит «люди». У этого языка есть и своя письменность: вместо привычных букв — уголки, крючки и дуги, похожие на маленькие домики и полумесяцы. Слова в нём бывают очень длинными: в одно слово можно вложить целую фразу. В Канаде есть место, где инуктитут — один из официальных языков: территория Нунавут. Школьники там учат и его, и английский.", "q": "Что значит слово «инуит»?", "a": [ "Люди", "Белый медведь", "Снежный дом" ] }, { "id": "ca-a-inuksuk", "e": "🪨", "t": "Каменный человечек", "s": "Среди северной тундры, где нет ни деревьев, ни заборов, вдруг видишь каменного человечка. Это инуксук. Его складывают из больших камней: ножки, туловище, а иногда и руки. Слово значит примерно «заменяющий человека». Инуксуки показывают путникам дорогу, подсказывают, где хорошие места для рыбалки, и помогают охотникам. Увидишь такого — значит, здесь уже бывали люди. Каменного человечка нарисовали и на эмблеме зимних Олимпийских игр 2010 года.", "q": "Что показывают путникам инуксуки?", "a": [ "Дорогу", "Время на часах", "Прогноз погоды на завтра" ] }, { "id": "ca-a-sled-dogs", "e": "🐕", "t": "Собаки в упряжке", "s": "Зимой на севере по снегу бегут собачьи упряжки. Собаки тянут нарты — длинные сани, а впереди бежит вожак. Инуиты веками держали сильных пушистых собак, которые не боятся мороза: они спят прямо на снегу, свернувшись клубком и накрыв нос хвостом. Хвост — тёплое одеяло. Погонщик не произносит длинных речей: собаки понимают короткие команды — направо, налево, стой. И мчат упряжку по льду много километров.", "q": "Чем собака накрывает нос, когда спит на снегу?", "a": [ "Хвостом", "Варежкой", "Шапкой" ] }, { "id": "ca-a-kayak", "e": "🛶", "t": "Каяк из шкур", "s": "Слово «каяк» пришло к нам от инуитов. Раньше их лодки делали так: из дерева или кости собирали лёгкий каркас, а сверху натягивали шкуры тюленя и зашивали швы. Получалась лодка-стрела, узкая и очень быстрая. Охотник садился в круглое отверстие посередине и надевал на него непромокаемую куртку, как юбку. Тогда в лодку не попадала ни капля воды. Даже если волна переворачивала каяк, ловкий гребец мог перевернуться обратно вместе с лодкой.", "q": "Чем обтягивали старинные каяки?", "a": [ "Шкурами тюленя", "Листьями клёна", "Стеклянными пластинами" ] }, { "id": "ca-a-parka", "e": "🧥", "t": "Парка с мешочком для малыша", "s": "Слово «парка» знает весь мир, а придумали такую одежду северные народы. Раньше парки шили из шкур карибу: у оленя шерсть пустая внутри и держит тепло лучше многих тканей. У инуитских мам была особая парка — амаути. У неё сзади большой капюшон, в котором сидел малыш. Ему там тепло, как в гнёздышке, а у мамы свободны руки. Иголки раньше делали из косточек, а нитки — из жил. Шили красиво, с узорами.", "q": "Где в амаути сидел малыш?", "a": [ "В большом капюшоне", "В кармане на рукаве", "В шапке с помпоном" ] }, { "id": "ca-a-tundra-buggy", "e": "🚌", "t": "Автобус на огромных колёсах", "s": "Чтобы посмотреть на белых медведей в Черчилле, туристы едут на тундра-баггиз. Это автобус на очень высоких колёсах: каждое выше взрослого человека. Он спокойно едет по кочкам, лужам и мху, где обычная машина застряла бы. Окна большие, а с задней площадки можно смотреть наружу. Медведи любопытные: подходят к автобусу, нюхают колёса и порой встают на задние лапы, чтобы заглянуть внутрь. Так что кто на кого смотрит — ещё вопрос.", "q": "Какие колёса у тундра-баггиз?", "a": [ "Очень высокие", "Квадратные", "Надувные, как шарики" ] }, { "id": "ca-a-bear-fur", "e": "🐻‍❄️", "t": "Белый медведь на самом деле не белый", "s": "Белый медведь только кажется белым. Его шерсть прозрачная, а белой она выглядит потому, что отражает свет, как снег и лёд. А кожа у него под шерстью чёрная: она хорошо ловит солнечное тепло. Медведь плавает в ледяной воде, и толстый слой жира с густым мехом спасают его от холода. Выйдя на берег, он отряхивается, как собака. Лапы у него огромные и широкие — прямо как снегоступы, поэтому он не проваливается в снег.", "q": "Какого цвета кожа у белого медведя?", "a": [ "Чёрная", "Розовая", "Зелёная" ] }, { "id": "ca-a-klondike", "e": "⛏️", "t": "Золото в ручье", "s": "В 1896 году у реки Клондайк, в канадской земле Юкон, в ручье нашли золото. Весть разлетелась по всему свету, и тысячи людей поехали на север: кто на лодке, кто пешком, а кто на санях. Власти требовали взять с собой запасы на целый год, около тонны груза. Всё это нужно было тащить в гору по снежным ступеням, много раз туда и обратно. Рядом со старательскими лагерями вырос городок Доусон, где в разгар «золотой лихорадки» жили тысячи человек.", "q": "Сколько груза должен был взять с собой золотоискатель?", "a": [ "Около тонны", "Один рюкзак", "Один маленький чемодан" ] }, { "id": "ca-a-sign-forest", "e": "🪧", "t": "Лес из табличек", "s": "В посёлке Уотсон-Лейк на Юконе растёт необычный лес. Деревьев в нём нет, зато есть столбы с табличками. Всё началось в 1942 году: солдат по имени Карл чинил дорожный указатель и повесил ещё одну табличку — с названием родного города, далеко на юге. Потом люди стали привозить таблички со всего света: из городов, школ, из разных стран. Теперь их десятки тысяч, и никто не знает точно, сколько. Кто приезжает, обычно привозит свою — и оставляет на память.", "q": "Что висит на столбах в Лесу табличек?", "a": [ "Таблички с названиями мест", "Шишки с картинками", "Воздушные шары" ] }, { "id": "ca-a-nunavut", "e": "🗺️", "t": "«Наша земля»", "s": "Первого апреля 1999 года на карте Канады появилась новая территория — Нунавут. На языке инуитов это слово значит «наша земля». Она огромная: по размеру больше, чем многие большие страны, но живёт там очень мало людей. Их так мало, что почти все друг друга знают. Главный город — Икалуит, а его название значит «место, где много рыбы». Дорог между городками почти нет: ездят на самолётах, на лодках или на снегоходах.", "q": "Что значит слово «Нунавут»?", "a": [ "Наша земля", "Белая тишина", "Земля медведей" ] }, { "id": "ca-a-yellowknife", "e": "🌌", "t": "Небо над Йеллоунайфом", "s": "Город Йеллоунайф на севере Канады называют столицей северного сияния. Зимой небо там часто ясное, и огни видны много ночей подряд. Зелёные и розовые ленты свиваются, как будто кто-то машет огромной шалью. Сияние рождается так: крошечные частицы от Солнца долетают до Земли и сталкиваются с воздухом, а воздух светится. Туристы надевают тёплые комбинезоны и ждут на улице, а в палатках-типи пьют горячий чай.", "q": "Что светится в небе во время сияния?", "a": [ "Воздух высоко над землёй", "Огромные светлячки", "Лёд на облаках" ] }, { "id": "ca-a-caribou-eyes", "e": "👀", "t": "Глаза, которые меняют цвет", "s": "У северного оленя, которого в Канаде зовут карибу, есть чудо: глаза меняют цвет! Летом, когда много света, они золотистые, а зимой, в полярную ночь, становятся синими. Так в темноте они лучше ловят слабый свет. А ещё карибу — великие путешественники. Весной стада идут к тундре, где рождаются телята, а к осени возвращаются в леса, и путь в обе стороны занимает больше тысячи километров. Малыш карибу встаёт на ножки через час после рождения.", "q": "Какого цвета глаза карибу зимой?", "a": [ "Синие", "Красные", "Фиолетовые" ] }, { "id": "ca-a-inuvik-sun", "e": "☀️", "t": "Месяц без солнца и два месяца без ночи", "s": "В городке Инувик, на самом севере Канады, зимой почти месяц солнце не поднимается над горизонтом. Стоит полярная ночь. А потом приходит праздник: в январе все выходят на улицу встречать первый рассвет. Зато летом всё наоборот — почти два месяца солнце не заходит совсем, и можно играть на улице в полночь. Белые ночи там длятся не одну неделю, а целое лето. Дети спят с плотными шторами на окнах.", "q": "Что делают в Инувике, когда солнце возвращается?", "a": [ "Встречают его праздником", "Закрывают окна", "Ложатся спать на месяц" ] }, { "id": "ca-a-permafrost", "e": "🏠", "t": "Дома на сваях", "s": "На севере земля под ногами твёрдая, как лёд, и зимой, и летом: это вечная мерзлота. Сверху она летом оттаивает, а глубже остаётся замёрзшей. Если поставить на неё тёплый дом, земля подтает, и стены поедут. Поэтому в Инувике дома ставят на сваи: между полом и землёй остаётся воздух, и земля не тает. А трубы с водой там тянут не под землёй, а над ней — в длинных коробах, которые идут вдоль улиц.", "q": "Почему северные дома ставят на сваи?", "a": [ "Чтобы не растаяла мёрзлая земля", "Чтобы белые медведи не залезли", "Чтобы дом был выше облаков" ] }, { "id": "ca-a-santa-post", "e": "🎅", "t": "Адрес Деда Мороза", "s": "В Канаде у Санты — Деда Мороза — есть свой почтовый индекс: Эйч-ноль-Эйч ноль-Эйч-ноль. Его легко запомнить, потому что читается как «хо-хо-хо». Дети пишут письма на адрес: Санта-Клаус, Северный полюс, Канада. Марку клеить не нужно! Почтальоны и добровольцы читают письма и отвечают, а если ребёнок написал на другом языке, ответят и на нём. Главное — написать на конверте обратный адрес, иначе Санте некуда будет присылать ответ.", "q": "Что нужно написать на конверте, чтобы получить ответ от Санты?", "a": [ "Обратный адрес", "Любимую конфету", "Размер ботинок" ] }, { "id": "ca-a-narwhal", "e": "🦄", "t": "Единорог северных морей", "s": "В холодных водах Арктики плавает кит-нарвал. У него торчит длинный закрученный бивень, как у единорога из сказок. На самом деле это зуб, и растёт он прямо из верхней челюсти, чаще слева. Бывает длиной до трёх метров. Раньше люди думали, что такие бивни достаются волшебным зверям, и продавали их как рог единорога. Нарвалы живут стаями, любят холод и ныряют очень глубоко. Кожа у них пятнистая, серая с белым.", "q": "Чем на самом деле является бивень нарвала?", "a": [ "Зубом", "Рогом", "Ледяной сосулькой" ] }, { "id": "ca-a-beluga", "e": "🐋", "t": "Поющая белуха", "s": "Белуха — белый кит, который живёт в северных водах. Летом белухи приплывают к устью реки у города Черчилль, в Гудзонов залив, и там их можно услышать: они щёлкают, свистят, пищат, поют. Моряки зовут их «морскими канарейками». Малыши белух рождаются серыми и постепенно светлеют. А ещё у белухи есть шея, и голова поворачивается в стороны — не то что у большинства китов. Туристы плавают рядом с ними на лодках и слушают концерт.", "q": "Как моряки называют белух?", "a": [ "Морскими канарейками", "Морскими воробьями", "Морскими кошками" ] }, { "id": "ca-a-muskox", "e": "🦬", "t": "Овцебык и мамонты", "s": "Овцебык — огромный лохматый зверь с длинной шерстью почти до самой земли. Он жил на Севере ещё тогда, когда по тундре ходили мамонты, и пережил их. Его подшёрсток зовётся «кивиут», и он куда теплее овечьей шерсти: из него вяжут шапки и шарфы для самых сильных морозов. Когда приходит волк, взрослые овцебыки встают кругом, а телята прячутся в середине. Рога наружу — и страшно подойти. Вот такая крепость из живых зверей.", "q": "Как овцебыки защищают телят?", "a": [ "Встают кругом, а телята в середине", "Убегают на льдину", "Зарывают их в снег" ] }, { "id": "ca-a-throat-singing", "e": "🎶", "t": "Игра в горловое пение", "s": "У инуитов есть старинная игра — катаджак, или горловое пение. Две женщины встают лицом к лицу, близко-близко, и по очереди выдыхают друг другу низкие звуки: хрип, рычание, вдох, будто ветер, гуси или собака. Звуки повторяются всё быстрее. Проигрывает та, у кого собьётся дыхание или кто рассмеётся! Говорят, раньше женщины так играли, пока мужчины были на охоте. Теперь катаджак показывают на концертах и учат детей.", "q": "Кто проигрывает в игре катаджак?", "a": [ "Тот, кто засмеялся", "Тот, кто промолчал", "Тот, кто чихнул громче всех" ] }, { "id": "ca-b-islands", "e": "⛴️", "t": "Острова напротив небоскрёбов", "s": "Напротив небоскрёбов Торонто, прямо в озере Онтарио, лежит цепочка из пятнадцати маленьких островов. Добраться туда можно на пароме, а ехать совсем недолго. На островах почти нет машин: все ходят пешком или катаются на велосипедах. Там есть пляжи, тихие лужайки и парк с каруселями и горками. А с берега видно весь город: небоскрёбы стоят на горизонте, как игрушечные.", "q": "Как добираются на острова Торонто?", "a": [ "На пароме", "На подводной лодке из банана", "На ракете с парашютом" ] }, { "id": "ca-b-path", "e": "🚇", "t": "Город под землёй", "s": "Зимой в Торонто бывает очень холодно, и горожане придумали подземный город. Под центром, под большими зданиями, тянутся длинные проходы с магазинами, кафе и станциями метро. Если сложить все коридоры, получится около тридцати километров! Можно дойти из одного здания в другое, не выходя на мороз и без шапки. Этот подземный торговый центр считали самым большим в мире.", "q": "Зачем жителям Торонто подземный город?", "a": [ "Чтобы ходить по делам и не мёрзнуть", "Чтобы разводить там кротов", "Чтобы прятаться от мороженого" ] }, { "id": "ca-b-rom", "e": "🦕", "t": "Динозавр по имени Гордо", "s": "В Музее Ройал Онтарио в Торонто живёт огромный динозавр. Это барозавр, и зовут его Гордо. Он длиннее двух автобусов, шея у него тянется вдоль стеклянных окон, и его видно даже с улицы. Музей получил кости в 1962 году, а потом про них надолго забыли. Вспомнили через много лет, и теперь Гордо стоит в здании, похожем на гигантский хрустальный кристалл.", "q": "Как зовут динозавра из музея в Торонто?", "a": [ "Гордо", "Пончик", "Бублик Иванович" ] }, { "id": "ca-b-rideau", "e": "⛸️", "t": "Канал-каток в Оттаве", "s": "В столице Канады, Оттаве, есть канал Ридо. Летом по нему плавают лодки, а зимой вода замерзает, и канал превращается в огромный каток! Он тянется почти на восемь километров. Люди едут на работу и в школу на коньках, а потом пьют горячий шоколад у ларьков прямо на льду. По версии Книги рекордов Гиннесса, это самый большой природный каток в мире: лёд там замораживает сама зима.", "q": "Что происходит с каналом Ридо зимой?", "a": [ "Он замерзает и становится катком", "Он уезжает в тёплые страны", "Он наполняется какао" ] }, { "id": "ca-b-tulips", "e": "🌷", "t": "Тюльпаны в подарок", "s": "Каждую весну в Оттаве расцветают сотни тысяч тюльпанов. Всё началось с гостьи. Нидерландская принцесса Юлиана когда-то жила в Оттаве, и там у неё родилась дочка Маргрит. Чтобы малышка точно считалась нидерландской, одну комнату в больнице на время объявили не канадской землёй. Потом принцесса прислала городу сто тысяч луковиц тюльпанов, чтобы сказать спасибо. До сих пор в мае в Оттаве проходит праздник тюльпанов.", "q": "Что принцесса Юлиана подарила Оттаве в благодарность?", "a": [ "Луковицы тюльпанов", "Коньки с бантиками", "Деревянную мельницу" ] }, { "id": "ca-b-bagels", "e": "🥯", "t": "Монреальские бублики", "s": "В Монреале любят бублики, но не такие, как везде. Тесто сначала варят в воде с мёдом, а потом запекают в дровяной печи. Поэтому монреальские бублики чуть сладкие, пахнут дымком, маленькие, с большой дыркой. Продают их ещё тёплыми, прямо из печки, в бумажном пакете. Монреальцы уверены, что их бублики вкуснее всех на свете, и спорят об этом с жителями других городов.", "q": "Как готовят монреальские бублики?", "a": [ "Варят в воде с мёдом и пекут в дровяной печи", "Жарят на солнце", "Замораживают в сугробе" ] }, { "id": "ca-b-carnival", "e": "⛄", "t": "Снеговик Бономм", "s": "В городе Квебеке каждую зиму проходит большой праздник, Зимний карнавал. Его главный герой — весёлый снеговик Бономм. Он в красном колпаке с кисточкой и в яркой стрелчатой повязке на талии. Для него строят ледяной дворец, по улицам идут парады, а смельчаки на лодках-каноэ плывут и бегут по льдинам через реку Святого Лаврентия. Все гуляют в тёплых куртках, смеются и пьют горячий шоколад.", "q": "Кто главный герой Зимнего карнавала в Квебеке?", "a": [ "Снеговик Бономм", "Пингвин-повар", "Дед Мороз на тракторе" ] }, { "id": "ca-b-stanley-park", "e": "🌲", "t": "Тотемы Стэнли-парка", "s": "В Ванкувере посреди города растёт огромный лес. Он называется Стэнли-парк, а вокруг него у самой воды идёт дорожка длиной около девяти километров. В парке стоят тотемные столбы. Их вырезали из кедра коренные жители побережья. На столбах — ворон, медведь, орёл, кит, и каждая фигура рассказывает историю семьи. Идёшь мимо, и кажется, что деревянные звери вот-вот заговорят.", "q": "Из чего вырезаны тотемные столбы в Стэнли-парке?", "a": [ "Из кедра", "Из мармелада", "Из сахарной ваты" ] }, { "id": "ca-b-orcas", "e": "🐋", "t": "Косатки у Ванкувера", "s": "Недалеко от Ванкувера в море живут косатки. Они не рыбы, а большие дельфины! Косатки плавают семьями, и главная в семье обычно бабушка. Малыши остаются рядом с мамой много лет. Семьи переговариваются щелчками и свистами, и у каждой есть свой «говор». Смотреть на косаток едут на лодках, но близко не подплывают, чтобы не пугать. А если в Ванкувере идёт дождь, а он идёт часто, то горожане просто надевают плащи.", "q": "Кто обычно главный в семье косаток?", "a": [ "Бабушка", "Самый маленький детёныш", "Чайка, которая сидит на спине" ] }, { "id": "ca-b-anne", "e": "👧", "t": "Энн с красными косами", "s": "На острове Принца Эдуарда в Канаде земля и дороги красные, потому что в песке много ржавчины-железа. А на острове стоит дом с зелёными окнами и крышей, куда писательница Люси Мод Монтгомери поселила свою героиню. Это Энн из «Зелёных Мезонинов», девочка с рыжими косами, которая очень любит болтать и выдумывать. Она даже дала имена деревьям: вишню у окна назвала Снежной королевой.", "q": "Какого цвета земля на острове Принца Эдуарда?", "a": [ "Красная", "Фиолетовая в полоску", "Голубая как небо" ] }, { "id": "ca-b-fundy", "e": "🌊", "t": "Море уходит и возвращается", "s": "В заливе Фанди на востоке Канады самые высокие в мире приливы. Дважды в сутки море поднимается и опускается, а в самые большие приливы вода меняется на целых шестнадцать метров. Это как пятиэтажный дом! На отливе лодки лежат прямо на дне, на мокром песке, и можно ходить по дну моря. Потом вода возвращается, и лодки снова всплывают. За один прилив в залив приходят миллиарды тонн воды.", "q": "Что делают лодки в заливе Фанди, когда вода уходит?", "a": [ "Лежат на дне, на песке", "Улетают в облака", "Прячутся в пещеры" ] }, { "id": "ca-b-banff-bridges", "e": "🦌", "t": "Мосты для зверей в Банфе", "s": "В национальном парке Банф, в Скалистых горах, через большую дорогу построили мосты и туннели — но не для людей, а для зверей. Там шесть мостов и тридцать восемь туннелей. Мосты заросли травой и деревьями, поэтому они похожи на лесные полянки. По ним перебираются олени, горные бараны и даже медведи гризли. Так звери ходят куда хотят, а машины ездят спокойно, никого не пугая.", "q": "Для кого построили мосты и туннели в Банфе?", "a": [ "Для лесных зверей", "Для динозавров", "Для людей на ходулях" ] }, { "id": "ca-b-columbia", "e": "🧊", "t": "Вездеход для ледника", "s": "В Скалистых горах есть поле льда — ледник Колумбия. Один его язык, ледник Атабаска, спускается почти к самой дороге. Чтобы выйти на него, люди садятся в особый вездеход с огромными колёсами, мягкими как воздушные шары. Он везёт по льду, как по ровной дорожке. А вода, которая тает на этом леднике, уходит в разные реки: одни текут к Тихому океану, а другие — к Северному Ледовитому.", "q": "На чём люди выезжают на ледник Атабаска?", "a": [ "На вездеходе с огромными колёсами", "На санях с пингвинами", "На ледяном самокате" ] }, { "id": "ca-b-turbines", "e": "💡", "t": "Водопад, который работает", "s": "Ниагарский водопад не только красивый, он ещё и работает. Часть воды из реки отводят по длинным туннелям к электростанциям. Там она крутит большие колёса — турбины, а они делают электричество для домов и школ. Но есть уговор: днём, когда много туристов, по водопаду пускают больше воды, чтобы он выглядел как можно красивее. А ночью, когда все спят, больше воды уходит к турбинам.", "q": "Что крутит вода Ниагары на электростанциях?", "a": [ "Турбины", "Карусели в парке", "Мельницы с блинами" ] }, { "id": "ca-b-syrup-facts", "e": "🥞", "t": "Сорок вёдер ради одного", "s": "Сок клёна, который собирают весной, почти как вода: прозрачный и чуть сладкий. Чтобы получить один литр кленового сиропа, нужно выпарить примерно сорок литров сока. Для этого его кипятят в больших котлах, пока он не станет густым и золотистым. Почти три четверти кленового сиропа в мире делает Канада. А в Квебеке любят ещё и сладкую конфету на снегу: горячий сироп льют на чистый снег, он застывает, и его наматывают на палочку.", "q": "Как выглядит сок клёна, из которого варят сироп?", "a": [ "Прозрачный, почти как вода", "Чёрный, как чернила", "Розовый, как клубничный" ] }, { "id": "ca-b-stanley-cup", "e": "🏆", "t": "Кубок, на котором пишут имена", "s": "Главный приз хоккея — кубок Стэнли. Его подарил лорд Стэнли: он был главным человеком Канады от королевы и очень любил хоккей. Кубок весит около шестнадцати килограммов. На нём выгравированы имена игроков команд-победителей. А потом каждый игрок победившей команды получает кубок на один день к себе: кто-то катает его на лодке, кто-то ест из него кашу вместе с семьёй. Если кубок едет в дорогу, его сопровождает специальный хранитель.", "q": "Что гравируют на кубке Стэнли?", "a": [ "Имена игроков победившей команды", "Рецепты блинов", "Рисунки шайб" ] }, { "id": "ca-b-poutine", "e": "🍟", "t": "Картошка со скрипучим сыром", "s": "В Квебеке придумали блюдо с забавным названием путин. Это горячая картошка фри, сверху — кусочки свежего молодого сыра, а потом всё поливают тёплым соусом. Сыр в путине особенный: пока он свежий, он скрипит на зубах! Блюдо появилось в деревнях Квебека, а теперь его едят по всей Канаде. Взрослые говорят, что путин лучше всего есть, когда на улице холодно.", "q": "Что особенного в сыре для путина?", "a": [ "Он скрипит на зубах", "Он поёт песни", "Он светится в темноте" ] }, { "id": "ca-b-geese", "e": "🪿", "t": "Гуси клином", "s": "Канадские гуси осенью улетают на юг, а весной возвращаются. Летят они клином, буквой «V». Так им легче: каждая птица летит чуть выше и сбоку от соседа, и воздух от его крыльев помогает ей. Впереди летит один гусь, ему труднее всех. Когда он устаёт, переходит назад, а вперёд вылетает другой. Гуси всё время перекликаются: «хонк-хонк!» — наверное, подбадривают друг друга.", "q": "Какой буквой выстраиваются в небе канадские гуси?", "a": [ "«V»", "«О»", "«Ш»" ] }, { "id": "ca-b-loonie", "e": "🪙", "t": "Лунни и тунни", "s": "Канадские деньги получили смешные имена. На монете в один доллар нарисована птица гагара, которая кричит, будто хохочет. По-английски она «лун», поэтому монету зовут «лунни». Потом появилась монета в два доллара из двух металлов: серебристого в серединке и золотистого по краю. Её назвали «тунни», потому что «ту» по-английски значит «два». Получается, что у канадцев в кармане звенят гагара и её младшая сестра.", "q": "Какая птица нарисована на монете «лунни»?", "a": [ "Гагара", "Курица", "Попугай" ] }, { "id": "ca-b-naismith", "e": "🏀", "t": "Баскетбол из корзин для персиков", "s": "Баскетбол придумал канадец Джеймс Нейсмит. В 1891 году он работал учителем физкультуры в США. Зимой ребятам было скучно в зале, и ему понадобилась новая игра. Он повесил на балкон две корзины из-под персиков, взял футбольный мяч и написал тринадцать правил. Корзины висели на высоте около трёх метров, и сегодня кольцо в баскетболе висит на такой же высоте.", "q": "Что повесил Нейсмит на балкон для первой игры?", "a": [ "Корзины из-под персиков", "Горшки с цветами", "Ведёрки для песка" ] } ], "sgp": [ { "id": "sgp-a-merlion", "e": "🦁", "t": "Мерлион — лев с рыбьим хвостом", "s": "У воды в Сингапуре стоит удивительная статуя: голова у неё львиная, а тело — рыбье, с чешуёй и хвостом. Её зовут Мерлион. Ростом он примерно с трёхэтажный дом и без перерыва выпускает изо рта струю воды. Рыба напоминает, что раньше здесь была рыбацкая деревня, а лев — что Сингапур значит «город льва». Рядом стоит и маленький мерлион, совсем крошка: ростом всего два метра.", "q": "Какое тело у Мерлиона?", "a": [ "Рыбье, с чешуёй и хвостом", "Птичье, с крыльями", "Змеиное, длинное" ] }, { "id": "sgp-a-mbs-ship", "e": "🚢", "t": "Корабль на трёх башнях", "s": "Посмотрите на гостиницу Марина Бэй Сэндс. Три высокие башни стоят рядом, а на их крышах лежит длинная площадка, похожая на корабль. Будто огромный корабль приплыл по воздуху и сел на три столба! Это целый парк на высоте, с деревьями и дорожками. А ещё там есть бассейн, из которого видно весь город. Плавать в нём можно только гостям гостиницы.", "q": "На что похожа площадка на трёх башнях?", "a": [ "На корабль", "На большой зонтик", "На мост через реку" ] }, { "id": "sgp-a-gardens-bay", "e": "🌳", "t": "Сады у залива", "s": "Рядом с заливом в Сингапуре раскинулись Сады у залива. Раньше на этом месте было море, а потом люди насыпали землю и посадили огромный сад. Здесь растут цветы и деревья со всего света: из жарких стран и из прохладных гор. По саду под открытым небом можно гулять целый день. Дорожки ведут к озёрам, к мостикам и к стеклянным домам с растениями.", "q": "Что было на месте Садов у залива раньше?", "a": [ "Море", "Большая гора", "Пустыня с песком" ] }, { "id": "sgp-a-supertrees", "e": "✨", "t": "Супердеревья зажигают огни", "s": "В Садах у залива стоят супердеревья, и они не настоящие, а железные! Высота у них от двадцати пяти до пятидесяти метров. Но по их стволам вьются настоящие цветы и папоротники. На некоторых кронах есть солнечные батареи, которые днём собирают свет. А вечером супердеревья вспыхивают разными цветами, и под музыку начинается шоу света. Зрители смотрят вверх и не могут оторваться.", "q": "Что делают супердеревья вечером?", "a": [ "Загораются разными цветами", "Складывают ветки и засыпают", "Начинают шуметь листьями" ] }, { "id": "sgp-a-flower-dome", "e": "🌸", "t": "Цветочный купол", "s": "В Садах у залива есть стеклянный дом, который называется Цветочный купол. Его записали в книгу рекордов как самую большую стеклянную теплицу в мире! На улице в Сингапуре жарко и сыро, а внутри купола прохладно. Поэтому там растут растения из тёплых, но не тропических стран: оливковые деревья, которым много сотен лет, и толстые баобабы. А в разное время года тут устраивают выставки цветов.", "q": "Что за дом — Цветочный купол?", "a": [ "Самая большая стеклянная теплица", "Домик для птиц", "Каменный дворец" ] }, { "id": "sgp-a-cloud-forest", "e": "☁️", "t": "Облачный лес с водопадом внутри", "s": "В другом стеклянном доме Садов у залива живёт Облачный лес. Только зайдёшь — и видишь гору, вся она покрыта зелёными растениями и орхидеями. А с самого верха падает водопад, прямо в доме! Он высотой около тридцати пяти метров. Вокруг стоит лёгкий туман, как в облаках, и пахнет влажными листьями. Подняться на гору можно на лифте, а спуститься по тропинке.", "q": "Что падает с горы в Облачном лесу?", "a": [ "Водопад", "Снег", "Яблоки" ] }, { "id": "sgp-a-jewel-changi", "e": "🌈", "t": "Водопад в аэропорту", "s": "Аэропорт Чанги в Сингапуре не раз называли одним из лучших в мире. Там есть здание Джуэл, а посреди него, в стеклянном доме, падает вниз огромный водопад. Он называется Радужный вихрь и высотой около сорока метров. Вода течёт из отверстия в крыше, а вокруг растёт целый лес. Вечером на водопаде загорается разноцветный свет. Самолёт ещё не скоро, а ты уже смотришь на чудо!", "q": "Как называется водопад в здании Джуэл?", "a": [ "Радужный вихрь", "Серебряный дождь", "Весёлый ручей" ] }, { "id": "sgp-a-island-map", "e": "🗺️", "t": "Остров, который стал страной", "s": "Найдите на карте юго-востока Азии маленькую точку на самом краю, у экватора. Это Сингапур: остров, город и страна — всё сразу! Это самое маленькое государство в Юго-Восточной Азии. Весь главный остров можно проехать из конца в конец за один день, и не один раз. А вокруг него рассыпаны ещё около шестидесяти островков, совсем крошечных, и на некоторых из них никто не живёт.", "q": "Чем одновременно является Сингапур?", "a": [ "Островом, городом и страной", "Горой и озером", "Рекой и морем" ] }, { "id": "sgp-a-garden-city", "e": "🏢", "t": "Небоскрёбы в зелени", "s": "Сингапур называют городом-садом. Здесь деревья не только в парках: они растут на крышах небоскрёбов, а по стенам домов поднимаются живые растения. Из окон гостиницы можно увидеть террасы, где цветут кусты, как зелёные ступеньки. Получается, что дом покрыт настоящим зелёным ковром. Растения дают тень, в доме прохладнее, а птицы и бабочки находят себе дорогу в самый центр города.", "q": "Где в Сингапуре растут растения, кроме парков?", "a": [ "На крышах и стенах домов", "Только в горшках на окнах", "Под землёй в метро" ] }, { "id": "sgp-a-bay-lights", "e": "🌃", "t": "Огни на заливе", "s": "Когда в Сингапуре наступает вечер, у залива зажигаются огни. Небоскрёбы светятся окошками, а вода в заливе повторяет каждый огонёк, как большое зеркало. Через залив перекинут пешеходный мост Хеликс, он закручен двойной спиралью, как будто две ленты обнялись. Можно медленно идти по нему и смотреть вокруг: видно и корабль на трёх башнях, и лотос музея, и огни на другом берегу.", "q": "Как закручен мост Хеликс?", "a": [ "Двойной спиралью", "Прямой стрелой", "Квадратными ступеньками" ] }, { "id": "sgp-a-river-boat", "e": "⛵", "t": "Лодки на реке Сингапур", "s": "По реке Сингапур ходят лодки, которые называются «бамбот». Раньше такие лодки возили по реке грузы: от больших кораблей, стоявших в море, к берегу и обратно. Теперь на лодках в старом стиле катают гостей. Вдоль берега стоят старые невысокие дома, а над ними — высокие стеклянные небоскрёбы. Старое и новое рядом! С воды хорошо видно, как они соседствуют друг с другом.", "q": "Что возили на лодках «бамбот» раньше?", "a": [ "Грузы от кораблей к берегу", "Только цветы и шарики", "Слонов с одного берега на другой" ] }, { "id": "sgp-a-flyer", "e": "🎡", "t": "Сингапурский флайер", "s": "Сингапурский флайер — огромное колесо обозрения. Оно высотой около ста шестидесяти пяти метров, как пятьдесят с лишним этажей! Кабины у колеса большие, стеклянные, как маленькие комнаты, и в каждую помещается много людей. Колесо вращается медленно, один круг занимает около получаса. Наверху видно залив, корабли и парки. А если посчитать лодки внизу, можно сбиться со счёта.", "q": "Как быстро вращается Сингапурский флайер?", "a": [ "Очень медленно, круг — около получаса", "Быстро, круг за одну минуту", "Он совсем не вращается" ] }, { "id": "sgp-a-artscience", "e": "🪷", "t": "Музей-лотос АртСайенс", "s": "У залива в Сингапуре стоит музей АртСайенс, и он похож на цветок лотоса. Его белые лепестки-«пальцы» раскрыты вверх, будто здание протягивает ладонь навстречу гостям. Внутри — выставки, где искусство встречается с наукой: огни, картинки и необычные игры. А ещё крыша устроена как чаша: дождевая вода стекает по ней вниз, в пруд в середине здания. Музей любит и поиграть, и подумать!", "q": "На какой цветок похож музей АртСайенс?", "a": [ "На лотос", "На подсолнух", "На ромашку" ] }, { "id": "sgp-b-four-languages", "e": "🗣️", "t": "Четыре языка на одной улице", "s": "В Сингапуре четыре государственных языка: английский, китайский, малайский и тамильский. Вывески в метро в основном написаны по-английски, потому что его понимают почти все. А в школе дети учат ещё и язык своей семьи: одни китайский, другие малайский, третьи тамильский. Так мальчик может болтать с соседкой на одном языке, а с бабушкой дома на другом.", "q": "Какой язык в Сингапуре понимают почти все и пишут на вывесках?", "a": [ "Английский", "Только тамильский", "Язык жителей Луны" ] }, { "id": "sgp-b-hawker-centre", "e": "🍜", "t": "Большой обеденный зал под крышей", "s": "В Сингапуре есть хокер-центры. Это огромные навесы со столами, а вокруг десятки маленьких кухонь. Одна семья берёт рис с курицей, другая суп с лапшой, третья шашлычки, и все едят за одним столом. В 2020 году ЮНЕСКО внесла хокерскую культуру в список нематериального наследия человечества: за то, что люди здесь вместе и вкусно обедают.", "q": "Что такое хокер-центр в Сингапуре?", "a": [ "Навес со столами и множеством маленьких кухонь", "Музей, где еду нельзя трогать", "Башня, где варят только чай" ] }, { "id": "sgp-b-chicken-rice", "e": "🍗", "t": "Рис с курицей по-хайнаньски", "s": "Любимое блюдо многих сингапурцев называется хайнаньский рис с курицей. Его придумали переселенцы с китайского острова Хайнань. Курицу варят в мягком, тихом кипении, и мясо получается нежным. Рис готовят в курином бульоне, поэтому он пахнет курочкой. К тарелке подают острый красный соус чили и тёртый имбирь. А ещё огурец и маленькую пиалку супа.", "q": "В чём варят рис для знаменитого блюда с курицей?", "a": [ "В курином бульоне", "В лимонаде", "В кокосовом молоке с мёдом и мороженым" ] }, { "id": "sgp-b-chilli-crab", "e": "🦀", "t": "Краб в густом красном соусе", "s": "Чили-краб — праздничное блюдо Сингапура. Целого краба тушат в густом соусе из томатов, чили и яйца. Соус сладковатый, чуть кисловатый и не слишком острый. Есть краба нужно руками, поэтому на столе лежат салфетки и щипцы для клешней. А к соусу подают мягкие булочки: их обмакивают в тарелку и съедают до последней капли.", "q": "Чем едят соус от чили-краба, чтобы ничего не пропало?", "a": [ "Обмакивают в него мягкие булочки", "Выпивают через трубочку из бамбука", "Намазывают на гигантский арбуз" ] }, { "id": "sgp-b-satay", "e": "🍢", "t": "Сатэ на угольках", "s": "Вечером в Сингапуре пахнет дымком: это жарят сатэ. На тонкие палочки нанизывают маленькие кусочки мяса и держат над горячими углями. Повар то и дело переворачивает их и веером раздувает жар. Готовые шашлычки подают с густым ореховым соусом из арахиса. Рядом лежат кусочки огурца и лука. Пальцы потом пахнут весело и вкусно!", "q": "Из чего делают густой соус к сатэ?", "a": [ "Из арахиса", "Из шоколадных конфет", "Из морской капусты и клубники" ] }, { "id": "sgp-b-kaya-toast", "e": "🍞", "t": "Тост с кокосовым вареньем", "s": "На завтрак сингапурцы любят тост с кая. Кая — нежное варенье из кокосового молока, яиц и сахара. Часто в него добавляют сок зелёных листьев пандана, и варенье становится зеленоватым и душистым. Тонкий хрустящий хлеб мажут кая и кладут ломтик холодного масла. К тосту подают мягкие яйца всмятку: их выливают в блюдечко и макают тост.", "q": "Из чего делают варенье кая для тостов?", "a": [ "Из кокосового молока, яиц и сахара", "Из огурцов и шоколада", "Из облаков и мёда" ] }, { "id": "sgp-b-laksa", "e": "🥥", "t": "Лакса: суп с кокосовым запахом", "s": "Лакса — это сингапурский суп с лапшой. Бульон в нём густой, оранжевый и сливочный, потому что в него налили кокосовое молоко. В тарелке плавают креветки и ломтики рыбных котлеток. В одном из самых известных видов лаксы лапшу режут на короткие кусочки, и её можно есть ложкой, без палочек. Попробуешь — и сразу пахнет тропиками.", "q": "Какое молоко делает суп лакса густым и сливочным?", "a": [ "Кокосовое", "Овсяное с мятой", "Верблюжье" ] }, { "id": "sgp-b-ice-cream-bread", "e": "🍦", "t": "Мороженое в булке", "s": "На сингапурской улице у лотка можно встретить продавца с большой коробкой-холодильником. Он достаёт кусок мороженого и кладёт его не в вафельный рожок, а в мягкую булку. Или заворачивает в яркий хлеб: розовый, жёлтый, зелёный. Так мороженое едят и взрослые, и дети. В жаркий день сладкая булка с холодной начинкой — настоящий подарок.", "q": "Во что на лотке иногда кладут мороженое вместо рожка?", "a": [ "В мягкую булку", "В фарфоровую чашку для чая", "В большой лист бамбука" ] }, { "id": "sgp-b-durian", "e": "🌵", "t": "Колючий фрукт с сильным запахом", "s": "Дуриан — большой колючий фрукт, покрытый шипами, как булава. Внутри мягкая жёлтая мякоть, и многие считают её очень вкусной. Но запах у дуриана такой сильный, что остаётся в комнате надолго. Поэтому в сингапурском метро и во многих гостиницах висят знаки: с дурианом нельзя! Его едят на улице или дома, где можно открыть окно.", "q": "Почему в метро Сингапура висит знак «с дурианом нельзя»?", "a": [ "У фрукта очень сильный запах", "Он может укусить пассажиров", "Он слишком быстро катится" ] }, { "id": "sgp-b-clean-city", "e": "🧹", "t": "Город, где любят чистоту", "s": "Сингапур известен чистыми улицами. Здесь есть правила, которые помогают всем жить удобно. За мусор на тротуаре полагается штраф, поэтому люди выбрасывают фантики в урны. А ещё в магазинах почти не продают жвачку: так решили давно, с 1992 года, чтобы она не прилипала к дверям метро и скамейкам. Дворники тоже помогают, но главное, что бросать мусор на землю никому не хочется.", "q": "Что в Сингапуре делают с фантиками и мусором?", "a": [ "Выбрасывают в урны", "Прячут под скамейки", "Дарят голубям" ] }, { "id": "sgp-b-mrt-driverless", "e": "🚇", "t": "Поезда без машиниста", "s": "В Сингапуре есть метро, которое называют MRT. Часть его линий работает без машиниста: поезд ведёт компьютер. Если встать у самой первой двери вагона, можно смотреть вперёд через стекло, как будто сам рулишь. Платить за проезд удобно проездной карточкой: её прикладывают к считывателю у входа, и калитка открывается. Такой же карточкой можно платить и в автобусе.", "q": "Кто ведёт поезда на некоторых линиях сингапурского метро?", "a": [ "Компьютер, без машиниста", "Дрессированный тигр", "Пассажиры по очереди" ] }, { "id": "sgp-b-hdb-homes", "e": "🏢", "t": "Дома, где живёт большинство города", "s": "Примерно четыре из пяти сингапурцев живут в высоких общих домах, которые строит государство. Их называют HDB. Такие дома стоят целыми кварталами, а рядом часто есть магазин, детская площадка и хокер-центр. На нижнем этаже многих домов нет квартир: там пусто и прохладно, и можно собраться на свадьбу или просто поиграть в тени. Соседи друг друга хорошо знают.", "q": "Что часто находится рядом с домом, где живут сингапурцы?", "a": [ "Площадка, магазин и хокер-центр", "Горнолыжный склон", "Ледяной дворец" ] }, { "id": "sgp-b-always-summer", "e": "⛈️", "t": "Тут всегда лето", "s": "Сингапур стоит почти на самой середине Земли, возле экватора. Поэтому здесь нет зимы: весь год тепло и влажно, а дождь может прийти в любой месяц. Часто он начинается после обеда. Небо темнеет, гремит гром, и ливень стучит по крышам. Сингапурцы не расстраиваются: прячутся под навесы, а потом снова выходит солнце, и город блестит.", "q": "Почему в Сингапуре нет зимы?", "a": [ "Он стоит почти на экваторе, где всегда тепло", "Зиму увозят на пароходе", "Её съедает дождь" ] }, { "id": "sgp-c-night-safari", "e": "🌙", "t": "Зоопарк, который просыпается вечером", "s": "В Сингапуре есть зоопарк, куда ходят после заката. Он называется Ночное сафари. Когда темнеет, там просыпаются те, кто днём спал: тигры, гиены, летучие мыши, летяги. По дорожке между деревьями тихо едет трамвайчик, а свет в парке приглушённый, как лунный, чтобы зверей не пугать. Считается, что это первый в мире зоопарк, который работает по ночам.", "q": "Когда работает Ночное сафари?", "a": [ "Вечером и ночью", "Только на рассвете", "Только зимой" ] }, { "id": "sgp-c-river-pandas", "e": "🐼", "t": "Панды у реки", "s": "В Сингапуре есть парк «Речные чудеса», раньше его называли «Речное сафари». В нём собраны уголки с большими реками мира: Янцзы, Миссисипи, Амазонка. Есть лодка, которая плывёт по «Амазонке», и огромный аквариум с ламантинами. А ещё в парке живут большие панды Кай Кай и Цзя Цзя. Для них сделали прохладный дом, ведь панды плохо переносят жару. Они подолгу жуют бамбук, и это их любимое занятие.", "q": "Что любят жевать панды?", "a": [ "Бамбук", "Морковку", "Сосновые шишки" ] }, { "id": "sgp-c-jurong-birds", "e": "🦩", "t": "Птичий парк Джуронг", "s": "Много лет в Сингапуре жил Птичий парк Джуронг. Там гуляли розовые фламинго, а попугаи ара умели повторять слова. Фламинго розовые из-за еды: в рачках и водорослях есть красящее вещество, и оно окрашивает перья. Птенцы у фламинго вовсе серые. В 2023 году Джуронг закрыли, а птиц перевезли в новый парк, который называется «Райский птичий парк». Он в другой части острова.", "q": "Почему фламинго розовые?", "a": [ "От еды: рачков и водорослей", "Их красят служители", "Они родились розовыми от солнца" ] }, { "id": "sgp-c-penguins-sgp", "e": "🐧", "t": "Пингвины в жарком городе", "s": "Сингапур стоит почти на экваторе, там жарко круглый год. Но в Райском птичьем парке живут пингвины! Для них построили холодный дом с ледяной водой, где всё как у Южного полюса. Через стекло можно смотреть, как пингвины летают под водой, будто маленькие торпеды. Там даже есть купол, под которым они проплывают над головой у гостей. А на суше пингвины смешно переваливаются с лапы на лапу.", "q": "Где в Сингапуре живут пингвины?", "a": [ "В прохладном доме со стеклянной стеной", "На раскалённом песке", "На крыше небоскрёба" ] }, { "id": "sgp-c-zoo-no-bars", "e": "🦧", "t": "Зоопарк без решёток", "s": "В Сингапурском зоопарке почти нет клеток. Звери живут словно на воле: от гостей их отделяют рвы с водой, кусты и склоны, так что решёток не видно. Рыжие орангутаны живут на высоких деревьях и канатах, и иногда их можно увидеть прямо над дорожкой. Малыши орангутанов любят качаться и кувыркаться. Смотреть можно, а кормить зверей гостям нельзя: у них свой завтрак.", "q": "Что в Сингапурском зоопарке отделяет зверей от гостей?", "a": [ "Рвы с водой и кусты", "Высокие заборы с колючками", "Стеклянные купола" ] }, { "id": "sgp-c-sentosa-cable", "e": "🚡", "t": "Остров Сентоза и канатная дорога", "s": "Сентоза — остров рядом с Сингапуром. Его название по-малайски значит «покой и тишина». Туда можно добраться на канатной дороге: кабинки плывут высоко над гаванью, внизу блестят корабли, а вдалеке видны небоскрёбы. На Сентозе есть песчаные пляжи с пальмами, где можно строить замки. Путь по воздуху похож на небольшое путешествие.", "q": "На чём можно добраться до Сентозы по воздуху?", "a": [ "На канатной дороге", "На воздушном шаре", "На вертолёте-такси" ] }, { "id": "sgp-c-oceanarium-sharks", "e": "🦈", "t": "Акулы за стеклом", "s": "На острове Сентоза есть огромный океанариум. Там большое окно в целую стену, а за ним плавают акулы, скаты и множество рыб. Акулы — особенные рыбы: у них нет настоящих костей. Скелет у акулы из хряща, а хрящ мягкий, как кончик вашего носа или ухо. Поэтому акула гибкая и быстрая. Смотреть, как рядом проплывает скат, очень здорово.", "q": "Из чего скелет акулы?", "a": [ "Из хряща", "Из камня", "Из ракушек" ] }, { "id": "sgp-c-botanic-unesco", "e": "🌳", "t": "Сад, которым гордится весь мир", "s": "В центре Сингапура есть Ботанический сад. Ему больше ста шестидесяти лет. Это тропический сад, куда приходят гулять, играть и устраивать пикники. В 2015 году его внесли в список Всемирного наследия ЮНЕСКО: это значит, что его бережёт весь мир. Говорят, он единственный тропический ботанический сад в этом списке. Там растут огромные деревья, в прудах цветут кувшинки, а на лужайках можно встретить птиц.", "q": "Какой в Сингапуре сад охраняет ЮНЕСКО?", "a": [ "Ботанический сад", "Сад камней", "Яблоневый сад" ] }, { "id": "sgp-c-vanda-miss-joaquim", "e": "🌸", "t": "Орхидея Мисс Джоахим", "s": "Национальный цветок Сингапура — орхидея Ванда Мисс Джоахим. Она розово-лиловая, с тёмными пятнышками. Её вывела в своём саду женщина по имени Агнес Джоахим: в 1893 году о её необычном цветке узнали садоводы. Новую орхидею назвали в её честь. А в Национальном саду орхидей растёт множество других красавиц на любой вкус и цвет.", "q": "В честь кого названа национальная орхидея Сингапура?", "a": [ "В честь садовницы Агнес Джоахим", "В честь королевы", "В честь знаменитой певицы" ] }, { "id": "sgp-c-otters", "e": "🦦", "t": "Выдры у небоскрёбов", "s": "На заливе в центре Сингапура живут гладкошёрстные выдры. Они держатся семьями: мама, папа и малыши. Их можно увидеть у воды: они ныряют за рыбой, греются на берегу и перекликаются тонкими голосами. Шерсть у них короткая и гладкая, а между пальцами есть перепонки, поэтому выдры хорошо плавают. Прохожие ради них останавливаются, но подходить близко не нужно.", "q": "Как выдры живут в Сингапуре?", "a": [ "Семьями", "По одной, каждая сама по себе", "В больших клетках" ] }, { "id": "sgp-c-pulau-ubin", "e": "🚲", "t": "Остров Убин: прогулка на велосипеде", "s": "Недалеко от Сингапура лежит остров Убин, где ещё сохранилась деревенька. Туда плывут на маленькой лодке-бамботе. Она обычно выходит в море, когда наберётся почти полный комплект пассажиров, примерно двенадцать человек. На острове нет высотных домов, зато есть велосипеды, и их берут напрокат. Кататься можно по тропкам среди зелени, мангровых зарослей и деревенских домиков.", "q": "Как удобнее всего ездить по острову Убин?", "a": [ "На велосипеде", "На электричке", "На верблюде" ] }, { "id": "sgp-c-mangrove", "e": "🦎", "t": "Мангры, ящерицы и рыбы с ногами", "s": "На берегах Сингапура растут мангровые леса. Их деревья стоят прямо в солёной воде на корнях, похожих на длинные ноги. В иле живут рыбки илистые прыгуны: они ползают по грязи на плавниках и даже вылезают из воды! А рядом бывают вараны, крупные ящерицы. Они хорошо плавают и спокойно греются на солнышке, если их не беспокоить.", "q": "Что делают илистые прыгуны?", "a": [ "Ползают по илу на плавниках", "Летают над водой", "Строят дома из камней" ] }, { "id": "sgp-d-temasek-lion", "e": "🦁", "t": "Легенда о льве", "s": "Давным-давно на острове было поселение Темасек, что, говорят, значит «морской город». Однажды к берегу приплыл принц Сан Нила Утама. Он увидел на берегу зверя и решил, что это лев. Так гласит старая легенда. Принц назвал остров Сингапура: на древнем языке это «город льва». Настоящих львов там, скорее всего, не было, но имя прижилось, и до сих пор Сингапур зовут Львиным городом.", "q": "Что значит старое имя Сингапура?", "a": [ "Город льва", "Город рыб", "Город дождя" ] }, { "id": "sgp-d-raffles", "e": "⛵", "t": "Стэмфорд Раффлз", "s": "В 1819 году к острову на корабле приплыл англичанин Стэмфорд Раффлз. Он увидел удобную бухту у устья реки и понял, что здесь можно построить порт. Тогда на берегу жило совсем немного людей. А вскоре сюда стали приезжать торговцы из Китая, Индии и Малайи. Сегодня у реки стоит белая статуя Раффлза: он стоит со скрещёнными руками и смотрит на воду, с которой всё началось.", "q": "Что понравилось Раффлзу на острове?", "a": [ "Удобная бухта у реки", "Высокая гора", "Горячие источники" ] }, { "id": "sgp-d-chinatown-temple", "e": "🏮", "t": "Храм в Чайнатауне", "s": "В Чайнатауне, китайском квартале Сингапура, стоит большой красный храм. В нём хранят реликвию: по преданию, это зуб самого Будды. Её прячут в золотой ступе, и каждый день к ней приходят люди. Храм построили не так давно, в 2007 году, но по старинному китайскому образцу, с изогнутыми крышами. Вокруг на улочках продают фонарики, веера и вкусные булочки.", "q": "Как называется китайский квартал Сингапура?", "a": [ "Чайнатаун", "Литтл-Индия", "Бугис" ] }, { "id": "sgp-d-little-india", "e": "🌼", "t": "Гирлянды Литтл-Индии", "s": "В квартале Литтл-Индия пахнет жасмином и специями. Здесь продавцы с утра нанизывают на нитки живые цветы: оранжевые бархатцы, белый жасмин, розовые розы. Получаются длинные гирлянды. Их вешают на статуи в храме, дарят друг другу на праздник и надевают гостям на шею. Дома здесь раскрашены в яркие цвета, как конфеты: розовые, жёлтые и голубые.", "q": "Из чего делают гирлянды в Литтл-Индии?", "a": [ "Из живых цветов", "Из конфет", "Из ракушек" ] }, { "id": "sgp-d-kampong-glam", "e": "🕌", "t": "Кампонг Глам", "s": "Кампонг Глам — это старый малайский квартал. Над ним сияет золотой купол мечети Султана, его видно издалека. А рядом тянется Арабская улица. В её лавках продают ткани с узорами, ковры, плетёные корзины и яркие фонари из цветных стёкол. По переулкам ходить интересно: на стенах нарисованы большие картинки, а в маленьких кафе пекут тонкие лепёшки.", "q": "Что блестит над кварталом Кампонг Глам?", "a": [ "Золотой купол мечети", "Серебряная башня", "Стеклянная гора" ] }, { "id": "sgp-d-chinese-new-year", "e": "🧧", "t": "Китайский Новый год", "s": "В конце зимы или в начале весны в Сингапуре начинается китайский Новый год. Улицы украшают красными фонарями: красный цвет приносит удачу. Детям дарят красные конверты с деньгами. А на площадях пляшут львы! Под огромной маской прячутся двое танцоров: один изображает голову, другой хвост. Под барабаны лев кивает, прыгает и «ест» зелёный салат. Это тоже на счастье.", "q": "Какого цвета конверты дарят детям на Новый год?", "a": [ "Красного", "Зелёного", "Серого" ] }, { "id": "sgp-d-hari-raya", "e": "🌙", "t": "Хари Райя", "s": "Хари Райя — большой праздник малайцев и всех мусульман Сингапура. Он наступает, когда заканчивается месяц поста. Перед праздником район Гейланг Серай украшают огоньками, а на рынке продают сладости. Дома готовят кетупат: это рис, сваренный в корзиночке из пальмовых листьев. Дети надевают нарядную одежду, ходят в гости, и им дарят зелёные конверты.", "q": "В какой корзиночке варят рис кетупат?", "a": [ "Из пальмовых листьев", "Из бумаги", "Из глины" ] }, { "id": "sgp-d-diwali", "e": "🪔", "t": "Дивали: праздник огней", "s": "Дивали — индийский праздник света. В Сингапуре перед ним вся Литтл-Индия загорается огнями: над улицей висят светящиеся арки и фонари. Дома зажигают маленькие глиняные светильники. А у порога рисуют узор из цветного порошка или риса. Он называется ранголи. Считается, что добрый свет прогоняет темноту, а нарядный порог встречает удачу.", "q": "Как называется узор у порога на Дивали?", "a": [ "Ранголи", "Кетупат", "Хонгбао" ] }, { "id": "sgp-d-national-day", "e": "🎆", "t": "Национальный день", "s": "Девятого августа в Сингапуре день рождения страны: в 1965 году она стала самостоятельной, отдельной страной. Это самый шумный праздник года. Над заливом пролетают самолёты, огромный вертолёт несёт большой флаг, а вечером в небе расцветают фейерверки. Люди в красных и белых одеждах поют общую песню. Дети машут флажками и приходят смотреть парад всей семьёй.", "q": "Какого числа Сингапур празднует Национальный день?", "a": [ "Девятого августа", "Первого января", "Двадцать пятого декабря" ] }, { "id": "sgp-d-land-reclaim", "e": "🏗️", "t": "Земля из моря", "s": "Сингапур — маленький остров, и места на нём мало. Поэтому люди придумали, как получить землю у моря. Они привозят много песка и насыпают его в воду у берега. Получается новый участок суши. Так остров за много лет стал примерно на четверть больше. На такой насыпной земле стоят часть аэропорта Чанги и сад Гарденс бай зе Бей у залива Марина-Бей.", "q": "Как в Сингапуре получают новую землю?", "a": [ "Насыпают песок у берега", "Поднимают дно волшебством", "Привозят острова на кораблях" ] }, { "id": "sgp-d-water", "e": "💧", "t": "Дождь и НЬЮотер", "s": "На острове мало места для больших рек и озёр, зато часто идут тёплые ливни. Сингапурцы собирают дождевую воду в водохранилища: дождь стекает по канавам и ручьям и попадает туда. А ещё воду очищают много раз. Очень чистая вода называется НЬЮотер. Её делают из уже использованной воды: сначала её очищают, а потом пропускают через тонкие фильтры. Её пьют не напрямую, а в основном используют на заводах.", "q": "Как называется очень чистая вода, которую делают в Сингапуре?", "a": [ "НЬЮотер", "Морская пена", "Радужная вода" ] }, { "id": "sgp-d-school", "e": "🎒", "t": "В сингапурской школе", "s": "В Сингапуре дети ходят в школу в форме. Обычно это светлая рубашка и шорты или юбка, а цвета и значки у каждой школы свои. Уроки идут в основном на английском языке. А ещё каждый ребёнок учит родной язык своей семьи: китайский, малайский или тамильский. Эти три языка, вместе с английским, в стране официальные, поэтому на улицах слышны сразу несколько.", "q": "На каком языке в основном идут уроки в сингапурской школе?", "a": [ "На английском", "На португальском", "На немецком" ] } ], "jpn": [ { "id": "jpn-a-shibuya", "e": "🚦", "t": "Перекрёсток Сибуя", "s": "В Токио есть перекрёсток, который любят снимать на видео. Это Сибуя. Когда загорается зелёный, машины замирают со всех сторон, и люди выходят на дорогу сразу отовсюду: и справа, и слева, и наискосок! Они идут навстречу друг другу, но никто не сталкивается. За один раз дорогу переходят сотни человек, а иногда, говорят, даже тысячи. Загорелся красный — и всё повторится заново.", "q": "Что происходит на Сибуе, когда загорается зелёный?", "a": [ "Люди переходят дорогу сразу во всех направлениях", "Все стоят на месте и ждут", "Люди переходят дорогу только в одну сторону" ] }, { "id": "jpn-a-tokyo-big", "e": "🏙️", "t": "Самый большой город", "s": "Токио — столица Японии, и людей в нём и вокруг него живёт больше, чем во всей Португалии. Это один из самых больших городов на Земле! Поезда там ходят точно по расписанию, а станции метро похожи на целые подземные городки с магазинами и кафе. Чтобы не потеряться, у каждой линии свой цвет, а у каждой станции свой номер.", "q": "Как в токийском метро помогают не потеряться?", "a": [ "У каждой линии свой цвет, у станции свой номер", "На станциях раздают волшебные карты", "Поезда сами спрашивают, куда ехать" ] }, { "id": "jpn-a-skytree", "e": "🗼", "t": "Башня Скайтри", "s": "В Токио стоит башня Токийское Небесное Дерево, или Скайтри. Она высотой 634 метра — это одна из самых высоких башен мира! Число 634 выбрали не случайно: по-японски цифры «му-са-си» звучат как «Мусаси», так раньше называлась эта земля. С высоты видно весь город, а в ясную погоду даже далёкую гору Фудзи. Лифт возносит людей так быстро, что, наверное, закладывает ушки.", "q": "Какая высота у башни Скайтри?", "a": [ "634 метра", "10 метров", "63 километра" ] }, { "id": "jpn-a-tuna", "e": "🐟", "t": "Утренний рынок тунцов", "s": "В Токио есть огромный рыбный рынок Тоёсу. Раньше такой рынок был в районе Цукидзи, но в 2018 году его перевезли на новое место. Там очень рано, когда на улице ещё темно, проходят торги: продают огромных тунцов. Одна рыбина бывает длиннее взрослого человека и тяжелее нескольких детей! Гости могут смотреть на всё это сверху, из специального коридора с окнами, чтобы не мешать работать.", "q": "Что продают на рынке рано утром?", "a": [ "Огромных тунцов", "Воздушных змеев", "Деревянные лодки" ] }, { "id": "jpn-a-akiba", "e": "🎮", "t": "Акихабара — город игр", "s": "В Токио есть район Акихабара. Его называют «электрическим городом»: там столько магазинов, что глаза разбегаются! В одних продают видеоигры и приставки, в других — маленьких роботов, комиксы манга и яркие фигурки героев мультфильмов. А ещё там есть этажи с игровыми автоматами, где слышна весёлая музыка. Многие дети и взрослые приезжают сюда из разных мест, чтобы найти любимую игрушку.", "q": "Чем знаменита Акихабара?", "a": [ "Магазинами игр, роботов и манги", "Большим морским пляжем", "Горными лыжами" ] }, { "id": "jpn-a-harajuku", "e": "🧁", "t": "Нарядная улица Харадзюку", "s": "В районе Харадзюку есть узкая улица Такэсита, где всё яркое, как конфетная обёртка. Здесь любят одеваться необычно: розовые банты, пёстрые носки, платья как у кукол. Продают здесь и вкусное: сладкие блинчики-крепы, свёрнутые рожком, с клубникой и взбитыми сливками. Люди на этой улице не боятся быть смешными, а наряжаются так, как им хочется.", "q": "Какое лакомство продают на улице Такэсита?", "a": [ "Крепы со сливками и клубникой", "Горячий борщ", "Солёные огурцы" ] }, { "id": "jpn-a-kyoto", "e": "⛩️", "t": "Киото — город храмов", "s": "Больше тысячи лет Киото был столицей Японии. Сегодня это город, который словно сошёл со старинной картинки: деревянные дома, узкие улочки, сады с прудами. А храмов здесь так много, что их не обойти и за неделю: больше тысячи! Одни стоят посреди города, а другие спрятались в лесу на холмах. Некоторым храмам уже много сотен лет.", "q": "Сколько храмов в Киото?", "a": [ "Больше тысячи", "Только два", "Ни одного" ] }, { "id": "jpn-a-fushimi", "e": "🦊", "t": "Красные ворота и лисы", "s": "В Киото есть святилище Фусими-Инари. К нему ведёт тропа через тысячи ярких красных ворот, которые называются тории. Они стоят так близко друг к другу, что получается длинный красный тоннель, а сквозь щели пробегают солнечные лучи. Вокруг сидят каменные лисы: считается, что лисы — посланницы Инари, богини риса. У многих лис в зубах ключ от рисового амбара, так говорят!", "q": "Что держат в зубах каменные лисы?", "a": [ "Ключ от рисового амбара", "Золотую рыбку", "Свёрнутую газету" ] }, { "id": "jpn-a-kinkaku", "e": "✨", "t": "Золотой павильон", "s": "В Киото стоит Золотой павильон — Кинкакудзи. Два его верхних этажа покрыты тонкими листочками настоящего золота! Павильон стоит у пруда, и в тихой воде видно второй такой же, перевёрнутый. Когда выглядывает солнце, он сияет так, что глазам щекотно. Давным-давно это был загородный дом знатного правителя, а потом здесь устроили храм, и сюда приезжают смотреть на него люди со всего мира.", "q": "Чем покрыты верхние этажи Золотого павильона?", "a": [ "Тонкими листочками золота", "Разноцветными конфетами", "Мягким мхом" ] }, { "id": "jpn-a-maiko", "e": "🎎", "t": "Майко учится танцевать", "s": "В Киото на улицах иногда встречаются майко. Это девушки, которые учатся быть гейшами: так называют мастериц танца, музыки и чайной церемонии. На них нарядное кимоно, высокая причёска и белый грим на лице. Учатся они много лет: танцуют с веером, играют на старинной трёхструнной гитаре сямисэн, подают чай. Это настоящие артистки, поэтому смотреть на них нужно вежливо и тихо, не мешая их пути.", "q": "Чему учатся майко?", "a": [ "Танцам, музыке и чайной церемонии", "Ловить рыбу", "Водить поезда" ] }, { "id": "jpn-a-bamboo", "e": "🎋", "t": "Бамбуковая роща Арасияма", "s": "На краю Киото, в районе Арасияма, есть бамбуковая роща. Стебли бамбука там толстые и очень высокие, гораздо выше человека. Они стоят так плотно, что по тропинке идёшь, как по зелёному коридору. А когда дует ветер, бамбук качается и тихонько шуршит, постукивает. Этот шелест так нравится людям, что рощу включили в список «100 звуков Японии».", "q": "Какой звук делает бамбук на ветру?", "a": [ "Тихо шуршит и постукивает", "Громко лает", "Звонит как телефон" ] }, { "id": "jpn-a-fuji", "e": "🗻", "t": "Гора Фудзи", "s": "Фудзи — самая высокая гора Японии, 3776 метров. Это вулкан, но он давно спит: последний раз просыпался больше трёхсот лет назад, в 1707 году. Вершина у горы белая даже тогда, когда внизу ещё тепло: на ней долго лежит снежная шапка. Фудзи так красива, что японцы часто рисуют её на картинах и открытках. Подниматься на гору обычно можно летом, когда тропа свободна от снега.", "q": "Что за гора Фудзи?", "a": [ "Спящий вулкан со снежной шапкой", "Остров в океане", "Огромный камень на пляже" ] }, { "id": "jpn-a-hanami", "e": "🌸", "t": "Пикник под сакурой", "s": "Весной в Японии расцветает сакура, и цветы так густо облепляют ветки, что дерево кажется розовым облаком. Японцы выходят в парки, расстилают на траве покрывала и устраивают пикник прямо под цветущими ветками. Это называется «ханами», то есть «любование цветами». Цветёт сакура недолго, всего неделю-две, а потом лепестки падают, как розовый снег. Поэтому каждый день цветения очень дорог.", "q": "Как называется любование цветущей сакурой?", "a": [ "Ханами", "Фудзи", "Тории" ] }, { "id": "jpn-a-momiji", "e": "🍁", "t": "Красные клёны осенью", "s": "Осенью Япония становится не розовой, а красной! Листья клёнов краснеют, как маленькие огоньки, и в Киото в садах и храмах горят целые клёновые костры. Так красиво, что у японцев есть особое слово: «момидзи» — осенние красные листья. Люди приезжают в парки и гуляют по дорожкам, любуясь алыми листьями, а на воде пруда плавают красные листья, как лодочки.", "q": "Как японцы называют осенние красные листья?", "a": [ "Момидзи", "Ханами", "Сямисэн" ] }, { "id": "jpn-b-nos-zimorodka", "e": "🚄", "t": "Нос как клюв зимородка", "s": "Поезд-пуля в Японии называется синкансэн. Раньше, когда быстрый поезд влетал в туннель, на другом конце туннеля раздавался громкий хлопок. Инженер, который любил наблюдать за птицами, вспомнил про зимородка: эта птица ныряет в воду почти без брызг. Поезду сделали длинный нос, похожий на клюв зимородка. С таким носом поезд входит в туннель тихо и мягко.", "q": "Чей клюв подсказал форму носа поезда?", "a": [ "Зимородка", "Аиста", "Попугая" ] }, { "id": "jpn-b-provodnik-poklon", "e": "🙇", "t": "Поклон в дверях вагона", "s": "В японском поезде проводник часто заходит в вагон и кланяется пассажирам. А когда уходит, останавливается в дверях, поворачивается к людям и кланяется ещё раз. Это знак уважения и благодарности. А на конечной станции вагоны убирают очень быстро: бригада уборщиков успевает навести чистоту примерно за семь минут. Перед работой они тоже кланяются.", "q": "Что делает проводник, когда заходит в вагон?", "a": [ "Кланяется пассажирам", "Играет на барабане", "Раздаёт воздушные шарики" ] }, { "id": "jpn-b-asimo", "e": "🤖", "t": "Асимо ходит по лестнице", "s": "Робота Асимо придумали в компании Хонда. Он ростом примерно с ребёнка, ходит на двух ногах и даже бегает. Асимо умеет подниматься по лестнице и наливать напиток в стакан. Он машет рукой, как будто здоровается. Инженеры учили его ходить много лет, потому что устойчиво стоять на двух ногах очень трудно, особенно роботу. В 2022 году Асимо ушёл на заслуженный отдых.", "q": "Что умеет делать робот Асимо?", "a": [ "Подниматься по лестнице", "Летать в космос", "Печь булочки" ] }, { "id": "jpn-b-avtomaty", "e": "🥤", "t": "Автомат на каждом углу", "s": "В Японии автоматы с напитками стоят почти везде: на улицах, у храмов и даже в горах. Они продают воду, чай, сок и кофе. Самое интересное, что один и тот же автомат даёт и холодные напитки, и горячие. Холодные банки обычно подписаны синим цветом, а горячие красным. В холодный день банка приятно греет ладошки, как маленькая грелка.", "q": "Какие напитки продаёт один японский автомат?", "a": [ "И холодные, и горячие", "Только мороженое", "Только сладкую вату" ] }, { "id": "jpn-b-shlem-samuraya", "e": "⛑️", "t": "Шлем самурая", "s": "Шлем самурая называется кабуто. Его делали из железных полосок, а на лоб прикрепляли яркое украшение: рога, полумесяц или даже рисунок зверя. Доспех из маленьких пластинок скрепляли шёлковыми шнурами и покрывали лаком, чтобы он блестел и не боялся сырости. Такой доспех был очень красивым, как нарядный костюм для праздника, и каждый мастер делал его по-своему.", "q": "Как называется шлем самурая?", "a": [ "Кабуто", "Кимоно", "Оригами" ] }, { "id": "jpn-b-katana", "e": "🔨", "t": "Мастера катаны", "s": "Катана — это длинный изогнутый меч самураев, и сделать его очень трудно. Кузнец раскаляет сталь, много раз складывает и куёт. Потом другой мастер часами полирует лезвие, а третий делает красивые ножны. Такой меч в Японии считают произведением искусства. Сегодня катаны можно увидеть в музеях, они хранятся там как драгоценные сокровища.", "q": "Что делает кузнец, когда создаёт катану?", "a": [ "Раскаляет и куёт сталь", "Лепит её из глины", "Вырезает из дерева" ] }, { "id": "jpn-b-himeji", "e": "🏯", "t": "Замок Белая цапля", "s": "Замок Химэдзи называют Белой цаплей. Его стены покрыты белой штукатуркой, а изогнутые крыши похожи на раскрытые крылья. Кажется, что огромная птица стоит на холме и вот-вот взлетит. Главную башню достроили около 1609 года, так что замку больше четырёхсот лет. Он занесён в список Всемирного наследия ЮНЕСКО, и сюда любят приезжать гости со всей планеты.", "q": "Какую птицу напоминает замок Химэдзи?", "a": [ "Белую цаплю", "Чёрного ворона", "Розового фламинго" ] }, { "id": "jpn-b-matsumoto", "e": "🐦‍⬛", "t": "Замок Ворон", "s": "Замок Мацумото называют замком Ворона, потому что его стены тёмные, почти чёрные, как вороньи перья. Он стоит не на горе, а на ровной земле, и вокруг него вода. Через ров перекинут красный мостик, а в воде отражается весь замок. Особенно красив он весной, когда рядом цветёт сакура. Замок очень старый: его начали строить около 1590 года.", "q": "Как называют замок Мацумото?", "a": [ "Замок Ворона", "Замок Лисы", "Замок Медведя" ] }, { "id": "jpn-b-origami-zhuravlik", "e": "🕊️", "t": "Тысяча журавликов", "s": "Оригами — это искусство складывать фигурки из бумаги. Самая известная фигурка — журавлик. В Японии говорят, что журавль живёт тысячу лет. Поэтому люди складывают тысячу журавликов, нанизывают их на нитки и дарят тому, кому желают здоровья и счастья. Для такой гирлянды нужно очень много бумаги и терпения, зато подарок получается яркий, как радуга.", "q": "Сколько журавликов складывают для гирлянды с пожеланием?", "a": [ "Тысячу", "Двух", "Сто тысяч" ] }, { "id": "jpn-b-kimono-obi", "e": "👘", "t": "Кимоно и пояс оби", "s": "Кимоно — традиционная японская одежда, похожая на длинный халат с широкими рукавами. Его запахивают и подвязывают широким поясом, который называется оби. Пояс бывает очень длинным, и на спине его завязывают красивым бантом. Банты бывают разных видов. Надеть кимоно не так просто, поэтому часто взрослые помогают друг другу.", "q": "Как называется пояс, которым подвязывают кимоно?", "a": [ "Оби", "Гэта", "Кабуто" ] }, { "id": "jpn-b-geta", "e": "🩴", "t": "Деревянные гэта", "s": "Гэта — это японские сандалии на деревянной подставке с двумя «зубцами» снизу. Они поднимают ногу над землёй, поэтому в дождь подол кимоно не промокает. Когда идёшь в гэта, они стучат: «клак, клак!» А рядом носят дзори, мягкие плоские сандалии. Те и другие надевают с носками таби, у которых большой палец отделён от остальных.", "q": "Что делает гэта высокими?", "a": [ "Деревянная подставка с двумя зубцами", "Воздушные шарики", "Железные пружины" ] }, { "id": "jpn-b-kalligrafiya", "e": "🖌️", "t": "Рисуем буквы кистью", "s": "Японцы умеют писать очень красиво. Это искусство называется сёдо — «путь письма». Для него нужны кисть, чёрная тушь и бумага. Тушь растирают на каменной плитке с водой. Каждая линия получается разной: то толстой, то тонкой, то лёгкой, как дымок. В начале года в Японии принято писать кистью первые слова нового года, и дети тоже так делают.", "q": "Что нужно японцам для искусства сёдо?", "a": [ "Кисть, тушь и бумага", "Мел и доска", "Ножницы и клей" ] }, { "id": "jpn-b-veer-vagasa", "e": "☂️", "t": "Веер и бумажный зонтик", "s": "В Японии веера бывают двух видов: плоские и складные. Складной веер умещается в рукав, а потом раскрывается, как цветок. Его берут на праздники и в танцы. А зонтик из бамбука и промасленной бумаги тоже очень красив. От дождя он защищает, а в солнечный день украшает прогулку: бумага красиво пропускает свет. Такие зонтики расписывают цветами, волнами или рыбками.", "q": "Из чего делают старинный японский зонтик?", "a": [ "Из бамбука и бумаги", "Из железа", "Из стекла" ] }, { "id": "jpn-c-snow-monkeys", "e": "🐒", "t": "Обезьяны в горячей ванне", "s": "В горах Японии, в долине Дзигокудани, зимой лежит глубокий снег. А в тёплой воде источника сидят макаки! Над водой видны только мордочки с красными щёчками, а на шерсти блестят снежинки. Макаки любят погреться, а малыши играют рядом. Говорят, первая обезьянка залезла в источник в 1960-х годах, а за ней потянулись и другие. Теперь у них есть свой бассейн.", "q": "Где зимой греются японские макаки?", "a": [ "В тёплой воде источника", "В домике из снега", "Под большим зонтом" ] }, { "id": "jpn-c-nara-deer", "e": "🦌", "t": "Олени, которые кланяются", "s": "В парке города Нара гуляют больше тысячи оленей, и никто их не боится. Они подходят к людям и просят угощение. Для них продают особое печенье, оно называется «сика-сэмбэй» и сделано из рисовых отрубей. Когда олень хочет печенье, он часто кивает головой, будто кланяется. Дети кланяются в ответ и протягивают угощение на ладони. Оленей в Наре издавна считают посланниками богов.", "q": "Что делают олени в парке Нара, когда просят печенье?", "a": [ "Кивают головой, будто кланяются", "Поют песенки", "Машут хвостом, как собаки" ] }, { "id": "jpn-c-nara-buddha", "e": "🛕", "t": "Огромный Будда в Наре", "s": "В Наре есть храм Тодайдзи, а в нём сидит огромный бронзовый Будда, ростом с пятиэтажный дом. Ему больше тысячи лет! Чтобы его укрыть, построили деревянный зал, один из самых больших деревянных зданий в мире. Позади Будды в одной колонне есть дырка, говорят, размером с ноздрю Будды. Дети пролезают через неё и загадывают желание. Считается, что кто пролез, тому повезёт.", "q": "Через какую дырку пролезают дети в храме Тодайдзи?", "a": [ "Размером с ноздрю Будды", "Размером с монетку", "Размером с окошко" ] }, { "id": "jpn-c-pagoda", "e": "🏯", "t": "Башня, которая покачивается", "s": "В Японии земля иногда дрожит, поэтому дома строят хитро. Старинные пагоды стоят уже много веков. Внутри пагоды в середине есть толстый столб, а этажи сложены вокруг него и не держатся за него намертво. Когда земля качнётся, этажи плавно покачиваются, как танцоры, и башня остаётся на месте. Эту мудрость взяли и для высокой башни Токио Скайтри: у неё тоже есть крепкий столб в середине.", "q": "Как устроена старинная японская пагода?", "a": [ "Внутри толстый столб, а этажи вокруг него", "Она стоит на больших пружинах", "Она сделана из одного камня" ] }, { "id": "jpn-c-school-drill", "e": "⛑️", "t": "Урок «как вести себя спокойно»", "s": "В японских школах дети учатся, что делать, если земля вдруг качнётся. Это спокойный урок, как физкультура. Все прячутся под парту, держатся за её ножку и защищают голову. У каждого есть мягкий капюшон-шлем, он лежит на стуле или в классе под рукой. Потом ребята выстраиваются и идут во двор. Дети знают, что делать, и поэтому чувствуют себя уверенно. А учитель потом хвалит всех.", "q": "Куда прячутся японские дети во время учебной тревоги?", "a": [ "Под парту", "В шкаф", "За дверь" ] }, { "id": "jpn-c-black-eggs", "e": "🥚", "t": "Чёрные яйца из долины пара", "s": "В Японии больше ста вулканов, которые ещё дышат теплом. Поэтому в стране много горячих источников, они называются «онсэн». Японцы любят в них отдыхать, но сначала тщательно моются под душем. А в горах возле Хаконэ, в долине, где идёт пар, варят яйца прямо в горячей воде источника. Скорлупа становится чёрной! Внутри яйцо самое обычное, белое и вкусное. Туристы берут их на память.", "q": "Какого цвета становится скорлупа яиц в долине Хаконэ?", "a": [ "Чёрного", "Розового", "Голубого" ] }, { "id": "jpn-c-cat-island", "e": "🐈", "t": "Остров кошек", "s": "У берега Японии лежит маленький островок Аосима. Живёт там совсем мало людей, в основном рыбаки, а вот кошек намного больше! Говорят, их привезли много лет назад, чтобы они ловили мышей на рыбацких лодках. Кошки остались и размножились. Они лежат на пристани, греются на солнышке и ждут, когда рыбаки вернутся с уловом. Туристы приезжают на остров, чтобы с ними познакомиться.", "q": "Зачем кошек привезли на остров Аосима?", "a": [ "Ловить мышей на лодках", "Чтобы они пели", "Чтобы украшать дома" ] }, { "id": "jpn-c-sapporo-snow", "e": "⛄", "t": "Город из снега в Саппоро", "s": "На севере Японии, на острове Хоккайдо, есть город Саппоро. Каждую зиму там проходит праздник снега. На главной улице-парке появляются огромные скульптуры: замки, звери и герои сказок, высотой с дом! Всё сделано из снега и льда. Начиналось с малого: в 1950 году школьники слепили в парке шесть снежных фигур. Людям понравилось, и теперь праздник знают во всём мире. А вечером скульптуры подсвечивают.", "q": "Кто слепил первые снежные скульптуры в Саппоро?", "a": [ "Школьники", "Зайцы", "Волшебник" ] }, { "id": "jpn-c-tancho", "e": "🦢", "t": "Журавли с красной шапочкой", "s": "На Хоккайдо живут журавли-танчо. Они белые, шея и кончики крыльев у них чёрные, а на макушке красное пятнышко, как шапочка. Зимой они танцуют на снегу: кланяются, подпрыгивают и раскрывают крылья. Давным-давно этих птиц осталось совсем мало, но люди стали заботиться о них и подкармливать зимой. Теперь журавлей снова почти две тысячи. В Японии журавль — символ долгой жизни и счастья.", "q": "Что у журавля-танчо на макушке?", "a": [ "Красное пятнышко", "Синий хохолок", "Жёлтый бантик" ] }, { "id": "jpn-c-tanuki", "e": "🍃", "t": "Тануки с листиком на голове", "s": "В японских сказках живёт тануки: зверёк с пушистым хвостом, похожий на енота. На самом деле это енотовидная собака. В сказках тануки умеет превращаться, например, в чайник, а чтобы превратиться, кладёт на голову листик. Возле японских ресторанов и лавок стоят забавные статуи тануки: с круглым животом, в большой шляпе и с бутылочкой в лапе. Люди верят, что они приносят удачу.", "q": "Что кладёт на голову тануки из сказок, чтобы превратиться?", "a": [ "Листик", "Камешек", "Ложку" ] }, { "id": "jpn-c-koi", "e": "🐟", "t": "Разноцветные рыбки кои", "s": "В японских садах есть пруды, где плавают большие рыбы кои. Они красные, белые, золотые, а у некоторых на спине узоры, как на картине. Выводить красивых кои начали около двухсот лет назад в горных деревнях, где выращивали рис. Их вывели из обычных карпов. Кои живут много лет, иногда несколько десятков! Они привыкают к людям и подплывают, когда те подходят к воде. А ещё кои любят, когда их кормят.", "q": "Из каких рыб вывели красивых кои?", "a": [ "Из обычных карпов", "Из акул", "Из золотых рыбок-лилипутов" ] }, { "id": "jpn-c-yakushima", "e": "🌲", "t": "Древний лес на Якусиме", "s": "На острове Якусима растёт старинный лес. Дожди идут там очень часто, поэтому всё покрыто мягким зелёным мхом, а с камней падают ручьи. Там живут дикие олени и макаки. Самые старые кедры на острове живут тысячи лет! Самый известный называют Дзёмон-суги. Некоторые говорят, что похожий лес на острове вдохновил мультфильм «Принцесса Мононоке». Идёшь по тропинке, и кажется, будто в тени прячутся лесные духи.", "q": "Чем покрыт лес на острове Якусима?", "a": [ "Мягким зелёным мхом", "Снегом круглый год", "Песком" ] }, { "id": "jpn-d-sushi-hands", "e": "🍣", "t": "Суши можно брать руками", "s": "Суши делают из риса, слегка приправленного уксусом, и кусочка рыбы или другой начинки. Повар сжимает рис ладонями так бережно, чтобы кусочек держался вместе. А едят суши и палочками, и просто руками! В Японии это совершенно вежливо. Суши макают в соевый соус рыбкой вниз, чтобы рис не размок и не развалился в чашке.", "q": "Чем можно есть суши в Японии?", "a": [ "Палочками или руками", "Только большой ложкой", "Только вилкой с тремя зубцами" ] }, { "id": "jpn-d-ramen-slurp", "e": "🍜", "t": "Хлюпать можно!", "s": "В Японии есть рамен — горячий суп с длинной лапшой. И знаете что? Лапшу там принято втягивать в рот с хлюпаньем! Говорят, так она быстрее остывает, а ещё хлюпанье показывает повару: «Как вкусно!» Едят рамен палочками и ложкой, а бульон многие пьют прямо из миски. Только не торопитесь: лапша бывает очень горячей.", "q": "Как в Японии принято есть горячую лапшу?", "a": [ "Втягивать и хлюпать", "Резать ножом на кусочки", "Есть шёпотом и очень тихо" ] }, { "id": "jpn-d-bento", "e": "🍱", "t": "Коробка с обедом", "s": "Японские дети часто берут с собой бенто — коробку с обедом, разделённую на отсеки. В одном лежит рис, в другом кусочки рыбы или яичный рулетик, в третьем овощи. А самое любимое — онигири: рисовый шарик или треугольник с начинкой внутри, часто обёрнутый листом сушёных водорослей нори. Мамы иногда выкладывают из еды мордочки зверят, чтобы малышу было радостно открывать коробку.", "q": "Что такое бенто?", "a": [ "Коробка с обедом из нескольких отсеков", "Тёплая шапка для зимы", "Лодка для ловли рыбы" ] }, { "id": "jpn-d-school-lunch", "e": "🥛", "t": "Дежурные в белых фартуках", "s": "Во многих японских школах обед дети не берут из дома, а едят в классе то, что привезли из кухни. Дежурные ученики надевают белые фартуки и колпачки, привозят тележку с едой и сами раздают порции одноклассникам. Потом все едят вместе, и учитель обычно тоже. А после обеда ребята сами наводят порядок в классе. Так они учатся заботиться о месте, где учатся каждый день.", "q": "Кто в японской школе раздаёт обед?", "a": [ "Дежурные ученики", "Робот-повар", "Директор школы" ] }, { "id": "jpn-d-koinobori", "e": "🎏", "t": "Карпы в небе", "s": "Пятого мая в Японии День детей. Над домами на высоких шестах поднимают кои-нобори — длинные флажки в форме карпов. Ветер надувает их, и рыбы будто плывут по небу! Карп упрямый и сильный: он умеет плыть вверх по течению. Поэтому японцы желают детям вырасти смелыми и сильными. Часто на шесте несколько карпов, большие и маленькие, как целая семья.", "q": "Какую рыбу изображают флажки кои-нобори?", "a": [ "Карпа", "Акулу", "Золотую рыбку" ] }, { "id": "jpn-d-tanabata", "e": "🎋", "t": "Праздник звёзд Танабата", "s": "Седьмого июля японцы празднуют Танабату. Старая легенда рассказывает о двух звёздах, Веге и Альтаире. Их разделяет небесная река, Млечный Путь, и встретиться они могут только раз в году. Люди пишут свои желания на разноцветных бумажных полосках и привязывают их к веткам бамбука. Получаются целые зелёные деревья, увешанные мечтами, которые тихо шуршат на ветру. В некоторых местах праздник отмечают в августе.", "q": "Куда в Танабату вешают бумажки с желаниями?", "a": [ "На ветки бамбука", "На хвост кота", "На колокол" ] }, { "id": "jpn-d-hinamatsuri", "e": "🎎", "t": "Праздник кукол", "s": "Третьего марта в Японии отмечают Хина-мацури, праздник кукол. В домах, где есть девочки, ставят лесенку, застеленную красной тканью. На ступенях сидят нарядные куклы: император и императрица на самом верху, а ниже придворные дамы и музыканты в старинных одеждах. Это не игрушки, а украшения: их достают на несколько недель в году и бережно убирают. Рядом ставят сладости и цветы.", "q": "Куда ставят кукол на Хина-мацури?", "a": [ "На лесенку с красной тканью", "Под одеяло", "В бумажную лодку" ] }, { "id": "jpn-d-new-year-bell", "e": "🔔", "t": "Колокол в новогоднюю ночь", "s": "В новогоднюю ночь в японских буддийских храмах звонит большой бронзовый колокол. Обычно его бьют сто восемь раз, не спеша, и звук плывёт над ночным городом. Говорят, что каждый удар помогает людям отпустить обиды и тревоги старого года. Бьют толстым деревянным бревном, подвешенным на цепях. Многие приходят в храм послушать звон и встретить новый год в тишине.", "q": "Сколько раз обычно звонит колокол в японском храме в новогоднюю ночь?", "a": [ "Сто восемь раз", "Три раза", "Двенадцать раз" ] }, { "id": "jpn-d-maneki-neko", "e": "🐱", "t": "Кошка с поднятой лапой", "s": "У входа в японские лавки и кафе часто сидит керамическая кошка манэки-нэко с поднятой лапой. Она будто зовёт: «Заходите!» Говорят, она приносит удачу. Лапа у разных кошек разная: одни поднимают левую, чтобы звать гостей, другие правую, чтобы привлекать деньги, но в разных местах это объясняют по-разному. А бывают кошки с двумя поднятыми лапами.", "q": "Что делает кошка манэки-нэко?", "a": [ "Зовёт гостей поднятой лапой", "Ловит рыбу удочкой", "Играет на барабане" ] }, { "id": "jpn-d-bow-shoes", "e": "🙇", "t": "Поклон и обувь у порога", "s": "Когда японцы здороваются, они обычно не жмут руки, а кланяются. Чем ниже поклон, тем больше уважения. Есть ещё одно правило: заходя в дом, обувь оставляют в прихожей, у самого порога. Дальше идут в тапочках или просто в носках. Так в комнатах чисто, и на полу удобно сидеть, играть, а в японских домах ещё и спать на мягком матрасе.", "q": "Что делают японцы, когда входят в дом?", "a": [ "Снимают обувь у порога", "Надевают шляпу", "Звонят в колокольчик на крыше" ] }, { "id": "jpn-d-tea", "e": "🍵", "t": "Чайная церемония", "s": "В Японии есть особая чайная церемония, и проходит она неспешно. Мастер взбивает бамбуковой кисточкой-венчиком зелёный порошок матчу с горячей водой, пока не поднимется нежная пена. Перед чаем гостям дают маленькую сладость, чтобы вкус чая казался мягче. Чашку держат двумя руками, а перед тем как пить, её аккуратно поворачивают. Каждое движение медленное и спокойное, как тихая музыка.", "q": "Чем взбивают матчу на чайной церемонии?", "a": [ "Бамбуковой кисточкой", "Большой ложкой", "Венчиком из перьев" ] }, { "id": "jpn-d-torii", "e": "⛩️", "t": "Ворота в воде", "s": "Ворота тории стоят у входа в японские святилища. Часто они ярко-красные, из двух столбов и двух перекладин. Они показывают, что за ними начинается особенное место, и многие слегка кланяются, проходя под ними. На острове Миядзима огромные ворота стоят прямо в море. Когда вода поднимается высоко, кажется, что они плывут по воде, а когда она уходит, к ним можно дойти пешком.", "q": "Что показывают ворота тории?", "a": [ "Вход в особенное место — святилище", "Начало футбольного поля", "Конец моста" ] } ], "chn": [ { "id": "chn-a-stena-gory", "e": "🏔️", "t": "Стена на горных хребтах", "s": "Великая Китайская стена не лежит ровной линией. Она карабкается по горным хребтам, как длинная каменная лента. Вверх, вниз и снова вверх. В некоторых местах ступени такие крутые, что приходится держаться за перила. Стену строили из кирпича и камня, а в безлесных краях даже из утрамбованной земли. Если сложить все её участки, рвы и природные преграды, по подсчётам получится больше двадцати тысяч километров. А от Москвы до Владивостока около девяти тысяч.", "q": "По чему карабкается стена?", "a": [ "По горным хребтам", "По дну озёр", "По крышам городов" ] }, { "id": "chn-a-stena-dym", "e": "🔥", "t": "Дым над башней", "s": "Вдоль стены стоят сторожевые башни, и каждая видна из соседней. Если стражник замечал что-то важное, он зажигал на крыше костёр. Днём была видна струя дыма, а ночью яркий огонь. Увидев сигнал, соседняя башня зажигала свой костёр, за ней следующая. Так весть бежала вдоль стены очень быстро. По преданию, для густого дыма в костёр добавляли даже сухой помёт.", "q": "Чем передавали весть от башни к башне?", "a": [ "Дымом и огнём", "Звоном колоколов", "Почтовыми голубями" ] }, { "id": "chn-a-stena-zima", "e": "❄️", "t": "Прогулка по стене зимой", "s": "Недалеко от Пекина есть участок стены Мутяньюй. Наверх туда можно подняться на канатной дороге, а вниз скатиться в тележке-санках по длинному жёлобу. Зимой на зубцах бывает снег, а вдали белеют горы. Идёшь по широкой дорожке, где когда-то ходили стражники, и вокруг очень тихо. Башни стоят в снегу, как домики в пушистых шапках.", "q": "Как можно спуститься со стены Мутяньюй?", "a": [ "В тележке-санках по жёлобу", "На воздушном шаре", "В лифте внутри башни" ] }, { "id": "chn-a-pekin-sever", "e": "🏙️", "t": "Северная столица", "s": "Слово «Пекин» составлено из двух слов. «Бэй» по-китайски значит «север», а «цзин» — «столица». Получается «северная столица». Есть в Китае и город Нанкин, а это «южная столица». В Пекине живёт больше двадцати миллионов человек. Город давно растёт и всё время строит новые улицы.", "q": "Что значит слово «Пекин»?", "a": [ "Северная столица", "Красный дворец", "Город у реки" ] }, { "id": "chn-a-pekin-golubi", "e": "🕊️", "t": "Голуби со свистульками", "s": "Старые улочки Пекина называют хутунами. Они узкие, а за стенами прячутся дворики с деревьями. Иногда в хутунах слышны необычные звуки. Это летят голуби, а к их хвостикам привязаны лёгкие свистульки. Ветер дует в свистульку, и над крышами звучит тонкая музыка. Старая традиция жива, хотя голубятников стало меньше. Пекинцы любят слушать небо, сидя во дворе.", "q": "Что привязывают голубям к хвосту?", "a": [ "Лёгкие свистульки", "Маленькие колокольчики", "Цветные ленточки" ] }, { "id": "chn-a-pekin-gnezdo", "e": "🪺", "t": "Стадион-гнездо", "s": "В Пекине стоит стадион, похожий на огромное птичье гнездо. Его построили к Олимпийским играм 2008 года. Стальные балки переплетены, как прутья в гнезде, а между ними видно небо. Издалека кажется, что гнездо свили великанские птицы. Внутри помещаются десятки тысяч зрителей. Недаром его так и зовут: «Птичье гнездо».", "q": "На что похож пекинский стадион?", "a": [ "На птичье гнездо", "На большую вазу", "На морскую раковину" ] }, { "id": "chn-a-zapgorod-dvortsy", "e": "🏯", "t": "Город, в который не пускали", "s": "В центре Пекина стоит Запретный город. Это огромный дворец, где много лет жили императоры. Он как целый город из залов, двориков и галерей, зданий там почти тысяча. Простым людям входить сюда было нельзя, потому город и назвали запретным. Теперь это музей, и каждый может прийти и погулять по дворикам. Главный зал называют Залом Высшей гармонии.", "q": "Почему город назвали запретным?", "a": [ "Простым людям входить было нельзя", "Он был закрыт зимой", "В нём запрещали шуметь" ] }, { "id": "chn-a-zapgorod-krasnoe", "e": "🟡", "t": "Красные стены, жёлтые крыши", "s": "Стены Запретного города красные. В Китае красный цвет считают цветом счастья. А крыши покрыты жёлтой черепицей. Жёлтый был цветом императора, и почти никому другому так красить крыши не разрешали. Когда светит солнце, жёлтые крыши блестят над красными стенами. Издалека кажется, что дворец сделан из золота и огня.", "q": "Какого цвета черепица на крышах дворца?", "a": [ "Жёлтая", "Синяя", "Зелёная" ] }, { "id": "chn-a-zapgorod-lvy", "e": "🦁", "t": "Каменные львы у ворот", "s": "У ворот дворцов в Китае часто сидят каменные или бронзовые львы, всегда парой. Один лев придерживает лапой шар. Рядом с другим сидит маленький львёнок. По старому поверью, такие львы охраняют дом. Они стоят и у ворот Запретного города. Дети любят искать, у какого льва шар, а у какого львёнок.", "q": "Что придерживает лапой один из львов?", "a": [ "Шар", "Свиток", "Рыбку" ] }, { "id": "chn-a-zapgorod-koshki", "e": "🐱", "t": "Кошки-сторожа во дворце", "s": "Запретный город теперь музей, и там живут кошки. Рыжие, серые, пёстрые, их, говорят, больше ста пятидесяти. Работники музея называют их сторожами: кошки ловят мышей, которые могли бы грызть старые вещи. Днём кошки прячутся от толпы, а ходят в основном ночью. О кошках заботятся: их кормят и лечат.", "q": "Зачем во дворце живут кошки?", "a": [ "Ловят мышей", "Стерегут ворота от львов", "Звонят в колокол" ] }, { "id": "chn-a-nebesny-hram", "e": "⛲", "t": "Круглый храм в парке", "s": "Небесный храм стоит в большом парке в Пекине. Главный зал у него круглый, с тремя ярусами синей крыши. По старым представлениям, небо круглое, а земля квадратная, поэтому зал сделали круглым. Утром в парке полно людей. Одни делают медленную зарядку, похожую на танец, другие поют, играют на флейтах или подбивают ногой воланчик с пёрышками.", "q": "Какой формы главный зал Небесного храма?", "a": [ "Круглый", "Квадратный", "Треугольный" ] }, { "id": "chn-a-panda-bambuk", "e": "🎋", "t": "Бамбуковый завтрак", "s": "Панда — это медведь, но ест она почти один бамбук. Побеги и стебли малопитательные, поэтому приходится есть очень много: больше десяти килограммов в день. Панда жуёт большую часть дня, сидя на попе, как человек. Она берёт стебель лапами, сдирает жёсткую кожуру и хрустит. Хруст слышно издалека. Потом она ложится вздремнуть, и снова за бамбук.", "q": "Что почти всё время жуёт панда?", "a": [ "Бамбук", "Морковь", "Мёд" ] }, { "id": "chn-a-panda-malysh", "e": "🍫", "t": "Малыш как плитка шоколада", "s": "Новорождённый панда совсем крошечный, розовый, почти без шерсти. Он весит около ста граммов, как плитка шоколада. Мама-панда тяжелее его в сотни раз. Около месяца малыш ничего не видит, глаза у него закрыты. Мама бережно держит его в лапе. Но малыш быстро растёт, покрывается чёрно-белой шерстью и скоро начинает ползать.", "q": "Сколько примерно весит новорождённый панда?", "a": [ "Как плитка шоколада", "Как большой арбуз", "Как кирпич" ] }, { "id": "chn-a-panda-cveta", "e": "🐼", "t": "Почему панда чёрно-белая", "s": "Почему у панды такая необычная шубка? Учёные думают, что белый мех помогает прятаться в снегу, а чёрные лапы и уши растворяются в тени деревьев. Тёмные пятна вокруг глаз, как считают некоторые, помогают пандам узнавать друг друга. Точно никто не знает. Учёные до сих пор наблюдают за пандами и придумывают проверки.", "q": "Где, по мнению учёных, помогают прятаться белые бока панды?", "a": [ "В снегу", "В тёмной пещере", "В реке" ] }, { "id": "chn-a-panda-chengdu", "e": "🏡", "t": "Детский сад для панд", "s": "В городе Чэнду, в провинции Сычуань, есть большой питомник панд. Там заботятся о пандах и помогают им растить малышей. Рядом с вольерами шумит бамбуковая роща. Малыши-панды играют, лазают по деревьям и неуклюже кувыркаются. Работники следят за здоровьем малышей. Гости приезжают издалека, чтобы посмотреть на пандят.", "q": "В каком городе большой питомник панд?", "a": [ "В Чэнду", "В Нанкине", "В Пекине" ] }, { "id": "chn-a-panda-palec", "e": "👍", "t": "Шестой палец панды", "s": "У панды на передних лапах пять пальцев. А ещё есть особый выступ, похожий на шестой палец. Это не настоящий палец, а выросшая косточка у запястья. Но им панда ловко прижимает стебель к лапе, как мы зажимаем палочку. Если смотреть, как панда ест, видно: стебель она держит очень уверенно. Это хорошее приспособление для обеда.", "q": "Чем панда удобно держит бамбук?", "a": [ "Лапой с выступом-«пальцем»", "Хоботом", "Хвостом" ] }, { "id": "chn-a-army-lica", "e": "🗿", "t": "Лица глиняных воинов", "s": "Под землёй возле города Сиань стоят тысячи глиняных воинов. Они в рост человека, а то и выше. Мастера лепили им лица, и почти нет двух одинаковых. У одного усы, у другого борода, у третьего другая причёска. Одни воины серьёзные, а другие будто чуть улыбаются. Гости ходят вдоль рядов и ищут самое доброе лицо.", "q": "Что особенного в лицах глиняных воинов?", "a": [ "Почти нет одинаковых", "Все одинаковые", "Все смеются" ] }, { "id": "chn-a-army-kolodec", "e": "🕳️", "t": "Колодец, который нашёл армию", "s": "Весной 1974 года крестьяне возле Сианя искали воду и копали колодец. Вдруг лопаты наткнулись на куски обожжённой глины. Это были осколки глиняных воинов, лежавших под землёй много веков. Крестьяне рассказали о находке, и приехали учёные. Так люди узнали о подземной армии. Теперь рядом стоит большой музей.", "q": "Что копали крестьяне, когда нашли воинов?", "a": [ "Колодец", "Погреб", "Пруд" ] }, { "id": "chn-a-army-loshadi", "e": "🐎", "t": "Лошади и колесницы", "s": "Рядом с воинами под землёй нашли глиняных лошадей. Они стоят упряжками и будто ждут команды. Лошади как живые. Позже нашли и колесницы. Они бронзовые и примерно вдвое меньше настоящих, но очень подробные, даже с навесом над возницей. Мастера старались, чтобы всё было как в жизни.", "q": "Из чего сделаны найденные колесницы?", "a": [ "Из бронзы", "Из золота", "Изо льда" ] }, { "id": "chn-a-bumaga-syuanchzhi", "e": "🖌️", "t": "Бумага для кисти", "s": "Для рисования тушью в Китае есть особая бумага, сюаньчжи. Её делают в провинции Аньхой из коры одного дерева и рисовой соломы. Бумага мягкая и впитывает тушь так, что мазок кисти получается живым, с переходами. Говорят, сюаньчжи может храниться очень долго. Художник проводит кистью по листу, и на нём вырастает гора или бамбук.", "q": "Из чего делают бумагу сюаньчжи?", "a": [ "Из коры дерева и рисовой соломы", "Из шёлка и воды", "Из листьев и песка" ] }, { "id": "chn-a-bumaga-vyrezki", "e": "✂️", "t": "Узоры из красной бумаги", "s": "В Китае умеют вырезать из бумаги настоящие картины. Берут красный лист, складывают его пополам или вчетверо и режут ножницами. Развернёшь, и появляется узор: цветок, рыбка, птичка. Половинки получаются одинаковые, потому что бумага была сложена. Такие вырезки клеят на окна, и свет красиво просвечивает через красные цветы.", "q": "Почему половинки узора получаются одинаковые?", "a": [ "Бумагу складывают пополам", "Узор рисуют по линейке", "Бумагу красят с двух сторон" ] }, { "id": "chn-a-shelk-tut", "e": "🐛", "t": "Гусеницы и тутовые листья", "s": "Шёлк делает гусеница шелкопряда. Из крошечного яичка она вылезает совсем маленькой. Ест она только листья тутовника, день за днём. Говорят, когда гусениц много, их хруст похож на шорох дождя. За месяц она становится в десятки раз тяжелее и четыре раза меняет кожу. Поэтому в Китае рядом с шёлком выращивали и тутовые деревья.", "q": "Какие листья едят шелкопряды?", "a": [ "Тутовые", "Дубовые", "Берёзовые" ] }, { "id": "chn-a-shelk-put", "e": "🐫", "t": "Шёлковый путь", "s": "Шёлковый путь — это не одна дорога, а много дорог через горы и пустыни. По ним шли караваны верблюдов. Купцы месяцами везли шёлк из Китая, а обратно привозили другие товары. Название придумал уже позднее учёный из Германии. Люди на тех дорогах узнавали друг у друга новые сказки и ремёсла.", "q": "На ком шли караваны по Шёлковому пути?", "a": [ "На верблюдах", "На слонах", "На лодках" ] }, { "id": "chn-a-farfor-kaolin", "e": "🏺", "t": "Белая глина каолин", "s": "Фарфор делают из особой белой глины, каолина. Её название пришло от места Гаолин, что значит «высокий холм» или «высокий хребет». В Китае есть город Цзиндэчжэнь, где фарфор делают много веков. Чашку обжигают в очень жаркой печи, и она становится твёрдой и звонкой. Если ударить по краю, раздаётся тонкий звук. Тонкая чашка даже просвечивает на свету.", "q": "Как называется белая глина для фарфора?", "a": [ "Каолин", "Гранит", "Мел" ] }, { "id": "chn-a-farfor-china", "e": "🍵", "t": "Чашка по имени «чайна»", "s": "По-английски фарфор называют «china», читается «чайна». Это то же слово, что и название страны Китай. Фарфоровые чашки и сервизы долго везли из Китая в другие страны, и люди так их и называли. Чайный сервиз из тонкого фарфора мог стоять в доме как драгоценность. Слово пришло вместе с товаром.", "q": "Как по-английски называют фарфор?", "a": [ "«Чайна», как и страну", "«Сильк», как шёлк", "«Кап», как чашку" ] }, { "id": "chn-b-hieroglyph-pictures", "e": "🈶", "t": "Иероглиф-картинка", "s": "Давным-давно китайские иероглифы были просто маленькими рисунками. Гору рисовали тремя острыми вершинами. Солнце было кружочком с точкой посередине. Дерево рисовали со стволом, ветками и корнями. Со временем рисунки стали проще и превратились в чёрточки. Но если приглядеться, в иероглифе «гора» до сих пор видны три вершины!", "q": "Что рисовали тремя острыми вершинами?", "a": [ "Гору", "Солнце", "Дерево" ] }, { "id": "chn-b-hieroglyph-count", "e": "📚", "t": "Сколько всего иероглифов", "s": "В больших китайских словарях собраны десятки тысяч иероглифов. Выучить все не может никто, даже самый умный профессор. Чтобы читать газету, достаточно знать несколько тысяч. А чтобы читать детскую книжку с картинками, хватит нескольких сотен. Китайские первоклассники учат иероглифы понемногу, день за днём.", "q": "Сколько иероглифов нужно знать, чтобы читать детскую книжку?", "a": [ "Несколько сотен", "Все до одного", "Всего пять" ] }, { "id": "chn-b-hieroglyph-brush", "e": "🖌️", "t": "Кисточка и вода", "s": "Иероглифы красиво писать кисточкой с чёрной тушью. У каждого иероглифа свой порядок чёрточек: сверху вниз и слева направо. Сначала дети учатся держать кисточку прямо, как будто в руке тонкий стебелёк. А ещё в Китае любят рисовать водой! В парках люди берут большую кисть и пишут иероглифы на камнях. Вода высыхает на солнце, и надпись исчезает, как волшебная.", "q": "Чем пишут иероглифы на камнях в парках?", "a": [ "Кистью с водой", "Мелом", "Карандашом" ] }, { "id": "chn-b-chopsticks-three-thousand", "e": "🥢", "t": "Две палочки вместо вилки", "s": "В Китае едят палочками уже около трёх тысяч лет. Сначала, говорят, их использовали при готовке, чтобы доставать еду из горячего котла. Потом палочки перешли на стол. Они делаются из бамбука или дерева. Вместо вилки и ножа человек берёт две тонкие палочки. Рис, лапшу и даже маленькую горошину можно взять, если потренироваться.", "q": "Из чего часто делают палочки?", "a": [ "Из бамбука или дерева", "Из стекла", "Из мягкой резины" ] }, { "id": "chn-b-chopsticks-round-table", "e": "🍽️", "t": "Длинные палочки за круглым столом", "s": "В Китае часто обедают всей семьёй за большим круглым столом. Посередине стоят общие блюда: рыба, овощи, пельмени. Каждый тянется палочками и берёт себе кусочек. Поэтому палочки длинные: ими легко достать до середины стола. Столик посередине иногда вертится, как карусель. Нужное блюдо просто подъезжает к тебе, и тянуться не нужно!", "q": "Почему палочки длинные?", "a": [ "Чтобы достать до блюд посередине стола", "Чтобы ими рисовать", "Чтобы они были красивее" ] }, { "id": "chn-b-newyear-red", "e": "🏮", "t": "Красный Новый год", "s": "Китайский Новый год называют Праздником весны. Всё вокруг становится красным: фонарики, ленточки, бумажные узоры на окнах. Красный цвет здесь приносит счастье. Есть старая легенда про зверя по имени Нянь. Говорят, он боялся красного цвета и яркого шума. Поэтому, говорят, в праздник дома украшают красными фонариками и устраивают шум. Фонарики светят весь праздник.", "q": "Какого цвета украшения на Новый год в Китае?", "a": [ "Красного", "Серого", "Коричневого" ] }, { "id": "chn-b-newyear-envelope", "e": "🧧", "t": "Красный конверт", "s": "На Новый год в Китае детям дарят красные конверты. Внутри лежат деньги, а на конверте напечатаны добрые слова. Конверт называют хунбао. Его дают взрослые родственники и просят: расти большим и здоровым. Принимают подарок двумя руками, как будто берут что-то хрупкое, и вежливо говорят «спасибо». Открывать конверт при всех обычно не принято.", "q": "Как называют красный новогодний конверт?", "a": [ "Хунбао", "Юаньсяо", "Пудун" ] }, { "id": "chn-b-lantern-festival", "e": "🎑", "t": "Праздник фонарей", "s": "Новогодние праздники в Китае заканчиваются Праздником фонарей. Он выпадает на пятнадцатый день после начала года. По вечерам улицы и парки заливает свет тысяч фонарей. Они бывают в форме рыб, зайцев и драконов. На некоторых фонариках написаны загадки, и всем хочется их отгадать. А ещё в этот день едят сладкие шарики из рисовой муки. Их называют юаньсяо.", "q": "Что написано на некоторых фонариках?", "a": [ "Загадки", "Рецепты", "Адреса" ] }, { "id": "chn-b-dragon-kind", "e": "🐉", "t": "Добрый дракон", "s": "В Китае дракон совсем не такой, как в европейских сказках. Он не дышит огнём и никого не пугает. У него длинное тело, как у змеи, рога, как у оленя, и когти, как у орла. Живёт он в реках и облаках и приносит людям дождь. Поэтому китайцы считают дракона добрым и счастливым знаком. Многие родители надеются, что у их ребёнка будет сила дракона.", "q": "Что приносит китайский дракон людям?", "a": [ "Дождь", "Огонь", "Снег" ] }, { "id": "chn-b-dragon-dance", "e": "🎊", "t": "Танец дракона", "s": "На праздниках по улицам Китая «ползёт» длинный дракон. Он сделан из ткани и бумаги, а внутри у него, как в вагоне поезда, шагают десятки людей. Каждый держит шест и поднимает свой кусочек тела. Впереди бежит человек с шариком, будто с жемчужиной. Дракон играет и гоняется за ней. Когда все шагают вместе, дракон извивается, как живой.", "q": "За чем гоняется дракон в танце?", "a": [ "За жемчужиной", "За мячом", "За хвостом" ] }, { "id": "chn-b-shanghai-skyscraper", "e": "🏙️", "t": "Башня до облаков", "s": "Шанхай — один из самых больших городов Китая. В нём много небоскрёбов. Шанхайская башня выше всех, около шестисот тридцати метров. Она закручена спиралью, словно её слегка повернули. Из-за этого ветру труднее раскачивать башню. На самом верху есть площадка. Оттуда видно, как внизу ползут крошечные кораблики и машинки.", "q": "Как закручена Шанхайская башня?", "a": [ "Спиралью", "Квадратом", "Зигзагом" ] }, { "id": "chn-b-shanghai-maglev", "e": "🚄", "t": "Поезд без колёс", "s": "В Шанхае есть поезд, который не касается рельсов. Он парит над путём на невидимой магнитной подушке. Поэтому его ход такой плавный и тихий. Раньше он разгонялся почти до четырёхсот тридцати километров в час, а сегодня идёт чуть медленнее. Тридцать километров до аэропорта он проезжает всего за восемь минут. Пассажиры чуть успевают рассмотреть город за окном!", "q": "На чём парит шанхайский поезд?", "a": [ "На магнитной подушке", "На воздушных шарах", "На воде" ] }, { "id": "chn-b-shanghai-bund", "e": "🌃", "t": "Набережная двух эпох", "s": "В Шанхае течёт река Хуанпу. На одном её берегу стоят старинные каменные дома с колоннами. Это набережная, которую называют Бунд. На другом берегу, в районе Пудун, высятся стеклянные небоскрёбы самых странных форм. Вечером весь город зажигается разноцветными огнями. Люди гуляют по набережной и смотрят: старое здесь рядом с новым.", "q": "Как называют старую набережную в Шанхае?", "a": [ "Бунд", "Пудун", "Хуанпу" ] }, { "id": "chn-b-terraces-yuanyang", "e": "🌾", "t": "Лестница для великана", "s": "На юге Китая горы похожи на гигантские лестницы. Это рисовые террасы Юаньян. Люди вырезали ступени прямо в склонах много веков назад. Весной в них заливают воду, и каждая ступенька блестит, как зеркало. В воде отражаются небо и облака. Рано утром, когда над горами туман, кажется, что лестница уходит прямо в небо.", "q": "Что отражается в воде на террасах?", "a": [ "Небо и облака", "Города", "Корабли" ] }, { "id": "chn-b-terraces-longji", "e": "🐲", "t": "Хребет дракона", "s": "Есть место, где рисовые террасы называют «Хребтом дракона». Это горы Лунцзи. Поля идут по склонам волнами, будто на горе лежит огромный дракон с чешуёй. Эти террасы создавали много поколений крестьян. Зимой они отдыхают, весной блестят от воды. Летом они ярко зелёные, а осенью золотые, когда рис спеет.", "q": "Каким становится рис осенью?", "a": [ "Золотым", "Синим", "Белым" ] }, { "id": "chn-b-guilin-towers", "e": "⛰️", "t": "Горы-башни Гуйлиня", "s": "Возле города Гуйлинь из земли торчат высокие зелёные холмы. Они стоят отдельно, как башни или огромные пальцы, и между ними вьётся река Ли. Здесь есть поговорка, что пейзаж Гуйлиня — самый красивый под небом. Когда над реками стоит дымка, горы будто плавают в воздухе. Художники рисовали эти холмы на свитках сотни лет.", "q": "На что похожи холмы возле Гуйлиня?", "a": [ "На башни", "На шарики", "На шатры" ] }, { "id": "chn-b-guilin-cormorants", "e": "🐦", "t": "Рыбаки и бакланы", "s": "На реке Ли иногда можно увидеть рыбака на длинном бамбуковом плоту. Рядом сидят чёрные птицы — бакланы. Птица ныряет и ловит рыбу, а хозяин забирает её. На шею птицы надевают тонкое колечко, чтобы она не проглотила большую рыбу. Мелкую рыбёшку баклан съедает сам. Это очень старый способ ловли: птицы и человек работают вместе.", "q": "Что надевают на шею баклану?", "a": [ "Колечко", "Бантик", "Шарфик" ] }, { "id": "chn-b-tea-legend", "e": "🍵", "t": "Как появился чай", "s": "Старая легенда рассказывает о правителе по имени Шэнь-нун. Он любил пить только кипячёную воду. Однажды он сидел под деревом, пока кипела вода. Ветер сорвал несколько листочков, и они упали в котелок. Вода стала золотистой и вкусно запахла. Правитель отпил и удивился: напиток был приятным и бодрым. Так, по легенде, люди и открыли чай, очень давно.", "q": "Что упало в котелок с кипятком?", "a": [ "Листочки с дерева", "Цветок", "Камешек" ] }, { "id": "chn-b-tea-green-black", "e": "🌿", "t": "Один куст — два чая", "s": "Зелёный и чёрный чай растут на одном и том же кусте! Просто листья обрабатывают по-разному. Для зелёного чая листья сразу слегка подсушивают и прогревают, и они остаются зелёными. Для чёрного листьям дают немного полежать на воздухе, и они темнеют, как яблоко на срезе. Поэтому и вкус у чаёв разный: один мягкий и травяной, другой тёплый и густой.", "q": "Что делают с листьями для чёрного чая?", "a": [ "Дают полежать на воздухе", "Замораживают", "Моют в молоке" ] }, { "id": "chn-b-tea-ceremony", "e": "🫖", "t": "Чай в маленьких чашках", "s": "В Китае чай заваривают неторопливо, как маленький праздник. Берут крохотный чайничек и совсем маленькие чашки, похожие на напёрстки. Первую воду выливают: так листья пробуждаются, а чашки согреваются. Потом наливают чай и подают гостю. Чай пьют маленькими глотками, не спеша, и разговаривают. Одни и те же листья можно заваривать много раз, и каждый раз вкус немного другой.", "q": "Какие чашки берут для чая?", "a": [ "Совсем маленькие", "Огромные", "Железные" ] }, { "id": "chn-b-fast-trains", "e": "🚅", "t": "Пули на рельсах", "s": "В Китае проложены десятки тысяч километров путей для скоростных поездов. Это самая большая такая сеть в мире. Поезда мчатся со скоростью больше трёхсот километров в час. Их острый нос похож на клюв или на пулю. Из окна поля, мосты и города проносятся, как в кино. Дорога из одного большого города в другой занимает всего несколько часов вместо целого дня.", "q": "На что похож нос скоростного поезда?", "a": [ "На клюв или пулю", "На ложку", "На шапку" ] }, { "id": "chn-b-two-rivers", "e": "🌊", "t": "Две великие реки", "s": "В Китае две самые известные реки. Янцзы — самая длинная в Азии, больше шести тысяч километров. Она течёт по горам и равнинам и впадает в море около Шанхая. Хуанхэ, что значит «Жёлтая река», тоже очень длинная. Вода в ней жёлтая, потому что несёт много песка и глины. Обе реки текут с запада на восток, и на их берегах люди живут с глубокой древности.", "q": "Почему вода в Хуанхэ жёлтая?", "a": [ "Несёт много песка и глины", "В ней растёт жёлтая трава", "Её красят жёлтой краской" ] }, { "id": "chn-b-zodiac", "e": "🐭", "t": "Гонка двенадцати животных", "s": "В китайском календаре у каждого года есть своё животное. Всего их двенадцать: крыса, бык, тигр, кролик, дракон, змея, лошадь, коза, обезьяна, петух, собака и свинья. По старой сказке, они устроили гонку через реку, и в одной из версий всё было так. Хитрая крыса забралась на спину быка, а у финиша спрыгнула и пришла первой. Поэтому год крысы считается первым. Через двенадцать лет круг начинается снова.", "q": "Кто, по сказке, пришёл первым?", "a": [ "Крыса", "Тигр", "Дракон" ] }, { "id": "chn-b-noodles", "e": "🍜", "t": "Лапша долгой жизни", "s": "На день рождения в Китае едят длинную лапшу. Её называют лапшой долголетия. Одну нитку лапши делают очень длинной и стараются не перекусывать, а съесть целиком. Считается, что чем длиннее лапша, тем дольше будет жизнь. Это просто весёлая добрая примета и вкусное пожелание. Поэтому на праздничный стол лапшу подают нерезаной, длинной, и все желают имениннику здоровья.", "q": "Какую лапшу едят на день рождения?", "a": [ "Длинную, нерезаную", "Совсем короткую", "Только холодную" ] }, { "id": "chn-b-compass", "e": "🧭", "t": "Ложка, которая смотрит на юг", "s": "Говорят, около двух тысяч лет назад в Китае придумали первый прибор, похожий на компас. По описаниям, это была ложка из особого камня — магнита. Её ставили на гладкую дощечку, и она поворачивалась ручкой к югу. Позже появилась стрелка, лежащая на воде или на нитке. Моряки взяли её с собой в плавание. Так стрелка помогала не заблудиться в открытом море.", "q": "На что был похож самый старый компас?", "a": [ "На ложку", "На ключ", "На зонтик" ] } ], "ind": [ { "id": "ind-a-taj-tsvet", "e": "🕌", "t": "Тадж-Махал меняет цвет", "s": "В индийском городе Агре стоит дворец-мавзолей Тадж-Махал. Он весь из белого мрамора. Рано утром он кажется нежно-розовым. Днём он сияет белизной, а к вечеру становится золотистым. В лунную ночь он будто светится серебром. Мрамор всё тот же, меняется только свет. Поэтому люди приходят сюда в разные часы и смотрят на него снова и снова.", "q": "Каким Тадж-Махал кажется рано утром?", "a": [ "Нежно-розовым", "Ярко-зелёным", "Чёрным как уголь" ] }, { "id": "ind-a-taj-22-goda", "e": "⏳", "t": "Двадцать два года стройки", "s": "Тадж-Махал строили очень долго — по большинству источников, около двадцати двух лет, с 1632 года. Работали тысячи мастеров: каменщики, резчики по камню, садовники. Белый мрамор везли издалека на повозках, а сильные быки помогали тянуть тяжёлые грузы. Говорят, что помогали и слоны. Дети, которые родились в начале стройки, к её концу уже стали взрослыми. Зато дворец получился таким красивым, что его знают во всём мире.", "q": "Сколько лет строили Тадж-Махал?", "a": [ "Около двадцати двух", "Около двух", "Около сорока" ] }, { "id": "ind-a-taj-kamni", "e": "🌸", "t": "Цветы из камня", "s": "Если подойти к стене Тадж-Махала поближе, увидишь цветы и веточки. Но это не краска! Мастера вырезали крошечные кусочки цветных камней и вставили их в белый мрамор, как в мозаику. Красные, зелёные, синие лепестки подогнаны так точно, что щели не видно. Один маленький цветок мог собираться из множества кусочков. Такие цветы никогда не вянут.", "q": "Из чего сделаны цветы на стенах Тадж-Махала?", "a": [ "Из кусочков цветных камней", "Из цветной краски", "Из кусочков ткани" ] }, { "id": "ind-a-taj-minarety", "e": "🏛️", "t": "Четыре башни и сад", "s": "У Тадж-Махала по углам площадки стоят четыре высокие тонкие башни — минареты. Каждая примерно сорок метров высотой, как большой многоэтажный дом. Говорят, они чуть наклонены наружу, чтобы в случае беды не задеть главное здание. Перед дворцом раскинулся сад с длинным прудом. В тихой воде отражается белый купол, и кажется, что дворцов два.", "q": "Сколько минаретов у Тадж-Махала?", "a": [ "Четыре", "Два", "Семь" ] }, { "id": "ind-a-slon-uhi", "e": "🐘", "t": "Уши индийского слона", "s": "Слоны бывают африканские и индийские. У африканского слона уши огромные, как два больших паруса. У индийского слона уши заметно меньше, зато спина круглая, как горка. В жаркий день слон машет ушами, как веерами. Кровь в тонкой коже ушей остывает, и слону становится прохладнее. Так у него есть свой собственный вентилятор.", "q": "Какие уши у индийского слона, если сравнить с африканским?", "a": [ "Поменьше", "Побольше", "Точно такие же" ] }, { "id": "ind-a-slon-hobot", "e": "🐘", "t": "Хобот — рука и нос", "s": "Хобот у слона — это нос и верхняя губа, которые срослись и стали очень длинными. В нём много тысяч мышц, поэтому он гибкий и сильный. Слон может поднять толстое бревно и подобрать с земли маленький орешек. Когда слон хочет пить, он набирает хоботом воду и льёт её себе в рот. Хоботом он нюхает, здоровается с друзьями и обнимает слонёнка.", "q": "Как слон пьёт воду?", "a": [ "Набирает хоботом и льёт в рот", "Лакает языком, как кошка", "Пьёт через уши" ] }, { "id": "ind-a-slon-prazdnik", "e": "🎉", "t": "Нарядные слоны", "s": "На некоторых праздниках на юге Индии слонов наряжают. На них надевают яркие накидки, вешают блестящие золотые украшения, на лбу ярким цветом выводят узоры. Слоны медленно идут по улице, а люди смотрят и радуются. Рядом с каждым слоном идёт его погонщик, который хорошо знает своего друга. Для многих индийцев слон — добрый, мудрый символ праздника.", "q": "Чем украшают слонов на праздниках в Индии?", "a": [ "Яркими накидками и золотыми украшениями", "Тёплыми меховыми шубами", "Фигурками изо льда" ] }, { "id": "ind-a-slonenok", "e": "🍼", "t": "Слонёнок в стаде", "s": "Слонёнок рождается очень большим: он весит около ста килограммов. Через несколько часов он уже стоит на ногах и идёт за мамой. Хоботом слонёнок сначала управляет плохо: он путается в нём и даже наступает на него. Учиться ему приходится много месяцев. Стадо ведёт старшая слониха, а за малышом присматривают мама и тёти. Они не дают его в обиду.", "q": "Кто присматривает за слонёнком в стаде?", "a": [ "Мама и тёти", "Только папа", "Никто, он один" ] }, { "id": "ind-a-slon-kupanie", "e": "💦", "t": "Слоны любят купаться", "s": "Индийские слоны обожают воду. Они заходят в реку, плещутся и обливают себя из хобота. Слоны хорошо плавают. Если вода глубокая, слон поднимает кончик хобота над водой и дышит через него, как через трубку. Потом он выходит на берег и обсыпает себя песком и пылью. Это как крем от солнца и от кусачих насекомых.", "q": "Как слон дышит, когда плывёт в глубокой воде?", "a": [ "Через поднятый хобот", "Через уши", "Он не дышит" ] }, { "id": "ind-a-tigr-bengal", "e": "🐯", "t": "Бенгальский тигр", "s": "Бенгальский тигр — рыжий, с чёрными полосами и белой грудкой. Это самый известный тигр Индии. Взрослый самец может весить больше двухсот килограммов. Больше всего диких тигров на свете живёт именно в Индии, в лесах и высоких травах. Днём тигр обычно отдыхает в тени, а охотится вечером и ночью. Хотя он такой большой, ходит он почти бесшумно.", "q": "В какой стране живёт больше всего диких тигров?", "a": [ "В Индии", "В Австралии", "В Африке" ] }, { "id": "ind-a-tigr-polosy", "e": "🔍", "t": "Полосы как отпечатки", "s": "У каждого тигра свой узор из полос. Двух тигров с одинаковым рисунком не бывает, как не бывает одинаковых отпечатков пальцев. Полосы есть даже на коже под шерстью. Учёные ставят в лесу камеры, которые фотографируют проходящих тигров. По узору полос они узнают каждого и знают, кто где живёт. Так можно сосчитать тигров и не потревожить их.", "q": "По чему учёные узнают каждого тигра?", "a": [ "По узору полос", "По размеру усов", "По голосу" ] }, { "id": "ind-a-tigr-voda", "e": "🏊", "t": "Тигр в воде", "s": "В отличие от многих кошек, тигры любят воду. В жаркий день тигр заходит в реку или озеро и лежит там, пока ему не станет прохладно. Тигры хорошо плавают и без страха переплывают широкие реки. На востоке Индии и в соседнем Бангладеш, в мангровых зарослях Сундарбана, тигры даже перебираются вплавь с острова на остров. Домашняя кошка бы удивилась.", "q": "Что делает тигр в жаркий день?", "a": [ "Лежит в воде", "Лезет на высокую пальму", "Зарывается в снег" ] }, { "id": "ind-a-pavlin-ptitsa", "e": "🦚", "t": "Национальная птица", "s": "Павлин — национальная птица Индии. В некоторых местах его можно встретить прямо у деревни или у старого храма, и никто его не гонит. У павлина сине-зелёная шея и маленький хохолок на голове. Самка гораздо скромнее, коричневая. Голос у павлина громкий и похож на протяжное кошачье «мяу». Услышишь такой крик и сразу оглянешься.", "q": "Какая птица — национальная птица Индии?", "a": [ "Павлин", "Аист", "Попугай" ] }, { "id": "ind-a-pavlin-hvost", "e": "✨", "t": "Танец павлина", "s": "То, что мы называем хвостом павлина, на самом деле длинные перья на его спине. Они бывают длиной больше метра. На каждом перышке есть блестящий «глазок». Когда павлин хочет понравиться самке, он раскрывает перья веером и начинает медленно кружиться и трясти ими. Это и есть его танец. Говорят, что павлины танцуют к дождю, но чаще это просто совпадает с сезоном дождей. Каждый год после лета перья осыпаются, а потом вырастают новые.", "q": "Зачем павлин раскрывает перья веером?", "a": [ "Чтобы понравиться самке", "Чтобы согреться", "Чтобы испугать улитку" ] }, { "id": "ind-a-kaziranga", "e": "🦏", "t": "Носороги Казиранги", "s": "На северо-востоке Индии есть парк Казиранга. Там растёт высокая трава, выше слона, и много болотистых озёр. В парке живёт примерно две трети всех индийских носорогов на свете. У них один рог, а кожа лежит складками, как броня. Носороги любят валяться в грязи, так им прохладнее. На деревьях рядом прыгают обезьяны-макаки, а по тропам иногда проходят слоны.", "q": "Сколько рогов у индийского носорога?", "a": [ "Один", "Два", "Три" ] }, { "id": "ind-a-holi-kraski", "e": "🎨", "t": "Праздник красок Холи", "s": "Весной, в марте, в Индии отмечают Холи — праздник красок. Люди надевают старую белую одежду и выходят на улицу с пакетиками разноцветной пудры. Пудру называют гулал. Все бросают её друг в друга, смеются и обнимаются. Через час лица и волосы становятся розовыми, жёлтыми, синими и зелёными. Взрослые и дети перестают отличаться друг от друга — все одинаково весёлые.", "q": "Что бросают друг в друга на празднике Холи?", "a": [ "Цветную пудру", "Снежки", "Конфеты" ] }, { "id": "ind-a-holi-krishna", "e": "💙", "t": "Синий Кришна и Холи", "s": "По одной старой легенде про Холи рассказывают так. Маленький Кришна был синекожим. Он переживал: понравится ли он светлокожей Радхе? Мама пошутила: «Раскрась ей лицо любым цветом, и вы станете одинаковыми». Кришна так и сделал, и все рассмеялись. С тех пор, говорят, люди и красят друг друга на Холи. Это история о дружбе.", "q": "Какой цвет кожи у маленького Кришны в этой истории?", "a": [ "Синий", "Красный", "Зелёный" ] }, { "id": "ind-a-holi-koster", "e": "🔥", "t": "Вечер перед Холи", "s": "Накануне Холи, вечером, люди собираются вместе и зажигают большой костёр. Они стоят вокруг, поют и разговаривают. По легенде, огонь напоминает о победе добра, а ещё о том, что зима кончается и приходит весна. А наутро начинается шумное веселье с красками. В гостях друг у друга угощаются сладостями, например сладкими пирожками гуджия. Дверь на Холи открыта для всех, даже для соседей.", "q": "Что зажигают вечером накануне Холи?", "a": [ "Большой костёр", "Свечку на торте", "Огни на ёлке" ] }, { "id": "ind-a-diwali-ogni", "e": "🪔", "t": "Дивали — праздник огней", "s": "Осенью, в октябре или ноябре, в Индии отмечают Дивали. Это праздник огней, и его название означает «ряд огней». В эти дни люди моют и убирают дома, надевают новую одежду и дарят друг другу сладости. Вечером в окнах, на крышах и на ступенях зажигают много огоньков. Целые города сияют, как будто по земле рассыпали звёзды. Для многих индийцев это время света и радости.", "q": "Что означает название «Дивали»?", "a": [ "Ряд огней", "Праздник воды", "Ночь зверей" ] }, { "id": "ind-a-diwali-diya", "e": "🏺", "t": "Глиняные лампы дия", "s": "На Дивали зажигают маленькие лампы дия. Это крошечные глиняные плошки. В них наливают масло, а в масло кладут хлопковый фитилёк. Гончары заранее лепят и обжигают столько плошек, что хватит на весь город. Дия расставляют рядами на подоконниках и перед входом. Маленькие огоньки дрожат на ветру, но всё равно светят. Они похожи на золотые капли.", "q": "Из чего делают лампы дия?", "a": [ "Из глины", "Из стекла", "Из льда" ] }, { "id": "ind-a-diwali-rangoli", "e": "🌼", "t": "Рисунки ранголи", "s": "К Дивали у порога дома рисуют ранголи. Это узор на полу из цветного порошка, рисовой муки или лепестков цветов. Чаще всего это цветок или звезда с одинаковыми половинками. Рисунок делают для гостей, чтобы им было приятно входить. Над узором часто работают всей семьёй, и дети тоже помогают. Через несколько дней ранголи сметают, а потом рисуют новый.", "q": "Где рисуют ранголи?", "a": [ "У порога дома", "На потолке", "На оконном стекле" ] }, { "id": "ind-a-gimalai-sneg", "e": "🏔️", "t": "Гималаи — дом снега", "s": "На севере Индии поднимаются Гималаи — самые высокие горы на Земле. В старинном индийском языке это слово значит «дом снега». Горы тянутся больше чем на две тысячи километров, а на вершинах снег лежит круглый год. Гималаи ещё молодые: они продолжают расти, понемногу, на несколько миллиметров в год. Из тающих льдов берут начало реки, которые поят многие города.", "q": "Что значит слово «Гималаи»?", "a": [ "Дом снега", "Гора ветров", "Небесная лестница" ] }, { "id": "ind-a-everest", "e": "⛰️", "t": "Эверест и древнее море", "s": "В Гималаях, недалеко от Индии, на границе Непала и Китая, стоит гора Эверест. Её высота — почти девять километров, чуть ниже, чем летят большие самолёты. Это самая высокая вершина на Земле. Учёные находили высоко в горах, в камне, отпечатки древних морских ракушек. Значит, много миллионов лет назад здесь было морское дно. Гора будто хранит память о море.", "q": "Что нашли в камнях высоко в горах учёные?", "a": [ "Отпечатки морских ракушек", "Старые санки", "Золотые монеты" ] }, { "id": "ind-a-gang-reka", "e": "🌊", "t": "Большая река Ганг", "s": "Ганг — одна из самых известных рек Индии. Он начинается в Гималаях, где тают ледники, и течёт около двух с половиной тысяч километров до Бенгальского залива. Вокруг реки лежит широкая плодородная равнина: там растут рис и пшеница. Многие индийцы верят, что Ганг священный, и ласково называют его Матерью Гангой. На рассвете люди приходят к берегу, умываются и спокойно молятся.", "q": "Где начинается Ганг?", "a": [ "В Гималаях, из ледников", "В жаркой пустыне", "В большой пещере под землёй" ] }, { "id": "ind-a-gang-delfin", "e": "🐬", "t": "Дельфин из Ганга", "s": "В Ганге живёт редкий речной дельфин. У него длинный тонкий нос, а глаза почти ничего не видят. Вода в реке мутная, зрение здесь не нужно. Дельфин находит дорогу по эху: он издаёт щёлкающие звуки и слушает, как они отражаются от рыб и берегов. Плавает он часто на боку. Таких дельфинов осталось мало, и люди стараются их защитить.", "q": "Как речной дельфин находит дорогу в мутной воде?", "a": [ "По эху своих щелчков", "По запаху", "Острым зрением" ] }, { "id": "ind-b-black-pepper", "e": "🌶️", "t": "Перец дороже золота", "s": "Чёрный перец растёт на юге Индии, на лозе, которая карабкается по деревьям. Из зелёных ягодок после сушки получаются чёрные морщинистые горошинки. Много веков назад перец возили в далёкие страны, и его ценили так высоко, что порой называли «чёрным золотом». Теперь он стоит на каждом столе. Попробуй: когда нюхаешь перец, хочется чихнуть!", "q": "На чём растёт перец, как сказано в рассказе?", "a": [ "На лозе, что карабкается по деревьям", "На низком кусте у реки", "На высокой пальме" ] }, { "id": "ind-b-turmeric", "e": "🟡", "t": "Жёлтая куркума", "s": "Куркума — это корневище, родственник имбиря. Если его высушить и растереть, получится ярко-жёлтый порошок. В Индии его кладут в рис, в чечевичный суп и в овощи. Он красит еду в цвет солнца, а пальцы и ложки — в жёлтый, и отмыть их не так просто! Ещё из куркумы с молоком готовят тёплое «золотое молоко».", "q": "В какой цвет куркума красит еду?", "a": [ "В ярко-жёлтый", "В красный", "В зелёный" ] }, { "id": "ind-b-cardamom", "e": "🫛", "t": "Кардамон, царица специй", "s": "Кардамон растёт в тёплых лесистых горах на юге Индии, например в Керале. Его называют царицей специй. Это маленькие зелёные стручки, а внутри — тёмные душистые зёрнышки. Их кладут в сладости и в масала-чай, и по всей кухне идёт тёплый, чуть сладкий запах. Стручок можно просто разжевать, и во рту станет свежо.", "q": "Как называют кардамон?", "a": [ "Царицей специй", "Королём овощей", "Принцем фруктов" ] }, { "id": "ind-b-darjeeling-tea", "e": "🍵", "t": "Чай в облаках Дарджилинга", "s": "В городке Дарджилинг на севере Индии чайные кусты растут на крутых склонах, прямо в тумане. Листья здесь собирают руками: берут два листочка и нежную почку. Из них получается светлый душистый чай, известный по всему миру. А по склонам до сих пор бегает крошечный поезд-игрушка на узких рельсах. Он идёт так медленно, что можно рассматривать каждый куст.", "q": "Что берут при сборе чая в Дарджилинге?", "a": [ "Два листочка и почку", "Только цветы", "Целые ветки" ] }, { "id": "ind-b-chess-born", "e": "♟️", "t": "Шахматы родом из Индии", "s": "Шахматы придумали в Индии, очень давно — говорят, около полутора тысяч лет назад. Старая игра называлась чатуранга, что значит «четыре части». У неё были фигурки пешеходов, всадников, слонов и колесниц. Потом игра ушла по торговым дорогам в Персию, а оттуда добралась до Европы. Наш слон и наша ладья — потомки индийских слонов и колесниц. Каждый, кто двигает по доске пешку, играет в индийскую игру!", "q": "Как называлась старая индийская игра, из которой вышли шахматы?", "a": [ "Чатуранга", "Манкала", "Парчиси" ] }, { "id": "ind-b-chess-grains", "e": "🌾", "t": "Легенда о зёрнах на клетках", "s": "Есть красивая легенда о создателе шахмат. Правитель так обрадовался игре, что предложил мудрецу любую награду. Тот попросил немного: одно зёрнышко риса на первую клетку, два на вторую, четыре на третью, и так каждый раз вдвое больше. Правитель посмеялся, но стал считать. На последней клетке зёрен вышло столько, что их не хватило бы во всей стране. Это только легенда, но считать зёрна весело.", "q": "Сколько зёрен просил мудрец на первую клетку?", "a": [ "Одно", "Десять", "Целый мешок" ] }, { "id": "ind-b-our-digits", "e": "🔢", "t": "Наши цифры пришли из Индии", "s": "Цифры 1, 2, 3 и остальные пришли к нам из Индии. В Европу они добрались через арабских купцов и учёных, поэтому их называют «арабскими». Индийские мастера записывали число так, что место цифры говорит о её величине: в 21 и в 12 цифры те же, а числа разные. Благодаря этому считать на бумаге стало намного легче, чем с римскими цифрами.", "q": "Где придумали наши цифры?", "a": [ "В Индии", "В Риме", "В Китае" ] }, { "id": "ind-b-zero", "e": "0️⃣", "t": "Ноль — знак пустоты", "s": "Ноль — это очень странная цифра: она значит «ничего». Индийские учёные давным-давно стали записывать пустое место кружочком или точкой. А слово, которым его называли, значило «пустота». Благодаря нолю можно отличить 5, 50 и 500. Без него не было бы ни телефонных номеров, ни огромных чисел. Маленький кружок, а дел у него много!", "q": "Что значит ноль?", "a": [ "Пустое место", "Одно яблоко", "Конец счёта" ] }, { "id": "ind-b-yoga-kind", "e": "🧘", "t": "Йога — добрая гимнастика", "s": "Йога родилась в Индии очень давно. Это неторопливая гимнастика, где нет победителей и соревнований. Делаешь плавное движение, дышишь глубоко и спокойно, как будто нюхаешь цветок и дуешь на свечку. После йоги тело становится гибким, а мысли тихими. Двадцать первого июня во всём мире даже отмечают Международный день йоги.", "q": "Когда отмечают Международный день йоги?", "a": [ "21 июня", "1 января", "8 марта" ] }, { "id": "ind-b-yoga-animals", "e": "🐍", "t": "Кобра, дерево и собака", "s": "Многие позы йоги названы в честь живых существ. В позе кобры лежишь на животе и поднимаешь грудь, как змея, которая выглянула из травы. В позе дерева стоишь на одной ноге, а руки тянешь вверх, как ветки. А в позе собаки, которая тянется после сна, упираешься руками и ногами в пол, а спину поднимаешь горкой. Попробуй дома — получится смешно!", "q": "Что делают в позе дерева?", "a": [ "Стоят на одной ноге", "Лежат на животе", "Сидят на корточках" ] }, { "id": "ind-b-sari-cloth", "e": "🥻", "t": "Сари — ткань без шитья", "s": "Сари — это длинный кусок ткани, обычно в пять-шесть метров, а бывает и до девяти. Самое удивительное, что его не режут и не сшивают. Ткань обёртывают вокруг тела, а конец перекидывают через плечо. Одно и то же сари можно носить по-разному, в каждом краю свои складки. Сари бывает хлопковое для жаркого дня и шёлковое для праздника. А узоры на нём — цветы, птицы и золотые каёмки — тоже рассказывают целые истории.", "q": "Сколько примерно метров ткани в сари?", "a": [ "Пять-шесть", "Один-два", "Двадцать" ] }, { "id": "ind-b-railway", "e": "🚂", "t": "Поезда без конца", "s": "В Индии одна из самых больших железных дорог на свете. Рельсы тянутся по пустыням, джунглям и горам на десятки тысяч километров. Тут тысячи станций, и каждый день в поездах едут миллионы людей. Многие любят ездить ночью: на полке можно лежать и слушать стук колёс. А в окне проплывают поля, реки и крошечные деревеньки.", "q": "Где можно лежать в ночном поезде?", "a": [ "На полке", "На крыше", "В багажнике" ] }, { "id": "ind-b-dabbawala", "e": "🍱", "t": "Даббавалы, курьеры с обедами", "s": "В Мумбаи живут люди, которые носят обеды. Их называют даббавалами. Утром они забирают дома горячие обеды в металлических коробочках и везут на велосипедах и поездах в офисы. После обеда пустые коробочки возвращаются домой. Каждый день так перевозят около двухсот тысяч коробочек! На крышке нет адреса, а есть значки, цифры и цвета. Они подсказывают, куда нести обед. Этой работе больше ста лет.", "q": "Что помогает даббавалам найти нужный офис?", "a": [ "Значки, цифры и цвета на коробочке", "Карта в телефоне", "Подсказки прохожих" ] }, { "id": "ind-b-chaiwalla", "e": "☕", "t": "Чайвалла на станции", "s": "Когда поезд останавливается на станции, по перрону бегут чайваллы, то есть продавцы чая. Они несут чайник и громко кричат: «Чай, чай!» Горячий сладкий чай с молоком и специями наливают в маленькие глиняные стаканчики. Выпил — и стаканчик можно разбить: глина снова станет землёй. Так на станциях часто пьют чай до сих пор.", "q": "Из чего бывают стаканчики для чая на станции?", "a": [ "Из глины", "Из стекла", "Из бумаги" ] }, { "id": "ind-b-bollywood-songs", "e": "🎬", "t": "Болливуд: кино с песнями", "s": "Индийские фильмы особенные: в них герои вдруг начинают петь и танцевать. Танцуют на лугах, на рынках, на крышах поездов. Много таких фильмов снимают в Мумбаи, который раньше звался Бомбей. Из слов «Бомбей» и «Голливуд» получилось весёлое слово Болливуд. Фильм длится около трёх часов, и посередине бывает антракт. Песни из кино потом знает вся страна.", "q": "Что часто делают герои индийских фильмов?", "a": [ "Поют и танцуют", "Только молчат", "Только едят" ] }, { "id": "ind-b-mango-fruit", "e": "🥭", "t": "Манго, любимый фрукт", "s": "Манго — один из самых любимых фруктов в Индии, его считают национальным. Есть сотни сортов: одни мелкие, как яйцо, другие большие и тяжёлые. Один знаменитый сорт зовут альфонсо, он очень сладкий и душистый. В жаркое лето на рынках горы жёлтых и оранжевых плодов, и воздух пахнет сладко. Внутри манго большая косточка, а мякоть сочная, и от неё липнут пальцы.", "q": "Как зовут знаменитый сладкий сорт манго?", "a": [ "Альфонсо", "Бананито", "Пепино" ] }, { "id": "ind-b-mango-leaves", "e": "🌳", "t": "Манго над дверью", "s": "Манго растёт на высоком раскидистом дереве с густой тенью. Под ним в жару отдыхают люди и играют дети. Листья манго длинные и тёмно-зелёные. В праздники из них плетут гирлянды и вешают над дверью, чтобы дом выглядел нарядным. А в сезон спелых плодов дети лазают за манго на ветки, и мамы зовут их ужинать.", "q": "Что плетут из листьев манго в праздники?", "a": [ "Гирлянды над дверью", "Шапки для детей", "Корзины для рынка" ] }, { "id": "ind-b-kerala-houseboats", "e": "🛶", "t": "Дом-лодка в Керале", "s": "В штате Керала есть тихие зелёные каналы и озёра. По ним плавают дома-лодки. Их делают из дерева и скрепляют верёвками из волокон кокоса, почти без гвоздей. Крышу плетут из пальмовых листьев. Раньше на таких лодках возили рис, а теперь на них живут путешественники. Лодка медленно скользит, по берегам качаются пальмы, а на ужин часто подают рыбу с рисом.", "q": "Из чего плетут крышу дома-лодки?", "a": [ "Из пальмовых листьев", "Из железа", "Из стекла" ] }, { "id": "ind-b-jaipur-pink", "e": "🏰", "t": "Розовый город Джайпур", "s": "Джайпур — город в Раджастане, и его называют Розовым. Старые дома там окрашены в тёплый розовый цвет, почти как закат. А на главной улице стоит Дворец ветров. Это стена из окошек, по ней можно насчитать почти тысячу узких окон с резными решётками. Через них внутрь заходит прохладный ветерок. Говорят, из них смотрели на улицу, оставаясь незамеченными.", "q": "Как называется знаменитое здание в Джайпуре?", "a": [ "Дворец ветров", "Дворец дождей", "Дворец снегов" ] }, { "id": "ind-b-camels", "e": "🐪", "t": "Верблюды пустыни Тар", "s": "В Раджастане есть пустыня Тар, а в ней живут верблюды. У верблюда широкие мягкие лапы, поэтому он не проваливается в песок. А ещё у него длинные густые ресницы, они спасают глаза от пыли. Осенью в городке Пушкар проходит ярмарка верблюдов: их красиво украшают, и они важно идут по песку. На ярмарке можно даже прокатиться на верблюде.", "q": "Что защищает глаза верблюда от пыли?", "a": [ "Длинные густые ресницы", "Тёмные очки", "Широкие брови" ] }, { "id": "ind-b-cricket", "e": "🏏", "t": "Крикет на любой улице", "s": "В Индии обожают крикет. Играют не только на больших стадионах, но и на любой улице, и во дворе. Вместо ворот ставят кирпичи или кучку камней, а биту иногда вырезают из куска доски. Мячом служит теннисный или тряпичный мячик. Есть и громадные стадионы, где помещается больше ста тысяч зрителей. Когда играет любимая команда, вся улица прилипает к телевизору.", "q": "Что ставят вместо ворот во дворе?", "a": [ "Кирпичи или камни", "Два ведра воды", "Большие мячи" ] }, { "id": "ind-b-mehendi", "e": "🌿", "t": "Мехенди, рисунки хной", "s": "Хну делают из высушенных листьев кустарника. Листья растирают в порошок, добавляют воду, и получается зелёная паста. Её выдавливают из маленького бумажного конуса на ладони и пальцы, рисуя цветы и завитки. Когда паста подсохнет, её счищают, а на коже остаётся рыжевато-коричневый узор. Он держится одну-две недели. Мехенди рисуют на праздники и на свадьбы.", "q": "Какого цвета остаётся узор мехенди на коже?", "a": [ "Рыжевато-коричневого", "Ярко-синего", "Зелёного" ] }, { "id": "ind-b-chapati-lassi", "e": "🫓", "t": "Чапати и ласси", "s": "Чапати — это тонкая лепёшка из пшеничной муки. Тесто раскатывают в кружок и кладут на горячую сковороду. Потом лепёшку переворачивают, и она вдруг надувается, как воздушный шарик! Чапати едят вместо ложки: отламывают кусочек и берут им еду. А к обеду пьют ласси — густой напиток из йогурта, сладкий, солёный или с манго. Холодное ласси в жару особенно хорошо.", "q": "Из чего делают ласси?", "a": [ "Из йогурта", "Из яблочного сока", "Из риса" ] }, { "id": "ind-b-rupee", "e": "💰", "t": "Рупия и её знак", "s": "Деньги в Индии называются рупиями. Одна рупия состоит из ста пайсов, как наш рубль из копеек. У рупии есть собственный значок, он похож на букву R с двумя чёрточками наверху. Его придумали не так давно, в 2010 году. А ещё на купюрах сумма написана на многих языках сразу, их больше десяти. В Индии живут люди, говорящие на разных языках, и каждый может прочитать цену.", "q": "На чём написана сумма на индийской купюре?", "a": [ "На многих языках сразу", "Только цифрами", "Только по-русски" ] }, { "id": "ind-b-lotus", "e": "🪷", "t": "Лотос — цветок из ила", "s": "Лотос — национальный цветок Индии. Растёт он в тихих прудах, а корни у него в липком иле. Но цветок поднимается над водой чистым и нежным, розовым или белым. Капли воды скатываются с его листьев, как бусинки, и листья остаются сухими. Утром лотос раскрывается, а к вечеру закрывается. Поэтому в Индии его любят и рисуют повсюду.", "q": "Где у лотоса находятся корни?", "a": [ "В иле на дне пруда", "На высоком дереве", "В горячем песке" ] } ], "isr": [ { "id": "isr-a-medovyj-kamen", "e": "🧱", "t": "Камень цвета мёда", "s": "Иерусалим — город из светлого камня. Дома, стены и мостовые сложены из известняка, который добывают в здешних холмах. Днём камень почти белый, а на закате становится медовым и розоватым, будто город подсвечивают изнутри. Говорят, это самый красивый час, чтобы пройтись по улицам. Давным-давно в городе приняли правило: новые дома одевать в такой же камень. Поэтому Иерусалим и новый, и старый кажутся родными братьями.", "q": "Каким становится иерусалимский камень на закате?", "a": [ "Медовым и розоватым", "Ярко-синим", "Чёрным как уголь" ] }, { "id": "isr-a-gorodskie-vorota", "e": "🚪", "t": "Ворота Старого города", "s": "Старый город Иерусалима окружён высокой каменной стеной. В ней несколько ворот, и у каждых своё имя: Яффские, Дамасские, Львиные. Через них много веков входят люди, которые приходят сюда из разных стран и верят по-разному. За воротами начинаются узкие улочки, лестницы и тихие дворики. Стена очень старая: её построили почти пятьсот лет назад. Если встать рядом и приложить ладонь к тёплому камню, можно почувствовать, как давно он здесь стоит.", "q": "Как называются одни из ворот Старого города?", "a": [ "Яффские", "Золотые часы", "Морковные" ] }, { "id": "isr-a-bashnya-davida", "e": "🏯", "t": "Башня Давида с ошибкой в названии", "s": "Рядом с Яффскими воротами стоит крепость с высокой башней. Её называют Башней Давида, хотя царь Давид жил гораздо раньше, чем её построили. Старинные путешественники просто ошиблись, а название так и осталось. Теперь внутри музей: можно ходить по каменным дворам, подниматься по лестницам на стены и смотреть сверху на крыши города. А вечером на старинных стенах иногда зажигают световое шоу с яркими картинками.", "q": "В чём ошиблись путешественники?", "a": [ "В названии башни", "В числе ворот", "В цвете неба" ] }, { "id": "isr-a-ierusalimskij-bublik", "e": "🥯", "t": "Иерусалимский бублик", "s": "Если пройтись по старому рынку, голова закружится от запахов: пахнет кардамоном, мятой, свежим кофе и тёплым хлебом. Продавцы раскладывают горки специй: красных, жёлтых, зелёных. А с утра на лотках лежат иерусалимские бублики. Они не круглые, а длинные и овальные, посыпанные кунжутом. Их часто едят с приправой из сушёных трав и с варёным яйцом. Попробуйте — корочка хрустит, а внутри мягко!", "q": "Какой формы иерусалимский бублик?", "a": [ "Длинный и овальный", "Квадратный", "Как звёздочка" ] }, { "id": "isr-a-zelenye-holmy", "e": "⛰️", "t": "Город на холмах", "s": "Иерусалим стоит на холмах, примерно на высоте семисот пятидесяти метров. Поэтому здесь прохладнее, чем у моря, а вечерами дует свежий ветерок. Иногда зимой даже выпадает снег, и это настоящий праздник: все выходят лепить снеговиков! Вокруг города растут сосны, кипарисы и старые оливковые деревья с серебристыми листьями. С холмов видно, как крыши из светлого камня уходят вдаль, словно ступеньки.", "q": "Что иногда случается в Иерусалиме зимой?", "a": [ "Выпадает снег", "Расцветают пальмы-великаны", "Замерзает море" ] }, { "id": "isr-a-koshki", "e": "🐈", "t": "Кошки Иерусалима", "s": "В Иерусалиме на каждом шагу встречаются кошки. Они лежат на тёплых ступенях, дремлют на подоконниках, важно шагают по стенам. Жители подкармливают их и не гонят. Кошки здесь пушистые, рыжие, серые, пятнистые, и у каждой, кажется, свой участок улицы. Если тихонько посидеть на каменной скамейке, можно увидеть, как очередной хвостатый житель проходит мимо с таким видом, будто он главный в городе.", "q": "Где в Иерусалиме любят лежать кошки?", "a": [ "На тёплых ступенях", "В ледяной воде", "На высоких деревьях" ] }, { "id": "isr-a-belyj-gorod", "e": "🏙️", "t": "Белый город Тель-Авива", "s": "В Тель-Авиве больше тысячи домов построили в особом стиле: его называют «Баухаус». Дома белые, простые, с ровными стенами, круглыми балконами и длинными окнами. Белый цвет отражает солнце, а балконы дают тень, чтобы в жару в комнатах было прохладнее. Эти кварталы так и называют — Белый город. Они такие необычные, что всемирная организация, которая защищает самое ценное на планете, внесла их в особый список.", "q": "Зачем дома в Белом городе белые?", "a": [ "Белый цвет отражает солнце", "Чтобы их видели ночью самолёты", "Потому что краски не было" ] }, { "id": "isr-a-rakushki", "e": "🐚", "t": "Город, который делили ракушками", "s": "Тель-Авив — молодой город. Его начали строить чуть больше ста лет назад на песчаных дюнах у моря. Рассказывают, что жители решили честно разделить участки. Они собрали на пляже ракушки, на одних написали свои имена, на других номера участков и вытаскивали по две. Так каждая семья получила свой кусочек песка. Название города переводится как «холм весны». Теперь здесь высокие дома, сады и огромный пляж.", "q": "Чем делили участки для домов?", "a": [ "Ракушками", "Камушками из реки", "Воздушными шарами" ] }, { "id": "isr-a-pljazh-matkot", "e": "🏖️", "t": "Пляж и игра маткот", "s": "Пляжи Тель-Авива тянутся вдоль моря на много километров, а песок мягкий и золотистый. Здесь любят играть в маткот. Нужны две деревянные ракетки и маленький резиновый мячик. Двое игроков стоят на расстоянии и перебрасывают мячик друг другу, стараясь не уронить. Тот, кто выиграл, — тот, кто дольше держался. Игра такая простая, что в неё играют и бабушки, и дети, а над песком весь день слышится стук мячика.", "q": "Чем играют в маткот?", "a": [ "Деревянными ракетками и резиновым мячиком", "Лопатками и вёдрами", "Мягкими игрушками" ] }, { "id": "isr-a-rynok-karmel", "e": "🍉", "t": "Рынок Кармель", "s": "На рынке Кармель в Тель-Авиве шумно и вкусно. Продавцы громко зовут покупателей, а прилавки завалены фруктами: гранаты, финики, инжир, арбузы, сладкие апельсины. Можно тут же выпить свежевыжатый сок или купить горсть орехов. Пахнет специями, тёплым хлебом и лимонами. Повсюду яркие цвета: красные, оранжевые, зелёные и жёлтые. Кажется, будто кто-то высыпал на улицу коробку красок.", "q": "Что можно выпить на рынке Кармель?", "a": [ "Свежевыжатый сок", "Снежный чай", "Тёплое молоко из колодца" ] }, { "id": "isr-a-jaffa-apelsiny", "e": "🍊", "t": "Яффа и апельсиновое дерево", "s": "Яффа — старый порт рядом с Тель-Авивом. Люди приплывали сюда на кораблях тысячи лет назад, это один из самых древних портов мира. По каменным улочкам можно подняться на холм и посмотреть на море. А ещё есть двор, где апельсиновое дерево растёт в большом глиняном горшке, подвешенном в воздухе. Яффские апельсины — большие, сладкие, с толстой кожурой — когда-то увозили на кораблях в дальние страны.", "q": "Где растёт необычное апельсиновое дерево в Яффе?", "a": [ "В горшке, подвешенном в воздухе", "На дне моря", "На крыше корабля" ] }, { "id": "isr-a-sady-bahai", "e": "🌺", "t": "Висячие сады Хайфы", "s": "Хайфа раскинулась на склоне горы Кармель, а на склоне лежат Сады Бахаи. Они спускаются к морю девятнадцатью зелёными террасами, словно лестница из цветов. Дорожки ровные, живые изгороди подстрижены, кругом клумбы и фонтаны, а наверху блестит золотой купол. Сады очень красивые и очень тихие: здесь хочется говорить шёпотом. Их внесли в список самых ценных мест на планете. С верхней террасы видно порт и море.", "q": "Сколько террас у Садов Бахаи?", "a": [ "Девятнадцать", "Две", "Сто" ] }, { "id": "isr-a-karmelit", "e": "🚇", "t": "Кармелит — крошечное метро", "s": "В Хайфе есть метро, и оно одно из самых коротких в мире. Называется Кармелит. Линия всего одна, станций шесть, а длина около двух километров. Но это не простое метро: оно едет в гору, а гора крутая. Поэтому пол в вагоне сделан ступеньками, чтобы пассажиры не скатывались. Весь путь от нижней станции до верхней занимает несколько минут. Поезда ходят под землёй, поэтому снаружи видна лишь маленькая дверца.", "q": "Почему в вагонах Кармелита пол ступеньками?", "a": [ "Метро едет в крутую гору", "Чтобы вагон был красивее", "Чтобы удобнее было прыгать" ] }, { "id": "isr-a-kanatka-hajfa", "e": "🚠", "t": "Канатная дорога над Хайфой", "s": "В Хайфе можно прокатиться по воздуху. Стеклянные кабинки канатной дороги скользят от берега моря на вершину горы Кармель. Внизу видны пляж, большой порт с кораблями и тёмно-синяя вода, а когда поднимаешься выше, открываются зелёные склоны и город. Кабинка идёт неторопливо, поэтому можно всё рассмотреть. Наверху ждёт площадка с видом на море, где дует тёплый ветерок и хочется помахать далёким кораблям.", "q": "Куда ведёт канатная дорога Хайфы?", "a": [ "На вершину горы Кармель", "На дно моря", "На остров с маяком" ] }, { "id": "isr-a-ne-tonut", "e": "🌊", "t": "Море, в котором не тонут", "s": "Мёртвое море — самое солёное из морей, воды там примерно в десять раз солонее, чем в обычном. Из-за этого вода очень плотная и сама выталкивает человека наверх. Можно лечь на спину и спокойно лежать, как на матрасе, даже с газетой в руках. Нырять и брызгаться не нужно: солёная вода щиплет глаза. Рыбы в нём не живут, поэтому и назвали «мёртвым». А ещё берег Мёртвого моря — самое низкое место на суше.", "q": "Почему в Мёртвом море не тонут?", "a": [ "Вода очень солёная и плотная", "В нём очень мелко", "Там нет волн" ] }, { "id": "isr-a-gryaz-sol", "e": "⬛", "t": "Чёрная грязь и соляные камни", "s": "На берегу Мёртвого моря лежит тёмная мягкая грязь. Люди берут её горстями, мажут руки и ноги, сидят на солнышке, а потом смывают в море — кожа становится гладкой. Выглядят все смешно, как чёрные статуи. А у воды растут настоящие соляные кристаллы: белые, острые, как сахарные. На палках и камнях налипает белая корка, будто всё покрыто инеем, хотя вокруг жарко.", "q": "Что делают с грязью на берегу Мёртвого моря?", "a": [ "Мажут ею кожу", "Лепят из неё кастрюли", "Едят на завтрак" ] }, { "id": "isr-a-masada", "e": "🏜️", "t": "Масада на скале", "s": "Над Мёртвым морем поднимается плоская скала Масада. На её вершине больше двух тысяч лет назад царь Ирод построил дворец и крепость. Наверх ведёт тропа, которую называют Змеиной: она вьётся, как змея. Можно подняться на закате, а можно на канатной дороге. Наверху видны древние стены, большие кладовые и ямы для воды. Если прийти на рассвете, увидишь, как солнце медленно встаёт над пустыней и морем.", "q": "Как называют тропу к вершине Масады?", "a": [ "Змеиная тропа", "Тропа бабочек", "Лягушачья тропа" ] }, { "id": "isr-a-ejn-gedi", "e": "🐐", "t": "Оазис Эйн-Геди", "s": "В жаркой пустыне у Мёртвого моря прячется зелёный оазис Эйн-Геди. Там бегут ручьи, шумят водопады, а в тени растут деревья. Вода идёт из родников, поэтому здесь можно искупаться и отдохнуть. В скалах живут нубийские горные козлы с большими рогами-дугами. Они ловко прыгают по камням. А ещё встречаются даманы — маленькие пушистые зверьки, похожие на сурков. Они греются на солнце и совсем не боятся людей.", "q": "Какие животные живут среди скал Эйн-Геди?", "a": [ "Нубийские горные козлы", "Белые медведи", "Пингвины" ] }, { "id": "isr-a-koraly-ejlat", "e": "🐠", "t": "Кораллы Красного моря", "s": "Эйлат стоит у самого Красного моря, и вода там очень тёплая и прозрачная. Под водой растёт коралловый риф. Кораллы похожи на цветные деревья, пальцы и мозги: красные, розовые, жёлтые. Между ними плавают рыбки-клоуны, рыбы-попугаи и ленивые морские черепахи. Рифы очень хрупкие, поэтому их трогать нельзя. Лучше смотреть в маске или с лодки. А ещё рядом есть залив, где дельфины живут на свободе и сами решают, когда подплыть.", "q": "Почему нельзя трогать кораллы?", "a": [ "Они очень хрупкие", "Они кусаются", "Они горячие" ] }, { "id": "isr-a-podvodnaya-observatoriya", "e": "🔭", "t": "Башня под водой", "s": "В Эйлате есть башня, которая стоит прямо в море. Внутри лестница ведёт вниз, под воду, примерно на шесть метров. Там круглые окна: за стеклом плывут яркие рыбы, ползают морские звёзды, колышутся кораллы. Ты сидишь в сухом и тёплом зале, но смотришь на морской мир как в кино. Рядом можно увидеть акул и черепах в больших аквариумах. А рыбки за окном будто тоже смотрят на тебя.", "q": "Что видно из окон подводной башни?", "a": [ "Рыб и кораллы", "Птиц на облаках", "Тракторы" ] }, { "id": "isr-a-krater-ramon", "e": "🌋", "t": "Кратер Рамон", "s": "В пустыне Негев есть огромная каменная долина. Её называют кратером Рамон, а на местном языке — махтеш. Она тянется примерно на сорок километров, а в глубину больше трёхсот метров. Звучит как след от космического камня, но на самом деле её медленно вырезали дожди и ветер. В долине цветные скалы: жёлтые, красные, фиолетовые. По краям можно встретить нубийских горных козлов, которые спокойно бродят у обрыва.", "q": "Кто вырезал долину Рамон?", "a": [ "Дожди и ветер", "Упавший космический камень", "Огромные кроты" ] }, { "id": "isr-a-avdat", "e": "🐪", "t": "Авдат — город в пустыне", "s": "Давным-давно по пустыне Негев шли караваны верблюдов. Они везли благовония и пряности. Купцам нужно было где-то отдыхать, и на холме выросли город Авдат. Его построили люди, которых называли набатеями. Они умели собирать редкую дождевую воду в глубокие каменные ёмкости. Сегодня на холме видны стены, дворы и пещеры. Можно побродить среди них и представить, как здесь стоят верблюды.", "q": "Что везли верблюжьи караваны через Негев?", "a": [ "Благовония и пряности", "Снежки и лёд", "Живых рыб" ] }, { "id": "isr-a-zvyozdy-negeva", "e": "🌌", "t": "Звёздное небо Негева", "s": "Ночью в пустыне Негев очень темно и тихо. Огней мало, поэтому небо сверкает так, как в городе не увидишь. Звёзд так много, что они сливаются в светлую дорожку — это Млечный Путь. Возле кратера Рамон даже создали особое место, где свет приглушают, чтобы звёздам ничего не мешало. Люди приезжают сюда с одеялами, лежат на песке и ищут падающие звёзды. А утром пустыня просыпается розовой.", "q": "Что видно в небе над Негевом?", "a": [ "Млечный Путь", "Лампочки на ниточках", "Радуга ночью" ] }, { "id": "isr-a-kinneret", "e": "🎵", "t": "Озеро-арфа Кинерет", "s": "На севере Израиля, среди зелёных холмов Галилеи, лежит озеро Кинерет. Его форма немного похожа на арфу, а слово «киннор» как раз и значит арфа. Оно пресное, вода в нём пригодна для питья, а ещё это самое низкое пресное озеро на Земле: его поверхность лежит примерно на двести метров ниже океана. Здесь тихо, на берегах растут пальмы и бананы, а по воде скользят лодочки.", "q": "На что похоже озеро Кинерет?", "a": [ "На арфу", "На сапог", "На звезду" ] }, { "id": "isr-a-ryba-svyatogo-petra", "e": "🐟", "t": "Рыба Святого Петра", "s": "В Кинерете живёт рыба, которую называют «рыбой Святого Петра». По-научному это тиляпия. Рыбаки ловят её сетями на рассвете, как делали это очень давно. У неё интересная забота о малышах: некоторые тиляпии носят икринки и мальков во рту, чтобы их никто не обидел. Когда опасность проходит, малыши выплывают погулять. А вечером в прибрежных кафе эту рыбу подают жареной.", "q": "Где тиляпия прячет своих малышей?", "a": [ "Во рту", "В песчаной норе-замке", "В кармане" ] }, { "id": "isr-a-zhuravli-hula", "e": "🦢", "t": "Журавли долины Хула", "s": "На севере Галилеи есть долина Хула. Осенью туда прилетают тысячи журавлей. Они летят издалека, из холодных стран, и делают остановку, чтобы отдохнуть и поесть. Серые птицы с длинными ногами ходят по полям целыми стаями и тихо курлычут. А когда взлетают, небо становится как будто серым и шумным. Через Израиль каждый год пролетает очень много перелётных птиц, и долина Хула — одно из лучших мест, чтобы за ними понаблюдать.", "q": "Кто осенью прилетает в долину Хула?", "a": [ "Журавли", "Пингвины", "Белые медведи" ] }, { "id": "isr-b-kibbutz-degania", "e": "🏡", "t": "Первый кибуц", "s": "Давно, в 1910 году, несколько молодых людей поселились у южного берега озера Кинерет и основали Деганию — первый кибуц. Кибуц — это такая деревня, где люди живут и работают вместе, как одна большая семья. Они сушили болото, сажали поля и сады и делили поровну и труд, и урожай. Дегания существует до сих пор, а кибуцев в Израиле теперь очень много. Поэтому Деганию и называют «матерью кибуцев».", "q": "Что такое кибуц?", "a": [ "Деревня, где люди живут и работают вместе", "Большой корабль на озере", "Школа для верблюдов" ] }, { "id": "isr-b-kibbutz-today", "e": "🍽️", "t": "Кибуц сегодня", "s": "Во многих кибуцах до сих пор есть общая столовая: туда приходят пообедать, поболтать с соседями и отметить праздник. Раньше дети жили не с родителями, а в детском доме, всей гурьбой. Сейчас они спят дома, а днём играют вместе в детском саду, на лужайках и у бассейна. В кибуцах выращивают апельсины, авокадо, финики, держат коров и кур, а ещё делают разные машины и игрушки. Каждый кибуц немного отличается от других.", "q": "Где спят дети в кибуцах сегодня?", "a": [ "Дома, с родителями", "Только в столовой", "На ферме у коров" ] }, { "id": "isr-b-drip-irrigation", "e": "💧", "t": "Капля за каплей", "s": "В Израиле много пустынь, а воды мало, поэтому здесь придумали капельный полив. По тонким трубкам с крошечными дырочками вода выходит прямо к корню растения: капля за каплей. Ничего не уходит зря и не испаряется на солнце. Инженер Симха Бласс рассказывал, что идею подсказало дерево, которое хорошо росло рядом с подтекающей трубой. В 1965 году в кибуце Хацерим начали делать такие системы, и теперь ими пользуются фермеры во многих странах.", "q": "Куда попадает вода при капельном поливе?", "a": [ "Прямо к корню растения", "Только на листья", "В небо, как дождик" ] }, { "id": "isr-b-usb-flash", "e": "🔑", "t": "Флешка размером с брелок", "s": "Ты когда-нибудь видел флешку? Это маленькая штучка, на которую можно записать фотографии, музыку и целые книги, а потом воткнуть её в компьютер. Одну из первых таких флешек в 2000 году выпустила израильская компания. Называлась она «ДискОнКей», то есть «диск на ключе»: её можно было носить на связке вместе с ключами. До этого данные таскали на больших дисках. А теперь целая библиотека помещается в кармане.", "q": "Почему флешку назвали «диск на ключе»?", "a": [ "Её носили на связке с ключами", "Она открывала двери", "Она была сделана из железного ключа" ] }, { "id": "isr-b-cherry-tomato", "e": "🍅", "t": "Помидорки черри", "s": "Мелкие сладкие помидорки, которые хочется класть в рот целиком, называются черри, то есть «вишенки». Есть они были и раньше, но были нежные: быстро лопались и портились. Израильские учёные и фермеры в 1970-х годах вывели сорта, которые дольше хранятся и их удобно возить, и теперь черри лежат на прилавках во многих странах. Кто первым придумал такие помидоры, спорят до сих пор, но Израиль точно помог им прославиться.", "q": "Что значит слово «черри»?", "a": [ "Вишенки", "Огурчики", "Звёздочки" ] }, { "id": "isr-b-solar-heaters", "e": "☀️", "t": "Бойлеры на солнце", "s": "Если посмотреть на израильские города сверху, на крышах почти везде видны блестящие плоские панели и белые бочки. Это солнечные водонагреватели. Солнце целый день греет воду в панелях, и вечером из крана течёт горячая вода — без газа и электричества. Солнца в Израиле много почти весь год, так что бесплатная горячая вода есть у большинства семей. Придумка простая, а помогает и семьям, и природе.", "q": "Чем нагревается вода в бойлерах на крышах?", "a": [ "Солнечными лучами", "Горячим песком", "Светом луны" ] }, { "id": "isr-b-desalination", "e": "🌊", "t": "Пресная вода из моря", "s": "Морская вода солёная, пить её нельзя. Но в Израиле построили большие заводы, которые превращают её в пресную. Воду прогоняют через особые мембраны, как через очень-очень мелкое сито: соль остаётся, а чистая вода проходит. Один из самых больших заводов стоит у долины Сорек, рядом со Средиземным морем. Благодаря таким заводам больше половины питьевой воды в стране берут из моря, и воды хватает всем.", "q": "Что остаётся на мембране-сите?", "a": [ "Соль", "Рыбки", "Песок из пустыни" ] }, { "id": "isr-b-waze", "e": "🚗", "t": "Навигатор Вейз", "s": "Waze — это приложение-навигатор, которое подсказывает водителю дорогу. У него есть секрет: ему помогают сами водители. Если на дороге пробка или яма, кто-то нажимает кнопку, и остальные узнают об этом заранее и едут в объезд. Приложение придумали в Израиле, в 2000-х годах, а его значок — улыбающаяся рожица. Позже его купила большая компания «Гугл», и теперь им пользуются люди по всему миру.", "q": "Как Waze узнаёт про пробки?", "a": [ "Водители сами сообщают о них", "Птицы приносят новости", "Дорожные знаки поют" ] }, { "id": "isr-b-hummus", "e": "🥣", "t": "Хумус", "s": "Хумус — любимое блюдо в Израиле. Его делают из нутовых зёрен, они похожи на маленькие золотистые орешки. Нут варят, разминают в нежное пюре, добавляют кунжутную пасту тахини, лимонный сок и чеснок, а сверху льют ложечку оливкового масла. Хумус едят, макая в него тёплую питу. Есть целые кафе, где подают только хумус: каждый повар уверен, что его хумус самый вкусный.", "q": "Из чего делают хумус?", "a": [ "Из нута", "Из риса", "Из яблок" ] }, { "id": "isr-b-pita", "e": "🫓", "t": "Пита-кармашек", "s": "Пита — круглая плоская лепёшка, которую пекут в очень горячей печи. Внутри неё есть чудо: когда тесто нагревается, пар надувает его, как шарик, и внутри остаётся пустота. Лепёшку разрезают, и получается кармашек! В него кладут фалафель — жареные шарики из нута, — свежие огурцы, помидоры, салат и соус. Такой сэндвич держат двумя руками, чтобы ничего не выпало, и едят прямо на улице.", "q": "Что кладут в питу-кармашек?", "a": [ "Фалафель и овощи", "Только мороженое", "Горячий чай" ] }, { "id": "isr-b-halva", "e": "🍬", "t": "Халва и тахини", "s": "Тахини — густая кремовая паста из кунжута. Кунжутные семечки поджаривают, перемалывают и получают масляную пасту, которую добавляют в хумус и соусы. А если смешать тахини с сахаром, получится халва: рассыпчатая, сладкая, с нежными волокнами. На рынках её продают огромными брусками, а продавец отрезает ломтик на пробу. Бывает халва с орехами, шоколадом или фисташками.", "q": "Из чего делают тахини?", "a": [ "Из кунжута", "Из шоколада", "Из лимонов" ] }, { "id": "isr-b-mahane-yehuda", "e": "🧺", "t": "Рынок Махане-Иегуда", "s": "В Иерусалиме есть шумный и яркий рынок Махане-Иегуда. Все зовут его просто «шук». Прилавки ломятся от гор разноцветных специй, блестящих оливок, сладких фиников, свежих фруктов и халвы. Торговцы громко зазывают покупателей, а из кафе пахнет свежим хлебом. По пятницам, перед субботой, сюда приходят за покупками толпы людей. Вечером на рынке бывает весело: играют музыканты и за столиками сидят гости.", "q": "Как все называют рынок Махане-Иегуда?", "a": [ "Шук", "Пита", "Кибуц" ] }, { "id": "isr-b-rosh-hashana", "e": "🍎", "t": "Яблоко с мёдом", "s": "Рош а-Шана — еврейский Новый год, он приходит осенью. В этот вечер за столом едят кусочек яблока, обмакнув его в мёд, и загадывают: пусть новый год будет сладким. Пекут круглую хлеб-халу, а в синагоге трубят в шофар — рог барана, он звучит громко и протяжно. Люди поздравляют друг друга словами «Шана това!», то есть «Хорошего года!». Праздник светлый, добрый и семейный.", "q": "Что едят на Рош а-Шана, чтобы год был сладким?", "a": [ "Яблоко с мёдом", "Лимон с солью", "Морковку с горчицей" ] }, { "id": "isr-b-hanukkah", "e": "🕎", "t": "Ханука: огоньки и пончики", "s": "Ханука длится восемь дней, и каждый вечер в особый подсвечник добавляют ещё одну свечку, пока не загорятся все. В окнах домов мерцают огоньки. В Израиле на Хануку едят сладкие пончики с вареньем — их называют суфгания — и играют в волчок. На сторонах волчка четыре буквы, и от них зависит, кто сколько получит конфет или орешков. Дети любят этот праздник за свет, игры и вкусности.", "q": "Сколько дней длится Ханука?", "a": [ "Восемь", "Два", "Тридцать" ] }, { "id": "isr-b-purim", "e": "🎭", "t": "Пурим — праздник костюмов", "s": "На Пурим в Израиле все наряжаются! На улицах встречаешь принцесс, пиратов, клоунов, космонавтов и даже говорящих бананов. Дети надевают костюмы в школу, а в городах проходят весёлые шествия. На Пурим принято дарить друзьям и соседям красивые корзинки со сладостями, а ещё пекут треугольное печенье с маком или вареньем, которое называется «уши Амана». Праздник шумный, смешной и добрый.", "q": "Что делают на Пурим?", "a": [ "Надевают карнавальные костюмы", "Катаются на санках", "Сажают ёлки" ] }, { "id": "isr-b-sukkot", "e": "🌿", "t": "Шалаш Суккот", "s": "Осенью, в праздник Суккот, семьи строят во дворе или на балконе шалаш — суку. Стены у неё из досок или ткани, а крышу кладут из веток и листьев, и в щели видно небо. Шалаш украшают рисунками, гирляндами, бумажными цепочками и фруктами. В нём обедают, а кое-кто даже спит под звёздами. Так люди вспоминают, как их предки когда-то странствовали и жили во временных домиках.", "q": "Из чего делают крышу шалаша на Суккот?", "a": [ "Из веток и листьев", "Из железа", "Из стекла" ] }, { "id": "isr-b-ibex-hyrax", "e": "🐐", "t": "Козлы и даманы Эйн-Геди", "s": "У Мёртвого моря, в заповеднике Эйн-Геди, на скалах пасутся нубийские горные козлы. У них длинные изогнутые рога, а копытца ловко цепляются за крутые камни, поэтому они не падают. Рядом греются на солнце даманы. Они похожи на толстых серых зверьков, которые размером с кролика. Забавно, что даманы — дальние родственники слонов! Это не шутка: у них, например, похожее строение зубов и ножек.", "q": "Кто дальний родственник слона?", "a": [ "Даман", "Нубийский козёл", "Кролик" ] }, { "id": "isr-b-hula-cranes", "e": "🦢", "t": "Журавли в долине Хула", "s": "Каждую осень и весну над Израилем пролетают сотни миллионов птиц: он лежит на пути из Европы в Африку и обратно. В долине Хула, на севере страны, птицам удобно отдохнуть у озера и в полях. Особенно заметны журавли: больше ста тысяч проходят через страну, а тысячи остаются тут зимовать. Они ходят по полям на длинных ногах и трубят громко и красиво. Люди приезжают в парк Агамон-Хула, чтобы на них посмотреть.", "q": "Почему птицы останавливаются в долине Хула?", "a": [ "Там можно отдохнуть и найти еду", "Там холодно", "Там стоит большой аэропорт" ] }, { "id": "isr-b-sea-turtles", "e": "🐢", "t": "Морские черепахи", "s": "На песчаных берегах Средиземного моря у Израиля летом выходят на сушу морские черепахи. Ночью черепаха выкапывает ямку, откладывает около ста мячиков-яиц и закапывает их в песок. Через два месяца вылупляются малыши размером с ладошку. Они бегут к воде, ориентируясь на свет у горизонта. Волонтёры помогают черепашатам: охраняют гнёзда и следят, чтобы малыши не потерялись. Такие гнёзда нельзя трогать — пусть растут.", "q": "Куда бегут черепашата, когда вылупятся?", "a": [ "К морю", "К пальмам", "К верблюдам" ] }, { "id": "isr-b-hebrew", "e": "📜", "t": "Иврит читают справа налево", "s": "На иврите, языке Израиля, читают и пишут справа налево, а книги открывают как бы с «конца». В его алфавите 22 буквы, и первые две — алеф и бет, откуда и слово «алфавит». Долгое время иврит звучал в основном в молитвах и книгах. А потом учёный Элиэзер Бен-Иегуда с семьёй стали говорить на нём дома, и язык снова зазвучал на улицах. Сегодня на иврите разговаривают, шутят и поют дети по всей стране.", "q": "В какую сторону читают на иврите?", "a": [ "Справа налево", "Сверху вниз по кругу", "Слева направо, как по-русски" ] }, { "id": "isr-b-dead-sea", "e": "🏖️", "t": "Самое низкое место на суше", "s": "Мёртвое море — самое низкое место суши на Земле: его берег примерно на 430 метров ниже уровня океана. Вода в нём почти в десять раз солонее, чем в обычном море, поэтому в ней невозможно утонуть. Ты ложишься на спину и спокойно плаваешь, даже можно читать газету! Рыбы там не живут, оттуда и название. А на берегу люди мажутся целебной тёмной грязью. Только в глаза брызгаться не надо — защиплет.", "q": "Почему в Мёртвом море не тонешь?", "a": [ "Вода очень солёная", "Она тёплая как чай", "В ней плавают спасатели" ] }, { "id": "isr-b-scrolls", "e": "🏺", "t": "Свитки из пещер", "s": "В 1947 году пастух искал потерявшегося козлёнка у Мёртвого моря и нашёл в пещере глиняные кувшины. В них лежали старинные свитки! Позже в других пещерах нашли ещё: их написали около двух тысяч лет назад. Теперь часть свитков хранится в Иерусалиме в Музее Израиля, в особом здании с белым куполом, похожим на крышку кувшина. Свитки очень хрупкие, поэтому их показывают в приглушённом свете и бережно.", "q": "Где нашли свитки?", "a": [ "В пещерах у Мёртвого моря", "На дне озера", "В цирке" ] }, { "id": "isr-b-biblical-zoo", "e": "🦁", "t": "Библейский зоопарк", "s": "В Иерусалиме есть зоопарк, который называют Библейским. Его создали, чтобы собрать животных, о которых рассказывается в Библии, — львов, бурых медведей, оленей, крокодилов. У многих вольеров висят таблички с коротким стихом из старой книги, где упоминается этот зверь. В зоопарке живут и редкие животные со всего света. В нём много зелени и тропинок, поэтому гулять по нему приятно. И детям, и взрослым там интересно.", "q": "Что висит у вольеров Библейского зоопарка?", "a": [ "Таблички со стихом из старой книги", "Мигающие лампочки", "Мешочки с лакомствами" ] }, { "id": "isr-b-solar-ashalim", "e": "🌞", "t": "Башня солнечных зеркал", "s": "В пустыне Негев стоит высоченная башня — выше двухсот метров. Вокруг неё на песке расставлены десятки тысяч зеркал. Все они поворачиваются за солнцем и отправляют лучи в одну точку на вершине башни. Там вода превращается в пар, пар вертит турбину, и получается электричество. Пустыня почти весь год залита солнцем, поэтому энергии здесь много. Станция называется Ашалим, и когда её построили, она считалась одной из самых высоких солнечных башен в мире.", "q": "Куда зеркала отправляют солнечные лучи?", "a": [ "На вершину башни", "На землю у моря", "В небо для самолётов" ] }, { "id": "isr-b-olive-trees", "e": "🫒", "t": "Оливы-старики", "s": "Олива — дерево с узким серебристым листом и толстым корявым стволом. Она растёт в Израиле с очень давних времён и живёт необыкновенно долго: некоторым деревьям, как считают, много сотен лет, а то и тысяча. Осенью урожай собирают, оливки давят и получают золотисто-зелёное масло. Его кладут в салаты, льют на хумус и макают в него хлеб. Старые оливы по-прежнему дают плоды — и за ними бережно ухаживают.", "q": "Что получают из оливок?", "a": [ "Масло", "Молоко", "Мёд" ] } ], "uae": [ { "id": "uae-a-burj-khalifa", "e": "🏙️", "t": "Самое высокое здание в мире", "s": "В Дубае стоит самое высокое здание на свете. Оно называется Бурдж-Халифа. В нём 163 этажа, а высота — около 828 метров. Если поставить футбольные поля одно за другим, их понадобится почти восемь, чтобы дотянуться до такой длины. Здание узкое и ступенчатое: каждый «уступ» поднимается выше предыдущего, и вершина будто тает в небе. Говорят, архитекторы придумали форму, глядя на пустынный цветок.", "q": "Сколько этажей в Бурдж-Халифе?", "a": [ "163", "16", "30" ] }, { "id": "uae-a-burj-lifts", "e": "🛗", "t": "Лифт как ракета", "s": "В Бурдж-Халифе лифты очень быстрые. Они едут со скоростью около десяти метров в секунду — быстрее, чем бежит любой человек. Чтобы доехать до смотровой площадки на 124-м этаже, нужно всего около минуты. Ничего страшного: кабина плавная, только уши немного закладывает, как в самолёте. Для разных этажей в здании свои лифты, а смотровая площадка ждёт гостей высоко над городом.", "q": "За сколько лифт довозит до смотровой площадки?", "a": [ "Примерно за минуту", "За целый час", "За одну секунду" ] }, { "id": "uae-a-dubai-fountain", "e": "⛲", "t": "Танцующий фонтан", "s": "У подножия Бурдж-Халифы раскинулось большое озеро, а в нём живёт Дубайский фонтан. Вечером он начинает танцевать под музыку: сотни струй взлетают выше многих домов, качаются, кружатся и сверкают разноцветными огнями. Музыка бывает разная — арабская и песни из других стран. Люди собираются на набережной, смотрят и хлопают. Это один из самых больших танцующих фонтанов в мире.", "q": "Под что танцует Дубайский фонтан?", "a": [ "Под музыку", "Под дождь", "Под тишину" ] }, { "id": "uae-a-view-top", "e": "🌅", "t": "Дубай с высоты", "s": "Если подняться на смотровую площадку Бурдж-Халифы, весь Дубай виден как на ладони. Машины — как жучки, дома — как кубики, а по краю города лежит жёлтая пустыня и блестит синее море. Иногда вершина здания прячется в облаках. А ещё говорят, что закат можно увидеть дважды: сначала с самого верха, а потом, спустившись вниз, увидеть, как солнце садится снова.", "q": "Что видно за городом с высоты?", "a": [ "Пустыня и море", "Снежные горы", "Густой лес" ] }, { "id": "uae-a-palm-island", "e": "🌴", "t": "Остров-пальма", "s": "Возле Дубая в море лежит остров в форме пальмы. Он называется Пальма Джумейра. Самое удивительное: природа его не создавала, его насыпали люди. Сверху видны «ствол», шестнадцать больших «листьев» и круг вокруг них. Остров такой огромный, что его замечают даже космонавты на орбите. А на его «листьях» стоят дома, у каждого есть выход к морю.", "q": "Кто создал остров Пальма Джумейра?", "a": [ "Люди его насыпали", "Его принесло течение", "Он вырос из семечка" ] }, { "id": "uae-a-palm-build", "e": "🏗️", "t": "Как насыпать остров", "s": "Как построить остров в море? В Дубае сделали так: со дна залива поднимали песок и выливали на нужное место, а вокруг сложили большие камни, чтобы волны не смыли берег. Так появились «ствол» и шестнадцать «листьев». А вокруг всей пальмы выложили длинную дамбу в форме полумесяца. Она заслоняет остров от больших волн, как забор от ветра.", "q": "Для чего вокруг пальмы дамба-полумесяц?", "a": [ "Чтобы защитить остров от волн", "Чтобы ловить рыбу", "Чтобы красиво светилась" ] }, { "id": "uae-a-museum-future", "e": "🔮", "t": "Музей Будущего", "s": "В Дубае стоит здание, похожее на огромное кольцо с дырой посередине. Это Музей Будущего. Он открылся в 2022 году. Его стены блестят, а на них — большие арабские буквы, красивый почерк, который называют каллиграфией. Ночью буквы подсвечены. Внутри можно посмотреть на выдумки и изобретения про завтрашний день: как люди, возможно, будут жить, лететь в космос и выращивать еду.", "q": "На что похоже здание Музея Будущего?", "a": [ "На большое кольцо", "На высокий шар", "На длинную змею" ] }, { "id": "uae-a-museum-letters", "e": "✍️", "t": "Здание, которое можно читать", "s": "Буквы на Музее Будущего — не просто украшение. Это мысли о будущем, написанные по-арабски красивым почерком. Их сочинил правитель Дубая. Окна музея вырезаны прямо в форме букв, и сквозь них внутрь проходит свет. Получается, что стены здания — как страницы большой книги, которую читают люди на улице. Арабская письменность идёт справа налево, не как русская.", "q": "В какую сторону пишут по-арабски?", "a": [ "Справа налево", "Слева направо", "Сверху вниз по кругу" ] }, { "id": "uae-a-ski-dubai", "e": "⛷️", "t": "Снег в пустыне", "s": "Летом в Дубае бывает жарче сорока градусов. А внутри одного торгового центра есть настоящий снег! Это Ски Дубай. Там всегда холодно, лежит белый снег, и люди катаются на лыжах, сноубордах и санках. Снег делают специальные машины. Можно слепить снеговика, бросить снежок, а потом выйти на улицу — и снова в жару. Тёплую куртку выдают прямо на входе.", "q": "Кто делает снег в Ски Дубай?", "a": [ "Специальные машины", "Тучи над крышей", "Дворники" ] }, { "id": "uae-a-penguins", "e": "🐧", "t": "Пингвины в жаркой стране", "s": "В снежном парке Ски Дубай живут настоящие пингвины. Их там небольшая колония. Они важно ходят вперевалочку, ныряют в холодную воду и скатываются по снегу. Пингвинам совсем не жарко: для них держат прохладу, как у них на родине, где холодно. Можно прийти на встречу с пингвинами и посмотреть на них вблизи. Представьте: пингвины — в стране, где вокруг пустыня!", "q": "Что делают пингвины в Ски Дубай?", "a": [ "Ходят вперевалочку и ныряют", "Летают под потолком", "Роют норы в песке" ] }, { "id": "uae-a-al-fahidi", "e": "🏛️", "t": "Старый Дубай и ловцы ветра", "s": "Старый Дубай совсем не похож на небоскрёбы. В квартале Аль-Фахиди — узкие улочки и дома из камня. На крышах стоят невысокие башни — «ловцы ветра». Они ловят ветерок и направляют его вниз, в комнаты, так люди охлаждали дома, когда не было кондиционеров. Рядом стоит форт Аль-Фахиди, которому больше двухсот лет. Сейчас в нём музей про жизнь прежнего Дубая.", "q": "Что делали башни-«ловцы ветра»?", "a": [ "Гнали прохладу в комнаты", "Ловили рыбу", "Показывали время" ] }, { "id": "uae-a-dubai-creek", "e": "🚤", "t": "Ручей посреди города", "s": "Посреди Дубая течёт «ручей»: так по-английски называют Дубай-Крик. На самом деле это морской залив, который длинной лентой заходит в город. Много лет назад здесь стояли торговые лодки и привозили специи, ткани и золото. Сегодня у берега тоже стоят деревянные лодки, а по воде катают гостей. Залив делит город на два берега, и они похожи на два соседних двора.", "q": "Что такое Дубай-Крик?", "a": [ "Морской залив в городе", "Горная речка", "Озеро в пустыне" ] }, { "id": "uae-a-abra", "e": "⛵", "t": "Абра — лодка-автобус", "s": "Через Дубай-Крик можно переправиться на абре. Это маленькая деревянная лодка с навесом от солнца. Она отходит, когда наберётся достаточно пассажиров, как автобус. Плыть недолго, ветерок обдувает лицо, а лодочник стоит у руля. Проезд стоит совсем недорого. С воды видно сразу и старые дома, и новые блестящие башни. Абры плавают здесь уже много лет.", "q": "Для чего нужна абра?", "a": [ "Чтобы переплыть залив", "Чтобы летать над городом", "Чтобы ездить по пустыне" ] }, { "id": "uae-a-pearl-divers", "e": "🦪", "t": "Ловцы жемчуга", "s": "Давным-давно, до того как нашли нефть, Дубай жил жемчугом. Летом мужчины выходили на больших лодках в залив ловить жемчуг. Они ныряли без акваланга, набирали полную корзину ракушек и всплывали. Жемчужина есть не в каждой ракушке, поэтому открывать приходилось очень много. Найденный жемчуг продавали торговцам, а те увозили его в разные страны.", "q": "Чем жил Дубай до нефти?", "a": [ "Ловлей жемчуга", "Продажей снега", "Постройкой самолётов" ] }, { "id": "uae-a-nose-clip", "e": "🤿", "t": "Зажим на носу", "s": "У ловцов жемчуга не было ни маски, ни акваланга. Зато был зажим на нос — маленькая прищепка из дерева, кости или панциря черепахи, чтобы вода не заливалась. На пальцах — кожаные напальчники, чтобы не порезаться об острые раковины. К ноге привязывали камень, чтобы быстро спуститься. А помощник наверху держал верёвку и вытаскивал ныряльщика, когда тот дёргал за неё.", "q": "Для чего ловцу жемчуга зажим на носу?", "a": [ "Чтобы вода не заливалась в нос", "Чтобы лучше слышать", "Чтобы не чихать на солнце" ] }, { "id": "uae-a-gold-souk", "e": "💍", "t": "Золотой сук", "s": "В Дубае есть рынок, где золота — как цветов на клумбе. Он называется Золотой сук, находится в районе Дейра. «Сук» по-арабски значит «рынок». Над узкой улицей — навес, а по обе стороны сияют витрины: цепочки, браслеты, серьги и кольца. Продавцы вежливо приглашают заглянуть. Сюда приходят покупатели из многих стран, и все улыбаются.", "q": "Что значит слово «сук»?", "a": [ "Рынок", "Золото", "Лодка" ] }, { "id": "uae-a-spice-souk", "e": "🌶️", "t": "Рынок, который пахнет", "s": "Рядом с Золотым суком есть Сук пряностей. Воздух там пахнет корицей, гвоздикой и сушёным лаймом. В мешках лежат красные, жёлтые и коричневые горки. Продавцы насыпают пряности в пакетики. Дороже всех шафран: его собирают вручную из серединок цветков крокуса, а на одну щепотку нужно очень много цветков. Попробуйте угадать запах с закрытыми глазами!", "q": "Из чего получают шафран?", "a": [ "Из серединок цветков крокуса", "Из морских ракушек", "Из жёлтого песка" ] }, { "id": "uae-a-dubai-frame", "e": "🖼️", "t": "Золотая рамка Дубая", "s": "В одном из парков Дубая стоит огромная золотая рамка. Называется она Дубай Фрейм, и в ней около ста пятидесяти метров высоты. Рамка — как окно в двух мирах. Если смотреть с одной стороны, видно старый Дубай с низкими домами. С другой стороны видны небоскрёбы и новые улицы. А наверху есть мост, где пол местами прозрачный: стоишь и видишь, что под ногами далеко внизу.", "q": "Какого цвета Дубай Фрейм?", "a": [ "Золотого", "Голубого", "Зелёного" ] }, { "id": "uae-a-aquarium", "e": "🦈", "t": "Аквариум в торговом центре", "s": "В торговом центре Дубай-молл есть огромный аквариум. Стекло у него такое большое, что рыб видно даже тем, кто просто идёт мимо. Внутри плавают акулы, скаты и тысячи других рыб. Можно пройти по стеклянному туннелю, а рыбы будут плыть над головой, как облака. Скаты взмахивают «крыльями», а акулы неторопливо ходят кругами. Это целое море внутри здания.", "q": "Где находится этот аквариум?", "a": [ "В торговом центре", "На вершине горы", "В пустыне под землёй" ] }, { "id": "uae-a-miracle-garden", "e": "🌸", "t": "Сад чудес", "s": "В пустыне вырос огромный сад — Сад чудес. В нём цветут миллионы цветов. Из цветов сложены не только клумбы, но и арки, сердца, домики и большие фигуры. Цветы поливают по капелькам, чтобы беречь воду. Сад открывают, когда на улице не слишком жарко: летом цветам и людям было бы тяжело. Идёшь по дорожкам, а вокруг — ковёр всех цветов радуги.", "q": "Из чего сделаны фигуры в Саду чудес?", "a": [ "Из цветов", "Из снега", "Из конфет" ] }, { "id": "uae-a-dubai-mall", "e": "🛍️", "t": "Город под одной крышей", "s": "Дубай-молл — один из самых больших торговых центров в мире. Внутри больше тысячи магазинов, каток, аквариум и водопад, у которого стоят золотые фигуры «ныряльщиков». Они будто прыгают с высоты в воду. Из торгового центра можно выйти прямо к фонтану и Бурдж-Халифе. Чтобы обойти всё, нужен не один день, и лучше взять запасные удобные ботинки!", "q": "Что есть внутри Дубай-молла?", "a": [ "Каток и аквариум", "Только одна лавка", "Большое поле для футбола и коровы" ] }, { "id": "uae-a-robots", "e": "🤖", "t": "Роботы-помощники", "s": "В Дубае любят роботов. В некоторых торговых центрах и на выставках гостей встречают роботы-помощники. Они умеют показать дорогу, ответить на вопрос или сфотографироваться с детьми. Есть даже роботы, которые готовят кофе или подают мороженое. Роботы не живые и не обижаются, если с ними не поздороваться. Но поздороваться всё равно вежливо — вдруг им приятно?", "q": "Что умеют роботы-помощники?", "a": [ "Показывают дорогу и отвечают на вопросы", "Рисуют звёзды на небе", "Играют на скрипке на улице" ] }, { "id": "uae-a-air-taxi", "e": "🚁", "t": "Летающие такси", "s": "В Дубае готовятся к летающим такси. Это небольшие аппараты с несколькими винтами, похожие на очень большой дрон, только с пассажирами. Они будут взлетать с площадок на крышах и перелетать над пробками. Так можно добраться из одного района в другой за несколько минут. Пока такие аппараты проверяют и испытывают: безопасность — главное, поэтому полетим не сразу.", "q": "Откуда взлетают летающие такси?", "a": [ "С площадок на крышах", "С верхушек пальм", "Из-под воды" ] }, { "id": "uae-a-burj-al-arab", "e": "⛵", "t": "Отель-парус", "s": "Недалеко от берега Дубая стоит отель, похожий на огромный белый парус. Это Бурдж-эль-Араб. Его высота — около 321 метра. Построили его на острове, который насыпали специально. Парус сделан из прочной ткани, а вечером по нему бегут разноцветные огни. К острову ведёт один мост. Кажется, что каменный корабль плывёт по морю, но он стоит на месте.", "q": "На что похож отель Бурдж-эль-Араб?", "a": [ "На парус", "На ракушку", "На яйцо" ] }, { "id": "uae-a-metro", "e": "🚇", "t": "Метро без машиниста", "s": "В Дубае метро ездит без машиниста. Поездом управляет компьютер, а в кабине спереди никто не сидит. Поэтому лучшие места — впереди, у большого окна: смотришь, как поезд мчится между небоскрёбами, и будто сидишь за штурвалом. Метро открыли в 2009 году, и большую часть пути оно идёт над землёй, на высоких мостах. На станциях работают кондиционеры, ведь на улице бывает очень жарко.", "q": "Кто управляет поездом в метро Дубая?", "a": [ "Компьютер", "Лодочник", "Пингвин" ] }, { "id": "uae-b-dunes-red", "e": "🏜️", "t": "Рыжий песок", "s": "В Эмиратах есть пустыни, где песок совсем рыжий, будто в нём растёрли кирпич. Цвет ему дают крошечные крупинки железа: они ржавеют на солнце и красят песчинки. Ветер гонит песок и складывает его в дюны — настоящие песчаные горы с острыми гребнями. Днём гребень горит оранжевым, а вечером становится розовым. Дюны не стоят на месте: за много лет они потихоньку переезжают, а на песке остаются волнистые узоры от ветра.", "q": "Что красит песок в рыжий цвет?", "a": [ "Крошечные крупинки железа", "Рыжая краска", "Морская соль" ] }, { "id": "uae-b-safari", "e": "🚙", "t": "Сафари по дюнам", "s": "В пустыне ОАЭ можно прокатиться на сафари. Джип сначала спускает часть воздуха из шин, чтобы колёса стали мягкими и не тонули в песке. Потом он взбирается на дюну и съезжает вниз, как с горки! Водитель знает каждый склон и едет осторожно. На вершине все выходят полюбоваться видом: кругом золотые волны песка до самого горизонта. Пассажиры пристёгнуты ремнями, поэтому катание безопасное и весёлое.", "q": "Что делают с шинами перед поездкой по дюнам?", "a": [ "Спускают часть воздуха", "Надевают цепи", "Красят в рыжий цвет" ] }, { "id": "uae-b-stars", "e": "🌌", "t": "Звёзды над пустыней", "s": "Когда в пустыне наступает ночь, на небе зажигается столько звёзд, что трудно поверить. В городах яркие огни мешают смотреть вверх, а в пустыне огней нет, и небо тёмное. Можно увидеть длинную молочную полосу — это Млечный Путь. Давным-давно путники в пустыне находили дорогу по звёздам, как по карте. Ночью в песках прохладно, поэтому берут тёплый плед, ложатся на спину и считают звёзды. До утра не сосчитать.", "q": "Как путники находили дорогу ночью в пустыне?", "a": [ "По звёздам", "По запаху цветов", "По следам лягушек" ] }, { "id": "uae-b-al-ain-oasis", "e": "🌴", "t": "Оазис Аль-Айн", "s": "Город Аль-Айн называют зелёным городом пустыни. В его оазисе растут тысячи финиковых пальм, а под ними — тень и прохладные дорожки. Воду сюда веками приводили по узким каналам, которые называются «фаладж». Вода течёт сама, по уклону, а фермеры по очереди направляют её к своим грядкам. Оазис такой старинный и особенный, что вошёл в список Всемирного наследия ЮНЕСКО. Гулять по нему приятно: жарко только там, где нет пальм.", "q": "Как называются старинные каналы, по которым пришла вода в оазис?", "a": [ "Фаладж", "Бассейн", "Фонтан" ] }, { "id": "uae-b-liwa-moreeb", "e": "⛰️", "t": "Пустыня Лива и дюна Мореб", "s": "Огромная пустыня Руб-эль-Хали лежит на нескольких странах, а её кусочек — оазис Лива в Абу-Даби. Там стоит дюна по имени Мореб, и она похожа на гигантскую песчаную гору: высотой около трёхсот метров, как большой небоскрёб. Склон у неё крутой, а песок гладкий, как покрывало. Смельчаки поднимаются на неё пешком или заезжают на машинах. Вокруг дюн растут островки пальм и зелёные пятна, где живут жуки и ящерицы.", "q": "Какой высоты примерно дюна Мореб?", "a": [ "Около трёхсот метров", "Как кошка", "Как табуретка" ] }, { "id": "uae-b-camel-hump", "e": "🐪", "t": "Горб не с водой", "s": "Многие думают, что в горбу верблюда хранится вода. Но на самом деле горб — это запас жира. Когда верблюду нечего есть, тело берёт силы из горба, и тогда он становится мягким и обвисает. Пока горб полный, верблюд может долго идти по пустыне без еды. Воду он пьёт быстро и помногу: за раз может выпить несколько вёдер. Жир собран в одном месте, а не по всему телу, поэтому верблюду легче переносить жару.", "q": "Что на самом деле хранится в горбу верблюда?", "a": [ "Жир", "Вода", "Песок" ] }, { "id": "uae-b-camel-lashes", "e": "👀", "t": "Верблюжьи ресницы", "s": "Верблюд придуман для пустыни, и всё у него устроено умно. Ресницы длинные и в два ряда, как густые щёточки: они защищают глаза от песка. Есть у верблюда и третье, прозрачное веко: оно закрывает глаз, но дорогу сквозь него видно. Ноздри он может прикрыть, когда дует песчаный ветер. А ступни у него широкие и мягкие, как подушки, чтобы не проваливаться в песок. Вот как хорошо верблюд устроен для жизни в пустыне.", "q": "Для чего верблюду длинные ресницы?", "a": [ "Защищать глаза от песка", "Подметать пол", "Чтобы красиво моргать" ] }, { "id": "uae-b-camel-race", "e": "🏁", "t": "Верблюжьи скачки", "s": "В Эмиратах любят верблюжьи скачки: верблюды бегут по длинной дорожке почти как лошади на ипподроме. Бегут они быстро, около сорока километров в час. Раньше на них сидели люди, а теперь на спину сажают лёгких роботов-жокеев. Робот держит поводья, а хозяин управляет им по пульту и едет рядом по дороге на машине. Так верблюдам скакать удобнее, а людям безопаснее. Победитель получает кубок, а верблюд — угощение и похвалу.", "q": "Кто сидит на верблюдах на современных скачках?", "a": [ "Роботы-жокеи", "Маленькие обезьянки", "Игрушечные медведи" ] }, { "id": "uae-b-camel-chocolate", "e": "🍫", "t": "Шоколад из верблюжьего молока", "s": "Верблюжье молоко в Эмиратах пьют с давних пор. Оно белое и чуть солоноватое. Несколько лет назад в Дубае придумали необычное лакомство: шоколад на верблюжьем молоке. Его делают в виде плиток и конфет, а в начинку кладут финики, орехи и пряности. Сладкоежки со всего мира покупают такие конфеты в красивых коробках. А верблюды просто дают молоко и не знают, какие вкусные конфеты из него получаются.", "q": "Из чего делают необычный шоколад в Дубае?", "a": [ "Из верблюжьего молока", "Из ослиной шерсти", "Из песка" ] }, { "id": "uae-b-falcon-symbol", "e": "🦅", "t": "Сокол — птица страны", "s": "Сокол — одна из главных птиц Эмиратов. Его изображают на гербе страны: золотой сокол с раскрытыми крыльями держит щит с флагом. Сокол смелый и зоркий: он замечает добычу издалека и летит очень быстро. Раньше он помогал людям в пустыне добывать пищу, поэтому его уважают как друга и помощника. Сокол — символ силы, терпения и красоты, и жители Эмиратов очень бережно к нему относятся.", "q": "Какая птица нарисована на гербе Эмиратов?", "a": [ "Сокол", "Попугай", "Страус" ] }, { "id": "uae-b-falcon-passport", "e": "✈️", "t": "Паспорт для сокола", "s": "Знаете, что в Эмиратах у соколов есть собственные паспорта? В нём записаны сведения о птице, а на лапу ей надевают колечко с номером, который есть и в паспорте. По этому номеру одного сокола можно отличить от другого. С таким паспортом сокол может отправиться путешествовать на самолёте. Птица сидит в колпачке, чтобы не волноваться, и ведёт себя спокойно, как настоящий пассажир. Правила у каждой авиакомпании свои, но главное — чтобы птица была здорова.", "q": "Что надевают соколу на лапу для паспорта?", "a": [ "Колечко с номером", "Тапочки", "Браслет с бантом" ] }, { "id": "uae-b-falcon-hospital", "e": "🏥", "t": "Больница для соколов", "s": "В Абу-Даби есть большая больница только для соколов. Там принимают много птиц: им делают осмотры, взвешивают их и лечат крылья и лапы. Врачи надевают птицам маленькие колпачки на голову — так сокол успокаивается и не боится. Есть палаты, где птицы отдыхают, и даже комнаты для полётов, где они разминают крылья после лечения. Когда сокол выздоравливает, его возвращают хозяину. Эту больницу называют одной из самых больших в мире.", "q": "Что врачи надевают соколам, чтобы они не боялись?", "a": [ "Колпачок на голову", "Тёмные очки", "Шарфик" ] }, { "id": "uae-b-falconry", "e": "🪶", "t": "Соколиная охота", "s": "Много лет назад жители пустыни приручали соколов, чтобы те помогали им добывать еду. Соколиная охота — старая традиция, которую передают от дедушек внукам. Сокол носит на голове колпачок, а человек — толстую кожаную перчатку, потому что у птицы острые когти. Сокол взлетает, замечает добычу и ловит её. Потом он возвращается к хозяину за кусочком мяса. Сегодня соколиная охота — любимое наследие страны, и ею гордятся.", "q": "Для чего соколиный охотник носит толстую перчатку?", "a": [ "Чтобы птица не поцарапала", "Чтобы руки не мёрзли", "Чтобы красиво выглядеть" ] }, { "id": "uae-b-oryx", "e": "🦌", "t": "Арабский орикс", "s": "Арабский орикс — белая антилопа с двумя длинными прямыми рогами. Она живёт в пустыне и привыкла к жаре: светлая шерсть отражает солнечный свет. Рога у ориксов такие стройные, что сбоку они кажутся одним рогом. Возможно, поэтому когда-то придумали сказки про единорогов. Одно время ориксов осталось очень мало, но люди заботились о них, и теперь они снова живут на воле, в заповедниках. Орикс — любимое животное жителей ОАЭ.", "q": "Чем арабские ориксы похожи на сказочных единорогов?", "a": [ "Рога сбоку кажутся одним рогом", "Они умеют летать", "Они светятся ночью" ] }, { "id": "uae-b-dates", "e": "🌴", "t": "Финики и финиковые пальмы", "s": "Финиковая пальма — самое известное дерево Эмиратов. Она растёт в жару и любит солнце. Каждый год на пальме созревают тяжёлые гроздья золотисто-коричневых плодов — фиников. Сортов фиников очень много, сотни: есть мягкие, сладкие, хрустящие и тёмные. Их едят свежими и сушёными, кладут в сладости и подают гостям. В Эмиратах проходят фестивали фиников, куда приносят самые красивые гроздья. Финики можно есть прямо с кожурой!", "q": "Сколько сортов фиников существует?", "a": [ "Сотни", "Только один", "Три" ] }, { "id": "uae-b-gahwa", "e": "☕", "t": "Кофе гавах", "s": "В Эмиратах гостей встречают особым кофе, который называют «гавах». Он светлый, почти как чай, и пахнет кардамоном — душистой пряностью. Иногда в него добавляют и шафран. Варят кофе в высоком кофейнике с длинным носиком. Наливают совсем чуть-чуть, в маленькую чашечку без ручки. Если гость выпил достаточно, он легонько покачивает пустой чашечкой. Хозяин понимает: хватит, спасибо. Подают кофе вместе с финиками.", "q": "Что делает гость, когда не хочет больше кофе?", "a": [ "Покачивает пустую чашку", "Прячет чашку", "Хлопает в ладоши" ] }, { "id": "uae-b-grand-mosque", "e": "🕌", "t": "Мечеть шейха Зайда", "s": "В Абу-Даби стоит одна из самых красивых мечетей на свете. Она сделана из белого мрамора, который блестит на солнце, как снег. У мечети восемьдесят два купола, а во дворе сверкают бассейны с водой. Внутри лежит огромный ковёр, сплетённый вручную из огромного числа узелков. Под куполом висят большие люстры с блестящими кристаллами. Мечеть открыта для гостей, но надо одеваться скромно и тихо ходить по залам. Вечером она подсвечена мягким светом.", "q": "Сколько куполов у мечети шейха Зайда?", "a": [ "Восемьдесят два", "Три", "Сто пятьдесят" ] }, { "id": "uae-b-louvre", "e": "🏛️", "t": "Лувр в Абу-Даби", "s": "В Абу-Даби есть музей с огромным куполом, похожим на серебристую тарелку. Это Лувр Абу-Даби. Купол очень широкий, около ста восьмидесяти метров, и сделан из металлических звёзд. Их почти восемь тысяч, разного размера, а между ними пробивается солнце. Внутри музея свет падает сверху, будто дождь из светлых точек. Его так и называют — «дождь света». Музей стоит у самой воды, а внутри собраны картины и скульптуры из разных стран.", "q": "Что называют «дождём света» в Лувре Абу-Даби?", "a": [ "Свет, пробивающийся сквозь купол из звёзд", "Брызги фонтана", "Огни фейерверка" ] }, { "id": "uae-b-yas-ferrari", "e": "🎢", "t": "Остров Яс и красные горки", "s": "Остров Яс в Абу-Даби — остров развлечений. Там есть парк Феррари-парк, где всё красного цвета, как у гоночных машин. А в нём — одни из самых быстрых американских горок на свете. Они называются «Формула Росса». Горки разгоняются примерно до двухсот сорока километров в час, и всего за пять секунд! Поэтому катающимся нужны защитные очки. Рядом на острове есть и трасса, где проходят настоящие автогонки.", "q": "Зачем на самых быстрых горках нужны очки?", "a": [ "Чтобы защитить глаза от ветра", "Чтобы красиво выглядеть", "Чтобы не слышать шум" ] }, { "id": "uae-b-flamingo-mangrove", "e": "🦩", "t": "Фламинго и мангры", "s": "В Абу-Даби на мелководье растут мангры — деревья, которые стоят прямо в солёной воде. Их корни торчат вверх, как трубочки, и помогают деревьям дышать. В зарослях живут крабики и рыбки, а неподалёку вышагивают розовые фламинго. Они часто стоят на одной ножке и ищут еду в воде. Розовыми их делает еда: рачки и водоросли. А птенцы рождаются серыми. Лучше всего любоваться птицами с байдарки: тихо подплыть и не спугнуть.", "q": "Чем питаются фламинго, чтобы стать розовыми?", "a": [ "Рачками и водорослями", "Свёклой", "Клубникой" ] }, { "id": "uae-b-fujairah", "e": "⛰️", "t": "Фуджейра и горы Хаджар", "s": "Эмират Фуджейра стоит на берегу другого моря — Оманского залива. А за ним поднимаются горы Хаджар. Слово «хаджар» по-арабски значит «камень». Горы коричневые, серые и красноватые, с глубокими ущельями — вади, где после дождя журчит вода. Здесь можно найти старинные форты и маленький остров, который называют островом Снупи: издали он похож на собаку, лежащую на воде. Люди любят там купаться и плавать с маской.", "q": "Что значит слово «хаджар» по-арабски?", "a": [ "Камень", "Верблюд", "Волна" ] }, { "id": "uae-b-seven-emirates", "e": "🇦🇪", "t": "Как семь эмиратов стали вместе", "s": "Давным-давно на этих землях жили в разных городках и оазисах. Люди ловили рыбу, ныряли за жемчугом и пасли верблюдов. Потом правители решили жить вместе, как одна большая семья. Второго декабря тысяча девятьсот семьдесят первого года шесть эмиратов объединились, а чуть позже к ним присоединился седьмой. Теперь это Абу-Даби, Дубай, Шарджа, Аджман, Умм-эль-Кайвайн, Фуджейра и Рас-эль-Хайма. Каждый год второго декабря в стране Национальный день.", "q": "Сколько эмиратов в стране?", "a": [ "Семь", "Три", "Двенадцать" ] }, { "id": "uae-b-dirham", "e": "💰", "t": "Деньги: дирхамы", "s": "В Эмиратах расплачиваются дирхамами. В одном дирхаме сто филсов — как в рубле сто копеек. Монетки блестят, а банкноты бывают разных цветов, и на них нарисованы красивые картинки. Слово «дирхам» очень старое: оно пришло из Древней Греции, от слова «драхма». Раньше дирхамами называли серебряные монеты, которыми платили купцы на верблюжьих тропах. Сегодня за дирхамы покупают сладости, игрушки и билеты в музеи.", "q": "Сколько филсов в одном дирхаме?", "a": [ "Сто", "Десять", "Два" ] }, { "id": "uae-b-clothes", "e": "👘", "t": "Кандура и абайя", "s": "Жара в Эмиратах сильная, поэтому одежда здесь удобная и лёгкая. Мужчины носят длинную рубашку — кандуру. Обычно она белая, потому что белый цвет отражает солнце. На голове — платок гутра, а чтобы он не слетел, его придерживает чёрный шнур. Женщины носят абайю — длинную лёгкую накидку, а на голову повязывают шарф. Абайи бывают с красивой вышивкой. Это повседневная одежда, и её носят с уважением и гордостью.", "q": "Для чего кандуру обычно шьют белой?", "a": [ "Белый цвет отражает солнце", "Так проще стирать", "Чтобы её видно ночью" ] }, { "id": "uae-b-turtles", "e": "🐢", "t": "Черепахи бисса", "s": "Около берегов Эмиратов живут морские черепахи. Одна из них называется бисса. У неё острый клюв, похожий на птичий, и красивый панцирь из пластинок, как черепица. Питается бисса морскими губками. Летом самки выбираются ночью на тихий пляж и откладывают яйца в яму в песке. Примерно через два месяца из яиц вылупляются малыши и бегут к воде. Люди следят, чтобы никто им не мешал.", "q": "Где бисса откладывает яйца?", "a": [ "В яму в песке на пляже", "На ветках пальмы", "В морской губке" ] } ] });
